-- R6c adds only forward, immutable authorities.  Existing supplier-only
-- relationship rows and every migration through 0036 remain untouched.
-- PERSON endpoints deliberately have no address, birth date, resident number,
-- family relation, score, rank, or probability column.

BEGIN;

-- BEGIN GENERATED EVENT PAYLOAD FORWARD OVERRIDES
-- Generated by scripts/generate_event_payload_registry.py; do not edit.
DO $event_payload_override$
DECLARE
  v_updated integer;
BEGIN
  WITH schema_overrides(event_type,payload_schema_uri,payload_schema) AS (
    VALUES
      ('attachment.scan_completed.v1','payloads/attachment_scan_completed_v1.schema.json',$event_schema${"additionalProperties":false,"properties":{"attachment_id":{"type":"string"},"attachment_kind":{"enum":["CORRECTION","RESPONSE"],"type":"string"},"scan_status":{"type":"string"},"sha256":{"type":"string"}},"required":["attachment_id","attachment_kind","scan_status","sha256"],"type":"object"}$event_schema$::jsonb),
      ('agent.run_control_changed.v2','payloads/agent_run_control_changed_v2.schema.json',$event_schema${"additionalProperties":false,"oneOf":[{"properties":{"actorId":{"oneOf":[{"format":"uuid","type":"string"},{"type":"null"}]},"actorType":{"const":"LEGACY_ACTOR_TYPE_MUST_BE_ABSENT"}}},{"properties":{"actorId":{"const":"analysis-worker"},"actorKind":{"const":"ANALYSIS_WORKER"},"actorType":{"const":"SERVICE"}},"required":["actorType","actorKind","actorId"]}],"properties":{"actorId":{"oneOf":[{"format":"uuid","type":"string"},{"type":"null"},{"const":"analysis-worker"}]},"actorKind":{"enum":["CONTROL_API","ANALYSIS_WORKER","RECONCILIATION_WORKER","SCHEDULER"],"type":"string"},"actorType":{"enum":["SERVICE"],"type":"string"},"affectedProviderTurnId":{"format":"uuid","type":["string","null"]},"affectedToolCallId":{"format":"uuid","type":["string","null"]},"aggregateVersion":{"minimum":1,"type":"integer"},"budgetDisposition":{"enum":["NONE","RESERVED","SETTLED","RELEASED","RECONCILIATION_REQUIRED"],"type":"string"},"budgetResolutionSetSha256":{"pattern":"^[0-9a-f]{64}$","type":"string"},"nextControlState":{"enum":["NONE","ACTIVE","CANCEL_REQUESTED","RECONCILIATION_REQUIRED","SETTLED"],"type":"string"},"nextStatus":{"enum":["QUEUED","RUNNING","SUCCEEDED","FAILED","CANCELLED","BUDGET_BLOCKED","POLICY_BLOCKED"],"type":"string"},"occurredAt":{"format":"date-time","type":"string"},"priorControlState":{"enum":["NONE","ACTIVE","CANCEL_REQUESTED","RECONCILIATION_REQUIRED","SETTLED",null],"type":["string","null"]},"priorStatus":{"enum":["QUEUED","RUNNING","SUCCEEDED","FAILED","CANCELLED","BUDGET_BLOCKED","POLICY_BLOCKED",null],"type":["string","null"]},"proofKind":{"enum":["COMMAND_INPUT","LEASE_CLAIM","PROVIDER_LOOKUP","IDEMPOTENCY_LOOKUP","TOOL_ADAPTER_LOOKUP","COST_USAGE_RECEIPT","DEFINITIVE_NO_DISPATCH","VALIDATED_FINAL_OUTPUT","DEFINITIVE_INTERNAL_FAILURE"],"type":"string"},"proofSha256":{"pattern":"^[0-9a-f]{64}$","type":"string"},"reasonCode":{"enum":["RUN_STARTED","TURN_ADVANCED","FINAL_OUTPUT_VALIDATED","DEFINITIVE_FAILURE","BUDGET_DENIED","POLICY_DENIED","PRE_DISPATCH_CANCELLED","CANCEL_REQUESTED","OUTCOME_AMBIGUOUS","SAFE_RETRY_AUTHORIZED","RECONCILED_SUCCEEDED","RECONCILED_FAILED","RECONCILED_CANCELLED","NO_STATE_CHANGE"],"type":"string"},"reasonSha256":{"pattern":"^[0-9a-f]{64}$","type":"string"},"receiptSha256":{"pattern":"^[0-9a-f]{64}$","type":"string"},"reconciliationEvidenceId":{"format":"uuid","type":["string","null"]},"reconciliationEvidenceSha256":{"pattern":"^[0-9a-f]{64}$","type":["string","null"]},"runId":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$","type":"string"}},"required":["runId","aggregateVersion","priorStatus","priorControlState","nextStatus","nextControlState","affectedProviderTurnId","affectedToolCallId","reconciliationEvidenceId","reconciliationEvidenceSha256","proofKind","proofSha256","budgetDisposition","budgetResolutionSetSha256","actorKind","actorId","reasonCode","reasonSha256","occurredAt","receiptSha256"],"type":"object"}$event_schema$::jsonb)
  ), updated AS (
    UPDATE ops.event_types AS registered
    SET payload_schema_uri=override.payload_schema_uri,
