$event_payload_override$;
-- END GENERATED EVENT PAYLOAD FORWARD OVERRIDES

-- The ingest parser already resolves the pinned parser version while writing
-- normalized connector rows.  Earlier migrations granted the relation only
-- to document-extractor; the owner path stays read-only for ingest-worker.
GRANT SELECT (
  parser_name, version, implementation_digest, status
) ON core.parser_versions TO gurine_ingest_worker;

-- Promotion is a SECURITY DEFINER boundary owned by gurine_migrator.  The
-- parser authority tables predate that owner role, so grant only the columns
-- needed to re-bind a selected segment to its active, successful parser run.
GRANT SELECT (
  id, source_document_id, parser_name, parser_version, status,
  input_content_sha256, output_digest, implementation_sha256,
  extraction_receipt_sha256
) ON core.parser_runs TO gurine_migrator;
GRANT SELECT (
  parser_name, version, supported_media_types, implementation_digest, status
) ON core.parser_versions TO gurine_migrator;

-- Provider-output validation and citation persistence replay the exact v2
-- proposal binding.  This is the closed production read set; table-wide
-- suggestion visibility remains unavailable to the analysis worker.
GRANT SELECT (
  id, agent_run_id, citation_validation_id, suggestion_type,
  proposal_contract_version, payload, payload_sha256, input_snapshot_sha256,
  target_schema_version, evidence_ids, citation_checks, payload_canonical
)
  ON ops.agent_suggestions TO gurine_analysis_worker;

ALTER TABLE raw.research_artifacts
  ADD CONSTRAINT research_artifacts_review_tier_binding_uq UNIQUE (
    id, asset_id, asset_revision, artifact_sha256, content_sha256
  );

ALTER TABLE ops.execution_authorizations
  ADD CONSTRAINT execution_authorizations_recursion_binding_uq UNIQUE (
    execution_id, generation, execution_digest
  );

ALTER TABLE core.dataset_snapshots
  ADD CONSTRAINT dataset_snapshots_generation_hash_binding_uq UNIQUE (
    id, producer_generation, snapshot_sha256
  );

-- Typed graph assertions are copied into AGENT_CASE snapshots as immutable
-- read-only corpus members.  The forward replacements preserve every prior
-- branch and add only the closed typed-assertion branch.
ALTER TABLE core.dataset_snapshot_members
  DROP CONSTRAINT dataset_snapshot_members_object_type_ck,
  ADD CONSTRAINT dataset_snapshot_members_object_type_ck CHECK (
    object_type IN (
      'AGENCY', 'SUPPLIER', 'CONTRACT', 'CONTRACT_LINE_ITEM',
      'CONTRACT_CHANGE', 'PRICE_OBSERVATION', 'EVIDENCE_SEGMENT',
      'RESPONSE', 'TYPED_RELATIONSHIP_ASSERTION'
    )
  ),
  DROP CONSTRAINT dataset_snapshot_members_source_shape_ck,
  ADD CONSTRAINT dataset_snapshot_members_source_shape_ck CHECK (
    (
      object_type = 'EVIDENCE_SEGMENT'
      AND evidence_segment_id IS NOT NULL
      AND evidence_segment_id = object_id
      AND response_id IS NULL
      AND normalization_run_id IS NULL
      AND normalization_version IS NULL
      AND normalization_sha256 IS NULL
    )
    OR (
      object_type = 'RESPONSE'
      AND response_id IS NOT NULL
      AND response_id = object_id
      AND evidence_segment_id IS NULL
      AND normalization_run_id IS NULL
      AND normalization_version IS NULL
      AND normalization_sha256 IS NULL
    )
    OR (
      snapshot_kind IN ('DETECTION_DATASET', 'AGENT_CASE')
      AND object_type = 'CONTRACT'
      AND evidence_segment_id IS NULL
      AND response_id IS NULL
      AND normalization_run_id IS NULL
      AND normalization_version IS NULL
      AND normalization_sha256 IS NULL
    )
    OR (
      snapshot_kind = 'AGENT_CASE'
      AND object_type = 'TYPED_RELATIONSHIP_ASSERTION'
      AND evidence_segment_id IS NULL
      AND response_id IS NULL
      AND normalization_run_id IS NULL
      AND normalization_version IS NULL
      AND normalization_sha256 IS NULL
    )
    OR (
      object_type NOT IN (
        'EVIDENCE_SEGMENT', 'RESPONSE', 'TYPED_RELATIONSHIP_ASSERTION'
      )
      AND NOT (
        snapshot_kind IN ('DETECTION_DATASET', 'AGENT_CASE')
        AND object_type = 'CONTRACT'
      )
      AND evidence_segment_id IS NULL
      AND response_id IS NULL
      AND normalization_run_id IS NOT NULL
      AND normalization_version IS NOT NULL
      AND normalization_sha256 IS NOT NULL
    )
  );

ALTER TABLE ops.agent_source_uses
  DROP CONSTRAINT agent_source_uses_source_shape_ck,
  ADD CONSTRAINT agent_source_uses_source_shape_ck CHECK (
    (
      source_kind = 'EVIDENCE_SEGMENT'
      AND dataset_snapshot_id IS NOT NULL
      AND snapshot_member_id IS NOT NULL
      AND snapshot_member_digest IS NOT NULL
      AND snapshot_member_source_id IS NOT NULL
      AND snapshot_member_source_digest IS NOT NULL
      AND member_source_kind = 'SOURCE_DOCUMENT'
      AND object_type = 'EVIDENCE_SEGMENT'
      AND object_id IS NOT NULL
      AND object_version IS NOT NULL AND object_version > 0
      AND object_content_sha256 IS NOT NULL
      AND evidence_segment_id IS NOT NULL AND evidence_segment_id = object_id
      AND source_document_id IS NOT NULL
      AND source_asset_id IS NOT NULL
      AND source_asset_revision IS NOT NULL AND source_asset_revision > 0
      AND source_content_sha256 IS NOT NULL
      AND selected_content_sha256 IS NOT NULL
      AND locator_sha256 IS NOT NULL
      AND response_id IS NULL AND response_version IS NULL
      AND response_content_sha256 IS NULL
      AND research_artifact_id IS NULL AND research_asset_id IS NULL
      AND research_asset_revision IS NULL
      AND research_artifact_sha256 IS NULL
      AND research_content_sha256 IS NULL
      AND research_source_fetch_id IS NULL
    )
    OR (
      source_kind = 'RESPONSE_SNAPSHOT'
      AND dataset_snapshot_id IS NOT NULL
      AND snapshot_member_id IS NOT NULL
      AND snapshot_member_digest IS NOT NULL
      AND snapshot_member_source_id IS NOT NULL
      AND snapshot_member_source_digest IS NOT NULL
      AND member_source_kind = 'RESPONSE'
      AND object_type = 'RESPONSE'
      AND object_id IS NOT NULL
      AND object_version IS NOT NULL AND object_version > 0
      AND object_content_sha256 IS NOT NULL
      AND response_id IS NOT NULL AND response_id = object_id
      AND response_version IS NOT NULL AND response_version = object_version
      AND response_content_sha256 IS NOT NULL
      AND response_content_sha256 = object_content_sha256
      AND source_document_id IS NULL AND source_asset_id IS NULL
      AND source_asset_revision IS NULL AND source_content_sha256 IS NULL
      AND evidence_segment_id IS NULL
      AND research_artifact_id IS NULL AND research_asset_id IS NULL
      AND research_asset_revision IS NULL
      AND research_artifact_sha256 IS NULL
      AND research_content_sha256 IS NULL
      AND research_source_fetch_id IS NULL
    )
    OR (
      source_kind = 'DATASET_MEMBER'
      AND dataset_snapshot_id IS NOT NULL
      AND snapshot_member_id IS NOT NULL
      AND snapshot_member_digest IS NOT NULL
      AND snapshot_member_source_id IS NOT NULL
      AND snapshot_member_source_digest IS NOT NULL
      AND member_source_kind = 'SOURCE_DOCUMENT'
      AND object_type IN (
        'AGENCY', 'SUPPLIER', 'CONTRACT', 'CONTRACT_LINE_ITEM',
        'CONTRACT_CHANGE', 'PRICE_OBSERVATION',
        'TYPED_RELATIONSHIP_ASSERTION'
      )
      AND object_id IS NOT NULL
      AND object_version IS NOT NULL AND object_version > 0
      AND object_content_sha256 IS NOT NULL
      AND source_document_id IS NOT NULL
      AND source_asset_id IS NOT NULL
      AND source_asset_revision IS NOT NULL AND source_asset_revision > 0
      AND source_content_sha256 IS NOT NULL
      AND evidence_segment_id IS NULL
      AND response_id IS NULL AND response_version IS NULL
      AND response_content_sha256 IS NULL
      AND research_artifact_id IS NULL AND research_asset_id IS NULL
      AND research_asset_revision IS NULL
      AND research_artifact_sha256 IS NULL
      AND research_content_sha256 IS NULL
      AND research_source_fetch_id IS NULL
    )
    OR (
      source_kind = 'RESEARCH_ARTIFACT'
      AND dataset_snapshot_id IS NULL
      AND snapshot_member_id IS NULL
      AND snapshot_member_digest IS NULL
      AND snapshot_member_source_id IS NULL
      AND snapshot_member_source_digest IS NULL
      AND member_source_kind IS NULL
      AND object_type IS NULL AND object_id IS NULL
      AND object_version IS NULL AND object_content_sha256 IS NULL
      AND evidence_segment_id IS NULL
      AND source_document_id IS NULL AND source_asset_id IS NULL
      AND source_asset_revision IS NULL AND source_content_sha256 IS NULL
      AND response_id IS NULL AND response_version IS NULL
      AND response_content_sha256 IS NULL
      AND response_publication_consent_sha256 IS NULL
      AND research_artifact_id IS NOT NULL
      AND research_asset_id IS NOT NULL
      AND research_asset_revision = 1
      AND research_artifact_sha256 IS NOT NULL
      AND research_content_sha256 IS NOT NULL
      AND research_source_fetch_id IS NOT NULL
    )
  );

ALTER TABLE raw.research_artifact_promotions
  ADD CONSTRAINT research_artifact_promotions_review_tier_binding_uq UNIQUE (
    promotion_id, receipt_sha256, research_artifact_id,
    research_asset_id, research_asset_revision,
    research_artifact_sha256, research_content_sha256
  );

CREATE TABLE raw.research_artifact_review_tiers (
  tier_id uuid NOT NULL DEFAULT gen_random_uuid(),
  research_artifact_id uuid NOT NULL,
  research_asset_id uuid NOT NULL,
  research_asset_revision bigint NOT NULL,
  research_artifact_sha256 char(64) NOT NULL,
  research_content_sha256 char(64) NOT NULL,
  revision bigint NOT NULL,
  review_tier text NOT NULL,
  reviewed_classification text NOT NULL,
  predecessor_revision bigint,
  predecessor_receipt_sha256 char(64),
  source_use_agent_run_id uuid,
  source_use_id uuid,
  source_use_sha256 char(64),
  source_locator_digest char(64) NOT NULL,
  official_source_registry_digest char(64) NOT NULL,
  promotion_id uuid,
  promotion_receipt_sha256 char(64),
  reviewed_by uuid,
  reviewed_at timestamptz,
  receipt_payload jsonb NOT NULL,
  receipt_canonical bytea NOT NULL,
  receipt_sha256 char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT research_artifact_review_tiers_pk PRIMARY KEY (tier_id),
  CONSTRAINT research_artifact_review_tiers_revision_uq
    UNIQUE (research_artifact_id, revision),
  CONSTRAINT research_artifact_review_tiers_chain_uq
    UNIQUE (research_artifact_id, revision, receipt_sha256),
  CONSTRAINT research_artifact_review_tiers_receipt_uq
    UNIQUE (receipt_sha256),
  CONSTRAINT research_artifact_review_tiers_artifact_fk FOREIGN KEY (
    research_artifact_id, research_asset_id, research_asset_revision,
    research_artifact_sha256, research_content_sha256
  ) REFERENCES raw.research_artifacts(
    id, asset_id, asset_revision, artifact_sha256, content_sha256
  ) ON DELETE RESTRICT,
  CONSTRAINT research_artifact_review_tiers_source_use_fk FOREIGN KEY (
    source_use_agent_run_id, source_use_id, source_use_sha256
  ) REFERENCES ops.agent_source_uses(
    agent_run_id, source_use_id, source_use_sha256
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT research_artifact_review_tiers_promotion_fk FOREIGN KEY (
    promotion_id, promotion_receipt_sha256, research_artifact_id,
    research_asset_id, research_asset_revision,
    research_artifact_sha256, research_content_sha256
  ) REFERENCES raw.research_artifact_promotions(
    promotion_id, receipt_sha256, research_artifact_id,
    research_asset_id, research_asset_revision,
    research_artifact_sha256, research_content_sha256
  ) ON DELETE RESTRICT,
  CONSTRAINT research_artifact_review_tiers_reviewer_fk
    FOREIGN KEY (reviewed_by) REFERENCES ops.users(id) ON DELETE RESTRICT,
  CONSTRAINT research_artifact_review_tiers_shape_ck CHECK (
    revision > 0
    AND num_nonnulls(
      source_use_agent_run_id, source_use_id, source_use_sha256
    ) IN (0, 3)
    AND review_tier IN ('OFFICIAL_UNREVIEWED', 'HUMAN_PROMOTED')
    AND reviewed_classification IN (
      'PUBLIC', 'INTERNAL', 'RESTRICTED', 'PERSONAL_DATA', 'LEGAL_HOLD'
    )
    AND (
      (
        review_tier = 'OFFICIAL_UNREVIEWED'
        AND reviewed_classification = 'RESTRICTED'
        AND revision = 1
        AND num_nonnulls(
          predecessor_revision, predecessor_receipt_sha256,
          promotion_id, promotion_receipt_sha256, reviewed_by, reviewed_at
        ) = 0
      )
      OR (
        review_tier = 'HUMAN_PROMOTED'
        AND revision = 2
        AND predecessor_revision = 1
        AND num_nonnulls(
          predecessor_receipt_sha256, promotion_id,
          promotion_receipt_sha256, reviewed_by, reviewed_at
        ) = 5
      )
    )
  ),
  CONSTRAINT research_artifact_review_tiers_digest_ck CHECK (
    research_artifact_sha256 ~ '^[0-9a-f]{64}$'
    AND research_content_sha256 ~ '^[0-9a-f]{64}$'
    AND (
      source_use_sha256 IS NULL
      OR source_use_sha256 ~ '^[0-9a-f]{64}$'
    )
    AND source_locator_digest ~ '^[0-9a-f]{64}$'
    AND official_source_registry_digest ~ '^[0-9a-f]{64}$'
    AND (
      predecessor_receipt_sha256 IS NULL
      OR predecessor_receipt_sha256 ~ '^[0-9a-f]{64}$'
    )
    AND (
      promotion_receipt_sha256 IS NULL
      OR promotion_receipt_sha256 ~ '^[0-9a-f]{64}$'
    )
    AND receipt_sha256 ~ '^[0-9a-f]{64}$'
  ),
  CONSTRAINT research_artifact_review_tiers_canonical_ck CHECK (
    convert_from(receipt_canonical, 'UTF8')::jsonb = receipt_payload
    AND receipt_sha256 = encode(
      extensions.digest(receipt_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE raw.research_artifact_review_tiers OWNER TO gurine_migrator;
ALTER TABLE raw.research_artifact_review_tiers
  ADD CONSTRAINT research_artifact_review_tiers_predecessor_fk FOREIGN KEY (
    research_artifact_id, predecessor_revision, predecessor_receipt_sha256
  ) REFERENCES raw.research_artifact_review_tiers(
    research_artifact_id, revision, receipt_sha256
  ) ON DELETE RESTRICT;
REVOKE ALL ON raw.research_artifact_review_tiers FROM PUBLIC;
GRANT SELECT ON raw.research_artifact_review_tiers
  TO gurine_analysis_worker, gurine_workflow_worker,
     gurine_control_api, gurine_auditor;
CREATE TRIGGER research_artifact_review_tiers_immutable_guard
  BEFORE UPDATE OR DELETE ON raw.research_artifact_review_tiers
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE core.relationship_graph_endpoints_v2 (
  endpoint_id uuid NOT NULL DEFAULT gen_random_uuid(),
  endpoint_kind text NOT NULL,
  identity_resolution_status text NOT NULL,
  entity_id uuid,
  entity_revision bigint,
  entity_digest char(64),
  contextual_name text,
  role_title text,
  person_node_digest char(64),
  source_locator text NOT NULL,
  source_locator_digest char(64) NOT NULL,
  identifier_digest char(64) NOT NULL,
  source_document_id uuid,
  source_asset_id uuid,
  source_asset_revision bigint,
  source_content_sha256 char(64),
  parser_run_id uuid,
  parsed_record_id uuid,
  parser_version text,
  parsed_payload_sha256 char(64),
  normalization_run_id uuid,
  normalization_version text,
  normalization_contract_sha256 char(64),
  source_use_agent_run_id uuid,
  source_use_id uuid,
  source_use_sha256 char(64),
  endpoint_payload jsonb NOT NULL,
  endpoint_canonical bytea NOT NULL,
  endpoint_digest char(64) NOT NULL,
  created_actor_type text NOT NULL,
  created_actor_id text NOT NULL,
  created_by uuid,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT relationship_graph_endpoints_v2_pk PRIMARY KEY (endpoint_id),
  CONSTRAINT relationship_graph_endpoints_v2_digest_uq
    UNIQUE (endpoint_digest),
  CONSTRAINT relationship_graph_endpoints_v2_exact_uq
    UNIQUE (endpoint_id, endpoint_digest),
  CONSTRAINT relationship_graph_endpoints_v2_kind_exact_uq
    UNIQUE (endpoint_id, endpoint_kind, endpoint_digest),
  CONSTRAINT relationship_graph_endpoints_v2_source_uq
    UNIQUE (endpoint_id, source_use_id, source_use_sha256),
  CONSTRAINT relationship_graph_endpoints_v2_document_fk FOREIGN KEY (
    source_document_id, source_asset_id, source_asset_revision,
    source_content_sha256
  ) REFERENCES raw.source_documents(
    id, asset_id, asset_revision, content_sha256
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_endpoints_v2_normalization_fk FOREIGN KEY (
    normalization_run_id, source_document_id
  ) REFERENCES core.normalization_runs(
    id, source_document_id
  ) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_endpoints_v2_parser_run_fk FOREIGN KEY (
    parser_run_id, source_document_id
  ) REFERENCES core.parser_runs(
    id, source_document_id
  ) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_endpoints_v2_parsed_record_fk FOREIGN KEY (
    parsed_record_id, source_document_id, parser_run_id,
    parser_version, parsed_payload_sha256
  ) REFERENCES raw.parsed_records(
    id, source_document_id, parser_run_id, parser_version, payload_sha256
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_endpoints_v2_source_use_fk FOREIGN KEY (
    source_use_agent_run_id, source_use_id, source_use_sha256
  ) REFERENCES ops.agent_source_uses(
    agent_run_id, source_use_id, source_use_sha256
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_endpoints_v2_creator_fk
    FOREIGN KEY (created_by) REFERENCES ops.users(id) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_endpoints_v2_kind_ck CHECK (
    endpoint_kind IN (
      'SUPPLIER', 'PERSON', 'AGENCY', 'PROCUREMENT_NOTICE', 'SANCTION'
    )
  ),
  CONSTRAINT relationship_graph_endpoints_v2_person_ck CHECK (
    (
      endpoint_kind = 'PERSON'
      AND identity_resolution_status = 'PENDING_HUMAN'
      AND num_nonnulls(entity_id, entity_revision, entity_digest) = 0
      AND person_node_digest IS NOT NULL
      AND nullif(btrim(contextual_name), '') IS NOT NULL
      AND nullif(btrim(role_title), '') IS NOT NULL
    )
    OR (
      endpoint_kind <> 'PERSON'
      AND identity_resolution_status = 'NOT_APPLICABLE'
      AND num_nonnulls(entity_id, entity_revision, entity_digest) = 3
      AND entity_revision > 0
      AND person_node_digest IS NULL
      AND contextual_name IS NULL
      AND role_title IS NULL
    )
  ),
  CONSTRAINT relationship_graph_endpoints_v2_text_ck CHECK (
    length(btrim(source_locator)) BETWEEN 1 AND 2048
    AND (contextual_name IS NULL OR length(btrim(contextual_name)) <= 300)
    AND (role_title IS NULL OR length(btrim(role_title)) <= 300)
  ),
  CONSTRAINT relationship_graph_endpoints_v2_digest_ck CHECK (
    source_locator_digest ~ '^[0-9a-f]{64}$'
    AND identifier_digest ~ '^[0-9a-f]{64}$'
    AND (
      source_use_sha256 IS NULL
      OR source_use_sha256 ~ '^[0-9a-f]{64}$'
    )
    AND (entity_digest IS NULL OR entity_digest ~ '^[0-9a-f]{64}$')
    AND (
      person_node_digest IS NULL
      OR person_node_digest ~ '^[0-9a-f]{64}$'
    )
    AND (
      source_content_sha256 IS NULL
      OR source_content_sha256 ~ '^[0-9a-f]{64}$'
    )
    AND (
      parsed_payload_sha256 IS NULL
      OR parsed_payload_sha256 ~ '^[0-9a-f]{64}$'
    )
    AND (
      normalization_contract_sha256 IS NULL
      OR normalization_contract_sha256 ~ '^[0-9a-f]{64}$'
    )
    AND endpoint_digest ~ '^[0-9a-f]{64}$'
    AND (
      endpoint_kind <> 'PERSON'
      OR (
        person_node_digest <> identifier_digest
        AND person_node_digest <> endpoint_digest
      )
    )
  ),
  CONSTRAINT relationship_graph_endpoints_v2_provenance_ck CHECK (
    (
      num_nonnulls(
        source_document_id, source_asset_id, source_asset_revision,
        source_content_sha256, parser_run_id, parsed_record_id,
        parser_version, parsed_payload_sha256
      ) = 8
      AND source_asset_revision > 0
      AND num_nonnulls(
        normalization_run_id, normalization_version,
        normalization_contract_sha256
      ) = 0
      AND num_nonnulls(
        source_use_agent_run_id, source_use_id, source_use_sha256
      ) = 0
    )
    OR (
      num_nonnulls(
        source_document_id, source_asset_id, source_asset_revision,
        source_content_sha256, normalization_run_id,
        normalization_version, normalization_contract_sha256
      ) = 7
      AND source_asset_revision > 0
      AND num_nonnulls(
        parser_run_id, parsed_record_id, parser_version,
        parsed_payload_sha256
      ) = 0
      AND num_nonnulls(
        source_use_agent_run_id, source_use_id, source_use_sha256
      ) = 0
    )
    OR (
      num_nonnulls(
        source_document_id, source_asset_id, source_asset_revision,
        source_content_sha256, parser_run_id, parsed_record_id,
        parser_version, parsed_payload_sha256, normalization_run_id,
        normalization_version, normalization_contract_sha256
      ) = 0
      AND num_nonnulls(
        source_use_agent_run_id, source_use_id, source_use_sha256
      ) = 3
    )
  ),
  CONSTRAINT relationship_graph_endpoints_v2_actor_ck CHECK (
    (
      created_actor_type = 'HUMAN'
      AND created_by IS NOT NULL
      AND created_actor_id = created_by::text
    )
    OR (
      created_actor_type = 'SERVICE'
      AND created_by IS NULL
      AND created_actor_id = 'ingest-worker'
    )
  ),
  CONSTRAINT relationship_graph_endpoints_v2_canonical_ck CHECK (
    convert_from(endpoint_canonical, 'UTF8')::jsonb = endpoint_payload
    AND endpoint_digest = encode(
      extensions.digest(endpoint_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE core.relationship_graph_endpoints_v2 OWNER TO gurine_migrator;
REVOKE ALL ON core.relationship_graph_endpoints_v2 FROM PUBLIC;
GRANT SELECT ON core.relationship_graph_endpoints_v2
  TO gurine_control_api, gurine_auditor;
CREATE TRIGGER relationship_graph_endpoints_v2_immutable_guard
  BEFORE UPDATE OR DELETE ON core.relationship_graph_endpoints_v2
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE core.relationship_graph_assertions_v2 (
  assertion_id uuid NOT NULL,
  assertion_revision bigint NOT NULL,
  assertion_digest char(64) NOT NULL,
  predecessor_revision bigint,
  predecessor_digest char(64),
  prior_receipt_sha256 char(64),
  relationship_kind text NOT NULL,
  source_kind text NOT NULL,
  source_locator text NOT NULL,
  source_locator_digest char(64) NOT NULL,
  subject_endpoint_id uuid NOT NULL,
  subject_endpoint_kind text NOT NULL,
  subject_endpoint_digest char(64) NOT NULL,
  object_endpoint_id uuid NOT NULL,
  object_endpoint_kind text NOT NULL,
  object_endpoint_digest char(64) NOT NULL,
  valid_from date,
  valid_to date,
  departed_on date,
  validity_coverage_status text NOT NULL,
  verification_status text NOT NULL,
  public_use_status text NOT NULL,
  evidence_count integer NOT NULL,
  evidence_set_digest char(64) NOT NULL,
  proposed_actor_type text NOT NULL,
  proposed_actor_id text NOT NULL,
  proposed_by uuid,
  verified_by uuid,
  verified_at timestamptz,
  verification_reason_digest char(64),
  assertion_payload jsonb NOT NULL,
  assertion_canonical bytea NOT NULL,
  receipt_payload jsonb NOT NULL,
  receipt_canonical bytea NOT NULL,
  receipt_sha256 char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT relationship_graph_assertions_v2_pk
    PRIMARY KEY (assertion_id, assertion_revision),
  CONSTRAINT relationship_graph_assertions_v2_exact_uq
    UNIQUE (assertion_id, assertion_revision, assertion_digest),
  CONSTRAINT relationship_graph_assertions_v2_chain_uq UNIQUE (
    assertion_id, assertion_revision, assertion_digest, receipt_sha256
  ),
  CONSTRAINT relationship_graph_assertions_v2_digest_uq
    UNIQUE (assertion_digest),
  CONSTRAINT relationship_graph_assertions_v2_receipt_uq
    UNIQUE (receipt_sha256),
  CONSTRAINT relationship_graph_assertions_v2_subject_fk FOREIGN KEY (
    subject_endpoint_id, subject_endpoint_kind, subject_endpoint_digest
  ) REFERENCES core.relationship_graph_endpoints_v2(
    endpoint_id, endpoint_kind, endpoint_digest
  ) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_assertions_v2_object_fk FOREIGN KEY (
    object_endpoint_id, object_endpoint_kind, object_endpoint_digest
  ) REFERENCES core.relationship_graph_endpoints_v2(
    endpoint_id, endpoint_kind, endpoint_digest
  ) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_assertions_v2_proposer_fk
    FOREIGN KEY (proposed_by) REFERENCES ops.users(id) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_assertions_v2_verifier_fk
    FOREIGN KEY (verified_by) REFERENCES ops.users(id) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_assertions_v2_kind_ck CHECK (
    relationship_kind IN (
      'OWNERSHIP', 'BENEFICIAL_OWNERSHIP', 'CONTROL', 'MANAGEMENT_ROLE',
      'LEGAL_REPRESENTATIVE', 'CONTRACTUAL_RELATIONSHIP',
      'BID_PARTICIPATION', 'SANCTION', 'FORMER_OFFICIAL_ROLE'
    )
  ),
  CONSTRAINT relationship_graph_assertions_v2_no_self_ck CHECK (
    subject_endpoint_id <> object_endpoint_id
  ),
  CONSTRAINT relationship_graph_assertions_v2_pair_ck CHECK (
    (
      relationship_kind IN (
        'OWNERSHIP', 'BENEFICIAL_OWNERSHIP', 'CONTROL',
        'CONTRACTUAL_RELATIONSHIP'
      )
      AND subject_endpoint_kind = 'SUPPLIER'
      AND object_endpoint_kind = 'SUPPLIER'
    )
    OR (
      relationship_kind IN ('MANAGEMENT_ROLE', 'LEGAL_REPRESENTATIVE')
      AND subject_endpoint_kind = 'PERSON'
      AND object_endpoint_kind = 'SUPPLIER'
    )
    OR (
      relationship_kind = 'BID_PARTICIPATION'
      AND subject_endpoint_kind = 'SUPPLIER'
      AND object_endpoint_kind = 'PROCUREMENT_NOTICE'
    )
    OR (
      relationship_kind = 'SANCTION'
      AND subject_endpoint_kind = 'SUPPLIER'
      AND object_endpoint_kind = 'SANCTION'
    )
    OR (
      relationship_kind = 'FORMER_OFFICIAL_ROLE'
      AND subject_endpoint_kind = 'PERSON'
      AND object_endpoint_kind = 'AGENCY'
    )
  ),
  CONSTRAINT relationship_graph_assertions_v2_revision_ck CHECK (
    assertion_revision > 0
    AND (
      (
        assertion_revision = 1
        AND num_nonnulls(
          predecessor_revision, predecessor_digest, prior_receipt_sha256
        ) = 0
      )
      OR (
        assertion_revision > 1
        AND predecessor_revision = assertion_revision - 1
        AND num_nonnulls(predecessor_digest, prior_receipt_sha256) = 2
      )
    )
  ),
  CONSTRAINT relationship_graph_assertions_v2_state_ck CHECK (
    validity_coverage_status IN (
      'COMPLETE', 'PARTIAL', 'UNKNOWN', 'NOT_AVAILABLE'
    )
    AND verification_status IN (
      'PENDING_HUMAN', 'VERIFIED', 'REJECTED', 'CONFLICTED', 'SUPERSEDED'
    )
    AND public_use_status IN ('NOT_REVIEWED', 'APPROVED', 'DENIED')
    AND (
      (
        assertion_revision = 1
        AND verification_status = 'PENDING_HUMAN'
        AND public_use_status = 'NOT_REVIEWED'
        AND num_nonnulls(
          verified_by, verified_at, verification_reason_digest
        ) = 0
      )
      OR (
        assertion_revision > 1
        AND verification_status = 'VERIFIED'
        AND public_use_status = 'APPROVED'
        AND validity_coverage_status = 'COMPLETE'
        AND verified_by IS NOT NULL
        AND verified_by IS DISTINCT FROM proposed_by
        AND verified_at IS NOT NULL
        AND verification_reason_digest IS NOT NULL
      )
      OR (
        assertion_revision > 1
        AND verification_status IN (
          'REJECTED', 'CONFLICTED', 'SUPERSEDED'
        )
        AND public_use_status IN ('NOT_REVIEWED', 'DENIED')
        AND verified_by IS NOT NULL
        AND verified_by IS DISTINCT FROM proposed_by
        AND verified_at IS NOT NULL
        AND verification_reason_digest IS NOT NULL
      )
    )
  ),
  CONSTRAINT relationship_graph_assertions_v2_evidence_ck CHECK (
    evidence_count BETWEEN 1 AND 1000
    AND evidence_set_digest ~ '^[0-9a-f]{64}$'
  ),
  CONSTRAINT relationship_graph_assertions_v2_time_ck CHECK (
    valid_from IS NULL OR valid_to IS NULL OR valid_from <= valid_to
  ),
  CONSTRAINT relationship_graph_assertions_v2_source_ck CHECK (
    length(btrim(source_kind)) BETWEEN 1 AND 128
    AND length(btrim(source_locator)) BETWEEN 1 AND 2048
    AND source_locator_digest ~ '^[0-9a-f]{64}$'
  ),
  CONSTRAINT relationship_graph_assertions_v2_departure_ck CHECK (
    (
      relationship_kind = 'FORMER_OFFICIAL_ROLE'
      AND departed_on IS NOT NULL
      AND valid_to IS NOT NULL
      AND valid_to = departed_on
      AND source_kind IN (
        'PUBLIC_OFFICIAL_ETHICS_NOTICE', 'OFFICIAL_GAZETTE'
      )
    )
    OR (
      relationship_kind <> 'FORMER_OFFICIAL_ROLE'
      AND departed_on IS NULL
      AND nullif(btrim(source_kind), '') IS NOT NULL
    )
  ),
  CONSTRAINT relationship_graph_assertions_v2_actor_ck CHECK (
    (
      proposed_actor_type = 'HUMAN'
      AND proposed_by IS NOT NULL
      AND proposed_actor_id = proposed_by::text
    )
    OR (
      proposed_actor_type = 'SERVICE'
      AND proposed_by IS NULL
      AND proposed_actor_id = 'ingest-worker'
    )
  ),
  CONSTRAINT relationship_graph_assertions_v2_digest_ck CHECK (
    assertion_digest ~ '^[0-9a-f]{64}$'
    AND subject_endpoint_digest ~ '^[0-9a-f]{64}$'
    AND object_endpoint_digest ~ '^[0-9a-f]{64}$'
    AND (predecessor_digest IS NULL OR predecessor_digest ~ '^[0-9a-f]{64}$')
    AND (
      prior_receipt_sha256 IS NULL OR prior_receipt_sha256 ~ '^[0-9a-f]{64}$'
    )
    AND (
      verification_reason_digest IS NULL
      OR verification_reason_digest ~ '^[0-9a-f]{64}$'
    )
    AND receipt_sha256 ~ '^[0-9a-f]{64}$'
  ),
  CONSTRAINT relationship_graph_assertions_v2_canonical_ck CHECK (
    convert_from(assertion_canonical, 'UTF8')::jsonb = assertion_payload
    AND assertion_digest = encode(
      extensions.digest(assertion_canonical, 'sha256'), 'hex'
    )
    AND convert_from(receipt_canonical, 'UTF8')::jsonb = receipt_payload
    AND receipt_sha256 = encode(
      extensions.digest(receipt_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE core.relationship_graph_assertions_v2 OWNER TO gurine_migrator;
ALTER TABLE core.relationship_graph_assertions_v2
  ADD CONSTRAINT relationship_graph_assertions_v2_predecessor_fk FOREIGN KEY (
    assertion_id, predecessor_revision, predecessor_digest
  ) REFERENCES core.relationship_graph_assertions_v2(
    assertion_id, assertion_revision, assertion_digest
  ) ON DELETE RESTRICT;
ALTER TABLE core.relationship_graph_assertions_v2
  ADD CONSTRAINT relationship_graph_assertions_v2_predecessor_receipt_fk
  FOREIGN KEY (
    assertion_id, predecessor_revision, predecessor_digest,
    prior_receipt_sha256
  ) REFERENCES core.relationship_graph_assertions_v2(
    assertion_id, assertion_revision, assertion_digest, receipt_sha256
  ) ON DELETE RESTRICT;
REVOKE ALL ON core.relationship_graph_assertions_v2 FROM PUBLIC;
GRANT SELECT ON core.relationship_graph_assertions_v2
  TO gurine_control_api, gurine_auditor;
CREATE TRIGGER relationship_graph_assertions_v2_immutable_guard
  BEFORE UPDATE OR DELETE ON core.relationship_graph_assertions_v2
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE core.relationship_graph_assertion_evidence_v2 (
  assertion_id uuid NOT NULL,
  assertion_revision bigint NOT NULL,
  assertion_digest char(64) NOT NULL,
  evidence_ordinal integer NOT NULL,
  evidence_id uuid NOT NULL,
  evidence_version bigint NOT NULL,
  evidence_digest char(64) NOT NULL,
  source_document_id uuid,
  source_asset_id uuid,
  source_asset_revision bigint,
  source_content_sha256 char(64),
  source_use_agent_run_id uuid,
  source_use_id uuid,
  source_use_sha256 char(64),
  locator_digest char(64) NOT NULL,
  evidence_binding_canonical bytea NOT NULL,
  evidence_member_digest char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT relationship_graph_assertion_evidence_v2_pk
    PRIMARY KEY (assertion_id, assertion_revision, evidence_ordinal),
  CONSTRAINT relationship_graph_assertion_evidence_v2_digest_uq
    UNIQUE (assertion_id, assertion_revision, evidence_member_digest),
  CONSTRAINT relationship_graph_assertion_evidence_v2_parent_fk FOREIGN KEY (
    assertion_id, assertion_revision, assertion_digest
  ) REFERENCES core.relationship_graph_assertions_v2(
    assertion_id, assertion_revision, assertion_digest
  ) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_assertion_evidence_v2_document_fk
    FOREIGN KEY (
      source_document_id, source_asset_id, source_asset_revision,
      source_content_sha256
    ) REFERENCES raw.source_documents(
      id, asset_id, asset_revision, content_sha256
    ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_assertion_evidence_v2_source_use_fk
    FOREIGN KEY (
      source_use_agent_run_id, source_use_id, source_use_sha256
    ) REFERENCES ops.agent_source_uses(
      agent_run_id, source_use_id, source_use_sha256
    ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_assertion_evidence_v2_scalar_ck CHECK (
    evidence_ordinal >= 0 AND evidence_version > 0
  ),
  CONSTRAINT relationship_graph_assertion_evidence_v2_digest_ck CHECK (
    assertion_digest ~ '^[0-9a-f]{64}$'
    AND evidence_digest ~ '^[0-9a-f]{64}$'
    AND (
      source_use_sha256 IS NULL
      OR source_use_sha256 ~ '^[0-9a-f]{64}$'
    )
    AND (
      source_content_sha256 IS NULL
      OR source_content_sha256 ~ '^[0-9a-f]{64}$'
    )
    AND locator_digest ~ '^[0-9a-f]{64}$'
    AND evidence_member_digest ~ '^[0-9a-f]{64}$'
    AND evidence_member_digest = encode(
      extensions.digest(evidence_binding_canonical, 'sha256'), 'hex'
    )
  ),
  CONSTRAINT relationship_graph_assertion_evidence_v2_source_ck CHECK (
    (
      num_nonnulls(
        source_document_id, source_asset_id,
        source_asset_revision, source_content_sha256
      ) = 4
      AND source_asset_revision > 0
      AND num_nonnulls(
        source_use_agent_run_id, source_use_id, source_use_sha256
      ) = 0
    )
    OR (
      num_nonnulls(
        source_document_id, source_asset_id,
        source_asset_revision, source_content_sha256
      ) = 0
      AND num_nonnulls(
        source_use_agent_run_id, source_use_id, source_use_sha256
      ) = 3
    )
  )
);
ALTER TABLE core.relationship_graph_assertion_evidence_v2
  OWNER TO gurine_migrator;
REVOKE ALL ON core.relationship_graph_assertion_evidence_v2 FROM PUBLIC;
GRANT SELECT ON core.relationship_graph_assertion_evidence_v2
  TO gurine_control_api, gurine_auditor;
