  BEFORE UPDATE OR DELETE ON core.relationship_graph_assertion_evidence_v2
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE core.relationship_graph_verification_decisions_v2 (
  decision_id uuid NOT NULL DEFAULT gen_random_uuid(),
  assertion_id uuid NOT NULL,
  prior_assertion_revision bigint NOT NULL,
  prior_assertion_digest char(64) NOT NULL,
  resulting_assertion_revision bigint NOT NULL,
  resulting_assertion_digest char(64) NOT NULL,
  decision_kind text NOT NULL,
  reviewer_user_id uuid NOT NULL,
  reason_digest char(64) NOT NULL,
  decision_payload jsonb NOT NULL,
  decision_canonical bytea NOT NULL,
  decision_digest char(64) NOT NULL,
  prior_receipt_sha256 char(64) NOT NULL,
  receipt_payload jsonb NOT NULL,
  receipt_canonical bytea NOT NULL,
  receipt_sha256 char(64) NOT NULL,
  decided_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT relationship_graph_verification_decisions_v2_pk
    PRIMARY KEY (decision_id),
  CONSTRAINT relationship_graph_verification_decisions_v2_assertion_uq
    UNIQUE (assertion_id, prior_assertion_revision),
  CONSTRAINT relationship_graph_verification_decisions_v2_digest_uq
    UNIQUE (decision_digest),
  CONSTRAINT relationship_graph_verification_decisions_v2_receipt_uq
    UNIQUE (receipt_sha256),
  CONSTRAINT relationship_graph_verification_decisions_v2_prior_fk
    FOREIGN KEY (
      assertion_id, prior_assertion_revision, prior_assertion_digest
    ) REFERENCES core.relationship_graph_assertions_v2(
      assertion_id, assertion_revision, assertion_digest
    ) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_verification_decisions_v2_prior_receipt_fk
    FOREIGN KEY (
      assertion_id, prior_assertion_revision,
      prior_assertion_digest, prior_receipt_sha256
    ) REFERENCES core.relationship_graph_assertions_v2(
      assertion_id, assertion_revision, assertion_digest, receipt_sha256
    ) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_verification_decisions_v2_result_fk
    FOREIGN KEY (
      assertion_id, resulting_assertion_revision,
      resulting_assertion_digest
  ) REFERENCES core.relationship_graph_assertions_v2(
    assertion_id, assertion_revision, assertion_digest
  ) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT relationship_graph_verification_decisions_v2_reviewer_fk
    FOREIGN KEY (reviewer_user_id) REFERENCES ops.users(id) ON DELETE RESTRICT,
  CONSTRAINT relationship_graph_verification_decisions_v2_kind_ck CHECK (
    decision_kind IN ('VERIFY', 'REJECT', 'MARK_CONFLICT', 'SUPERSEDE')
  ),
  CONSTRAINT relationship_graph_verification_decisions_v2_revision_ck CHECK (
    resulting_assertion_revision = prior_assertion_revision + 1
  ),
  CONSTRAINT relationship_graph_verification_decisions_v2_digest_ck CHECK (
    prior_assertion_digest ~ '^[0-9a-f]{64}$'
    AND resulting_assertion_digest ~ '^[0-9a-f]{64}$'
    AND reason_digest ~ '^[0-9a-f]{64}$'
    AND decision_digest ~ '^[0-9a-f]{64}$'
    AND prior_receipt_sha256 ~ '^[0-9a-f]{64}$'
    AND receipt_sha256 ~ '^[0-9a-f]{64}$'
  ),
  CONSTRAINT relationship_graph_verification_decisions_v2_canonical_ck CHECK (
    convert_from(decision_canonical, 'UTF8')::jsonb = decision_payload
    AND decision_digest = encode(
      extensions.digest(decision_canonical, 'sha256'), 'hex'
    )
    AND convert_from(receipt_canonical, 'UTF8')::jsonb = receipt_payload
    AND receipt_sha256 = encode(
      extensions.digest(receipt_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE core.relationship_graph_verification_decisions_v2
  OWNER TO gurine_migrator;
REVOKE ALL ON core.relationship_graph_verification_decisions_v2 FROM PUBLIC;
GRANT SELECT ON core.relationship_graph_verification_decisions_v2
  TO gurine_control_api, gurine_auditor;
CREATE TRIGGER relationship_graph_verification_decisions_v2_immutable_guard
  BEFORE UPDATE OR DELETE ON core.relationship_graph_verification_decisions_v2
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE core.dataset_snapshot_relationship_assertions_v2 (
  binding_id uuid NOT NULL DEFAULT gen_random_uuid(),
  dataset_snapshot_id uuid NOT NULL,
  snapshot_sha256 char(64) NOT NULL,
  snapshot_generation bigint NOT NULL,
  assertion_ordinal bigint NOT NULL,
  assertion_id uuid NOT NULL,
  assertion_revision bigint NOT NULL,
  assertion_digest char(64) NOT NULL,
  binding_canonical bytea NOT NULL,
  binding_digest char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT dataset_snapshot_relationship_assertions_v2_pk
    PRIMARY KEY (binding_id),
  CONSTRAINT dataset_snapshot_relationship_assertions_v2_ordinal_uq
    UNIQUE (dataset_snapshot_id, assertion_ordinal),
  CONSTRAINT dataset_snapshot_relationship_assertions_v2_assertion_uq
    UNIQUE (dataset_snapshot_id, assertion_id, assertion_revision),
  CONSTRAINT dataset_snapshot_relationship_assertions_v2_digest_uq
    UNIQUE (dataset_snapshot_id, binding_digest),
  CONSTRAINT dataset_snapshot_relationship_assertions_v2_snapshot_fk
    FOREIGN KEY (
      dataset_snapshot_id, snapshot_generation, snapshot_sha256
    ) REFERENCES core.dataset_snapshots(
      id, producer_generation, snapshot_sha256
    ) ON DELETE RESTRICT,
  CONSTRAINT dataset_snapshot_relationship_assertions_v2_assertion_fk
    FOREIGN KEY (assertion_id, assertion_revision, assertion_digest)
    REFERENCES core.relationship_graph_assertions_v2(
      assertion_id, assertion_revision, assertion_digest
    ) ON DELETE RESTRICT,
  CONSTRAINT dataset_snapshot_relationship_assertions_v2_scalar_ck CHECK (
    snapshot_generation > 0 AND assertion_ordinal >= 0
  ),
  CONSTRAINT dataset_snapshot_relationship_assertions_v2_digest_ck CHECK (
    snapshot_sha256 ~ '^[0-9a-f]{64}$'
    AND assertion_digest ~ '^[0-9a-f]{64}$'
    AND binding_digest ~ '^[0-9a-f]{64}$'
    AND binding_digest = encode(
      extensions.digest(binding_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE core.dataset_snapshot_relationship_assertions_v2
  OWNER TO gurine_migrator;
REVOKE ALL ON core.dataset_snapshot_relationship_assertions_v2 FROM PUBLIC;
GRANT SELECT ON core.dataset_snapshot_relationship_assertions_v2
  TO gurine_control_api, gurine_auditor;
CREATE TRIGGER dataset_snapshot_relationship_assertions_v2_immutable_guard
  BEFORE UPDATE OR DELETE ON core.dataset_snapshot_relationship_assertions_v2
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

ALTER TABLE core.dataset_snapshots
  ADD COLUMN conflict_input_count bigint,
  ADD COLUMN conflict_input_set_sha256 char(64),
  ADD CONSTRAINT dataset_snapshots_conflict_input_shape_ck CHECK (
    (
      conflict_input_count IS NULL
      AND conflict_input_set_sha256 IS NULL
    )
    OR (
      conflict_input_count > 0
      AND conflict_input_set_sha256 ~ '^[0-9a-f]{64}$'
    )
  );

CREATE TABLE core.dataset_snapshot_conflict_inputs_v2 (
  input_id uuid NOT NULL DEFAULT gen_random_uuid(),
  dataset_snapshot_id uuid NOT NULL,
  snapshot_kind text NOT NULL,
  producer_generation bigint NOT NULL,
  snapshot_contract_version smallint NOT NULL,
  rule_id text NOT NULL,
  rule_version_id uuid NOT NULL,
  rule_version_digest char(64) NOT NULL,
  coverage_status text NOT NULL,
  input_payload jsonb NOT NULL,
  input_canonical bytea NOT NULL,
  input_sha256 char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT dataset_snapshot_conflict_inputs_v2_pk PRIMARY KEY (input_id),
  CONSTRAINT dataset_snapshot_conflict_inputs_v2_rule_uq UNIQUE (
    dataset_snapshot_id, rule_id, rule_version_id
  ),
  CONSTRAINT dataset_snapshot_conflict_inputs_v2_digest_uq UNIQUE (
    dataset_snapshot_id, input_sha256
  ),
  CONSTRAINT dataset_snapshot_conflict_inputs_v2_header_fk FOREIGN KEY (
    dataset_snapshot_id, snapshot_kind, producer_generation,
    snapshot_contract_version
  ) REFERENCES core.dataset_snapshots(
    id, snapshot_kind, producer_generation, contract_version
  ) ON DELETE RESTRICT,
  CONSTRAINT dataset_snapshot_conflict_inputs_v2_rule_fk
    FOREIGN KEY (rule_version_id)
    REFERENCES core.rule_versions(id) ON DELETE RESTRICT,
  CONSTRAINT dataset_snapshot_conflict_inputs_v2_shape_ck CHECK (
    snapshot_kind = 'DETECTION_DATASET'
    AND snapshot_contract_version = 1
    AND producer_generation > 0
    AND rule_id IN (
      'OFFICER_OVERLAP_AWARD', 'OWNERSHIP_LINKED_COMPETITORS',
      'BID_ROTATION', 'REVOLVING_DOOR_CONTRACT',
      'SANCTIONED_SUCCESSOR'
    )
    AND coverage_status IN ('COMPLETE', 'PARTIAL', 'BLOCKED')
  ),
  CONSTRAINT dataset_snapshot_conflict_inputs_v2_digest_ck CHECK (
    rule_version_digest ~ '^[0-9a-f]{64}$'
    AND input_sha256 ~ '^[0-9a-f]{64}$'
    AND convert_from(input_canonical, 'UTF8')::jsonb = input_payload
    AND input_sha256 = encode(
      extensions.digest(input_canonical, 'sha256'), 'hex'
    )
  ),
  CONSTRAINT dataset_snapshot_conflict_inputs_v2_payload_ck CHECK (
    jsonb_typeof(input_payload) = 'object'
    AND input_payload->>'schema_version' = 'conflict-detection-input.v2'
    AND input_payload->>'rule_id' = rule_id
    AND input_payload->>'rule_version_id' = rule_version_id::text
    AND input_payload->>'rule_version_digest' = btrim(rule_version_digest)
    AND input_payload->>'coverage_status' = coverage_status
    AND NOT (input_payload ? 'policy')
    AND jsonb_typeof(input_payload->'coverage') = 'object'
    AND jsonb_typeof(input_payload->'contracts') = 'array'
    AND jsonb_typeof(input_payload->'suppliers') = 'array'
    AND jsonb_typeof(input_payload->'procurement_notices') = 'array'
    AND jsonb_typeof(input_payload->'procurement_awards') = 'array'
    AND jsonb_typeof(input_payload->'bidder_participations') = 'array'
    AND jsonb_typeof(input_payload->'sanctions') = 'array'
    AND jsonb_typeof(input_payload->'typed_relationship_assertions') = 'array'
    AND jsonb_typeof(input_payload->'strong_identifier_facts') = 'array'
  )
);
ALTER TABLE core.dataset_snapshot_conflict_inputs_v2
  OWNER TO gurine_migrator;
REVOKE ALL ON core.dataset_snapshot_conflict_inputs_v2 FROM PUBLIC;
GRANT SELECT ON core.dataset_snapshot_conflict_inputs_v2
  TO gurine_analysis_worker, gurine_control_api, gurine_auditor;
CREATE TRIGGER dataset_snapshot_conflict_inputs_v2_immutable_guard
  BEFORE UPDATE OR DELETE ON core.dataset_snapshot_conflict_inputs_v2
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE ops.hypothesis_recursion_policies (
  policy_id uuid NOT NULL DEFAULT gen_random_uuid(),
  policy_key text NOT NULL DEFAULT 'HYPOTHESIS_RECURSION',
  version bigint NOT NULL,
  enabled boolean NOT NULL,
  max_depth integer NOT NULL,
  case_budget_micros_krw bigint NOT NULL,
  market_researcher_stage_budget_micros_krw bigint NOT NULL,
  skeptic_stage_budget_micros_krw bigint NOT NULL,
  provider_policy_version text NOT NULL,
  provider_policy_sha256 char(64) NOT NULL,
  provider_classification text NOT NULL,
  provider_candidate_ids text[] NOT NULL,
  budget_policy_version text NOT NULL,
  budget_policy_sha256 char(64) NOT NULL,
  max_provider_turns integer NOT NULL,
  max_tool_calls integer NOT NULL,
  deadline_interval interval NOT NULL,
  market_researcher_prompt_id text NOT NULL,
  market_researcher_prompt_version text NOT NULL,
  market_researcher_prompt_sha256 char(64) NOT NULL,
  market_researcher_output_schema_id text NOT NULL,
  market_researcher_output_schema_version text NOT NULL,
  market_researcher_output_schema_sha256 char(64) NOT NULL,
  skeptic_prompt_id text NOT NULL,
  skeptic_prompt_version text NOT NULL,
  skeptic_prompt_sha256 char(64) NOT NULL,
  skeptic_output_schema_id text NOT NULL,
  skeptic_output_schema_version text NOT NULL,
  skeptic_output_schema_sha256 char(64) NOT NULL,
  created_by uuid NOT NULL,
  retention_schedule_id uuid,
  retention_record_class text,
  retention_schedule_digest char(64),
  policy_canonical bytea NOT NULL,
  policy_digest char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT hypothesis_recursion_policies_pk PRIMARY KEY (policy_id),
  CONSTRAINT hypothesis_recursion_policies_version_uq
    UNIQUE (policy_key, version),
  CONSTRAINT hypothesis_recursion_policies_id_version_uq
    UNIQUE (policy_id, version),
  CONSTRAINT hypothesis_recursion_policies_exact_uq
    UNIQUE (policy_id, version, policy_digest),
  CONSTRAINT hypothesis_recursion_policies_digest_uq
    UNIQUE (policy_digest),
  CONSTRAINT hypothesis_recursion_policies_creator_fk
    FOREIGN KEY (created_by) REFERENCES ops.users(id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_policies_retention_ck CHECK (
    retention_record_class IS NULL
    OR retention_record_class = 'AGENT_RUNTIME_POLICY'
  ),
  CONSTRAINT hypothesis_recursion_policies_retention_fk FOREIGN KEY (
    retention_schedule_id, retention_record_class, retention_schedule_digest
  ) REFERENCES ops.record_class_schedules(
    id, record_class, schedule_digest
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_policies_key_ck CHECK (
    policy_key = 'HYPOTHESIS_RECURSION' AND version > 0
  ),
  CONSTRAINT hypothesis_recursion_policies_required_ck CHECK (
    COALESCE((
      max_depth BETWEEN 1 AND 16
      AND case_budget_micros_krw > 0
      AND market_researcher_stage_budget_micros_krw > 0
      AND skeptic_stage_budget_micros_krw > 0
      AND nullif(btrim(provider_policy_version), '') IS NOT NULL
      AND provider_policy_sha256 ~ '^[0-9a-f]{64}$'
      AND provider_classification IN ('PUBLIC', 'INTERNAL')
      AND provider_candidate_ids IS NOT NULL
      AND ops.agent_provider_candidates_are_valid(provider_candidate_ids)
      AND nullif(btrim(budget_policy_version), '') IS NOT NULL
      AND budget_policy_sha256 ~ '^[0-9a-f]{64}$'
      AND max_provider_turns BETWEEN 1 AND 32
      AND max_tool_calls BETWEEN 0 AND 32
      AND deadline_interval > interval '0 seconds'
      AND nullif(btrim(market_researcher_prompt_id), '') IS NOT NULL
      AND nullif(btrim(market_researcher_prompt_version), '') IS NOT NULL
      AND market_researcher_prompt_sha256 ~ '^[0-9a-f]{64}$'
      AND nullif(btrim(market_researcher_output_schema_id), '') IS NOT NULL
      AND nullif(
        btrim(market_researcher_output_schema_version), ''
      ) IS NOT NULL
      AND market_researcher_output_schema_sha256 ~ '^[0-9a-f]{64}$'
      AND nullif(btrim(skeptic_prompt_id), '') IS NOT NULL
      AND nullif(btrim(skeptic_prompt_version), '') IS NOT NULL
      AND skeptic_prompt_sha256 ~ '^[0-9a-f]{64}$'
      AND nullif(btrim(skeptic_output_schema_id), '') IS NOT NULL
      AND nullif(btrim(skeptic_output_schema_version), '') IS NOT NULL
      AND skeptic_output_schema_sha256 ~ '^[0-9a-f]{64}$'
      AND created_by IS NOT NULL
    ), false)
  ),
  CONSTRAINT hypothesis_recursion_policies_canonical_ck CHECK (
    policy_digest ~ '^[0-9a-f]{64}$'
    AND policy_digest = encode(
      extensions.digest(policy_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE ops.hypothesis_recursion_policies OWNER TO gurine_migrator;
REVOKE ALL ON ops.hypothesis_recursion_policies FROM PUBLIC;
GRANT SELECT ON ops.hypothesis_recursion_policies
  TO gurine_workflow_worker, gurine_control_api, gurine_auditor;
CREATE TRIGGER hypothesis_recursion_policies_immutable_guard
  BEFORE UPDATE OR DELETE ON ops.hypothesis_recursion_policies
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE ops.hypothesis_recursion_plans (
  plan_id uuid NOT NULL DEFAULT gen_random_uuid(),
  case_id uuid NOT NULL,
  root_hypothesis_execution_id uuid NOT NULL,
  root_hypothesis_execution_generation bigint NOT NULL,
  root_hypothesis_execution_digest char(64) NOT NULL,
  dataset_snapshot_id uuid NOT NULL,
  snapshot_sha256 char(64) NOT NULL,
  policy_id uuid NOT NULL,
  policy_version bigint NOT NULL,
  policy_digest char(64) NOT NULL,
  max_depth integer NOT NULL,
  case_budget_micros_krw bigint NOT NULL,
  actor_type text NOT NULL DEFAULT 'SERVICE',
  actor_id text NOT NULL DEFAULT 'workflow-worker',
  retention_schedule_id uuid,
  retention_record_class text,
  retention_schedule_digest char(64),
  plan_canonical bytea NOT NULL,
  plan_digest char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT hypothesis_recursion_plans_pk PRIMARY KEY (plan_id),
  CONSTRAINT hypothesis_recursion_plans_root_uq
    UNIQUE (
      root_hypothesis_execution_id, root_hypothesis_execution_generation
    ),
  CONSTRAINT hypothesis_recursion_plans_node_binding_uq UNIQUE (
    plan_id, case_id, dataset_snapshot_id, snapshot_sha256
  ),
  CONSTRAINT hypothesis_recursion_plans_digest_uq UNIQUE (plan_digest),
  CONSTRAINT hypothesis_recursion_plans_case_fk
    FOREIGN KEY (case_id) REFERENCES editorial.cases(id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_plans_execution_fk FOREIGN KEY (
    root_hypothesis_execution_id, root_hypothesis_execution_generation,
    root_hypothesis_execution_digest
  ) REFERENCES ops.execution_authorizations(
    execution_id, generation, execution_digest
  ) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_plans_snapshot_fk FOREIGN KEY (
    dataset_snapshot_id, snapshot_sha256
  ) REFERENCES core.dataset_snapshots(id, snapshot_sha256) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_plans_policy_fk FOREIGN KEY (
    policy_id, policy_version, policy_digest
  ) REFERENCES ops.hypothesis_recursion_policies(
    policy_id, version, policy_digest
  ) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_plans_retention_ck CHECK (
    retention_record_class IS NULL
    OR retention_record_class = 'AGENT_RUNTIME_INITIATION_RECEIPT'
  ),
  CONSTRAINT hypothesis_recursion_plans_retention_fk FOREIGN KEY (
    retention_schedule_id, retention_record_class, retention_schedule_digest
  ) REFERENCES ops.record_class_schedules(
    id, record_class, schedule_digest
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_plans_shape_ck CHECK (
    root_hypothesis_execution_generation > 0
    AND max_depth BETWEEN 1 AND 16
    AND case_budget_micros_krw > 0
    AND actor_type = 'SERVICE'
    AND actor_id = 'workflow-worker'
  ),
  CONSTRAINT hypothesis_recursion_plans_digest_ck CHECK (
    root_hypothesis_execution_digest ~ '^[0-9a-f]{64}$'
    AND snapshot_sha256 ~ '^[0-9a-f]{64}$'
    AND policy_digest ~ '^[0-9a-f]{64}$'
    AND plan_digest ~ '^[0-9a-f]{64}$'
    AND plan_digest = encode(
      extensions.digest(plan_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE ops.hypothesis_recursion_plans OWNER TO gurine_migrator;
REVOKE ALL ON ops.hypothesis_recursion_plans FROM PUBLIC;
GRANT SELECT ON ops.hypothesis_recursion_plans
  TO gurine_workflow_worker, gurine_analysis_worker,
     gurine_control_api, gurine_auditor;
CREATE TRIGGER hypothesis_recursion_plans_immutable_guard
  BEFORE UPDATE OR DELETE ON ops.hypothesis_recursion_plans
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE ops.hypothesis_recursion_nodes (
  node_id uuid NOT NULL DEFAULT gen_random_uuid(),
  plan_id uuid NOT NULL,
  parent_node_id uuid,
  parent_depth integer,
  case_id uuid NOT NULL,
  depth integer NOT NULL,
  stage text NOT NULL,
  hypothesis_execution_digest char(64) NOT NULL,
  dataset_snapshot_id uuid NOT NULL,
  snapshot_sha256 char(64) NOT NULL,
  agent_run_id uuid NOT NULL,
  job_id uuid NOT NULL,
  reserved_micros_krw bigint NOT NULL,
  dedupe_key_sha256 char(64) NOT NULL,
  retention_schedule_id uuid,
  retention_record_class text,
  retention_schedule_digest char(64),
  node_canonical bytea NOT NULL,
  node_digest char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT hypothesis_recursion_nodes_pk PRIMARY KEY (node_id),
  CONSTRAINT hypothesis_recursion_nodes_dedupe_uq
    UNIQUE (dedupe_key_sha256),
  CONSTRAINT hypothesis_recursion_nodes_run_uq UNIQUE (agent_run_id),
  CONSTRAINT hypothesis_recursion_nodes_job_uq UNIQUE (job_id),
  CONSTRAINT hypothesis_recursion_nodes_parent_binding_uq UNIQUE (
    node_id, plan_id, case_id, dataset_snapshot_id, snapshot_sha256, depth
  ),
  CONSTRAINT hypothesis_recursion_nodes_plan_fk
    FOREIGN KEY (
      plan_id, case_id, dataset_snapshot_id, snapshot_sha256
    ) REFERENCES ops.hypothesis_recursion_plans(
      plan_id, case_id, dataset_snapshot_id, snapshot_sha256
    ) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_nodes_case_fk
    FOREIGN KEY (case_id) REFERENCES editorial.cases(id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_nodes_snapshot_fk FOREIGN KEY (
    dataset_snapshot_id, snapshot_sha256
  ) REFERENCES core.dataset_snapshots(id, snapshot_sha256) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_nodes_run_fk
    FOREIGN KEY (agent_run_id) REFERENCES ops.agent_runs(id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_nodes_job_fk
    FOREIGN KEY (job_id) REFERENCES ops.jobs(id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_nodes_retention_ck CHECK (
    retention_record_class IS NULL
    OR retention_record_class = 'AGENT_RUNTIME_INITIATION_RECEIPT'
  ),
  CONSTRAINT hypothesis_recursion_nodes_retention_fk FOREIGN KEY (
    retention_schedule_id, retention_record_class, retention_schedule_digest
  ) REFERENCES ops.record_class_schedules(
    id, record_class, schedule_digest
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_nodes_stage_ck CHECK (
    stage IN ('MARKET_RESEARCHER', 'SKEPTIC')
  ),
  CONSTRAINT hypothesis_recursion_nodes_shape_ck CHECK (
    depth BETWEEN 1 AND 16
    AND (
      (
        depth = 1
        AND parent_node_id IS NULL
        AND parent_depth IS NULL
      )
      OR (
        depth > 1
        AND parent_node_id IS NOT NULL
        AND parent_depth = depth - 1
      )
    )
    AND reserved_micros_krw > 0
    AND hypothesis_execution_digest ~ '^[0-9a-f]{64}$'
    AND snapshot_sha256 ~ '^[0-9a-f]{64}$'
    AND dedupe_key_sha256 ~ '^[0-9a-f]{64}$'
    AND node_digest ~ '^[0-9a-f]{64}$'
    AND node_digest = encode(
      extensions.digest(node_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE ops.hypothesis_recursion_nodes OWNER TO gurine_migrator;
ALTER TABLE ops.hypothesis_recursion_nodes
  ADD CONSTRAINT hypothesis_recursion_nodes_parent_fk FOREIGN KEY (
    parent_node_id, plan_id, case_id, dataset_snapshot_id,
    snapshot_sha256, parent_depth
  ) REFERENCES ops.hypothesis_recursion_nodes(
    node_id, plan_id, case_id, dataset_snapshot_id,
    snapshot_sha256, depth
  ) ON DELETE RESTRICT;
REVOKE ALL ON ops.hypothesis_recursion_nodes FROM PUBLIC;
GRANT SELECT ON ops.hypothesis_recursion_nodes
  TO gurine_workflow_worker, gurine_analysis_worker,
     gurine_control_api, gurine_auditor;
CREATE TRIGGER hypothesis_recursion_nodes_immutable_guard
  BEFORE UPDATE OR DELETE ON ops.hypothesis_recursion_nodes
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE ops.hypothesis_recursion_transitions (
  transition_id uuid NOT NULL DEFAULT gen_random_uuid(),
  plan_id uuid NOT NULL,
  node_id uuid,
  transition_sequence bigint NOT NULL,
  transition_scope text NOT NULL,
  stage text,
  prior_state text,
  next_state text NOT NULL,
  proof_kind text NOT NULL,
  proof_sha256 char(64) NOT NULL,
  actor_type text NOT NULL DEFAULT 'SERVICE',
  actor_id text NOT NULL DEFAULT 'workflow-worker',
  prior_transition_sequence bigint,
  prior_receipt_sha256 char(64),
  retention_schedule_id uuid,
  retention_record_class text,
  retention_schedule_digest char(64),
  transition_payload jsonb NOT NULL,
  transition_canonical bytea NOT NULL,
  receipt_sha256 char(64) NOT NULL,
  occurred_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT hypothesis_recursion_transitions_pk PRIMARY KEY (transition_id),
  CONSTRAINT hypothesis_recursion_transitions_sequence_uq
    UNIQUE (plan_id, transition_sequence),
  CONSTRAINT hypothesis_recursion_transitions_chain_uq
    UNIQUE (plan_id, transition_sequence, receipt_sha256),
  CONSTRAINT hypothesis_recursion_transitions_receipt_uq
    UNIQUE (receipt_sha256),
  CONSTRAINT hypothesis_recursion_transitions_plan_fk
    FOREIGN KEY (plan_id)
    REFERENCES ops.hypothesis_recursion_plans(plan_id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_transitions_node_fk
    FOREIGN KEY (node_id)
    REFERENCES ops.hypothesis_recursion_nodes(node_id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_transitions_retention_ck CHECK (
    retention_record_class IS NULL
    OR retention_record_class = 'AGENT_RUNTIME_INITIATION_RECEIPT'
  ),
  CONSTRAINT hypothesis_recursion_transitions_retention_fk FOREIGN KEY (
    retention_schedule_id, retention_record_class, retention_schedule_digest
  ) REFERENCES ops.record_class_schedules(
    id, record_class, schedule_digest
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_transitions_scope_ck CHECK (
    (
      transition_scope = 'PLAN' AND node_id IS NULL AND stage IS NULL
      AND next_state IN ('ACTIVE', 'REVIEWED_TERMINAL', 'BUDGET_EXHAUSTED')
    )
    OR (
      transition_scope = 'NODE' AND node_id IS NOT NULL
      AND stage IN ('MARKET_RESEARCHER', 'SKEPTIC')
      AND next_state IN ('QUEUED', 'SUCCEEDED', 'FAILED', 'BUDGET_BLOCKED')
    )
  ),
  CONSTRAINT hypothesis_recursion_transitions_chain_ck CHECK (
    transition_sequence > 0
    AND (
      (
        transition_sequence = 1
        AND prior_transition_sequence IS NULL
        AND prior_receipt_sha256 IS NULL
      )
      OR (
        transition_sequence > 1
        AND prior_transition_sequence = transition_sequence - 1
        AND prior_receipt_sha256 ~ '^[0-9a-f]{64}$'
      )
    )
    AND actor_type = 'SERVICE'
    AND actor_id = 'workflow-worker'
  ),
  CONSTRAINT hypothesis_recursion_transitions_digest_ck CHECK (
    proof_sha256 ~ '^[0-9a-f]{64}$'
    AND receipt_sha256 ~ '^[0-9a-f]{64}$'
    AND convert_from(transition_canonical, 'UTF8')::jsonb
      = transition_payload
    AND receipt_sha256 = encode(
      extensions.digest(transition_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE ops.hypothesis_recursion_transitions OWNER TO gurine_migrator;
ALTER TABLE ops.hypothesis_recursion_transitions
  ADD CONSTRAINT hypothesis_recursion_transitions_prior_fk FOREIGN KEY (
    plan_id, prior_transition_sequence, prior_receipt_sha256
  ) REFERENCES ops.hypothesis_recursion_transitions(
    plan_id, transition_sequence, receipt_sha256
  ) ON DELETE RESTRICT;
REVOKE ALL ON ops.hypothesis_recursion_transitions FROM PUBLIC;
GRANT SELECT ON ops.hypothesis_recursion_transitions
  TO gurine_workflow_worker, gurine_analysis_worker,
     gurine_control_api, gurine_auditor;
CREATE TRIGGER hypothesis_recursion_transitions_immutable_guard
  BEFORE UPDATE OR DELETE ON ops.hypothesis_recursion_transitions
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE ops.hypothesis_recursion_receipts (
  receipt_id uuid NOT NULL DEFAULT gen_random_uuid(),
  trigger_kind text NOT NULL,
  trigger_id uuid NOT NULL,
  trigger_generation bigint NOT NULL,
  trigger_digest char(64) NOT NULL,
  trigger_receipt_sha256 char(64) NOT NULL,
  producer_job_id uuid NOT NULL,
  policy_id uuid,
  policy_version bigint,
  disposition text NOT NULL,
  plan_id uuid,
  node_id uuid,
  agent_run_id uuid,
  job_id uuid,
  actor_type text NOT NULL DEFAULT 'SERVICE',
  actor_id text NOT NULL DEFAULT 'workflow-worker',
  retention_schedule_id uuid,
  retention_record_class text,
  retention_schedule_digest char(64),
  receipt_payload jsonb NOT NULL,
  receipt_canonical bytea NOT NULL,
  receipt_digest char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT hypothesis_recursion_receipts_pk PRIMARY KEY (receipt_id),
  CONSTRAINT hypothesis_recursion_receipts_trigger_uq
    UNIQUE (trigger_kind, trigger_id, trigger_generation),
  CONSTRAINT hypothesis_recursion_receipts_digest_uq UNIQUE (receipt_digest),
  CONSTRAINT hypothesis_recursion_receipts_producer_job_fk
    FOREIGN KEY (producer_job_id) REFERENCES ops.jobs(id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_receipts_policy_fk FOREIGN KEY (
    policy_id, policy_version
  ) REFERENCES ops.hypothesis_recursion_policies(
    policy_id, version
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_receipts_plan_fk
    FOREIGN KEY (plan_id)
    REFERENCES ops.hypothesis_recursion_plans(plan_id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_receipts_node_fk
    FOREIGN KEY (node_id)
    REFERENCES ops.hypothesis_recursion_nodes(node_id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_receipts_run_fk
    FOREIGN KEY (agent_run_id) REFERENCES ops.agent_runs(id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_receipts_job_fk
    FOREIGN KEY (job_id) REFERENCES ops.jobs(id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_receipts_retention_ck CHECK (
    retention_record_class IS NULL
    OR retention_record_class = 'AGENT_RUNTIME_INITIATION_RECEIPT'
  ),
  CONSTRAINT hypothesis_recursion_receipts_retention_fk FOREIGN KEY (
    retention_schedule_id, retention_record_class, retention_schedule_digest
  ) REFERENCES ops.record_class_schedules(
    id, record_class, schedule_digest
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_receipts_trigger_kind_ck CHECK (
    trigger_kind IN ('ACTION_EXECUTION', 'AGENT_RUN')
    AND trigger_generation > 0
  ),
  CONSTRAINT hypothesis_recursion_receipts_disposition_ck CHECK (
    disposition IN (
      'STARTED', 'POLICY_ABSENT', 'POLICY_DISABLED',
      'MAX_DEPTH_REACHED', 'CASE_BUDGET_BLOCKED',
      'NOT_HYPOTHESIS', 'NOT_SUCCEEDED', 'NODE_NOT_RECURSIVE',
      'STAGE_NOT_MARKET_RESEARCHER', 'RUN_NOT_SUCCEEDED',
      'PLAN_TERMINAL'
    )
  ),
  CONSTRAINT hypothesis_recursion_receipts_created_shape_ck CHECK (
    (
      disposition = 'STARTED'
      AND num_nonnulls(plan_id, node_id, agent_run_id, job_id) = 4
      AND policy_id IS NOT NULL
    )
    OR (
      disposition <> 'STARTED'
      AND num_nonnulls(plan_id, node_id, agent_run_id, job_id) = 0
    )
  ),
  CONSTRAINT hypothesis_recursion_receipts_actor_ck CHECK (
    actor_type = 'SERVICE' AND actor_id = 'workflow-worker'
  ),
  CONSTRAINT hypothesis_recursion_receipts_digest_ck CHECK (
    trigger_digest ~ '^[0-9a-f]{64}$'
    AND trigger_receipt_sha256 ~ '^[0-9a-f]{64}$'
    AND receipt_digest ~ '^[0-9a-f]{64}$'
    AND convert_from(receipt_canonical, 'UTF8')::jsonb = receipt_payload
    AND receipt_digest = encode(
      extensions.digest(receipt_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE ops.hypothesis_recursion_receipts OWNER TO gurine_migrator;
REVOKE ALL ON ops.hypothesis_recursion_receipts FROM PUBLIC;
GRANT SELECT ON ops.hypothesis_recursion_receipts
  TO gurine_workflow_worker, gurine_analysis_worker,
     gurine_control_api, gurine_auditor;
CREATE TRIGGER hypothesis_recursion_receipts_immutable_guard
  BEFORE UPDATE OR DELETE ON ops.hypothesis_recursion_receipts
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE TABLE ops.hypothesis_recursion_budget_ledger (
  ledger_id uuid NOT NULL DEFAULT gen_random_uuid(),
  plan_id uuid NOT NULL,
  node_id uuid NOT NULL,
  ledger_sequence bigint NOT NULL,
  stage text NOT NULL,
  entry_kind text NOT NULL,
  amount_micros_krw bigint NOT NULL,
  prior_reserved_micros_krw bigint NOT NULL,
  next_reserved_micros_krw bigint NOT NULL,
  prior_settled_micros_krw bigint NOT NULL,
  next_settled_micros_krw bigint NOT NULL,
  actor_type text NOT NULL DEFAULT 'SERVICE',
  actor_id text NOT NULL DEFAULT 'workflow-worker',
  prior_ledger_sequence bigint,
  prior_receipt_sha256 char(64),
  retention_schedule_id uuid,
  retention_record_class text,
  retention_schedule_digest char(64),
  ledger_payload jsonb NOT NULL,
  ledger_canonical bytea NOT NULL,
  receipt_sha256 char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT hypothesis_recursion_budget_ledger_pk PRIMARY KEY (ledger_id),
  CONSTRAINT hypothesis_recursion_budget_ledger_sequence_uq
    UNIQUE (plan_id, ledger_sequence),
  CONSTRAINT hypothesis_recursion_budget_ledger_chain_uq
    UNIQUE (plan_id, ledger_sequence, receipt_sha256),
  CONSTRAINT hypothesis_recursion_budget_ledger_receipt_uq
    UNIQUE (receipt_sha256),
  CONSTRAINT hypothesis_recursion_budget_ledger_plan_fk
    FOREIGN KEY (plan_id)
    REFERENCES ops.hypothesis_recursion_plans(plan_id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_budget_ledger_node_fk
    FOREIGN KEY (node_id)
    REFERENCES ops.hypothesis_recursion_nodes(node_id) ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_budget_ledger_retention_ck CHECK (
    retention_record_class IS NULL
    OR retention_record_class = 'AGENT_RUNTIME_INITIATION_RECEIPT'
  ),
  CONSTRAINT hypothesis_recursion_budget_ledger_retention_fk FOREIGN KEY (
    retention_schedule_id, retention_record_class, retention_schedule_digest
  ) REFERENCES ops.record_class_schedules(
    id, record_class, schedule_digest
  ) MATCH FULL ON DELETE RESTRICT,
  CONSTRAINT hypothesis_recursion_budget_ledger_shape_ck CHECK (
    ledger_sequence > 0
    AND stage IN ('MARKET_RESEARCHER', 'SKEPTIC')
    AND entry_kind IN ('RESERVE', 'SETTLE', 'RELEASE')
    AND amount_micros_krw >= 0
    AND prior_reserved_micros_krw >= 0
    AND next_reserved_micros_krw >= 0
    AND prior_settled_micros_krw >= 0
    AND next_settled_micros_krw >= 0
    AND next_settled_micros_krw <= next_reserved_micros_krw
    AND actor_type = 'SERVICE'
    AND actor_id = 'workflow-worker'
    AND (
      (
        ledger_sequence = 1
        AND prior_ledger_sequence IS NULL
        AND prior_receipt_sha256 IS NULL
      )
      OR (
        ledger_sequence > 1
        AND prior_ledger_sequence = ledger_sequence - 1
        AND prior_receipt_sha256 ~ '^[0-9a-f]{64}$'
      )
    )
  ),
  CONSTRAINT hypothesis_recursion_budget_ledger_entry_ck CHECK (
    (
      entry_kind = 'RESERVE'
      AND next_reserved_micros_krw
        = prior_reserved_micros_krw + amount_micros_krw
      AND next_settled_micros_krw = prior_settled_micros_krw
    )
    OR (
      entry_kind = 'SETTLE'
      AND next_reserved_micros_krw = prior_reserved_micros_krw
      AND next_settled_micros_krw
        = prior_settled_micros_krw + amount_micros_krw
    )
    OR (
      entry_kind = 'RELEASE'
      AND next_reserved_micros_krw
        = prior_reserved_micros_krw - amount_micros_krw
      AND next_settled_micros_krw = prior_settled_micros_krw
    )
  ),
  CONSTRAINT hypothesis_recursion_budget_ledger_digest_ck CHECK (
    receipt_sha256 ~ '^[0-9a-f]{64}$'
    AND convert_from(ledger_canonical, 'UTF8')::jsonb = ledger_payload
    AND receipt_sha256 = encode(
      extensions.digest(ledger_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE ops.hypothesis_recursion_budget_ledger OWNER TO gurine_migrator;
ALTER TABLE ops.hypothesis_recursion_budget_ledger
  ADD CONSTRAINT hypothesis_recursion_budget_ledger_prior_fk FOREIGN KEY (
    plan_id, prior_ledger_sequence, prior_receipt_sha256
  ) REFERENCES ops.hypothesis_recursion_budget_ledger(
    plan_id, ledger_sequence, receipt_sha256
  ) ON DELETE RESTRICT;
REVOKE ALL ON ops.hypothesis_recursion_budget_ledger FROM PUBLIC;
GRANT SELECT ON ops.hypothesis_recursion_budget_ledger
  TO gurine_workflow_worker, gurine_analysis_worker,
     gurine_control_api, gurine_auditor;
CREATE TRIGGER hypothesis_recursion_budget_ledger_immutable_guard
  BEFORE UPDATE OR DELETE ON ops.hypothesis_recursion_budget_ledger
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

CREATE OR REPLACE FUNCTION ops.bind_r6c_audit_retention_schedule_v1()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, pg_temp
AS $$
DECLARE
  v_class text;
  v_count bigint;
  v_schedule ops.record_class_schedules%ROWTYPE;
BEGIN
  v_class := CASE TG_TABLE_NAME
    WHEN 'hypothesis_recursion_policies' THEN 'AGENT_RUNTIME_POLICY'
    WHEN 'hypothesis_recursion_plans'
      THEN 'AGENT_RUNTIME_INITIATION_RECEIPT'
    WHEN 'hypothesis_recursion_nodes'
      THEN 'AGENT_RUNTIME_INITIATION_RECEIPT'
    WHEN 'hypothesis_recursion_transitions'
      THEN 'AGENT_RUNTIME_INITIATION_RECEIPT'
    WHEN 'hypothesis_recursion_receipts'
      THEN 'AGENT_RUNTIME_INITIATION_RECEIPT'
    WHEN 'hypothesis_recursion_budget_ledger'
      THEN 'AGENT_RUNTIME_INITIATION_RECEIPT'
    ELSE NULL
  END;
  IF v_class IS NULL THEN
    RAISE EXCEPTION 'r6c_retention_relation_invalid'
      USING ERRCODE = '55000';
  END IF;
  IF num_nonnulls(
    NEW.retention_schedule_id, NEW.retention_record_class,
    NEW.retention_schedule_digest
  ) <> 0 THEN
    RAISE EXCEPTION 'r6c_retention_override_forbidden'
      USING ERRCODE = '23514';
  END IF;
  LOCK TABLE ops.record_class_schedules IN SHARE MODE;
  SELECT count(*) INTO v_count
  FROM ops.record_class_schedules AS schedule
  WHERE schedule.record_class = v_class
    AND schedule.effective_at <= NEW.created_at
    AND schedule.review_expires_at > NEW.created_at
    AND schedule.active_duration_seconds IS NOT NULL
    AND schedule.backup_duration_seconds IS NOT NULL
    AND schedule.terminal_action IN ('DELETE', 'ANONYMIZE', 'CRYPTO_ERASE');
  IF v_count = 0 THEN
    RAISE EXCEPTION 'r6c_retention_schedule_missing'
      USING ERRCODE = '55000';
  ELSIF v_count <> 1 THEN
    RAISE EXCEPTION 'r6c_retention_schedule_ambiguous'
      USING ERRCODE = '55000';
  END IF;
  SELECT schedule.* INTO STRICT v_schedule
  FROM ops.record_class_schedules AS schedule
  WHERE schedule.record_class = v_class
    AND schedule.effective_at <= NEW.created_at
    AND schedule.review_expires_at > NEW.created_at
    AND schedule.active_duration_seconds IS NOT NULL
    AND schedule.backup_duration_seconds IS NOT NULL
    AND schedule.terminal_action IN ('DELETE', 'ANONYMIZE', 'CRYPTO_ERASE')
  ORDER BY schedule.revision DESC, schedule.effective_at DESC, schedule.id
  LIMIT 1
  FOR SHARE;
  NEW.retention_schedule_id := v_schedule.id;
  NEW.retention_record_class := v_schedule.record_class;
  NEW.retention_schedule_digest := v_schedule.schedule_digest;
  RETURN NEW;
END
$$;
ALTER FUNCTION ops.bind_r6c_audit_retention_schedule_v1()
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.bind_r6c_audit_retention_schedule_v1()
  FROM PUBLIC;

CREATE TRIGGER hypothesis_recursion_policies_retention_guard
  BEFORE INSERT ON ops.hypothesis_recursion_policies
  FOR EACH ROW EXECUTE FUNCTION ops.bind_r6c_audit_retention_schedule_v1();
CREATE TRIGGER hypothesis_recursion_plans_retention_guard
  BEFORE INSERT ON ops.hypothesis_recursion_plans
  FOR EACH ROW EXECUTE FUNCTION ops.bind_r6c_audit_retention_schedule_v1();
CREATE TRIGGER hypothesis_recursion_nodes_retention_guard
