CREATE TRIGGER hypothesis_recursion_transitions_retention_guard
  BEFORE INSERT ON ops.hypothesis_recursion_transitions
  FOR EACH ROW EXECUTE FUNCTION ops.bind_r6c_audit_retention_schedule_v1();
CREATE TRIGGER hypothesis_recursion_receipts_retention_guard
  BEFORE INSERT ON ops.hypothesis_recursion_receipts
  FOR EACH ROW EXECUTE FUNCTION ops.bind_r6c_audit_retention_schedule_v1();
CREATE TRIGGER hypothesis_recursion_budget_ledger_retention_guard
  BEFORE INSERT ON ops.hypothesis_recursion_budget_ledger
  FOR EACH ROW EXECUTE FUNCTION ops.bind_r6c_audit_retention_schedule_v1();

ALTER TABLE ops.hypothesis_recursion_policies
  ALTER COLUMN retention_schedule_id SET NOT NULL,
