CREATE OR REPLACE FUNCTION ops.enforce_fetch_url_restricted_v1()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, raw, ops, pg_temp
AS $function$
BEGIN
  IF NEW.request_kind = 'FETCH_URL' THEN
    NEW.classification := 'RESTRICTED';
  END IF;
  RETURN NEW;
END
$function$;
ALTER FUNCTION ops.enforce_fetch_url_restricted_v1()
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.enforce_fetch_url_restricted_v1() FROM PUBLIC;

