-- Forward replacement for the 0030 owner routine. FETCH_URL material stays
-- private research input until a separate human promotion; search results
-- remain discovery-only metadata.
CREATE OR REPLACE FUNCTION ops.record_research_fetch_v1(
  p_agent_run_id uuid,
  p_provider_turn_id uuid,
  p_tool_call_id uuid,
  p_call_id text,
  p_input_snapshot_sha256 char(64),
  p_request_kind text,
  p_source_id text,
  p_external_locator text,
  p_source_url_redacted text,
  p_final_url_redacted text,
  p_http_status integer,
  p_content_media_type text,
  p_request_sha256 char(64),
  p_content bytea,
  p_object_key text,
  p_policy_version text,
  p_result_sha256 char(64),
  p_fetch_id uuid,
  p_asset_id uuid,
  p_artifact_id uuid,
  p_source_use_id uuid,
  p_source_use_sha256 char(64),
  p_receipt_digest char(64),
  p_safe_headers jsonb DEFAULT '[]'::jsonb,
  p_redirect_chain jsonb DEFAULT '[]'::jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, raw, ops, extensions, pg_temp
AS $function$
DECLARE
  v_fetch_id uuid := coalesce(p_fetch_id,gen_random_uuid());
  v_asset_id uuid := coalesce(p_asset_id,gen_random_uuid());
  v_artifact_id uuid := coalesce(p_artifact_id,gen_random_uuid());
  v_rights_id uuid;
  v_capability_id uuid;
  v_source_use_id uuid := coalesce(p_source_use_id,gen_random_uuid());
  v_now timestamptz;
  v_content_sha char(64) := encode(extensions.digest(coalesce(p_content,''::bytea),'sha256'),'hex');
  v_safety_state text := CASE WHEN position(decode('00504f49534f4e' ,'hex') in coalesce(p_content,''::bytea)) > 0 THEN 'QUARANTINED' ELSE 'CLEAN' END;
  v_headers jsonb := coalesce(p_safe_headers,'[]'::jsonb);
  v_redirects jsonb := coalesce(p_redirect_chain,'[]'::jsonb);
  v_artifact_canonical bytea;
  v_artifact_sha char(64);
  v_artifact_created_at timestamptz;
  v_asset_rights_canonical bytea;
  v_asset_rights_sha char(64);
  v_locator text := coalesce(nullif(p_final_url_redacted,''),nullif(p_source_url_redacted,''),p_external_locator);
  v_locator_sha char(64);
  v_source_registry_sha char(64);
  v_policy_sha char(64);
  v_rights_sha char(64);
  v_source_use_canonical bytea;
  v_source_use_sha char(64) := p_source_use_sha256;
  v_fetch_receipt char(64) := coalesce(p_receipt_digest,encode(extensions.digest(convert_to(p_source_id||':'||p_external_locator||':'||v_content_sha,'UTF8'),'sha256'),'hex'));
  v_existing_artifact uuid;
  v_existing_artifact_sha char(64);
  v_existing_source_use uuid;
  v_reviewer_user_id uuid;
  v_tool_request_sha char(64);
  v_tool_result_sha char(64);
  v_capability_version bigint;
  v_capability_effective timestamptz;
  v_capability_expires timestamptz;
  v_access_right text;
  v_private_storage_right text;
  v_model_egress_right text;
  v_model_use_right text;
  v_derivative_creation_right text;
  v_excerpt_right text;
  v_redistribution_right text;
  v_commercial_use_right text;
  v_public_display_right text;
  v_rights_snapshot jsonb;
  v_capability_decisions jsonb;
  v_capability_decision_set_sha char(64);
  v_execution_receipt_set_sha char(64);
  v_license_evidence_digests text[] := '{}'::text[];
  v_review_tier_payload jsonb;
  v_review_tier_canonical bytea;
  v_review_tier_receipt_sha char(64);
BEGIN
  IF p_agent_run_id IS NULL OR p_provider_turn_id IS NULL OR p_tool_call_id IS NULL
     OR p_call_id IS NULL OR btrim(p_call_id)='' OR p_input_snapshot_sha256 !~ '^[0-9a-f]{64}$'
     OR p_request_kind NOT IN ('SEARCH_PUBLIC_WEB','FETCH_URL')
     OR p_source_id IS NULL OR p_external_locator IS NULL OR p_http_status NOT BETWEEN 100 AND 599
     OR p_request_sha256 !~ '^[0-9a-f]{64}$' OR p_result_sha256 !~ '^[0-9a-f]{64}$'
     OR p_content IS NULL OR p_object_key IS NULL OR p_fetch_id IS NULL OR p_asset_id IS NULL
     OR p_artifact_id IS NULL OR p_source_use_id IS NULL OR p_source_use_sha256 !~ '^[0-9a-f]{64}$'
     OR p_receipt_digest !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'RESEARCH_FETCH_INVALID' USING ERRCODE='22023'; END IF;
  IF p_request_kind='FETCH_URL' AND (p_source_url_redacted IS NULL OR p_final_url_redacted IS NULL
     OR p_source_url_redacted !~ '^https://.*' OR p_final_url_redacted !~ '^https://.*')
  THEN RAISE EXCEPTION 'RESEARCH_FETCH_URL_INVALID' USING ERRCODE='22023'; END IF;
  v_now := clock_timestamp();
  PERFORM pg_advisory_xact_lock(hashtextextended(p_source_id, 13));
  -- The rights decision and record path share the exact hold locks.
  PERFORM h.id
    FROM editorial.legal_holds h
   WHERE h.active AND (h.expires_at IS NULL OR h.expires_at > v_now)
     AND (h.affected_ids @> jsonb_build_array(p_source_id)
          OR h.object_id::text = p_source_id OR h.case_id::text = p_source_id)
   FOR UPDATE;
  PERFORM a.id
    FROM ops.legal_hold_target_anchors a
    JOIN editorial.legal_holds h ON a.target_id IN (h.object_id,h.case_id)
   WHERE h.active AND (h.expires_at IS NULL OR h.expires_at > v_now)
     AND (h.affected_ids @> jsonb_build_array(p_source_id)
          OR h.object_id::text = p_source_id OR h.case_id::text = p_source_id)
   FOR UPDATE;
  IF p_receipt_digest <> encode(extensions.digest(convert_to('content-safety-v2:'||v_content_sha||':'||v_safety_state,'UTF8'),'sha256'),'hex')
  THEN RAISE EXCEPTION 'CONTENT_SAFETY_RECEIPT_MISMATCH' USING ERRCODE='22023'; END IF;
  PERFORM 1 FROM ops.agent_runs WHERE id=p_agent_run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'AGENT_RUN_NOT_FOUND' USING ERRCODE='22023'; END IF;
  SELECT created_by INTO v_reviewer_user_id FROM ops.agent_runs WHERE id=p_agent_run_id;
  IF v_reviewer_user_id IS NULL THEN
    RAISE EXCEPTION 'AGENT_RUN_REVIEWER_MISSING' USING ERRCODE='22023';
  END IF;
  PERFORM 1 FROM ops.agent_provider_turns WHERE provider_turn_id=p_provider_turn_id AND agent_run_id=p_agent_run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'PROVIDER_TURN_NOT_FOUND' USING ERRCODE='22023'; END IF;
  SELECT request_sha256, result_sha256
    INTO v_tool_request_sha, v_tool_result_sha
    FROM ops.agent_tool_calls
   WHERE tool_call_id=p_tool_call_id AND agent_run_id=p_agent_run_id
     AND provider_turn_id=p_provider_turn_id AND call_id=p_call_id
     AND status='SUCCEEDED';
  IF v_tool_result_sha IS NULL THEN RAISE EXCEPTION 'TOOL_CALL_NOT_COMPLETED' USING ERRCODE='22023'; END IF;
  IF v_tool_request_sha IS DISTINCT FROM p_request_sha256 THEN
    RAISE EXCEPTION 'TOOL_REQUEST_DIGEST_MISMATCH' USING ERRCODE='22023';
  END IF;
  IF v_tool_result_sha <> p_result_sha256 THEN
    RAISE EXCEPTION 'TOOL_RESULT_DIGEST_MISMATCH' USING ERRCODE='22023';
  END IF;
  v_rights_snapshot := ops.research_rights_snapshot_v1(p_source_id,v_now);
  IF v_rights_snapshot IS NULL
     OR v_rights_snapshot->'dimensions'->>'accessRight'<>'ALLOW'
     OR v_rights_snapshot->'dimensions'->>'modelEgressRight'<>'ALLOW'
     OR (p_request_kind='FETCH_URL' AND (
       v_rights_snapshot->'dimensions'->>'privateStorageRight'<>'ALLOW'
       OR v_rights_snapshot->'dimensions'->>'modelUseRight'<>'ALLOW'))
     OR EXISTS (SELECT 1 FROM editorial.legal_holds h WHERE h.active AND (h.expires_at IS NULL OR h.expires_at > v_now)
       AND (h.affected_ids @> jsonb_build_array(p_source_id) OR h.object_id::text = p_source_id OR h.case_id::text = p_source_id))
  THEN
    RAISE EXCEPTION 'SOURCE_RIGHTS_UNAVAILABLE' USING ERRCODE='42501';
  END IF;
  v_capability_id := (v_rights_snapshot->'primaryDecision'->>'decisionId')::uuid;
  v_capability_version := (v_rights_snapshot->'primaryDecision'->>'decisionVersion')::bigint;
  v_capability_effective := (v_rights_snapshot->>'effectiveAt')::timestamptz;
  v_capability_expires := NULLIF(v_rights_snapshot->>'expiresAt','')::timestamptz;
  v_capability_decisions := v_rights_snapshot->'capabilityDecisions';
  v_capability_decision_set_sha := (v_rights_snapshot->>'capabilityDecisionSetSha256')::char(64);
  v_execution_receipt_set_sha := (v_rights_snapshot->>'executionReceiptSetSha256')::char(64);
  SELECT COALESCE(array_agg(value ORDER BY value),'{}'::text[])
    INTO v_license_evidence_digests
    FROM jsonb_array_elements_text(v_rights_snapshot->'licenseEvidenceDigests');
  v_access_right := v_rights_snapshot->'dimensions'->>'accessRight';
  v_private_storage_right := v_rights_snapshot->'dimensions'->>'privateStorageRight';
  v_model_egress_right := v_rights_snapshot->'dimensions'->>'modelEgressRight';
  v_model_use_right := v_rights_snapshot->'dimensions'->>'modelUseRight';
  v_derivative_creation_right := v_rights_snapshot->'dimensions'->>'derivativeCreationRight';
  v_excerpt_right := v_rights_snapshot->'dimensions'->>'excerptRight';
  v_redistribution_right := v_rights_snapshot->'dimensions'->>'redistributionRight';
  v_commercial_use_right := v_rights_snapshot->'dimensions'->>'commercialUseRight';
  v_public_display_right := v_rights_snapshot->'dimensions'->>'publicDisplayRight';
  v_rights_id := v_asset_id;
  v_rights_sha := (v_rights_snapshot->'primaryDecision'->>'decisionSha256')::char(64);
  v_locator_sha := encode(extensions.digest(convert_to(v_locator,'UTF8'),'sha256'),'hex');
  v_source_registry_sha := encode(extensions.digest(convert_to(p_source_id,'UTF8'),'sha256'),'hex');
  v_policy_sha := encode(extensions.digest(convert_to(p_policy_version,'UTF8'),'sha256'),'hex');

  v_artifact_canonical := ops.canonical_jsonb_v1(jsonb_build_object(
    'schemaVersion','research-artifact.v2','researchArtifactId',v_artifact_id,
    'assetId',v_asset_id,'assetRevision',1,'sourceFetchId',v_fetch_id,
    'artifactOrdinal',0,'fetchOutcome','STORED','sourceAuthority',p_source_id,
    'finalOrigin',v_locator,'httpStatus',p_http_status,
    'contentMediaType',coalesce(p_content_media_type,'application/octet-stream'),
    'contentSizeBytes',octet_length(p_content),'contentSha256',v_content_sha,
    'responseHeadersSha256',encode(extensions.digest(ops.canonical_jsonb_v1(v_headers),'sha256'),'hex'),
    'contentSafetyState',v_safety_state,'contentSafetyReceiptSha256',v_fetch_receipt));
  v_artifact_sha := encode(extensions.digest(v_artifact_canonical,'sha256'),'hex');
  v_asset_rights_canonical := ops.canonical_jsonb_v1(jsonb_build_object(
    'schemaVersion','asset-rights-decision.v1','decisionId',v_rights_id,
    'assetId',v_asset_id,'assetSha256',v_content_sha,'assetRevision',1,
    'decisionVersion',1,'assetKind','RESEARCH_ARTIFACT','researchArtifactId',v_artifact_id,
    'decisionKind','GRANT','accessRight',v_access_right,'privateStorageRight',v_private_storage_right,
    'modelEgressRight',v_model_egress_right,'modelUseRight',v_model_use_right,
    'derivativeCreationRight',v_derivative_creation_right,'excerptRight',v_excerpt_right,
    'redistributionRight',v_redistribution_right,'commercialUseRight',v_commercial_use_right,
    'publicDisplayRight',v_public_display_right,'policyVersion',p_policy_version,
    'policySha256',v_policy_sha,'legalBasisCode','PUBLIC_RESEARCH','legalBasisReference',p_source_id,
    'jurisdiction','GLOBAL','attributionRequired',false,'effectiveAt',coalesce(v_capability_effective,v_now),
    'expiresAt',v_capability_expires,'capabilityDecisionId',v_capability_id,
    'capabilityDecisionVersion',v_capability_version,'capabilityDecisionSha256',v_rights_sha,
    'capabilityDecisions',v_capability_decisions,
    'capabilityDecisionSetSha256',v_capability_decision_set_sha,
    'executionReceiptSetSha256',v_execution_receipt_set_sha));
  v_asset_rights_sha := encode(extensions.digest(v_asset_rights_canonical,'sha256'),'hex');

  -- This preimage matches the current Rust caller. Relative to 0030, the
  -- only classification change is PUBLIC -> RESTRICTED.
  v_source_use_canonical := ops.canonical_jsonb_v1(jsonb_build_object(
    'schemaVersion','source-use.v2','sourceUseId',v_source_use_id,'agentRunId',p_agent_run_id,
    'providerTurnId',p_provider_turn_id,'toolCallId',p_tool_call_id,
    'parentSourceUseId',NULL,'parentSourceUseSha256',NULL,
    'useKind','TOOL_QUERY','sourceKind','RESEARCH_ARTIFACT',
    'sourceIdentity',jsonb_build_object('kind','RESEARCH_ARTIFACT','researchArtifactId',v_artifact_id,
      'assetId',v_asset_id,'assetRevision',1,'artifactSha256',v_artifact_sha,
      'contentSha256',v_content_sha,'sourceFetchId',v_fetch_id),
    'locator',jsonb_build_object('kind','HTML_CSS_SELECTOR','value',v_locator,'locatorSha256',v_locator_sha),
    'selectedContentSha256',v_content_sha,'classification','RESTRICTED',
    'rightsDecision',jsonb_build_object('decisionId',v_rights_id,'decisionVersion',1,
      'decisionSha256',v_asset_rights_sha,'effectiveAt',coalesce(v_capability_effective,v_now),'expiresAt',v_capability_expires,
      'accessRight',v_access_right,'privateStorageRight',v_private_storage_right,'modelEgressRight',v_model_egress_right,
      'modelUseRight',v_model_use_right,'derivativeCreationRight',v_derivative_creation_right,'excerptRight',v_excerpt_right,
      'redistributionRight',v_redistribution_right,'commercialUseRight',v_commercial_use_right,'publicDisplayRight',v_public_display_right),
    'providerReceiptId',NULL,'occurredAt',coalesce(v_capability_effective,v_now)));
  v_source_use_sha := encode(extensions.digest(v_source_use_canonical,'sha256'),'hex');

  INSERT INTO raw.source_fetches(id,source_id,source_run_id,external_locator,requested_at,completed_at,http_status,content_type,payload_sha256,payload_size_bytes,object_key)
  VALUES(v_fetch_id,p_source_id,NULL,p_external_locator,v_now,v_now,p_http_status,p_content_media_type,v_content_sha,octet_length(p_content),p_object_key)
  ON CONFLICT (source_id,external_locator,payload_sha256) DO UPDATE SET completed_at=EXCLUDED.completed_at
  RETURNING id INTO v_fetch_id;
  -- SEARCH_PUBLIC_WEB remains a discovery receipt with no artifact, source
  -- use, or review tier. A collision with materialized lineage fails closed.
  IF p_request_kind='SEARCH_PUBLIC_WEB' THEN
    IF EXISTS (
      SELECT 1 FROM raw.research_artifacts artifact
       WHERE artifact.source_fetch_id=v_fetch_id
    ) THEN
      RAISE EXCEPTION 'RESEARCH_SEARCH_DISCOVERY_LINEAGE_COLLISION'
        USING ERRCODE='55000';
    END IF;
    RETURN jsonb_build_object('schemaVersion','source.fetch.receipt.v2',
      'sourceFetchId',v_fetch_id,'payloadSha256',v_content_sha,
      'receiptDigest',v_fetch_receipt,'policyVersion',p_policy_version,
      'policySha256',v_policy_sha,'recordedAt',v_now,
      'discoveryOnly',true);
  END IF;
  IF p_source_use_sha256 <> v_source_use_sha THEN
    RAISE EXCEPTION 'SOURCE_USE_DIGEST_MISMATCH' USING ERRCODE='22023';
  END IF;

  SELECT id INTO v_existing_artifact
    FROM raw.research_artifacts
   WHERE source_fetch_id=v_fetch_id;
  IF v_existing_artifact IS NOT NULL THEN
    -- Replay must bind the exact immutable caller tuple. Never adopt a row
    -- selected only by creation order or source-fetch identity.
    SELECT artifact.artifact_sha256, artifact.created_at
      INTO v_existing_artifact_sha, v_artifact_created_at
      FROM raw.research_artifacts artifact
     WHERE artifact.id=v_artifact_id
       AND artifact.source_fetch_id=v_fetch_id
       AND artifact.asset_id=v_asset_id
       AND artifact.asset_revision=1
       AND artifact.agent_run_id=p_agent_run_id
       AND artifact.provider_turn_id=p_provider_turn_id
       AND artifact.tool_call_id=p_tool_call_id
       AND artifact.call_id=p_call_id
       AND artifact.artifact_ordinal=0
       AND artifact.input_snapshot_sha256=p_input_snapshot_sha256
       AND artifact.request_kind='FETCH_URL'
       AND artifact.request_sha256=p_request_sha256
       AND artifact.result_sha256=p_result_sha256
       AND artifact.fetch_outcome='STORED'
       AND artifact.source_url_redacted=p_source_url_redacted
       AND artifact.final_url_redacted=p_final_url_redacted
       AND artifact.source_authority=p_source_id
       AND artifact.http_status=p_http_status
       AND artifact.content_media_type=coalesce(p_content_media_type,'application/octet-stream')
       AND artifact.content_size_bytes=octet_length(p_content)
       AND artifact.content_sha256=v_content_sha
       AND artifact.response_headers_sha256=encode(extensions.digest(ops.canonical_jsonb_v1(v_headers),'sha256'),'hex')
       AND artifact.artifact_sha256=v_artifact_sha
       AND artifact.object_key=p_object_key
       AND artifact.object_key_hash=encode(extensions.digest(convert_to(p_object_key,'UTF8'),'sha256'),'hex')
       AND artifact.safe_headers=v_headers
       AND artifact.safe_headers_canonical=ops.canonical_jsonb_v1(v_headers)
       AND artifact.redirect_chain=v_redirects
       AND artifact.redirect_chain_canonical=ops.canonical_jsonb_v1(v_redirects)
       AND artifact.classification='RESTRICTED'
       AND artifact.content_safety_state=v_safety_state
       AND artifact.content_safety_receipt_sha256=v_fetch_receipt
       AND artifact.artifact_canonical=v_artifact_canonical;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'RESEARCH_FETCH_REPLAY_ARTIFACT_MISMATCH'
        USING ERRCODE='55000';
    END IF;
  ELSE
    INSERT INTO raw.research_artifacts(
      id,asset_id,asset_revision,source_fetch_id,agent_run_id,provider_turn_id,tool_call_id,call_id,artifact_ordinal,
      input_snapshot_sha256,request_kind,request_sha256,result_sha256,fetch_outcome,source_url_redacted,final_url_redacted,
      source_authority,retrieved_at,http_status,content_media_type,content_size_bytes,content_sha256,response_headers_sha256,
      artifact_sha256,object_key,object_key_hash,safe_headers,safe_headers_canonical,redirect_chain,redirect_chain_canonical,
      classification,content_safety_state,content_safety_receipt_sha256,artifact_canonical)
    VALUES(v_artifact_id,v_asset_id,1,v_fetch_id,p_agent_run_id,p_provider_turn_id,p_tool_call_id,p_call_id,0,
      p_input_snapshot_sha256,p_request_kind,p_request_sha256,p_result_sha256,'STORED',p_source_url_redacted,p_final_url_redacted,
      p_source_id,v_now,p_http_status,coalesce(p_content_media_type,'application/octet-stream'),octet_length(p_content),v_content_sha,
      encode(extensions.digest(ops.canonical_jsonb_v1(v_headers),'sha256'),'hex'),v_artifact_sha,p_object_key,
      encode(extensions.digest(convert_to(p_object_key,'UTF8'),'sha256'),'hex'),v_headers,ops.canonical_jsonb_v1(v_headers),v_redirects,
      ops.canonical_jsonb_v1(v_redirects),'RESTRICTED',v_safety_state,v_fetch_receipt,v_artifact_canonical)
    RETURNING created_at INTO v_artifact_created_at;

    INSERT INTO raw.asset_rights_decisions(
      id,asset_id,asset_sha256,asset_revision,decision_version,asset_kind,research_artifact_id,decision_kind,
      access_right,private_storage_right,model_egress_right,model_use_right,derivative_creation_right,excerpt_right,
      redistribution_right,commercial_use_right,public_display_right,dimensions_sha256,legal_basis_code,legal_basis_reference,
      legal_basis_sha256,license_evidence_digests,license_evidence_set_sha256,jurisdiction,attribution_required,attribution_sha256,
      policy_version,policy_sha256,approval_sha256,execution_sha256,evidence_receipt_id,evidence_receipt_sha256,reviewer_user_id,
      effective_at,decision_sha256)
    VALUES(v_rights_id,v_asset_id,v_content_sha,1,1,'RESEARCH_ARTIFACT',v_artifact_id,'GRANT',
      v_access_right,v_private_storage_right,v_model_egress_right,v_model_use_right,v_derivative_creation_right,v_excerpt_right,
      v_redistribution_right,v_commercial_use_right,v_public_display_right,
      encode(extensions.digest(ops.canonical_jsonb_v1(jsonb_build_object(
        'accessRight',v_access_right,'privateStorageRight',v_private_storage_right,
        'modelEgressRight',v_model_egress_right,'modelUseRight',v_model_use_right,
        'derivativeCreationRight',v_derivative_creation_right,'excerptRight',v_excerpt_right,
        'redistributionRight',v_redistribution_right,'commercialUseRight',v_commercial_use_right,
        'publicDisplayRight',v_public_display_right)),'sha256'),'hex'),'PUBLIC_RESEARCH',p_source_id,
      v_source_registry_sha,
      v_license_evidence_digests,
      encode(extensions.digest(ops.canonical_jsonb_v1(to_jsonb(v_license_evidence_digests)),'sha256'),'hex'),
      'GLOBAL',false,encode(extensions.digest(convert_to('','UTF8'),'sha256'),'hex'),p_policy_version,v_policy_sha,
      v_capability_decision_set_sha,v_execution_receipt_set_sha,v_fetch_id,v_fetch_receipt,v_reviewer_user_id,coalesce(v_capability_effective,v_now),
      v_asset_rights_sha);
    INSERT INTO ops.agent_source_uses(
      source_use_id,source_use_contract_version,agent_run_id,provider_turn_id,tool_call_id,use_kind,source_kind,
      research_artifact_id,research_asset_id,research_asset_revision,research_artifact_sha256,research_content_sha256,
      research_source_fetch_id,locator_kind,locator_value,locator_sha256,selected_content_sha256,classification,rights_binding_kind,
      rights_asset_id,rights_asset_revision,rights_asset_sha256,asset_rights_decision_id,asset_rights_decision_version,
      asset_rights_decision_sha256,rights_effective_at,rights_expires_at,access_right,private_storage_right,model_egress_right,model_use_right,
      derivative_creation_right,excerpt_right,redistribution_right,commercial_use_right,public_display_right,rights_policy_version,
      rights_policy_sha256,occurred_at,source_use_canonical,source_use_sha256)
    VALUES(v_source_use_id,2,p_agent_run_id,p_provider_turn_id,p_tool_call_id,'TOOL_QUERY','RESEARCH_ARTIFACT',
      v_artifact_id,v_asset_id,1,v_artifact_sha,v_content_sha,v_fetch_id,'HTML_CSS_SELECTOR',v_locator,v_locator_sha,v_content_sha,
      'RESTRICTED','ASSET_RIGHTS',v_asset_id,1,v_content_sha,v_rights_id,1,
      v_asset_rights_sha,coalesce(v_capability_effective,v_now),v_capability_expires,
      v_access_right,v_private_storage_right,v_model_egress_right,v_model_use_right,v_derivative_creation_right,
      v_excerpt_right,v_redistribution_right,v_commercial_use_right,v_public_display_right,p_policy_version,v_policy_sha,coalesce(v_capability_effective,v_now),
      v_source_use_canonical,v_source_use_sha)
    ON CONFLICT (agent_run_id,source_use_sha256) DO NOTHING;
  END IF;

  -- Fresh writes and replays both bind the exact source-use row. The digest
  -- alone is insufficient because legacy rows did not enforce agreement
  -- between projection columns and canonical bytes.
  SELECT source_use.source_use_id INTO v_existing_source_use
    FROM ops.agent_source_uses source_use
   WHERE source_use.source_use_id=v_source_use_id
     AND source_use.source_use_contract_version=2
     AND source_use.agent_run_id=p_agent_run_id
     AND source_use.provider_turn_id=p_provider_turn_id
     AND source_use.tool_call_id=p_tool_call_id
     AND source_use.parent_source_use_id IS NULL
     AND source_use.parent_source_use_sha256 IS NULL
     AND source_use.promotion_id IS NULL
     AND source_use.promotion_receipt_sha256 IS NULL
     AND source_use.use_kind='TOOL_QUERY'
     AND source_use.source_kind='RESEARCH_ARTIFACT'
     AND source_use.research_artifact_id=v_artifact_id
     AND source_use.research_asset_id=v_asset_id
     AND source_use.research_asset_revision=1
     AND source_use.research_artifact_sha256=v_artifact_sha
     AND source_use.research_content_sha256=v_content_sha
     AND source_use.research_source_fetch_id=v_fetch_id
     AND source_use.locator_kind='HTML_CSS_SELECTOR'
     AND source_use.locator_value=v_locator
     AND source_use.locator_sha256=v_locator_sha
     AND source_use.selected_content_sha256=v_content_sha
     AND source_use.classification='RESTRICTED'
     AND source_use.rights_binding_kind='ASSET_RIGHTS'
     AND source_use.rights_asset_id=v_asset_id
     AND source_use.rights_asset_revision=1
     AND source_use.rights_asset_sha256=v_content_sha
     AND source_use.asset_rights_decision_id=v_rights_id
     AND source_use.asset_rights_decision_version=1
     AND source_use.asset_rights_decision_sha256=v_asset_rights_sha
     AND source_use.rights_effective_at=coalesce(v_capability_effective,v_now)
     AND source_use.rights_expires_at IS NOT DISTINCT FROM v_capability_expires
     AND source_use.access_right=v_access_right
     AND source_use.private_storage_right=v_private_storage_right
     AND source_use.model_egress_right=v_model_egress_right
     AND source_use.model_use_right=v_model_use_right
     AND source_use.derivative_creation_right=v_derivative_creation_right
     AND source_use.excerpt_right=v_excerpt_right
     AND source_use.redistribution_right=v_redistribution_right
     AND source_use.commercial_use_right=v_commercial_use_right
     AND source_use.public_display_right=v_public_display_right
     AND source_use.rights_policy_version=p_policy_version
     AND source_use.rights_policy_sha256=v_policy_sha
     AND source_use.provider_receipt_id IS NULL
     AND source_use.provider_receipt_sha256 IS NULL
     AND source_use.occurred_at=coalesce(v_capability_effective,v_now)
     AND source_use.source_use_canonical=v_source_use_canonical
     AND source_use.source_use_sha256=v_source_use_sha;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESEARCH_FETCH_SOURCE_USE_MISMATCH'
      USING ERRCODE='55000';
  END IF;

  -- The 0037 AFTER INSERT trigger owns the initial tier append. Reconstruct
  -- its complete receipt rather than inferring tier from classification.
  v_review_tier_payload := jsonb_build_object(
    'schemaVersion','research-artifact-review-tier.receipt.v1',
    'researchArtifactId',v_artifact_id,
    'researchAssetId',v_asset_id,
    'researchAssetRevision',1,
    'researchArtifactSha256',v_artifact_sha,
    'researchContentSha256',v_content_sha,
    'revision',1,
    'reviewTier','OFFICIAL_UNREVIEWED',
    'reviewedClassification','RESTRICTED',
    'predecessorRevision',NULL,
    'predecessorReceiptSha256',NULL,
    'sourceUseAgentRunId',NULL,
    'sourceUseId',NULL,
    'sourceUseSha256',NULL,
    'sourceLocatorDigest',v_locator_sha,
    'officialSourceRegistryDigest',v_source_registry_sha,
    'promotionId',NULL,
    'promotionReceiptSha256',NULL,
    'reviewedBy',NULL,
    'reviewedAt',NULL,
    'recordedAt',v_artifact_created_at);
  v_review_tier_canonical := ops.canonical_jsonb_v1(v_review_tier_payload);
  v_review_tier_receipt_sha := encode(
    extensions.digest(v_review_tier_canonical,'sha256'),'hex'
  );
  PERFORM 1
    FROM raw.research_artifact_review_tiers tier
   WHERE tier.research_artifact_id=v_artifact_id
     AND tier.research_asset_id=v_asset_id
     AND tier.research_asset_revision=1
     AND tier.research_artifact_sha256=v_artifact_sha
     AND tier.research_content_sha256=v_content_sha
     AND tier.revision=1
     AND tier.review_tier='OFFICIAL_UNREVIEWED'
     AND tier.reviewed_classification='RESTRICTED'
     AND tier.predecessor_revision IS NULL
     AND tier.predecessor_receipt_sha256 IS NULL
     AND tier.source_use_agent_run_id IS NULL
     AND tier.source_use_id IS NULL
     AND tier.source_use_sha256 IS NULL
     AND tier.source_locator_digest=v_locator_sha
     AND tier.official_source_registry_digest=v_source_registry_sha
     AND tier.promotion_id IS NULL
     AND tier.promotion_receipt_sha256 IS NULL
     AND tier.reviewed_by IS NULL
     AND tier.reviewed_at IS NULL
     AND tier.receipt_payload=v_review_tier_payload
     AND tier.receipt_canonical=v_review_tier_canonical
     AND tier.receipt_sha256=v_review_tier_receipt_sha
     AND tier.created_at=v_artifact_created_at;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESEARCH_FETCH_REVIEW_TIER_MISMATCH'
      USING ERRCODE='55000';
  END IF;

  IF v_existing_artifact IS NOT NULL THEN
    RETURN jsonb_build_object('schemaVersion','source.fetch.receipt.v2','sourceFetchId',v_fetch_id,
      'researchArtifactId',v_artifact_id,'sourceUseId',v_source_use_id,
      'payloadSha256',v_content_sha,'artifactSha256',v_existing_artifact_sha,'receiptDigest',v_fetch_receipt,
      'policyVersion',p_policy_version,'policySha256',v_policy_sha,'recordedAt',v_now,
      'reviewTier','OFFICIAL_UNREVIEWED','idempotencyReplay',true);
  END IF;
  RETURN jsonb_build_object('schemaVersion','source.fetch.receipt.v2','sourceFetchId',v_fetch_id,'researchArtifactId',v_artifact_id,
    'sourceUseId',v_source_use_id,'assetId',v_asset_id,'payloadSha256',v_content_sha,'artifactSha256',v_artifact_sha,
    'receiptDigest',v_fetch_receipt,'policyVersion',p_policy_version,'policySha256',v_policy_sha,'recordedAt',v_now,
    'reviewTier','OFFICIAL_UNREVIEWED');
END
$function$;
ALTER FUNCTION ops.record_research_fetch_v1(uuid,uuid,uuid,text,char(64),text,text,text,text,text,integer,text,char(64),bytea,text,text,char(64),uuid,uuid,uuid,uuid,char(64),char(64),jsonb,jsonb)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.record_research_fetch_v1(uuid,uuid,uuid,text,char(64),text,text,text,text,text,integer,text,char(64),bytea,text,text,char(64),uuid,uuid,uuid,uuid,char(64),char(64),jsonb,jsonb)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.record_research_fetch_v1(uuid,uuid,uuid,text,char(64),text,text,text,text,text,integer,text,char(64),bytea,text,text,char(64),uuid,uuid,uuid,uuid,char(64),char(64),jsonb,jsonb)
  TO gurine_analysis_worker;

-- Standalone R6c conflict-detection snapshot authority.
--
-- Integration order:
--   1. typed graph v2 relations and snapshot-binding relation
--   2. conflict-input columns on core.dataset_snapshots
--   3. core.dataset_snapshot_conflict_inputs_v2
--   4. this snippet
--
-- The conflict input row is the sole materializer authority after READY.
-- Live procurement, supplier, and relationship tables are read only while the
-- snapshot is BUILDING.  PERSON display fields and raw source locators never
-- enter the frozen payload.

CREATE OR REPLACE FUNCTION core.conflict_detection_policy_v2_is_valid(
  p_rule_id text,
  p_configuration jsonb
) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
  v_policy jsonb;
  v_key_count bigint;
  v_number numeric;
  v_other numeric;
  v_token text;
  v_tokens text[] := ARRAY[]::text[];
BEGIN
  IF p_rule_id NOT IN (
       'OFFICER_OVERLAP_AWARD',
       'OWNERSHIP_LINKED_COMPETITORS',
       'BID_ROTATION',
       'REVOLVING_DOOR_CONTRACT',
       'SANCTIONED_SUCCESSOR'
     )
     OR jsonb_typeof(p_configuration) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_configuration->'policy') IS DISTINCT FROM 'object' THEN
    RETURN false;
  END IF;
  v_policy := p_configuration->'policy';
  SELECT count(*) INTO v_key_count FROM jsonb_object_keys(v_policy);

  CASE p_rule_id
    WHEN 'OFFICER_OVERLAP_AWARD' THEN
      IF v_key_count <> 1
         OR NOT v_policy ? 'minimum_distinct_suppliers'
         OR jsonb_typeof(v_policy->'minimum_distinct_suppliers') <> 'number'
      THEN
        RETURN false;
      END IF;
      v_number := (v_policy->>'minimum_distinct_suppliers')::numeric;
      RETURN v_number = trunc(v_number) AND v_number >= 2;

    WHEN 'OWNERSHIP_LINKED_COMPETITORS' THEN
      IF v_key_count <> 2
         OR NOT v_policy ?& ARRAY[
           'minimum_linked_participants', 'maximum_relationship_hops'
         ]
         OR jsonb_typeof(v_policy->'minimum_linked_participants') <> 'number'
         OR jsonb_typeof(v_policy->'maximum_relationship_hops') <> 'number'
      THEN
        RETURN false;
      END IF;
      v_number := (v_policy->>'minimum_linked_participants')::numeric;
      v_other := (v_policy->>'maximum_relationship_hops')::numeric;
      RETURN v_number = 2
        AND v_other = trunc(v_other) AND v_other BETWEEN 1 AND 2;

    WHEN 'BID_ROTATION' THEN
      IF v_key_count <> 8
         OR NOT v_policy ?& ARRAY[
           'minimum_notice_count', 'window_days',
           'minimum_bidders_per_notice', 'minimum_distinct_winners',
           'cluster_metric', 'cluster_tolerance_bps', 'currency',
           'tie_handling'
         ]
         OR jsonb_typeof(v_policy->'minimum_notice_count') <> 'number'
         OR jsonb_typeof(v_policy->'window_days') <> 'number'
         OR jsonb_typeof(v_policy->'minimum_bidders_per_notice') <> 'number'
         OR jsonb_typeof(v_policy->'minimum_distinct_winners') <> 'number'
         OR jsonb_typeof(v_policy->'cluster_tolerance_bps') <> 'number'
         OR jsonb_typeof(v_policy->'cluster_metric') <> 'string'
         OR jsonb_typeof(v_policy->'currency') <> 'string'
         OR jsonb_typeof(v_policy->'tie_handling') <> 'string' THEN
        RETURN false;
      END IF;
      v_number := (v_policy->>'minimum_notice_count')::numeric;
      IF v_number <> trunc(v_number) OR v_number < 3 THEN RETURN false; END IF;
      v_number := (v_policy->>'window_days')::numeric;
      IF v_number <> trunc(v_number) OR v_number < 0 THEN RETURN false; END IF;
      v_number := (v_policy->>'minimum_bidders_per_notice')::numeric;
      IF v_number <> trunc(v_number) OR v_number < 3 THEN RETURN false; END IF;
      v_other := (v_policy->>'minimum_distinct_winners')::numeric;
      IF v_other <> trunc(v_other) OR v_other < 2 OR v_other > v_number THEN
        RETURN false;
      END IF;
      v_number := (v_policy->>'cluster_tolerance_bps')::numeric;
      RETURN v_number >= 0
        AND v_policy->>'cluster_metric' = 'LOSING_BID_RANGE_BPS'
        AND v_policy->>'currency' ~ '^[A-Z]{3}$'
        AND v_policy->>'tie_handling' = 'BLOCK';

    WHEN 'REVOLVING_DOOR_CONTRACT' THEN
      IF v_key_count <> 3
         OR NOT v_policy ?& ARRAY[
           'cooling_period_days', 'procurement_method_allowlist',
           'cooling_boundary'
         ]
         OR jsonb_typeof(v_policy->'cooling_period_days') <> 'number'
         OR jsonb_typeof(v_policy->'procurement_method_allowlist') <> 'array'
         OR jsonb_typeof(v_policy->'cooling_boundary') <> 'string'
         OR jsonb_array_length(v_policy->'procurement_method_allowlist') < 1
         OR v_policy->>'cooling_boundary' <>
           'DEPARTURE_EXCLUSIVE_COOLING_END_INCLUSIVE' THEN
        RETURN false;
      END IF;
      v_number := (v_policy->>'cooling_period_days')::numeric;
      IF v_number <> trunc(v_number) OR v_number < 1 THEN RETURN false; END IF;
      FOR v_token IN
        SELECT value
        FROM jsonb_array_elements_text(
          v_policy->'procurement_method_allowlist'
        )
      LOOP
        IF v_token !~ '^[A-Z][A-Z0-9_]{0,63}$'
           OR v_token = ANY(v_tokens) THEN
          RETURN false;
        END IF;
        v_tokens := array_append(v_tokens, v_token);
      END LOOP;
      RETURN true;

    WHEN 'SANCTIONED_SUCCESSOR' THEN
      IF v_key_count <> 4
         OR NOT v_policy ?& ARRAY[
           'maximum_new_entity_age_days',
           'post_sanction_award_window_days',
           'sanction_effective_date_semantics', 'link_match_mode'
         ]
         OR jsonb_typeof(v_policy->'maximum_new_entity_age_days') <> 'number'
         OR jsonb_typeof(
           v_policy->'post_sanction_award_window_days'
         ) <> 'number'
         OR jsonb_typeof(
           v_policy->'sanction_effective_date_semantics'
         ) <> 'string'
         OR jsonb_typeof(v_policy->'link_match_mode') <> 'string' THEN
        RETURN false;
      END IF;
      v_number := (v_policy->>'maximum_new_entity_age_days')::numeric;
      IF v_number <> trunc(v_number) OR v_number < 0 THEN RETURN false; END IF;
      v_number := (v_policy->>'post_sanction_award_window_days')::numeric;
      RETURN v_number = trunc(v_number) AND v_number >= 0
        AND v_policy->>'sanction_effective_date_semantics' IN (
          'START_DATE_INCLUSIVE', 'END_DATE_INCLUSIVE'
        )
        AND v_policy->>'link_match_mode' IN (
          'STRONG_IDENTIFIER_OR_APPROVED_OFFICER',
          'STRONG_IDENTIFIER_ONLY', 'APPROVED_OFFICER_ONLY'
        );
    ELSE
      RETURN false;
  END CASE;
EXCEPTION
  WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN false;
END
$$;
ALTER FUNCTION core.conflict_detection_policy_v2_is_valid(text,jsonb)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  core.conflict_detection_policy_v2_is_valid(text,jsonb) FROM PUBLIC;

-- A separate finalizer preserves the v1 manifest contract byte-for-byte for
-- existing builders while adding the frozen conflict-input aggregate to the
-- v2 snapshot digest.
CREATE OR REPLACE FUNCTION core.finalize_conflict_detection_dataset_snapshot_v2(
  p_snapshot_id uuid,
  p_expected_version bigint,
  p_snapshot_manifest jsonb,
  p_snapshot_manifest_canonical bytea,
  p_terminal_receipt_sha256 char(64),
  p_terminal_audit_event_id uuid
) RETURNS TABLE(
  snapshot_id uuid,
  state text,
  version bigint,
  snapshot_sha256 char(64),
  member_count bigint,
  conflict_input_count bigint,
  conflict_input_set_sha256 char(64)
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_snapshot core.dataset_snapshots%ROWTYPE;
  v_member_count bigint;
  v_member_set_sha256 char(64);
  v_conflict_count bigint;
  v_conflict_set_sha256 char(64);
  v_snapshot_sha256 char(64);
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_snapshot_id IS NULL OR p_expected_version < 1
     OR p_snapshot_manifest IS NULL
     OR p_snapshot_manifest_canonical IS NULL
     OR p_terminal_receipt_sha256 !~ '^[0-9a-f]{64}$'
     OR p_terminal_audit_event_id IS NULL
     OR p_snapshot_manifest_canonical <>
       ops.canonical_jsonb_v1(p_snapshot_manifest) THEN
    RAISE EXCEPTION 'conflict_snapshot_finalization_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT snapshot.* INTO v_snapshot
  FROM core.dataset_snapshots AS snapshot
  WHERE snapshot.id = p_snapshot_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'conflict_snapshot_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*)::bigint,
         encode(extensions.digest(
           ops.canonical_jsonb_v1(COALESCE(jsonb_agg(
             btrim(member.member_digest)
             ORDER BY member.member_ordinal
           ), '[]'::jsonb)), 'sha256'
         ), 'hex')::char(64)
  INTO v_member_count, v_member_set_sha256
  FROM core.dataset_snapshot_members AS member
  WHERE member.dataset_snapshot_id = p_snapshot_id;

  SELECT count(*)::bigint,
         encode(extensions.digest(
           ops.canonical_jsonb_v1(COALESCE(jsonb_agg(
             btrim(input.input_sha256)
             ORDER BY input.rule_id, input.rule_version_id::text
           ), '[]'::jsonb)), 'sha256'
         ), 'hex')::char(64)
  INTO v_conflict_count, v_conflict_set_sha256
  FROM core.dataset_snapshot_conflict_inputs_v2 AS input
  WHERE input.dataset_snapshot_id = p_snapshot_id;

  IF v_snapshot.state = 'READY' THEN
    IF v_snapshot.version = p_expected_version + 1
       AND v_snapshot.snapshot_kind = 'DETECTION_DATASET'
       AND v_snapshot.member_count = 0
       AND v_member_count = 0
       AND v_snapshot.member_set_sha256 = v_member_set_sha256
       AND v_snapshot.conflict_input_count = v_conflict_count
       AND v_snapshot.conflict_input_set_sha256 = v_conflict_set_sha256
       AND v_snapshot.snapshot_manifest = p_snapshot_manifest
       AND v_snapshot.snapshot_manifest_canonical =
         p_snapshot_manifest_canonical
       AND v_snapshot.terminal_receipt_sha256 =
         p_terminal_receipt_sha256
       AND v_snapshot.terminal_audit_event_id =
         p_terminal_audit_event_id THEN
      RETURN QUERY SELECT v_snapshot.id, v_snapshot.state,
        v_snapshot.version, v_snapshot.snapshot_sha256,
        v_snapshot.member_count, v_snapshot.conflict_input_count,
        v_snapshot.conflict_input_set_sha256;
      RETURN;
    END IF;
    RAISE EXCEPTION 'conflict_snapshot_finalization_replay_conflict'
      USING ERRCODE = '40001';
  END IF;

  IF v_snapshot.state <> 'BUILDING'
     OR v_snapshot.version <> p_expected_version
     OR v_snapshot.snapshot_kind <> 'DETECTION_DATASET'
     OR v_member_count <> 0
     OR v_conflict_count < 1
     OR v_snapshot.conflict_input_count <> v_conflict_count
     OR v_snapshot.conflict_input_set_sha256 <> v_conflict_set_sha256
     OR EXISTS (
       SELECT 1
       FROM core.dataset_snapshot_conflict_inputs_v2 AS input
       WHERE input.dataset_snapshot_id = p_snapshot_id
         AND (
           input.snapshot_kind <> 'DETECTION_DATASET'
           OR input.producer_generation <> v_snapshot.producer_generation
           OR input.snapshot_contract_version <> v_snapshot.contract_version
           OR input.input_canonical <>
             ops.canonical_jsonb_v1(input.input_payload)
           OR input.input_sha256 <> encode(
             extensions.digest(input.input_canonical, 'sha256'), 'hex'
           )
         )
     ) THEN
    RAISE EXCEPTION 'conflict_snapshot_child_integrity_mismatch'
      USING ERRCODE = '23514';
  END IF;

  IF p_snapshot_manifest <> jsonb_build_object(
       'schemaVersion', 'dataset-snapshot-manifest.v2',
       'snapshotId', p_snapshot_id,
       'snapshotKind', v_snapshot.snapshot_kind,
       'producerDigest', btrim(v_snapshot.producer_digest),
       'producerGeneration', v_snapshot.producer_generation,
       'selectionSha256', btrim(v_snapshot.selection_sha256),
       'sourceWatermarkSha256', btrim(v_snapshot.source_watermark_sha256),
       'normalizationSetSha256', btrim(v_snapshot.normalization_set_sha256),
       'memberCount', 0,
       'memberSetSha256', btrim(v_member_set_sha256),
       'conflictInputCount', v_conflict_count,
       'conflictInputSetSha256', btrim(v_conflict_set_sha256)
     ) THEN
    RAISE EXCEPTION 'conflict_snapshot_manifest_binding_mismatch'
      USING ERRCODE = '23514';
  END IF;

  PERFORM 1
  FROM ops.audit_events AS audit
  WHERE audit.id = p_terminal_audit_event_id
    AND audit.actor_type = 'SERVICE'
    AND audit.actor_id = 'analysis-worker'
    AND audit.action = 'DATASET_SNAPSHOT_READY'
    AND audit.object_type = 'DatasetSnapshot'
    AND audit.object_id = p_snapshot_id::text
    AND audit.capability = 'jobs.operate'
    AND audit.outcome = 'SUCCESS'
    AND audit.request_id = v_snapshot.producer_job_id
    AND audit.details->>'snapshotId' = p_snapshot_id::text
    AND audit.details->>'state' = 'READY'
    AND audit.details->>'terminalReceiptDigest' =
      btrim(p_terminal_receipt_sha256)
    AND audit.details->>'conflictInputCount' = v_conflict_count::text
    AND audit.details->>'conflictInputSetSha256' =
      btrim(v_conflict_set_sha256);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'conflict_snapshot_terminal_audit_binding_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_snapshot_sha256 := encode(
    extensions.digest(p_snapshot_manifest_canonical, 'sha256'), 'hex'
  );
  UPDATE core.dataset_snapshots AS snapshot
  SET state = 'READY', member_count = 0,
      member_set_sha256 = v_member_set_sha256,
      snapshot_manifest = p_snapshot_manifest,
      snapshot_manifest_canonical = p_snapshot_manifest_canonical,
      snapshot_sha256 = v_snapshot_sha256,
      terminal_receipt_sha256 = p_terminal_receipt_sha256,
      terminal_audit_event_id = p_terminal_audit_event_id,
      version = snapshot.version + 1, ready_at = v_now
  WHERE snapshot.id = p_snapshot_id
    AND snapshot.state = 'BUILDING'
    AND snapshot.version = p_expected_version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'conflict_snapshot_finalization_fence_stale'
      USING ERRCODE = '40001';
  END IF;

  PERFORM ops.enqueue_outbox(
    'DatasetSnapshot', p_snapshot_id::text, p_expected_version + 1,
    'dataset.snapshot_created.v1',
    jsonb_build_object(
      'snapshotId', p_snapshot_id,
      'snapshotKind', v_snapshot.snapshot_kind,
      'producerComponent', v_snapshot.producer_component,
      'producerDigest', v_snapshot.producer_digest,
      'producerGeneration', v_snapshot.producer_generation,
      'projectionWatermark', NULL,
      'memberCount', 0,
      'sourceWatermarkDigest', v_snapshot.source_watermark_sha256,
      'state', 'READY',
      'terminalReceiptDigest', p_terminal_receipt_sha256,
      'snapshotSha256', v_snapshot_sha256,
      'errorCode', NULL,
      'errorDigest', NULL,
      'occurredAt', v_now
    ), v_now
  );

  RETURN QUERY SELECT p_snapshot_id, 'READY'::text,
    p_expected_version + 1, v_snapshot_sha256, 0::bigint,
    v_conflict_count, v_conflict_set_sha256;
END
$$;
ALTER FUNCTION core.finalize_conflict_detection_dataset_snapshot_v2(
  uuid,bigint,jsonb,bytea,char(64),uuid
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  core.finalize_conflict_detection_dataset_snapshot_v2(
    uuid,bigint,jsonb,bytea,char(64),uuid
  ) FROM PUBLIC;

CREATE OR REPLACE FUNCTION core.build_conflict_detection_dataset_snapshot_v2(
  p_job_id uuid,
  p_lease_token uuid,
  p_job_fencing_token bigint
) RETURNS TABLE(
  snapshot_id uuid,
  snapshot_sha256 char(64),
  member_count bigint,
  conflict_input_count bigint,
  conflict_input_set_sha256 char(64),
  replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, raw, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_job ops.jobs%ROWTYPE;
  v_rule core.rule_versions%ROWTYPE;
  v_identity record;
  v_existing core.dataset_snapshots%ROWTYPE;
  v_existing_count bigint;
  v_existing_input core.dataset_snapshot_conflict_inputs_v2%ROWTYPE;
  v_configuration_sha256 char(64);
  v_rule_version_digest char(64);
  v_producer_key text;
  v_producer_canonical bytea;
  v_producer_digest char(64);
  v_contracts jsonb;
  v_contracts_complete boolean;
  v_suppliers jsonb;
  v_notices jsonb;
  v_notices_complete boolean;
  v_awards jsonb;
  v_awards_complete boolean;
  v_bidders jsonb;
  v_bidders_complete boolean;
  v_graph_assertions jsonb;
  v_graph_complete boolean;
  v_graph_count bigint;
  v_strong_facts jsonb;
  v_strong_complete boolean;
  v_sanctions jsonb;
  v_koneps_ready boolean;
  v_dart_ready boolean;
  v_bidder_source_ready boolean;
  v_sanction_source_ready boolean;
  v_required_authority_ready boolean;
  v_required_inputs_complete boolean;
  v_coverage_status text;
  v_coverage jsonb;
  v_input_id uuid := gen_random_uuid();
  v_input_payload jsonb;
  v_input_canonical bytea;
  v_input_sha256 char(64);
  v_conflict_count bigint := 1;
  v_conflict_set_sha256 char(64);
  v_selection jsonb;
  v_selection_canonical bytea;
  v_source_watermarks jsonb;
  v_source_watermarks_canonical bytea;
  v_normalization_versions jsonb;
  v_normalization_canonical bytea;
  v_build_request jsonb;
  v_build_request_sha256 char(64);
  v_snapshot_id uuid := gen_random_uuid();
  v_build_started_audit_event_id uuid;
  v_begin record;
  v_snapshot_manifest jsonb;
  v_snapshot_manifest_canonical bytea;
  v_snapshot_sha256 char(64);
  v_terminal_at timestamptz;
  v_terminal_receipt jsonb;
  v_terminal_receipt_sha256 char(64);
  v_terminal_audit_event_id uuid;
  v_final record;
  v_updated bigint;
  v_graph_row record;
  v_binding_canonical bytea;
  v_binding_digest char(64);
BEGIN
  IF p_job_id IS NULL OR p_lease_token IS NULL
     OR p_job_fencing_token IS NULL OR p_job_fencing_token < 1 THEN
    RAISE EXCEPTION 'conflict_snapshot_build_fence_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_job_id
    AND job.job_type = 'DETECTION_SNAPSHOT_BUILD'
    AND job.queue = 'analysis-worker'
    AND job.status = 'RUNNING'
    AND job.lease_token = p_lease_token
    AND job.fencing_token = p_job_fencing_token
    AND job.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'conflict_snapshot_build_lease_stale'
      USING ERRCODE = '40001';
  END IF;
  IF jsonb_typeof(v_job.payload) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(v_job.payload)) <> 5
     OR NOT v_job.payload ?& ARRAY[
       'schemaVersion', 'ruleVersionId', 'ruleId',
       'contractIdentitySetSha256', 'contractCount'
     ]
     OR jsonb_typeof(v_job.payload->'schemaVersion') <> 'string'
     OR v_job.payload->>'schemaVersion' <>
       'detection-snapshot-build-job.v1'
     OR jsonb_typeof(v_job.payload->'ruleVersionId') <> 'string'
     OR jsonb_typeof(v_job.payload->'ruleId') <> 'string'
     OR v_job.payload->>'ruleId' NOT IN (
       'OFFICER_OVERLAP_AWARD',
       'OWNERSHIP_LINKED_COMPETITORS',
       'BID_ROTATION',
       'REVOLVING_DOOR_CONTRACT',
       'SANCTIONED_SUCCESSOR'
     )
     OR jsonb_typeof(v_job.payload->'contractIdentitySetSha256') <> 'string'
     OR v_job.payload->>'contractIdentitySetSha256' !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(v_job.payload->'contractCount') <> 'number'
     OR v_job.payload->>'contractCount' !~ '^(0|[1-9][0-9]*)$' THEN
    RAISE EXCEPTION 'conflict_snapshot_build_payload_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT version.* INTO v_rule
  FROM core.rule_versions AS version
  WHERE version.id::text = v_job.payload->>'ruleVersionId'
  FOR SHARE;
  IF NOT FOUND OR v_rule.status <> 'ACTIVE'
     OR v_rule.rule_id <> v_job.payload->>'ruleId'
     OR v_rule.code_digest !~ '^[0-9a-f]{64}$'
     OR NOT core.conflict_detection_policy_v2_is_valid(
       v_rule.rule_id, v_rule.configuration
     ) THEN
    RAISE EXCEPTION 'conflict_snapshot_rule_policy_inactive_or_invalid'
      USING ERRCODE = '55000';
  END IF;

  v_configuration_sha256 := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_rule.configuration), 'sha256'
  ), 'hex');
  -- Evaluation already carries the immutable rule code digest.  Reusing that
  -- exact authority lets the worker bind the frozen input without inventing a
  -- second digest vocabulary; configuration remains separately bound below.
  v_rule_version_digest := btrim(v_rule.code_digest);
  v_producer_key := 'conflict-detection-rule:' || v_rule.id::text;
  v_producer_canonical := ops.canonical_jsonb_v1(jsonb_build_object(
    'schemaVersion', 'r6c-conflict-snapshot-producer.v2',
    'ruleId', v_rule.rule_id,
    'ruleVersionId', v_rule.id,
    'ruleCodeSha256', btrim(v_rule_version_digest),
    'ruleConfigurationSha256', btrim(v_configuration_sha256)
  ));
  v_producer_digest := encode(
    extensions.digest(v_producer_canonical, 'sha256'), 'hex'
  );

  SELECT count(*) INTO v_existing_count
  FROM core.dataset_snapshots AS snapshot
  WHERE snapshot.producer_job_id = p_job_id;
  IF v_existing_count > 1 THEN
    RAISE EXCEPTION 'conflict_snapshot_replay_cardinality_invalid'
      USING ERRCODE = '40001';
  ELSIF v_existing_count = 1 THEN
    SELECT snapshot.* INTO STRICT v_existing
    FROM core.dataset_snapshots AS snapshot
    WHERE snapshot.producer_job_id = p_job_id
    FOR UPDATE;
    SELECT input.* INTO STRICT v_existing_input
    FROM core.dataset_snapshot_conflict_inputs_v2 AS input
    WHERE input.dataset_snapshot_id = v_existing.id
      AND input.rule_id = v_rule.rule_id
      AND input.rule_version_id = v_rule.id;
    IF v_existing.state <> 'READY'
       OR v_existing.snapshot_kind <> 'DETECTION_DATASET'
       OR v_existing.producer_key <> v_producer_key
       OR v_existing.producer_digest <> v_producer_digest
       OR v_existing.conflict_input_count <> 1
       OR v_existing.conflict_input_set_sha256 <> encode(
         extensions.digest(ops.canonical_jsonb_v1(jsonb_build_array(
           btrim(v_existing_input.input_sha256)
         )), 'sha256'), 'hex'
       )
       OR v_existing_input.producer_generation <>
         v_existing.producer_generation
       OR v_existing_input.rule_version_digest <> v_rule_version_digest
       OR v_existing_input.input_canonical <>
         ops.canonical_jsonb_v1(v_existing_input.input_payload)
       OR v_existing_input.input_sha256 <> encode(
         extensions.digest(v_existing_input.input_canonical, 'sha256'), 'hex'
       )
       OR v_existing.snapshot_sha256 <> encode(
         extensions.digest(v_existing.snapshot_manifest_canonical, 'sha256'),
         'hex'
       )
       OR (SELECT count(*)
           FROM core.dataset_snapshot_relationship_assertions_v2 AS binding
           WHERE binding.dataset_snapshot_id = v_existing.id) <>
         jsonb_array_length(
           v_existing_input.input_payload->'typed_relationship_assertions'
         ) THEN
      RAISE EXCEPTION 'conflict_snapshot_replay_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN QUERY SELECT v_existing.id, v_existing.snapshot_sha256,
      v_existing.member_count, v_existing.conflict_input_count,
      v_existing.conflict_input_set_sha256, true;
    RETURN;
  END IF;

  -- The scheduler's D1 contract identity is still the job fence.  R6c adds
  -- procurement and graph material without weakening that existing fence.
  SELECT * INTO STRICT v_identity
  FROM core.current_detection_contract_identity_v1();
  IF v_identity.contract_count <> (v_job.payload->>'contractCount')::bigint
     OR btrim(v_identity.contract_identity_set_sha256) <>
       v_job.payload->>'contractIdentitySetSha256'
     OR v_job.dedupe_key IS DISTINCT FROM
       'detection-snapshot-build:' || v_rule.id::text || ':' ||
       btrim(v_identity.contract_identity_set_sha256) THEN
    RAISE EXCEPTION 'conflict_snapshot_contract_identity_stale'
      USING ERRCODE = '40001';
  END IF;

  SELECT
    EXISTS (
      SELECT 1 FROM ops.source_registry AS source
      WHERE source.source_id = 'koneps-bid-results'
        AND source.enabled AND source.legal_status = 'APPROVED'
    ),
    EXISTS (
      SELECT 1 FROM ops.source_registry AS source
      WHERE source.source_id = 'open-dart'
        AND source.enabled AND source.legal_status = 'APPROVED'
    ),
    EXISTS (
      SELECT 1 FROM ops.source_registry AS source
      WHERE source.source_id = 'koneps-structured-bidder-participation'
        AND source.enabled AND source.legal_status = 'APPROVED'
    ),
    EXISTS (
      SELECT 1 FROM ops.source_registry AS source
      WHERE source.source_id = 'pps-sanctions'
        AND source.enabled AND source.legal_status = 'APPROVED'
    )
  INTO v_koneps_ready, v_dart_ready, v_bidder_source_ready,
       v_sanction_source_ready;

  WITH contract_rows AS (
    SELECT contract.id, contract.version, contract.updated_at,
      jsonb_build_object(
        'id', contract.id,
        'version', contract.version,
        'agency_id', contract.agency_id,
        'supplier_id', contract.supplier_id,
        'signed_on', CASE WHEN contract.signed_at IS NULL THEN NULL
          ELSE to_char(contract.signed_at, 'YYYY-MM-DD') END,
        'procurement_method', contract.procurement_method,
        'current_amount', CASE WHEN contract.current_amount IS NULL THEN NULL
          ELSE trim_scale(contract.current_amount)::text END,
        'currency', btrim(contract.currency),
        'source_id', contract.source_id,
        'source_document_id', contract.source_document_id,
        'source_content_sha256', btrim(document.content_sha256),
        'updated_at', to_char(
          contract.updated_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        )
      ) AS payload,
      contract.supplier_id IS NOT NULL
        AND contract.signed_at IS NOT NULL
        AND nullif(btrim(contract.procurement_method), '') IS NOT NULL
        AS complete
    FROM core.contracts AS contract
    JOIN raw.source_documents AS document
      ON document.id = contract.source_document_id
  )
  SELECT COALESCE(jsonb_agg(
           row.payload ORDER BY row.id::text, row.version, row.updated_at
         ), '[]'::jsonb),
         COALESCE(count(*) > 0 AND bool_and(row.complete), false)
  INTO v_contracts, v_contracts_complete
  FROM contract_rows AS row;

  WITH supplier_rows AS (
    SELECT supplier.id,
      CASE WHEN supplier.incorporation_date IS NULL THEN NULL
        ELSE to_char(supplier.incorporation_date, 'YYYY-MM-DD')
      END AS incorporated_at,
      supplier.identity_status
    FROM core.suppliers AS supplier
  ), projected AS (
    SELECT row.*,
      encode(extensions.digest(ops.canonical_jsonb_v1(
        jsonb_build_object(
          'id', row.id,
          'incorporated_at', row.incorporated_at,
          'identity_status', row.identity_status
        )
      ), 'sha256'), 'hex') AS object_digest
    FROM supplier_rows AS row
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', supplier.id,
           'incorporated_at', supplier.incorporated_at,
           'identity_status', supplier.identity_status,
           'object_digest', supplier.object_digest
         ) ORDER BY supplier.id::text), '[]'::jsonb)
  INTO v_suppliers
  FROM projected AS supplier;

  WITH ranked AS (
    SELECT notice.*,
      row_number() OVER (
        PARTITION BY notice.root_id
        ORDER BY notice.revision DESC, notice.revision_id::text DESC
      ) AS current_rank
    FROM core.procurement_notice_revisions AS notice
    WHERE notice.connector_id = 'koneps-bid-results'
  ), current_rows AS (
    SELECT * FROM ranked WHERE current_rank = 1
  )
  -- The v1 procurement-notice authority has no bid-opening instant.  It is
  -- intentionally frozen as null; publication/closing dates must never be
  -- substituted for the rule's bid_opened_at field.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', notice.root_id,
           'agency_id', notice.agency_id,
           'published_on', CASE WHEN notice.published_at IS NULL THEN NULL
             ELSE to_char(
               notice.published_at AT TIME ZONE 'UTC', 'YYYY-MM-DD'
             ) END,
           'bid_opened_at', NULL::text
         ) ORDER BY notice.root_id::text), '[]'::jsonb),
         COALESCE(count(*) > 0 AND bool_and(
           notice.coverage_status = 'COMPLETE'
           AND notice.revision_state NOT IN ('DELETED', 'SUPERSEDED')
           AND notice.agency_id IS NOT NULL
           AND notice.published_at IS NOT NULL
         ), false)
  INTO v_notices, v_notices_complete
  FROM current_rows AS notice;

  WITH ranked AS (
    SELECT award.*,
      row_number() OVER (
        PARTITION BY award.root_id
        ORDER BY award.revision DESC, award.revision_id::text DESC
      ) AS current_rank
    FROM core.procurement_award_revisions AS award
    WHERE award.connector_id = 'koneps-bid-results'
  ), current_rows AS (
    SELECT * FROM ranked WHERE current_rank = 1
  ), award_rows AS (
    SELECT award.*, notice.agency_id,
      COALESCE(winner.supplier_ids, '[]'::jsonb) AS supplier_ids,
      COALESCE(winner.actual_count, 0) AS actual_winner_count,
      COALESCE(winner.all_verified, false) AS all_winners_verified
    FROM current_rows AS award
    JOIN core.procurement_notice_revisions AS notice
      ON notice.root_id = award.notice_root_id
     AND notice.revision_id = award.notice_revision_id
     AND notice.revision = award.notice_revision
     AND notice.record_digest = award.notice_record_digest
    LEFT JOIN LATERAL (
      SELECT jsonb_agg(
               to_jsonb(item.canonical_supplier_id)
               ORDER BY item.winner_ordinal
             ) FILTER (
               WHERE item.canonical_supplier_id IS NOT NULL
             ) AS supplier_ids,
             count(*)::bigint AS actual_count,
             bool_and(
               item.identity_status = 'VERIFIED'
               AND item.canonical_supplier_id IS NOT NULL
             ) AS all_verified
      FROM core.procurement_award_winner_revisions AS item
      WHERE item.award_revision_id = award.revision_id
    ) AS winner ON true
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', award.root_id,
           'notice_id', award.notice_root_id,
           'agency_id', award.agency_id,
           'awarded_on', award.awarded_at_value,
           'supplier_ids', award.supplier_ids
         ) ORDER BY award.root_id::text), '[]'::jsonb),
         COALESCE(count(*) > 0 AND bool_and(
           award.coverage_status = 'COMPLETE'
           AND award.actual_winner_count = award.winner_count
           AND award.actual_winner_count > 0
           AND award.all_winners_verified
           AND award.agency_id IS NOT NULL
           AND nullif(btrim(award.awarded_at_value), '') IS NOT NULL
         ), false)
  INTO v_awards, v_awards_complete
  FROM award_rows AS award;

  WITH ranked AS (
    SELECT bidder.*,
      row_number() OVER (
        PARTITION BY bidder.root_id
        ORDER BY bidder.revision DESC, bidder.revision_id::text DESC
      ) AS current_rank
    FROM core.procurement_bidder_participation_revisions AS bidder
    WHERE bidder.connector_id =
      'koneps-structured-bidder-participation'
  ), current_rows AS (
    SELECT * FROM ranked WHERE current_rank = 1
  ), bidder_rows AS (
    SELECT bidder.*, candidate.identity_status,
      candidate.canonical_supplier_id
    FROM current_rows AS bidder
    JOIN core.supplier_identity_candidates AS candidate
      ON candidate.candidate_id = bidder.candidate_id
     AND candidate.candidate_revision = bidder.candidate_revision
     AND candidate.candidate_digest = bidder.candidate_digest
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', bidder.root_id,
           'notice_id', bidder.notice_root_id,
           'supplier_id', bidder.canonical_supplier_id,
           'participation_status', bidder.participation_status,
           'identity_status', bidder.identity_status,
           'coverage_status', bidder.coverage_status,
           'bid_amount', CASE WHEN bidder.bid_amount IS NULL THEN NULL
             ELSE trim_scale(bidder.bid_amount)::text END,
           'currency', CASE WHEN bidder.bid_currency IS NULL THEN NULL
             ELSE btrim(bidder.bid_currency) END,
           'rank', bidder.rank
         ) ORDER BY bidder.root_id::text), '[]'::jsonb),
         COALESCE(v_bidder_source_ready AND count(*) > 0 AND bool_and(
           bidder.coverage_status = 'COMPLETE'
           AND bidder.identity_status = 'VERIFIED'
           AND bidder.canonical_supplier_id IS NOT NULL
         ), false)
  INTO v_bidders, v_bidders_complete
  FROM bidder_rows AS bidder;

  WITH heads AS (
    SELECT assertion.*
    FROM core.relationship_graph_assertions_v2 AS assertion
    WHERE assertion.relationship_kind IN (
      'OWNERSHIP', 'CONTROL', 'MANAGEMENT_ROLE',
      'BID_PARTICIPATION', 'SANCTION', 'FORMER_OFFICIAL_ROLE'
    )
      AND NOT EXISTS (
        SELECT 1
        FROM core.relationship_graph_assertions_v2 AS newer
        WHERE newer.assertion_id = assertion.assertion_id
          AND newer.assertion_revision > assertion.assertion_revision
      )
  ), approved AS (
    SELECT head.*
    FROM heads AS head
    WHERE head.verification_status = 'VERIFIED'
      AND head.public_use_status = 'APPROVED'
      AND head.validity_coverage_status = 'COMPLETE'
      AND (
        head.subject_endpoint_kind <> 'PERSON'
        OR head.source_kind IN (
          'DART_EXECUTIVE_STATUS', 'ALIO_EXECUTIVE_STATUS',
          'PUBLIC_OFFICIAL_ETHICS_NOTICE', 'OFFICIAL_GAZETTE'
        )
      )
  ), graph_rows AS (
    SELECT assertion.assertion_id, assertion.assertion_revision,
      jsonb_build_object(
        'relationship_id', assertion.assertion_id,
        'assertion_revision', assertion.assertion_revision,
        'assertion_digest', btrim(assertion.assertion_digest),
        'relationship_kind', assertion.relationship_kind,
        'subject_kind', assertion.subject_endpoint_kind,
        'subject_entity_id', subject_endpoint.entity_id,
        'object_kind', assertion.object_endpoint_kind,
        'object_entity_id', object_endpoint.entity_id,
        'person_identifier_digest', CASE
          WHEN subject_endpoint.endpoint_kind = 'PERSON'
            THEN btrim(subject_endpoint.identifier_digest)
          WHEN object_endpoint.endpoint_kind = 'PERSON'
            THEN btrim(object_endpoint.identifier_digest)
          ELSE NULL
        END,
        'valid_from', CASE WHEN assertion.valid_from IS NULL THEN NULL
          ELSE to_char(assertion.valid_from, 'YYYY-MM-DD') END,
        'valid_to', CASE WHEN assertion.valid_to IS NULL THEN NULL
          ELSE to_char(assertion.valid_to, 'YYYY-MM-DD') END,
        'departed_on', CASE WHEN assertion.departed_on IS NULL THEN NULL
          ELSE to_char(assertion.departed_on, 'YYYY-MM-DD') END,
        'validity_coverage_status', assertion.validity_coverage_status,
        'verification_status', assertion.verification_status,
        'public_use_status', assertion.public_use_status,
        'independent_human_verification',
          assertion.verified_by IS NOT NULL
          AND assertion.verified_by IS DISTINCT FROM assertion.proposed_by,
        'source_kind', assertion.source_kind,
        'source_locators', evidence.source_locators,
        'evidence_ids', evidence.evidence_ids,
        'evidence_count', assertion.evidence_count,
        'evidence_set_digest', btrim(assertion.evidence_set_digest),
        'proposed_actor_type', assertion.proposed_actor_type,
        'proposed_actor_id', assertion.proposed_actor_id,
        'proposed_by', assertion.proposed_by,
        'verified_by', assertion.verified_by,
        'verified_at', to_char(
          assertion.verified_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        ),
        'verification_reason_digest',
          btrim(assertion.verification_reason_digest)
      ) AS payload
    FROM approved AS assertion
    JOIN core.relationship_graph_endpoints_v2 AS subject_endpoint
      ON subject_endpoint.endpoint_id = assertion.subject_endpoint_id
     AND subject_endpoint.endpoint_digest = assertion.subject_endpoint_digest
    JOIN core.relationship_graph_endpoints_v2 AS object_endpoint
      ON object_endpoint.endpoint_id = assertion.object_endpoint_id
     AND object_endpoint.endpoint_digest = assertion.object_endpoint_digest
    JOIN LATERAL (
      SELECT count(*)::bigint AS actual_count,
             encode(extensions.digest(ops.canonical_jsonb_v1(
               COALESCE(jsonb_agg(
                 to_jsonb(btrim(item.evidence_member_digest))
                 ORDER BY item.evidence_member_digest
               ), '[]'::jsonb)
             ), 'sha256'), 'hex')::char(64) AS actual_set_digest,
             COALESCE(jsonb_agg(
               to_jsonb(item.evidence_id::text)
               ORDER BY item.evidence_ordinal
             ), '[]'::jsonb) AS evidence_ids,
             COALESCE(jsonb_agg(
               to_jsonb(btrim(item.locator_digest))
               ORDER BY item.evidence_ordinal
             ), '[]'::jsonb) AS source_locators
      FROM core.relationship_graph_assertion_evidence_v2 AS item
      WHERE item.assertion_id = assertion.assertion_id
        AND item.assertion_revision = assertion.assertion_revision
        AND item.assertion_digest = assertion.assertion_digest
    ) AS evidence
      ON evidence.actual_count = assertion.evidence_count
     AND evidence.actual_set_digest = assertion.evidence_set_digest
  )
  SELECT COALESCE(jsonb_agg(
           row.payload ORDER BY row.assertion_id::text,
             row.assertion_revision
         ), '[]'::jsonb),
         count(*)::bigint,
         COALESCE(count(*) > 0
           AND count(*) = (SELECT count(*) FROM approved)
           AND NOT EXISTS (
           SELECT 1 FROM heads AS head
           WHERE head.verification_status <> 'VERIFIED'
              OR head.public_use_status <> 'APPROVED'
              OR head.validity_coverage_status <> 'COMPLETE'
              OR (
                head.subject_endpoint_kind = 'PERSON'
                AND head.source_kind NOT IN (
                  'DART_EXECUTIVE_STATUS', 'ALIO_EXECUTIVE_STATUS',
                  'PUBLIC_OFFICIAL_ETHICS_NOTICE', 'OFFICIAL_GAZETTE'
                )
              )
         ), false)
  INTO v_graph_assertions, v_graph_count, v_graph_complete
  FROM graph_rows AS row;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'supplier_id', identifier.supplier_id,
           'scheme', identifier.scheme,
           'value_hash', btrim(identifier.value_hash),
           'verification_status', identifier.verification_status,
           'proof_state', identifier.proof_state
         ) ORDER BY identifier.supplier_id::text, identifier.scheme,
           btrim(identifier.value_hash), identifier.id::text), '[]'::jsonb),
         true
  INTO v_strong_facts, v_strong_complete
  FROM core.supplier_identifiers AS identifier
  WHERE identifier.scheme IN (
      'KOREAN_BUSINESS_NUMBER', 'OPEN_DART_CORP_CODE', 'KONEPS_PARTY_KEY'
    )
    AND identifier.verification_status = 'VERIFIED'
    AND identifier.proof_state = 'PROVEN_V1';

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', relation->>'object_entity_id',
           'supplier_id', relation->>'subject_entity_id',
           'effective_from', relation->'valid_from',
           'effective_to', relation->'valid_to',
           'source_status', CASE WHEN v_sanction_source_ready
             THEN 'READY' ELSE 'DISABLED' END,
           'coverage_status', CASE WHEN v_sanction_source_ready
             THEN 'COMPLETE' ELSE 'NOT_AVAILABLE' END,
           'relationship_id', relation->>'relationship_id'
         ) ORDER BY relation->>'relationship_id'), '[]'::jsonb)
  INTO v_sanctions
  FROM jsonb_array_elements(v_graph_assertions) AS relation
  WHERE relation->>'relationship_kind' = 'SANCTION';

  v_notices_complete := v_koneps_ready AND v_notices_complete;
  v_awards_complete := v_koneps_ready AND v_awards_complete;
  v_coverage := jsonb_build_object(
    'contracts_complete', v_contracts_complete,
    'procurement_notices_complete', v_notices_complete,
    'procurement_awards_complete', v_awards_complete,
    'bidder_participations_complete', v_bidders_complete,
    'typed_relationships_complete', v_graph_complete,
    'strong_identifier_facts_complete', v_strong_complete,
    'bidder_participation_authority',
      'koneps-structured-bidder-participation'
  );

  CASE v_rule.rule_id
    WHEN 'OFFICER_OVERLAP_AWARD' THEN
      v_required_authority_ready := v_koneps_ready AND v_dart_ready;
      v_required_inputs_complete := v_notices_complete
        AND v_awards_complete AND v_graph_complete
        AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(v_graph_assertions) AS item
          WHERE item->>'relationship_kind' = 'MANAGEMENT_ROLE'
        );
    WHEN 'OWNERSHIP_LINKED_COMPETITORS' THEN
      v_required_authority_ready := v_bidder_source_ready;
      v_required_inputs_complete := v_bidders_complete
        AND v_notices_complete AND v_graph_complete;
    WHEN 'BID_ROTATION' THEN
      v_required_authority_ready := v_bidder_source_ready;
      v_required_inputs_complete := v_bidders_complete
        AND v_notices_complete AND v_awards_complete;
    WHEN 'REVOLVING_DOOR_CONTRACT' THEN
      v_required_authority_ready := v_dart_ready AND EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_graph_assertions) AS item
        WHERE item->>'relationship_kind' = 'FORMER_OFFICIAL_ROLE'
          AND item->>'source_kind' IN (
            'PUBLIC_OFFICIAL_ETHICS_NOTICE', 'OFFICIAL_GAZETTE'
          )
      );
      v_required_inputs_complete := v_contracts_complete
        AND v_graph_complete
        AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(v_graph_assertions) AS item
          WHERE item->>'relationship_kind' = 'MANAGEMENT_ROLE'
        );
    WHEN 'SANCTIONED_SUCCESSOR' THEN
      v_required_authority_ready := v_sanction_source_ready;
      v_required_inputs_complete := v_notices_complete
        AND v_awards_complete AND v_graph_complete
        AND v_strong_complete AND jsonb_array_length(v_sanctions) > 0;
    ELSE
      RAISE EXCEPTION 'conflict_snapshot_rule_not_closed'
        USING ERRCODE = '55000';
  END CASE;
  v_coverage_status := CASE
    WHEN NOT v_required_authority_ready THEN 'BLOCKED'
    WHEN v_required_inputs_complete THEN 'COMPLETE'
    ELSE 'PARTIAL'
  END;

  v_input_payload := jsonb_build_object(
    'schema_version', 'conflict-detection-input.v2',
    'rule_id', v_rule.rule_id,
    'rule_version_id', v_rule.id,
    'rule_version_digest', btrim(v_rule_version_digest),
    'coverage_status', v_coverage_status,
    'coverage', v_coverage,
    'contracts', v_contracts,
    'procurement_notices', v_notices,
    'procurement_awards', v_awards,
    'bidder_participations', v_bidders,
    'typed_relationship_assertions', v_graph_assertions,
    'strong_identifier_facts', v_strong_facts,
    'suppliers', v_suppliers,
    'sanctions', v_sanctions
  );
  v_input_canonical := ops.canonical_jsonb_v1(v_input_payload);
  v_input_sha256 := encode(
    extensions.digest(v_input_canonical, 'sha256'), 'hex'
  );
  v_conflict_set_sha256 := encode(extensions.digest(
    ops.canonical_jsonb_v1(jsonb_build_array(btrim(v_input_sha256))),
    'sha256'
  ), 'hex');

  v_selection := jsonb_build_object(
    'snapshotKind', 'DETECTION_DATASET',
    'ruleId', v_rule.rule_id,
    'ruleVersionId', v_rule.id,
    'ruleVersionDigest', btrim(v_rule_version_digest),
    'ruleCodeSha256', btrim(v_rule.code_digest),
    'ruleConfigurationSha256', btrim(v_configuration_sha256),
    'conflictInputSha256', btrim(v_input_sha256),
    'selectionPolicyVersion', 'r6c-conflict-detection-v2'
  );
  v_selection_canonical := ops.canonical_jsonb_v1(v_selection);
  v_source_watermarks := jsonb_build_object(
    'schemaVersion', 'dataset-source-watermarks.v1',
    'eventFence', 0,
    'checkpoints', jsonb_build_array(jsonb_build_object(
      'authority', 'conflict-input-v2',
      'inputSha256', btrim(v_input_sha256)
    ))
  );
  v_source_watermarks_canonical :=
    ops.canonical_jsonb_v1(v_source_watermarks);
  v_normalization_versions := jsonb_build_object(
    'schemaVersion', 'dataset-normalization-versions.v1',
    'entries', '[]'::jsonb,
    'conflictDetectionAuthority', jsonb_build_object(
      'schemaVersion', 'r6c-conflict-detection-authority.v2',
      'ruleVersionDigest', btrim(v_rule_version_digest),
      'inputSha256', btrim(v_input_sha256),
      'coverageStatus', v_coverage_status
    )
  );
  v_normalization_canonical :=
    ops.canonical_jsonb_v1(v_normalization_versions);
  v_build_request := jsonb_build_object(
    'schemaVersion', 'conflict-snapshot-build-request.v2',
    'snapshotId', v_snapshot_id,
    'jobId', p_job_id,
    'jobPayload', v_job.payload,
    'producerKey', v_producer_key,
    'producerDigest', btrim(v_producer_digest),
    'ruleVersionDigest', btrim(v_rule_version_digest),
    'inputSha256', btrim(v_input_sha256)
  );
  v_build_request_sha256 := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_build_request), 'sha256'
  ), 'hex');
  v_build_started_audit_event_id := ops.append_audit_event(
    'snapshot:' || v_snapshot_id::text, 'SERVICE', 'analysis-worker', NULL,
    'DATASET_SNAPSHOT_BUILD_STARTED', 'DatasetSnapshot',
    v_snapshot_id::text, 'jobs.operate', 'SUCCESS', NULL, p_job_id,
    jsonb_build_object(
      'snapshotId', v_snapshot_id,
      'snapshotKind', 'DETECTION_DATASET',
      'producerJobId', p_job_id,
      'buildRequestSha256', btrim(v_build_request_sha256),
      'ruleId', v_rule.rule_id,
      'ruleVersionId', v_rule.id,
      'ruleVersionDigest', btrim(v_rule_version_digest),
      'inputSha256', btrim(v_input_sha256)
    )
  );
  SELECT * INTO STRICT v_begin
  FROM core.begin_dataset_snapshot(
    'DETECTION_DATASET', p_job_id, v_producer_key, v_producer_digest,
    'dataset-snapshot.v2', v_selection, v_selection_canonical,
    v_source_watermarks, v_source_watermarks_canonical,
    v_normalization_versions, v_normalization_canonical,
    v_build_request_sha256, v_build_started_audit_event_id
  );
  IF v_begin.snapshot_id <> v_snapshot_id OR v_begin.reused
     OR v_begin.state <> 'BUILDING' OR v_begin.producer_generation < 1 THEN
    RAISE EXCEPTION 'conflict_snapshot_begin_conflict'
      USING ERRCODE = '40001';
  END IF;

  INSERT INTO core.dataset_snapshot_conflict_inputs_v2(
    input_id, dataset_snapshot_id, snapshot_kind, producer_generation,
    snapshot_contract_version, rule_id, rule_version_id,
    rule_version_digest, coverage_status, input_payload, input_canonical,
    input_sha256
  ) VALUES (
    v_input_id, v_snapshot_id, 'DETECTION_DATASET',
    v_begin.producer_generation, 1, v_rule.rule_id, v_rule.id,
    v_rule_version_digest, v_coverage_status, v_input_payload,
    v_input_canonical, v_input_sha256
  );
  UPDATE core.dataset_snapshots AS snapshot
  SET conflict_input_count = v_conflict_count,
      conflict_input_set_sha256 = v_conflict_set_sha256
  WHERE snapshot.id = v_snapshot_id
    AND snapshot.state = 'BUILDING'
    AND snapshot.version = 1
    AND snapshot.producer_generation = v_begin.producer_generation;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> 1 THEN
    RAISE EXCEPTION 'conflict_snapshot_header_fence_lost'
      USING ERRCODE = '40001';
  END IF;

  v_snapshot_manifest := jsonb_build_object(
    'schemaVersion', 'dataset-snapshot-manifest.v2',
    'snapshotId', v_snapshot_id,
    'snapshotKind', 'DETECTION_DATASET',
    'producerDigest', btrim(v_producer_digest),
    'producerGeneration', v_begin.producer_generation,
    'selectionSha256', encode(
      extensions.digest(v_selection_canonical, 'sha256'), 'hex'
    ),
    'sourceWatermarkSha256', encode(
      extensions.digest(v_source_watermarks_canonical, 'sha256'), 'hex'
    ),
    'normalizationSetSha256', encode(
      extensions.digest(v_normalization_canonical, 'sha256'), 'hex'
    ),
    'memberCount', 0,
    'memberSetSha256', encode(extensions.digest(
      ops.canonical_jsonb_v1('[]'::jsonb), 'sha256'
    ), 'hex'),
    'conflictInputCount', v_conflict_count,
    'conflictInputSetSha256', btrim(v_conflict_set_sha256)
  );
  v_snapshot_manifest_canonical :=
    ops.canonical_jsonb_v1(v_snapshot_manifest);
  v_snapshot_sha256 := encode(extensions.digest(
    v_snapshot_manifest_canonical, 'sha256'
  ), 'hex');
  v_terminal_at := clock_timestamp();
  v_terminal_receipt := jsonb_build_object(
    'schemaVersion', 'dataset-snapshot-terminal-receipt.v2',
    'snapshotId', v_snapshot_id,
    'state', 'READY',
    'aggregateVersion', 3,
    'snapshotSha256', btrim(v_snapshot_sha256),
    'memberCount', 0,
    'conflictInputCount', v_conflict_count,
    'conflictInputSetSha256', btrim(v_conflict_set_sha256),
    'occurredAt', to_char(
      v_terminal_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
  v_terminal_receipt_sha256 := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_terminal_receipt), 'sha256'
  ), 'hex');
  v_terminal_audit_event_id := ops.append_audit_event(
    'snapshot:' || v_snapshot_id::text, 'SERVICE', 'analysis-worker', NULL,
    'DATASET_SNAPSHOT_READY', 'DatasetSnapshot', v_snapshot_id::text,
    'jobs.operate', 'SUCCESS', NULL, p_job_id, jsonb_build_object(
      'snapshotId', v_snapshot_id,
      'state', 'READY',
      'terminalReceiptDigest', btrim(v_terminal_receipt_sha256),
      'snapshotSha256', btrim(v_snapshot_sha256),
      'memberCount', 0,
      'conflictInputCount', v_conflict_count,
      'conflictInputSetSha256', btrim(v_conflict_set_sha256)
    )
  );
  SELECT * INTO STRICT v_final
  FROM core.finalize_conflict_detection_dataset_snapshot_v2(
    v_snapshot_id, 1, v_snapshot_manifest,
    v_snapshot_manifest_canonical, v_terminal_receipt_sha256,
    v_terminal_audit_event_id
  );
  IF v_final.snapshot_id <> v_snapshot_id OR v_final.state <> 'READY'
     OR v_final.version <> 2
     OR v_final.snapshot_sha256 <> v_snapshot_sha256
     OR v_final.member_count <> 0
     OR v_final.conflict_input_count <> v_conflict_count
     OR v_final.conflict_input_set_sha256 <> v_conflict_set_sha256 THEN
    RAISE EXCEPTION 'conflict_snapshot_finalization_conflict'
      USING ERRCODE = '40001';
  END IF;

  FOR v_graph_row IN
    SELECT item.value AS payload, item.ordinality - 1 AS ordinal
    FROM jsonb_array_elements(v_graph_assertions)
      WITH ORDINALITY AS item(value, ordinality)
    ORDER BY item.ordinality
  LOOP
    v_binding_canonical := ops.canonical_jsonb_v1(jsonb_build_object(
      'schemaVersion', 'dataset-snapshot-relationship-binding.v2',
      'snapshotId', v_snapshot_id,
      'snapshotSha256', btrim(v_snapshot_sha256),
      'snapshotGeneration', v_begin.producer_generation,
      'assertionOrdinal', v_graph_row.ordinal,
      'assertionId', (v_graph_row.payload->>'relationship_id')::uuid,
      'assertionRevision',
        (v_graph_row.payload->>'assertion_revision')::bigint,
      'assertionDigest', v_graph_row.payload->>'assertion_digest'
    ));
    v_binding_digest := encode(
      extensions.digest(v_binding_canonical, 'sha256'), 'hex'
    );
    INSERT INTO core.dataset_snapshot_relationship_assertions_v2(
      dataset_snapshot_id, snapshot_sha256, snapshot_generation,
      assertion_ordinal, assertion_id, assertion_revision,
      assertion_digest, binding_canonical, binding_digest
    ) VALUES (
      v_snapshot_id, v_snapshot_sha256, v_begin.producer_generation,
      v_graph_row.ordinal,
      (v_graph_row.payload->>'relationship_id')::uuid,
      (v_graph_row.payload->>'assertion_revision')::bigint,
      (v_graph_row.payload->>'assertion_digest')::char(64),
      v_binding_canonical, v_binding_digest
    );
  END LOOP;

  RETURN QUERY SELECT v_snapshot_id, v_snapshot_sha256, 0::bigint,
    v_conflict_count, v_conflict_set_sha256, false;
END
$$;
ALTER FUNCTION core.build_conflict_detection_dataset_snapshot_v2(
  uuid,uuid,bigint
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION core.build_conflict_detection_dataset_snapshot_v2(
  uuid,uuid,bigint
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION core.build_conflict_detection_dataset_snapshot_v2(
  uuid,uuid,bigint
) TO gurine_analysis_worker;

-- Runtime materialization reads exactly one frozen owner row.  No live
-- procurement, relationship, supplier, or identifier relation is consulted.
CREATE OR REPLACE FUNCTION core.read_conflict_detection_input_v2(
  p_dataset_snapshot_id uuid,
  p_producer_generation bigint,
  p_snapshot_sha256 char(64),
  p_rule_id text,
  p_rule_version_id uuid
) RETURNS TABLE(
  rule_id text,
  rule_version_id uuid,
  coverage_status text,
  input_payload jsonb,
  input_canonical bytea,
  input_sha256 char(64)
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_snapshot core.dataset_snapshots%ROWTYPE;
  v_input core.dataset_snapshot_conflict_inputs_v2%ROWTYPE;
  v_actual_count bigint;
  v_actual_set_sha256 char(64);
  v_graph_count bigint;
BEGIN
  IF p_dataset_snapshot_id IS NULL
     OR p_producer_generation < 1
     OR p_snapshot_sha256 !~ '^[0-9a-f]{64}$'
     OR p_rule_id NOT IN (
       'OFFICER_OVERLAP_AWARD', 'OWNERSHIP_LINKED_COMPETITORS',
       'BID_ROTATION', 'REVOLVING_DOOR_CONTRACT',
       'SANCTIONED_SUCCESSOR'
     )
     OR p_rule_version_id IS NULL THEN
    RAISE EXCEPTION 'conflict_input_read_binding_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT snapshot.* INTO v_snapshot
  FROM core.dataset_snapshots AS snapshot
  WHERE snapshot.id = p_dataset_snapshot_id
  FOR SHARE;
  IF NOT FOUND
     OR v_snapshot.snapshot_kind <> 'DETECTION_DATASET'
     OR v_snapshot.state <> 'READY'
     OR v_snapshot.producer_generation <> p_producer_generation
     OR v_snapshot.snapshot_sha256 <> p_snapshot_sha256
     OR v_snapshot.schema_version <> 'dataset-snapshot.v2'
     OR v_snapshot.member_count <> 0
     OR v_snapshot.conflict_input_count IS NULL
     OR v_snapshot.conflict_input_count < 1
     OR v_snapshot.snapshot_manifest IS NULL
     OR v_snapshot.snapshot_manifest_canonical IS NULL
     OR v_snapshot.snapshot_manifest_canonical <>
       ops.canonical_jsonb_v1(v_snapshot.snapshot_manifest)
     OR v_snapshot.snapshot_sha256 <> encode(
       extensions.digest(v_snapshot.snapshot_manifest_canonical, 'sha256'),
       'hex'
     ) THEN
    RAISE EXCEPTION 'conflict_input_ready_snapshot_mismatch'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*)::bigint,
         encode(extensions.digest(ops.canonical_jsonb_v1(
           COALESCE(jsonb_agg(
             to_jsonb(btrim(input.input_sha256))
             ORDER BY input.rule_id, input.rule_version_id::text
           ), '[]'::jsonb)
         ), 'sha256'), 'hex')::char(64)
  INTO v_actual_count, v_actual_set_sha256
  FROM core.dataset_snapshot_conflict_inputs_v2 AS input
  WHERE input.dataset_snapshot_id = p_dataset_snapshot_id;
  IF v_actual_count <> v_snapshot.conflict_input_count
     OR v_actual_set_sha256 <> v_snapshot.conflict_input_set_sha256
     OR jsonb_typeof(v_snapshot.snapshot_manifest) IS DISTINCT FROM 'object'
     OR (SELECT count(*)
         FROM jsonb_object_keys(v_snapshot.snapshot_manifest)) <> 12
     OR NOT (v_snapshot.snapshot_manifest ?& ARRAY[
       'schemaVersion', 'snapshotId', 'snapshotKind', 'producerDigest',
       'producerGeneration', 'selectionSha256', 'sourceWatermarkSha256',
       'normalizationSetSha256', 'memberCount', 'memberSetSha256',
       'conflictInputCount', 'conflictInputSetSha256'
     ])
     OR v_snapshot.snapshot_manifest->>'schemaVersion' <>
       'dataset-snapshot-manifest.v2'
     OR v_snapshot.snapshot_manifest->>'snapshotId' <>
       p_dataset_snapshot_id::text
     OR v_snapshot.snapshot_manifest->>'snapshotKind' <>
       'DETECTION_DATASET'
     OR v_snapshot.snapshot_manifest->>'producerDigest' <>
       btrim(v_snapshot.producer_digest)
     OR v_snapshot.snapshot_manifest->>'producerGeneration' <>
       p_producer_generation::text
     OR v_snapshot.snapshot_manifest->>'selectionSha256' <>
       btrim(v_snapshot.selection_sha256)
     OR v_snapshot.snapshot_manifest->>'sourceWatermarkSha256' <>
       btrim(v_snapshot.source_watermark_sha256)
     OR v_snapshot.snapshot_manifest->>'normalizationSetSha256' <>
       btrim(v_snapshot.normalization_set_sha256)
     OR v_snapshot.snapshot_manifest->>'memberCount' <> '0'
     OR v_snapshot.snapshot_manifest->>'memberSetSha256' <>
       btrim(v_snapshot.member_set_sha256)
     OR v_snapshot.snapshot_manifest->>'conflictInputCount' <>
       v_actual_count::text
     OR v_snapshot.snapshot_manifest->>'conflictInputSetSha256' <>
       btrim(v_actual_set_sha256) THEN
    RAISE EXCEPTION 'conflict_input_set_integrity_mismatch'
      USING ERRCODE = '23514';
  END IF;

  SELECT input.* INTO v_input
  FROM core.dataset_snapshot_conflict_inputs_v2 AS input
  WHERE input.dataset_snapshot_id = p_dataset_snapshot_id
    AND input.rule_id = p_rule_id
    AND input.rule_version_id = p_rule_version_id
  FOR SHARE;
  IF NOT FOUND
     OR v_input.snapshot_kind <> 'DETECTION_DATASET'
     OR v_input.producer_generation <> p_producer_generation
     OR v_input.snapshot_contract_version <> v_snapshot.contract_version
     OR v_input.coverage_status NOT IN ('COMPLETE', 'PARTIAL', 'BLOCKED')
     OR v_input.input_canonical <>
       ops.canonical_jsonb_v1(v_input.input_payload)
     OR v_input.input_sha256 <> encode(
       extensions.digest(v_input.input_canonical, 'sha256'), 'hex'
     )
     OR jsonb_typeof(v_input.input_payload) IS DISTINCT FROM 'object'
     OR (SELECT count(*)
         FROM jsonb_object_keys(v_input.input_payload)) <> 14
     OR NOT (v_input.input_payload ?& ARRAY[
       'schema_version', 'rule_id', 'rule_version_id',
       'rule_version_digest', 'coverage_status', 'coverage', 'contracts',
       'procurement_notices', 'procurement_awards',
       'bidder_participations', 'typed_relationship_assertions',
       'strong_identifier_facts', 'suppliers', 'sanctions'
     ])
     OR v_input.input_payload->>'schema_version' <>
       'conflict-detection-input.v2'
     OR v_input.input_payload->>'rule_id' <> p_rule_id
     OR v_input.input_payload->>'rule_version_id' <>
       p_rule_version_id::text
     OR v_input.input_payload->>'rule_version_digest' <>
       btrim(v_input.rule_version_digest)
     OR NOT EXISTS (
       SELECT 1
       FROM core.rule_versions AS version
       WHERE version.id = p_rule_version_id
         AND version.rule_id = p_rule_id
         AND version.code_digest ~ '^[0-9a-f]{64}$'
         AND btrim(version.code_digest) = btrim(v_input.rule_version_digest)
     )
     OR v_input.input_payload->>'coverage_status' <>
       v_input.coverage_status
     OR v_input.input_payload ? 'policy'
     OR jsonb_typeof(v_input.input_payload->'coverage')
       IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(
           v_input.input_payload->'coverage'
         )) <> 7
     OR NOT ((v_input.input_payload->'coverage') ?& ARRAY[
       'contracts_complete', 'procurement_notices_complete',
       'procurement_awards_complete', 'bidder_participations_complete',
       'typed_relationships_complete',
       'strong_identifier_facts_complete',
       'bidder_participation_authority'
     ])
     OR EXISTS (
       SELECT 1
       FROM unnest(ARRAY[
         'contracts_complete', 'procurement_notices_complete',
         'procurement_awards_complete', 'bidder_participations_complete',
         'typed_relationships_complete',
         'strong_identifier_facts_complete'
       ]) AS key(name)
       WHERE jsonb_typeof(
         v_input.input_payload->'coverage'->key.name
       ) IS DISTINCT FROM 'boolean'
     )
     OR v_input.input_payload->'coverage'->>
       'bidder_participation_authority' <>
       'koneps-structured-bidder-participation'
     OR EXISTS (
       SELECT 1
       FROM unnest(ARRAY[
         'contracts', 'procurement_notices', 'procurement_awards',
         'bidder_participations', 'typed_relationship_assertions',
         'strong_identifier_facts', 'suppliers', 'sanctions'
       ]) AS key(name)
       WHERE jsonb_typeof(v_input.input_payload->key.name)
         IS DISTINCT FROM 'array'
     ) THEN
    RAISE EXCEPTION 'conflict_input_owner_integrity_mismatch'
      USING ERRCODE = '23514';
  END IF;

  -- Only approved, independently verified typed assertions can enter rule
  -- input.  The closed shape makes PERSON display fields and raw locators
  -- unrepresentable; only digests cross this boundary.
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      v_input.input_payload->'typed_relationship_assertions'
    ) AS item(value)
    WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'object'
       OR (SELECT count(*) FROM jsonb_object_keys(item.value)) <> 27
       OR NOT (item.value ?& ARRAY[
         'relationship_id', 'assertion_revision', 'assertion_digest',
         'relationship_kind', 'subject_kind', 'subject_entity_id',
         'object_kind', 'object_entity_id', 'person_identifier_digest',
         'valid_from', 'valid_to', 'departed_on',
         'validity_coverage_status', 'verification_status',
         'public_use_status', 'independent_human_verification',
         'source_kind', 'source_locators', 'evidence_ids',
         'evidence_count', 'evidence_set_digest', 'proposed_actor_type',
         'proposed_actor_id', 'proposed_by', 'verified_by', 'verified_at',
         'verification_reason_digest'
       ])
       OR item.value->>'relationship_id' !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR item.value->>'assertion_revision' !~ '^[1-9][0-9]*$'
       OR item.value->>'assertion_digest' !~ '^[0-9a-f]{64}$'
       OR item.value->>'relationship_kind' NOT IN (
         'OWNERSHIP', 'CONTROL', 'MANAGEMENT_ROLE',
         'BID_PARTICIPATION', 'SANCTION', 'FORMER_OFFICIAL_ROLE'
       )
       OR item.value->>'subject_kind' NOT IN (
         'SUPPLIER', 'PERSON', 'AGENCY',
         'PROCUREMENT_NOTICE', 'SANCTION'
       )
       OR item.value->>'object_kind' NOT IN (
         'SUPPLIER', 'PERSON', 'AGENCY',
         'PROCUREMENT_NOTICE', 'SANCTION'
       )
       OR item.value->>'validity_coverage_status' <> 'COMPLETE'
       OR item.value->>'verification_status' <> 'VERIFIED'
       OR item.value->>'public_use_status' <> 'APPROVED'
       OR item.value->'independent_human_verification' <> 'true'::jsonb
       OR item.value->>'evidence_count' !~ '^[1-9][0-9]*$'
       OR item.value->>'evidence_set_digest' !~ '^[0-9a-f]{64}$'
       OR item.value->>'verification_reason_digest' !~ '^[0-9a-f]{64}$'
       OR jsonb_typeof(item.value->'source_locators')
         IS DISTINCT FROM 'array'
       OR jsonb_typeof(item.value->'evidence_ids')
         IS DISTINCT FROM 'array'
       OR jsonb_array_length(item.value->'source_locators') <>
         (item.value->>'evidence_count')::integer
       OR jsonb_array_length(item.value->'evidence_ids') <>
         (item.value->>'evidence_count')::integer
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements_text(
           item.value->'source_locators'
         ) AS locator(value)
         WHERE locator.value !~ '^[0-9a-f]{64}$'
       )
       OR item.value ?| ARRAY[
         'person_name', 'person_title', 'contextual_name', 'role_title',
         'source_locator', 'address', 'birth_date', 'resident_number',
         'family_relation', 'score', 'rank', 'probability'
       ]
       OR (
         item.value->>'subject_kind' = 'PERSON'
         AND (
           item.value->>'person_identifier_digest' !~ '^[0-9a-f]{64}$'
           OR item.value->'subject_entity_id' <> 'null'::jsonb
           OR item.value->>'source_kind' NOT IN (
             'DART_EXECUTIVE_STATUS', 'ALIO_EXECUTIVE_STATUS',
             'PUBLIC_OFFICIAL_ETHICS_NOTICE', 'OFFICIAL_GAZETTE'
           )
         )
       )
       OR (
         item.value->>'relationship_kind' = 'FORMER_OFFICIAL_ROLE'
         AND item.value->'departed_on' = 'null'::jsonb
       )
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      v_input.input_payload->'strong_identifier_facts'
    ) AS fact(value)
    WHERE jsonb_typeof(fact.value) IS DISTINCT FROM 'object'
       OR (SELECT count(*) FROM jsonb_object_keys(fact.value)) <> 5
       OR NOT (fact.value ?& ARRAY[
         'supplier_id', 'scheme', 'value_hash',
         'verification_status', 'proof_state'
       ])
       OR fact.value->>'scheme' NOT IN (
         'KOREAN_BUSINESS_NUMBER', 'OPEN_DART_CORP_CODE',
         'KONEPS_PARTY_KEY'
       )
       OR fact.value->>'value_hash' !~ '^[0-9a-f]{64}$'
       OR fact.value->>'verification_status' <> 'VERIFIED'
       OR fact.value->>'proof_state' <> 'PROVEN_V1'
  ) THEN
    RAISE EXCEPTION 'conflict_input_l1_l2_boundary_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*)::bigint INTO v_graph_count
  FROM core.dataset_snapshot_relationship_assertions_v2 AS binding
  WHERE binding.dataset_snapshot_id = p_dataset_snapshot_id
    AND binding.snapshot_generation = p_producer_generation
    AND binding.snapshot_sha256 = p_snapshot_sha256;
  IF v_graph_count <> jsonb_array_length(
       v_input.input_payload->'typed_relationship_assertions'
     ) OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(
         v_input.input_payload->'typed_relationship_assertions'
       ) WITH ORDINALITY AS item(value, ordinality)
       LEFT JOIN core.dataset_snapshot_relationship_assertions_v2 AS binding
         ON binding.dataset_snapshot_id = p_dataset_snapshot_id
        AND binding.snapshot_generation = p_producer_generation
        AND binding.snapshot_sha256 = p_snapshot_sha256
        AND binding.assertion_ordinal = item.ordinality - 1
       WHERE binding.binding_id IS NULL
          OR binding.assertion_id::text IS DISTINCT FROM
            item.value->>'relationship_id'
          OR binding.assertion_revision::text IS DISTINCT FROM
            item.value->>'assertion_revision'
          OR btrim(binding.assertion_digest) IS DISTINCT FROM
            item.value->>'assertion_digest'
          OR binding.binding_digest <> encode(
            extensions.digest(binding.binding_canonical, 'sha256'), 'hex'
          )
     ) THEN
    RAISE EXCEPTION 'conflict_input_frozen_graph_binding_invalid'
      USING ERRCODE = '23514';
  END IF;

  RETURN QUERY SELECT v_input.rule_id, v_input.rule_version_id,
    v_input.coverage_status, v_input.input_payload,
    v_input.input_canonical, v_input.input_sha256;
END
$$;
ALTER FUNCTION core.read_conflict_detection_input_v2(
  uuid,bigint,char(64),text,uuid
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION core.read_conflict_detection_input_v2(
  uuid,bigint,char(64),text,uuid
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION core.read_conflict_detection_input_v2(
  uuid,bigint,char(64),text,uuid
) TO gurine_analysis_worker;

CREATE OR REPLACE FUNCTION core.read_frozen_relationship_assertions_for_rule_v2(
  p_dataset_snapshot_id uuid,
  p_producer_generation bigint,
  p_snapshot_sha256 char(64),
  p_rule_id text,
  p_rule_version_id uuid
) RETURNS TABLE(
  assertion_ordinal bigint,
  assertion_payload jsonb
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_payload jsonb;
BEGIN
  SELECT owner.input_payload INTO STRICT v_payload
  FROM core.read_conflict_detection_input_v2(
    p_dataset_snapshot_id, p_producer_generation, p_snapshot_sha256,
    p_rule_id, p_rule_version_id
  ) AS owner;
  RETURN QUERY
  SELECT item.ordinality - 1, item.value
  FROM jsonb_array_elements(v_payload->'typed_relationship_assertions')
    WITH ORDINALITY AS item(value, ordinality)
  ORDER BY item.ordinality;
END
$$;
ALTER FUNCTION core.read_frozen_relationship_assertions_for_rule_v2(
  uuid,bigint,char(64),text,uuid
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  core.read_frozen_relationship_assertions_for_rule_v2(
    uuid,bigint,char(64),text,uuid
  ) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION
  core.read_frozen_relationship_assertions_for_rule_v2(
    uuid,bigint,char(64),text,uuid
  ) TO gurine_analysis_worker;

-- All runtime writes cross the SECURITY DEFINER builder.  Direct mutation of
-- immutable frozen authorities remains unavailable to service roles.
REVOKE INSERT, UPDATE, DELETE, TRUNCATE
  ON core.dataset_snapshot_conflict_inputs_v2
  FROM gurine_analysis_worker, gurine_control_api, gurine_auditor;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE
  ON core.dataset_snapshot_relationship_assertions_v2
  FROM gurine_analysis_worker, gurine_control_api, gurine_auditor;

-- R6c typed relationship graph owner routines.
-- Integration prerequisite: core.relationship_graph_endpoints_v2 includes
-- identity_resolution_status text NOT NULL, parser_run_id uuid,
-- parsed_record_id uuid, parser_version text and parsed_payload_sha256 char(64).
-- PERSON is PENDING_HUMAN; every other endpoint kind is NOT_APPLICABLE.

CREATE OR REPLACE FUNCTION ops.jsonb_object_has_exact_keys_v1(
  p_value jsonb,
  p_expected text[]
) RETURNS boolean
LANGUAGE sql IMMUTABLE PARALLEL SAFE
SET search_path = pg_catalog, pg_temp
AS $$
  SELECT CASE
    -- CASE is deliberate: jsonb_object_keys rejects scalar and null JSON.
    -- Boolean AND is not an evaluation-order boundary in PostgreSQL.
    WHEN jsonb_typeof(p_value) = 'object' AND p_expected IS NOT NULL THEN
      cardinality(p_expected) = (
        SELECT count(*)::integer FROM jsonb_object_keys(p_value)
      )
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_object_keys(p_value) AS actual(key)
        WHERE NOT (actual.key = ANY (p_expected))
      )
      AND NOT EXISTS (
        SELECT 1
        FROM unnest(p_expected) AS expected(key)
        WHERE expected.key IS NULL OR NOT (p_value ? expected.key)
      )
    ELSE false
  END
$$;
ALTER FUNCTION ops.jsonb_object_has_exact_keys_v1(jsonb,text[])
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.jsonb_object_has_exact_keys_v1(jsonb,text[])
  FROM PUBLIC;

CREATE OR REPLACE FUNCTION core.record_typed_relationship_endpoint_v2(
  p_request jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, raw, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_endpoint_kind text;
  v_contextual_name text;
  v_role_title text;
  v_source_kind text;
  v_source_locator text;
  v_source_locator_digest char(64);
  v_identifier_digest char(64);
  v_entity_id uuid;
  v_entity_revision bigint;
  v_entity_digest char(64);
  v_source jsonb;
  v_source_document_id uuid;
  v_source_asset_id uuid;
  v_source_asset_revision bigint;
  v_source_content_sha256 char(64);
  v_parser_run_id uuid;
  v_parsed_record_id uuid;
  v_parser_version text;
  v_parsed_payload_sha256 char(64);
  v_normalization_run_id uuid;
  v_normalization_version text;
  v_normalization_contract_sha256 char(64);
  v_identity_resolution_status text;
  v_person_node_digest char(64);
  v_endpoint_payload jsonb;
  v_endpoint_canonical bytea;
  v_endpoint_digest char(64);
  v_endpoint_id uuid;
  v_existing core.relationship_graph_endpoints_v2%ROWTYPE;
  v_inserted boolean := false;
BEGIN
  IF NOT ops.jsonb_object_has_exact_keys_v1(p_request, ARRAY[
    'schemaVersion', 'endpointKind', 'contextualName', 'roleTitle',
    'sourceKind', 'sourceLocator', 'identifierDigest', 'entityId',
    'entityRevision', 'entityDigest', 'sourceDocument', 'operationId'
  ]::text[]) THEN
    RAISE EXCEPTION 'typed_relationship_endpoint_request_shape_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF p_request->>'schemaVersion' <>
       'typed-relationship-endpoint.record.request.v2'
     OR p_request->>'operationId' <> 'recordTypedRelationshipEndpoint'
     OR COALESCE(jsonb_typeof(p_request->'endpointKind'), '') <> 'string'
     OR COALESCE(jsonb_typeof(p_request->'sourceKind'), '') <> 'string'
     OR COALESCE(jsonb_typeof(p_request->'sourceLocator'), '') <> 'string'
     OR COALESCE(jsonb_typeof(p_request->'identifierDigest'), '') <> 'string'
     OR NOT ops.jsonb_object_has_exact_keys_v1(
       p_request->'sourceDocument', ARRAY[
         'id', 'assetId', 'assetRevision', 'contentSha256',
         'parserRunId', 'parsedRecordId', 'parserVersion',
         'parsedPayloadSha256'
       ]::text[]
     ) THEN
    RAISE EXCEPTION 'typed_relationship_endpoint_request_invalid'
      USING ERRCODE = '22023';
  END IF;

  v_endpoint_kind := p_request->>'endpointKind';
  v_contextual_name := p_request->>'contextualName';
  v_role_title := p_request->>'roleTitle';
  v_source_kind := p_request->>'sourceKind';
  v_source_locator := p_request->>'sourceLocator';
  v_identifier_digest := p_request->>'identifierDigest';
  v_source := p_request->'sourceDocument';

  IF v_endpoint_kind NOT IN (
       'SUPPLIER', 'PERSON', 'AGENCY', 'PROCUREMENT_NOTICE', 'SANCTION'
     )
     OR nullif(btrim(v_source_kind), '') IS NULL
     OR length(btrim(v_source_kind)) > 100
     OR nullif(btrim(v_source_locator), '') IS NULL
     OR length(btrim(v_source_locator)) > 2048
     OR COALESCE(v_identifier_digest ~ '^[0-9a-f]{64}$', false) = false
     OR COALESCE(v_source->>'id' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
     OR COALESCE(v_source->>'assetId' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
     OR COALESCE(v_source->>'parserRunId' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
     OR COALESCE(v_source->>'parsedRecordId' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
     OR COALESCE(jsonb_typeof(v_source->'assetRevision'), '') <> 'number'
     OR COALESCE((v_source->>'assetRevision')::bigint > 0, false) = false
     OR COALESCE(v_source->>'contentSha256' ~ '^[0-9a-f]{64}$', false) = false
     OR nullif(btrim(v_source->>'parserVersion'), '') IS NULL
     OR COALESCE(
       v_source->>'parsedPayloadSha256' ~ '^[0-9a-f]{64}$',
       false
     ) = false THEN
    RAISE EXCEPTION 'typed_relationship_endpoint_value_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF v_endpoint_kind = 'PERSON' THEN
    IF COALESCE(jsonb_typeof(p_request->'contextualName'), '') <> 'string'
       OR COALESCE(jsonb_typeof(p_request->'roleTitle'), '') <> 'string'
       OR nullif(btrim(v_contextual_name), '') IS NULL
       OR length(btrim(v_contextual_name)) > 300
       OR nullif(btrim(v_role_title), '') IS NULL
       OR length(btrim(v_role_title)) > 300
       OR p_request->'entityId' <> 'null'::jsonb
       OR p_request->'entityRevision' <> 'null'::jsonb
       OR p_request->'entityDigest' <> 'null'::jsonb
       OR v_source_kind NOT IN (
         'DART_EXECUTIVE_STATUS', 'ALIO_EXECUTIVE_STATUS',
         'OFFICIAL_GAZETTE', 'PUBLIC_OFFICIAL_ETHICS_NOTICE'
       ) THEN
      RAISE EXCEPTION 'typed_person_endpoint_l4_boundary_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_identity_resolution_status := 'PENDING_HUMAN';
  ELSE
    IF p_request->'contextualName' <> 'null'::jsonb
       OR p_request->'roleTitle' <> 'null'::jsonb
       OR COALESCE(p_request->>'entityId' ~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
         false) = false
       OR COALESCE(jsonb_typeof(p_request->'entityRevision'), '') <> 'number'
       OR COALESCE((p_request->>'entityRevision')::bigint > 0, false) = false
       OR COALESCE(p_request->>'entityDigest' ~ '^[0-9a-f]{64}$', false) = false THEN
      RAISE EXCEPTION 'typed_nonperson_endpoint_identity_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_entity_id := (p_request->>'entityId')::uuid;
    v_entity_revision := (p_request->>'entityRevision')::bigint;
    v_entity_digest := p_request->>'entityDigest';
    v_identity_resolution_status := 'NOT_APPLICABLE';
    v_contextual_name := NULL;
    v_role_title := NULL;
  END IF;

  v_source_document_id := (v_source->>'id')::uuid;
  v_source_asset_id := (v_source->>'assetId')::uuid;
  v_source_asset_revision := (v_source->>'assetRevision')::bigint;
  v_source_content_sha256 := v_source->>'contentSha256';
  v_parser_run_id := (v_source->>'parserRunId')::uuid;
  v_parsed_record_id := (v_source->>'parsedRecordId')::uuid;
  v_parser_version := v_source->>'parserVersion';
  v_parsed_payload_sha256 := v_source->>'parsedPayloadSha256';
  v_source_locator_digest := encode(
    extensions.digest(convert_to(v_source_locator, 'UTF8'), 'sha256'), 'hex'
  );

  IF v_endpoint_kind = 'PERSON' THEN
    v_person_node_digest := encode(extensions.digest(
      ops.canonical_jsonb_v1(jsonb_build_object(
        'schemaVersion', 'typed-person-node-identity.v2',
        'identifierDigest', btrim(v_identifier_digest),
        'sourceKind', v_source_kind,
        'sourceLocatorDigest', btrim(v_source_locator_digest),
        'sourceDocumentId', v_source_document_id,
        'sourceAssetId', v_source_asset_id,
        'sourceAssetRevision', v_source_asset_revision,
        'sourceContentSha256', btrim(v_source_content_sha256),
        'parserRunId', v_parser_run_id,
        'parsedRecordId', v_parsed_record_id,
        'parserVersion', v_parser_version,
        'parsedPayloadSha256', btrim(v_parsed_payload_sha256)
      )), 'sha256'
    ), 'hex');
  END IF;

  v_endpoint_payload := jsonb_build_object(
    'schemaVersion', 'typed-relationship-endpoint.v2',
    'endpointKind', v_endpoint_kind,
    'identityResolutionStatus', v_identity_resolution_status,
    'entityId', v_entity_id,
    'entityRevision', v_entity_revision,
    'entityDigest', v_entity_digest,
    'contextualName', v_contextual_name,
    'roleTitle', v_role_title,
    'personNodeDigest', v_person_node_digest,
    'sourceKind', v_source_kind,
    'sourceLocator', v_source_locator,
    'sourceLocatorDigest', btrim(v_source_locator_digest),
    'identifierDigest', btrim(v_identifier_digest),
    'sourceDocument', jsonb_build_object(
      'id', v_source_document_id,
      'assetId', v_source_asset_id,
      'assetRevision', v_source_asset_revision,
      'contentSha256', btrim(v_source_content_sha256),
      'parserRunId', v_parser_run_id,
      'parsedRecordId', v_parsed_record_id,
      'parserVersion', v_parser_version,
      'parsedPayloadSha256', btrim(v_parsed_payload_sha256)
    ),
    'createdActor', jsonb_build_object(
      'type', 'SERVICE', 'id', 'ingest-worker'
    )
  );
  v_endpoint_canonical := ops.canonical_jsonb_v1(v_endpoint_payload);
  v_endpoint_digest := encode(
    extensions.digest(v_endpoint_canonical, 'sha256'), 'hex'
  );
  IF v_endpoint_kind = 'PERSON'
     AND v_person_node_digest IN (v_identifier_digest, v_endpoint_digest) THEN
    RAISE EXCEPTION 'typed_person_endpoint_digest_domain_collision'
      USING ERRCODE = '23514';
  END IF;

  SELECT endpoint.* INTO v_existing
  FROM core.relationship_graph_endpoints_v2 AS endpoint
  WHERE endpoint.endpoint_digest = v_endpoint_digest
  FOR SHARE;
  IF FOUND THEN
    IF v_existing.endpoint_payload IS DISTINCT FROM v_endpoint_payload
       OR v_existing.endpoint_canonical IS DISTINCT FROM v_endpoint_canonical THEN
      RAISE EXCEPTION 'typed_relationship_endpoint_digest_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN jsonb_build_object(
      'schemaVersion', 'typed-relationship-endpoint.record.response.v2',
      'endpointId', v_existing.endpoint_id,
      'endpointKind', v_existing.endpoint_kind,
      'endpointDigest', btrim(v_existing.endpoint_digest),
      'identityResolutionStatus', v_existing.identity_resolution_status,
      'replayed', true
    );
  END IF;

  INSERT INTO core.relationship_graph_endpoints_v2(
    endpoint_kind, identity_resolution_status,
    entity_id, entity_revision, entity_digest,
    contextual_name, role_title, person_node_digest,
    source_locator, source_locator_digest, identifier_digest,
    source_document_id, source_asset_id, source_asset_revision,
    source_content_sha256, parser_run_id, parsed_record_id,
    parser_version, parsed_payload_sha256,
    normalization_run_id, normalization_version,
    normalization_contract_sha256,
    endpoint_payload, endpoint_canonical, endpoint_digest,
    created_actor_type, created_actor_id, created_by
  ) VALUES (
    v_endpoint_kind, v_identity_resolution_status,
    v_entity_id, v_entity_revision, v_entity_digest,
    v_contextual_name, v_role_title, v_person_node_digest,
    v_source_locator, v_source_locator_digest, v_identifier_digest,
    v_source_document_id, v_source_asset_id, v_source_asset_revision,
    v_source_content_sha256, v_parser_run_id, v_parsed_record_id,
    v_parser_version, v_parsed_payload_sha256,
    NULL, NULL, NULL,
    v_endpoint_payload, v_endpoint_canonical, v_endpoint_digest,
    'SERVICE', 'ingest-worker', NULL
  )
  ON CONFLICT (endpoint_digest) DO NOTHING
  RETURNING endpoint_id INTO v_endpoint_id;
  v_inserted := FOUND;

  IF NOT v_inserted THEN
    SELECT endpoint.* INTO STRICT v_existing
    FROM core.relationship_graph_endpoints_v2 AS endpoint
    WHERE endpoint.endpoint_digest = v_endpoint_digest
    FOR SHARE;
    v_endpoint_id := v_existing.endpoint_id;
  END IF;

  RETURN jsonb_build_object(
    'schemaVersion', 'typed-relationship-endpoint.record.response.v2',
    'endpointId', v_endpoint_id,
    'endpointKind', v_endpoint_kind,
    'endpointDigest', btrim(v_endpoint_digest),
    'identityResolutionStatus', v_identity_resolution_status,
    'replayed', NOT v_inserted
  );
END
$$;
ALTER FUNCTION core.record_typed_relationship_endpoint_v2(jsonb)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION core.record_typed_relationship_endpoint_v2(jsonb)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION core.record_typed_relationship_endpoint_v2(jsonb)
  TO gurine_ingest_worker;

CREATE OR REPLACE FUNCTION core.record_typed_relationship_assertion_v2(
  p_request jsonb
) RETURNS TABLE(
  assertion_id uuid,
  assertion_revision bigint,
  assertion_digest char(64),
  receipt_sha256 char(64),
  verification_status text,
  public_use_status text,
  disposition text,
  replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, raw, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_assertion_id uuid;
  v_relationship_kind text;
  v_source_kind text;
  v_source_locator text;
  v_source_locator_digest char(64);
  v_subject_ref jsonb;
  v_object_ref jsonb;
  v_subject core.relationship_graph_endpoints_v2%ROWTYPE;
  v_object core.relationship_graph_endpoints_v2%ROWTYPE;
  v_valid_from date;
  v_valid_to date;
  v_departed_on date;
  v_coverage text;
  v_actor jsonb;
  v_actor_type text;
  v_actor_id text;
  v_actor_user_id uuid;
  v_session_actor text;
  v_evidence jsonb;
  v_evidence_payload jsonb;
  v_evidence_canonical bytea;
  v_evidence_member_digest char(64);
  v_evidence_members jsonb := '[]'::jsonb;
  v_evidence_digests jsonb;
  v_evidence_count integer;
  v_evidence_set_digest char(64);
  v_source_document jsonb;
  v_source_use jsonb;
  v_assertion_payload jsonb;
  v_assertion_canonical bytea;
  v_assertion_digest char(64);
  v_receipt_payload jsonb;
  v_receipt_canonical bytea;
  v_receipt_sha256 char(64);
  v_created_at timestamptz := clock_timestamp();
  v_existing core.relationship_graph_assertions_v2%ROWTYPE;
  v_actual_count bigint;
  v_actual_set_digest char(64);
  v_ordinal integer := 0;
  v_member jsonb;
BEGIN
  IF NOT ops.jsonb_object_has_exact_keys_v1(p_request, ARRAY[
    'schemaVersion', 'assertionId', 'relationshipKind', 'sourceKind',
    'sourceLocator',
    'subjectEndpoint', 'objectEndpoint', 'validFrom', 'validTo',
    'departedOn', 'validityCoverageStatus', 'evidence',
    'proposedActor', 'operationId'
  ]::text[]) THEN
    RAISE EXCEPTION 'typed_relationship_assertion_request_shape_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF p_request->>'schemaVersion' <>
       'typed-relationship-assertion.record.request.v2'
     OR p_request->>'operationId' <> 'recordTypedRelationshipAssertion'
     OR COALESCE(p_request->>'assertionId' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
     OR COALESCE(jsonb_typeof(p_request->'relationshipKind'), '') <> 'string'
     OR COALESCE(jsonb_typeof(p_request->'sourceKind'), '') <> 'string'
     OR COALESCE(jsonb_typeof(p_request->'sourceLocator'), '') <> 'string'
     OR NOT ops.jsonb_object_has_exact_keys_v1(
       p_request->'subjectEndpoint',
       ARRAY['endpointId', 'endpointKind', 'endpointDigest']::text[]
     )
     OR NOT ops.jsonb_object_has_exact_keys_v1(
       p_request->'objectEndpoint',
       ARRAY['endpointId', 'endpointKind', 'endpointDigest']::text[]
     )
     OR COALESCE(jsonb_typeof(p_request->'evidence'), '') <> 'array'
     OR jsonb_array_length(p_request->'evidence') NOT BETWEEN 1 AND 1000
     OR NOT ops.jsonb_object_has_exact_keys_v1(
       p_request->'proposedActor', ARRAY['type', 'id']::text[]
     ) THEN
    RAISE EXCEPTION 'typed_relationship_assertion_request_invalid'
      USING ERRCODE = '22023';
  END IF;

  v_assertion_id := (p_request->>'assertionId')::uuid;
  v_relationship_kind := p_request->>'relationshipKind';
  v_source_kind := p_request->>'sourceKind';
  v_source_locator := p_request->>'sourceLocator';
  v_subject_ref := p_request->'subjectEndpoint';
  v_object_ref := p_request->'objectEndpoint';
  v_coverage := p_request->>'validityCoverageStatus';
  v_actor := p_request->'proposedActor';
  v_actor_type := v_actor->>'type';
  v_actor_id := v_actor->>'id';

  IF v_relationship_kind NOT IN (
       'OWNERSHIP', 'BENEFICIAL_OWNERSHIP', 'CONTROL', 'MANAGEMENT_ROLE',
       'LEGAL_REPRESENTATIVE', 'CONTRACTUAL_RELATIONSHIP',
       'BID_PARTICIPATION', 'SANCTION', 'FORMER_OFFICIAL_ROLE'
     )
     OR nullif(btrim(v_source_kind), '') IS NULL
     OR length(btrim(v_source_kind)) > 128
     OR nullif(btrim(v_source_locator), '') IS NULL
     OR length(btrim(v_source_locator)) > 2048
     OR v_coverage NOT IN ('COMPLETE', 'PARTIAL', 'UNKNOWN', 'NOT_AVAILABLE')
     OR COALESCE(v_subject_ref->>'endpointId' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
     OR COALESCE(v_object_ref->>'endpointId' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
     OR COALESCE(v_subject_ref->>'endpointDigest' ~ '^[0-9a-f]{64}$', false)
       = false
     OR COALESCE(v_object_ref->>'endpointDigest' ~ '^[0-9a-f]{64}$', false)
       = false THEN
    RAISE EXCEPTION 'typed_relationship_assertion_value_invalid'
      USING ERRCODE = '22023';
  END IF;

  v_source_locator_digest := encode(
    extensions.digest(convert_to(v_source_locator, 'UTF8'), 'sha256'), 'hex'
  );

  IF p_request->'validFrom' <> 'null'::jsonb THEN
    IF COALESCE(jsonb_typeof(p_request->'validFrom'), '') <> 'string'
       OR COALESCE(p_request->>'validFrom' ~ '^\d{4}-\d{2}-\d{2}$', false)
         = false THEN
      RAISE EXCEPTION 'typed_relationship_valid_from_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_valid_from := (p_request->>'validFrom')::date;
    IF to_char(v_valid_from, 'YYYY-MM-DD') <> p_request->>'validFrom' THEN
      RAISE EXCEPTION 'typed_relationship_valid_from_invalid'
        USING ERRCODE = '22023';
    END IF;
  END IF;
  IF p_request->'validTo' <> 'null'::jsonb THEN
    IF COALESCE(jsonb_typeof(p_request->'validTo'), '') <> 'string'
       OR COALESCE(p_request->>'validTo' ~ '^\d{4}-\d{2}-\d{2}$', false)
         = false THEN
      RAISE EXCEPTION 'typed_relationship_valid_to_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_valid_to := (p_request->>'validTo')::date;
    IF to_char(v_valid_to, 'YYYY-MM-DD') <> p_request->>'validTo' THEN
      RAISE EXCEPTION 'typed_relationship_valid_to_invalid'
        USING ERRCODE = '22023';
    END IF;
  END IF;
  IF p_request->'departedOn' <> 'null'::jsonb THEN
    IF COALESCE(jsonb_typeof(p_request->'departedOn'), '') <> 'string'
       OR COALESCE(p_request->>'departedOn' ~ '^\d{4}-\d{2}-\d{2}$', false)
         = false THEN
      RAISE EXCEPTION 'typed_relationship_departed_on_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_departed_on := (p_request->>'departedOn')::date;
    IF to_char(v_departed_on, 'YYYY-MM-DD') <> p_request->>'departedOn' THEN
      RAISE EXCEPTION 'typed_relationship_departed_on_invalid'
        USING ERRCODE = '22023';
    END IF;
  END IF;
  IF v_valid_from IS NOT NULL AND v_valid_to IS NOT NULL
     AND v_valid_from > v_valid_to THEN
    RAISE EXCEPTION 'typed_relationship_validity_window_invalid'
      USING ERRCODE = '23514';
  END IF;
  IF (
       v_relationship_kind = 'FORMER_OFFICIAL_ROLE'
       AND (
         v_departed_on IS NULL OR v_valid_to IS DISTINCT FROM v_departed_on
         OR v_source_kind NOT IN (
           'PUBLIC_OFFICIAL_ETHICS_NOTICE', 'OFFICIAL_GAZETTE'
         )
       )
     ) OR (
       v_relationship_kind <> 'FORMER_OFFICIAL_ROLE'
       AND v_departed_on IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'typed_relationship_departure_contract_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF v_actor_type = 'SERVICE' THEN
    IF v_actor_id <> 'ingest-worker'
       OR NOT pg_has_role(session_user, 'gurine_ingest_worker', 'MEMBER') THEN
      RAISE EXCEPTION 'typed_relationship_service_proposer_invalid'
        USING ERRCODE = '42501';
    END IF;
  ELSIF v_actor_type = 'HUMAN' THEN
    IF COALESCE(v_actor_id ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
       OR NOT pg_has_role(session_user, 'gurine_identity_api', 'MEMBER') THEN
      RAISE EXCEPTION 'typed_relationship_human_proposer_invalid'
        USING ERRCODE = '42501';
    END IF;
    v_actor_user_id := v_actor_id::uuid;
    IF NOT EXISTS (
      SELECT 1 FROM ops.users AS active_user
      WHERE active_user.id = v_actor_user_id
        AND active_user.status = 'ACTIVE'
    ) THEN
      RAISE EXCEPTION 'typed_relationship_human_proposer_inactive'
        USING ERRCODE = '28000';
    END IF;
    v_session_actor := nullif(
      current_setting('gurine.actor_user_id', true), ''
    );
    IF v_session_actor IS NULL
       OR v_session_actor IS DISTINCT FROM v_actor_id THEN
      RAISE EXCEPTION 'typed_relationship_human_proposer_mismatch'
        USING ERRCODE = '28000';
    END IF;
  ELSE
    RAISE EXCEPTION 'typed_relationship_proposer_type_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT endpoint.* INTO v_subject
  FROM core.relationship_graph_endpoints_v2 AS endpoint
  WHERE endpoint.endpoint_id = (v_subject_ref->>'endpointId')::uuid
    AND endpoint.endpoint_kind = v_subject_ref->>'endpointKind'
    AND endpoint.endpoint_digest = v_subject_ref->>'endpointDigest'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'typed_relationship_subject_endpoint_not_found'
      USING ERRCODE = 'P0002';
  END IF;
  SELECT endpoint.* INTO v_object
  FROM core.relationship_graph_endpoints_v2 AS endpoint
  WHERE endpoint.endpoint_id = (v_object_ref->>'endpointId')::uuid
    AND endpoint.endpoint_kind = v_object_ref->>'endpointKind'
    AND endpoint.endpoint_digest = v_object_ref->>'endpointDigest'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'typed_relationship_object_endpoint_not_found'
      USING ERRCODE = 'P0002';
  END IF;
  IF v_subject.endpoint_kind = 'PERSON'
     AND v_subject.endpoint_payload->>'sourceKind' IS DISTINCT FROM v_source_kind THEN
    RAISE EXCEPTION 'typed_relationship_person_source_kind_mismatch'
      USING ERRCODE = '23514';
  END IF;

  FOR v_evidence IN
    SELECT item.value
    FROM jsonb_array_elements(p_request->'evidence') AS item(value)
  LOOP
    IF NOT ops.jsonb_object_has_exact_keys_v1(v_evidence, ARRAY[
      'evidenceId', 'evidenceVersion', 'evidenceDigest',
      'sourceDocument', 'sourceUse', 'locatorDigest'
    ]::text[])
       OR COALESCE(v_evidence->>'evidenceId' ~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
         false) = false
       OR COALESCE(jsonb_typeof(v_evidence->'evidenceVersion'), '') <> 'number'
       OR COALESCE((v_evidence->>'evidenceVersion')::bigint > 0, false) = false
       OR COALESCE(v_evidence->>'evidenceDigest' ~ '^[0-9a-f]{64}$', false)
         = false
       OR COALESCE(v_evidence->>'locatorDigest' ~ '^[0-9a-f]{64}$', false)
         = false
       OR num_nonnulls(
         CASE WHEN v_evidence->'sourceDocument' <> 'null'::jsonb
           THEN v_evidence->'sourceDocument' END,
         CASE WHEN v_evidence->'sourceUse' <> 'null'::jsonb
           THEN v_evidence->'sourceUse' END
       ) <> 1 THEN
      RAISE EXCEPTION 'typed_relationship_evidence_shape_invalid'
        USING ERRCODE = '22023';
    END IF;

    v_source_document := v_evidence->'sourceDocument';
    v_source_use := v_evidence->'sourceUse';
    IF v_source_document <> 'null'::jsonb THEN
      IF NOT ops.jsonb_object_has_exact_keys_v1(v_source_document, ARRAY[
        'id', 'assetId', 'assetRevision', 'contentSha256'
      ]::text[])
         OR COALESCE(v_source_document->>'id' ~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
           false) = false
         OR COALESCE(v_source_document->>'assetId' ~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
           false) = false
         OR COALESCE(jsonb_typeof(v_source_document->'assetRevision'), '')
           <> 'number'
         OR COALESCE((v_source_document->>'assetRevision')::bigint > 0, false)
           = false
         OR COALESCE(
           v_source_document->>'contentSha256' ~ '^[0-9a-f]{64}$', false
         ) = false THEN
        RAISE EXCEPTION 'typed_relationship_evidence_document_invalid'
          USING ERRCODE = '22023';
      END IF;
    ELSE
      IF NOT ops.jsonb_object_has_exact_keys_v1(v_source_use, ARRAY[
        'agentRunId', 'sourceUseId', 'sourceUseSha256'
      ]::text[])
         OR COALESCE(v_source_use->>'agentRunId' ~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
           false) = false
         OR COALESCE(v_source_use->>'sourceUseId' ~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
           false) = false
         OR COALESCE(
           v_source_use->>'sourceUseSha256' ~ '^[0-9a-f]{64}$', false
         ) = false THEN
        RAISE EXCEPTION 'typed_relationship_evidence_source_use_invalid'
          USING ERRCODE = '22023';
      END IF;
    END IF;

    v_evidence_payload := jsonb_build_object(
      'schemaVersion', 'typed-relationship-assertion-evidence.v2',
      'evidenceId', (v_evidence->>'evidenceId')::uuid,
      'evidenceVersion', (v_evidence->>'evidenceVersion')::bigint,
      'evidenceDigest', v_evidence->>'evidenceDigest',
      'sourceDocument', v_source_document,
      'sourceUse', v_source_use,
      'locatorDigest', v_evidence->>'locatorDigest'
    );
    v_evidence_canonical := ops.canonical_jsonb_v1(v_evidence_payload);
    v_evidence_member_digest := encode(
      extensions.digest(v_evidence_canonical, 'sha256'), 'hex'
    );
    v_evidence_members := v_evidence_members || jsonb_build_array(
      jsonb_build_object(
        'payload', v_evidence_payload,
        'memberDigest', btrim(v_evidence_member_digest)
      )
    );
  END LOOP;

  SELECT count(*)::integer,
         count(DISTINCT member.value->>'memberDigest')::integer,
         jsonb_agg(
           to_jsonb(member.value->>'memberDigest')
           ORDER BY member.value->>'memberDigest'
         )
  INTO v_evidence_count, v_ordinal, v_evidence_digests
  FROM jsonb_array_elements(v_evidence_members) AS member(value);
  IF v_evidence_count IS NULL OR v_evidence_count < 1
     OR v_ordinal <> v_evidence_count THEN
    RAISE EXCEPTION 'typed_relationship_evidence_set_not_unique'
      USING ERRCODE = '23514';
  END IF;
  v_evidence_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_evidence_digests), 'sha256'
  ), 'hex');

  v_assertion_payload := jsonb_build_object(
    'schemaVersion', 'typed-relationship-assertion.v2',
    'assertionId', v_assertion_id,
    'assertionRevision', 1,
    'relationshipKind', v_relationship_kind,
    'sourceKind', v_source_kind,
    'sourceLocator', v_source_locator,
    'sourceLocatorDigest', btrim(v_source_locator_digest),
    'subjectEndpoint', jsonb_build_object(
      'endpointId', v_subject.endpoint_id,
      'endpointKind', v_subject.endpoint_kind,
      'endpointDigest', btrim(v_subject.endpoint_digest)
    ),
    'objectEndpoint', jsonb_build_object(
      'endpointId', v_object.endpoint_id,
      'endpointKind', v_object.endpoint_kind,
      'endpointDigest', btrim(v_object.endpoint_digest)
    ),
    'validFrom', v_valid_from,
    'validTo', v_valid_to,
    'departedOn', v_departed_on,
    'validityCoverageStatus', v_coverage,
    'verificationStatus', 'PENDING_HUMAN',
    'publicUseStatus', 'NOT_REVIEWED',
    'evidenceCount', v_evidence_count,
    'evidenceSetDigest', btrim(v_evidence_set_digest),
    'evidenceMemberDigests', v_evidence_digests,
    'proposedActor', jsonb_build_object(
      'type', v_actor_type, 'id', v_actor_id
    ),
    'verifiedBy', NULL,
    'verifiedAt', NULL,
    'verificationReasonDigest', NULL
  );
  v_assertion_canonical := ops.canonical_jsonb_v1(v_assertion_payload);
  v_assertion_digest := encode(
    extensions.digest(v_assertion_canonical, 'sha256'), 'hex'
  );

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'TYPED_RELATIONSHIP_ASSERTION:' || v_assertion_id::text, 0
  ));
  SELECT assertion.* INTO v_existing
  FROM core.relationship_graph_assertions_v2 AS assertion
  WHERE assertion.assertion_id = v_assertion_id
    AND assertion.assertion_revision = 1
  FOR SHARE;
  IF FOUND THEN
    SELECT count(*)::bigint,
           encode(extensions.digest(ops.canonical_jsonb_v1(
             COALESCE(jsonb_agg(
               to_jsonb(btrim(evidence.evidence_member_digest))
               ORDER BY evidence.evidence_member_digest
             ), '[]'::jsonb)
           ), 'sha256'), 'hex')
    INTO v_actual_count, v_actual_set_digest
    FROM core.relationship_graph_assertion_evidence_v2 AS evidence
    WHERE evidence.assertion_id = v_existing.assertion_id
      AND evidence.assertion_revision = v_existing.assertion_revision;
    IF v_existing.assertion_digest IS DISTINCT FROM v_assertion_digest
       OR v_existing.assertion_payload IS DISTINCT FROM v_assertion_payload
       OR v_existing.evidence_count IS DISTINCT FROM v_actual_count
       OR v_existing.evidence_set_digest IS DISTINCT FROM v_actual_set_digest THEN
      RAISE EXCEPTION 'typed_relationship_assertion_replay_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN QUERY SELECT
      v_existing.assertion_id, v_existing.assertion_revision,
      v_existing.assertion_digest, v_existing.receipt_sha256,
      v_existing.verification_status, v_existing.public_use_status,
      'PENDING_HUMAN'::text, true;
    RETURN;
  END IF;

  v_receipt_payload := jsonb_build_object(
    'schemaVersion', 'typed-relationship-assertion-record-receipt.v2',
    'assertionId', v_assertion_id,
    'assertionRevision', 1,
    'assertionDigest', btrim(v_assertion_digest),
    'verificationStatus', 'PENDING_HUMAN',
    'publicUseStatus', 'NOT_REVIEWED',
    'evidenceCount', v_evidence_count,
    'evidenceSetDigest', btrim(v_evidence_set_digest),
    'proposedActor', jsonb_build_object(
      'type', v_actor_type, 'id', v_actor_id
    ),
    'recordedAt', v_created_at
  );
  v_receipt_canonical := ops.canonical_jsonb_v1(v_receipt_payload);
  v_receipt_sha256 := encode(
    extensions.digest(v_receipt_canonical, 'sha256'), 'hex'
  );

  INSERT INTO core.relationship_graph_assertions_v2(
    assertion_id, assertion_revision, assertion_digest,
    predecessor_revision, predecessor_digest, prior_receipt_sha256,
    relationship_kind, source_kind, source_locator, source_locator_digest,
    subject_endpoint_id, subject_endpoint_kind, subject_endpoint_digest,
    object_endpoint_id, object_endpoint_kind, object_endpoint_digest,
    valid_from, valid_to, departed_on, validity_coverage_status,
    verification_status, public_use_status,
    evidence_count, evidence_set_digest,
    proposed_actor_type, proposed_actor_id, proposed_by,
    verified_by, verified_at, verification_reason_digest,
    assertion_payload, assertion_canonical,
    receipt_payload, receipt_canonical, receipt_sha256, created_at
  ) VALUES (
    v_assertion_id, 1, v_assertion_digest,
    NULL, NULL, NULL,
    v_relationship_kind, v_source_kind,
    v_source_locator, v_source_locator_digest,
    v_subject.endpoint_id, v_subject.endpoint_kind, v_subject.endpoint_digest,
    v_object.endpoint_id, v_object.endpoint_kind, v_object.endpoint_digest,
    v_valid_from, v_valid_to, v_departed_on, v_coverage,
    'PENDING_HUMAN', 'NOT_REVIEWED',
    v_evidence_count, v_evidence_set_digest,
    v_actor_type, v_actor_id, v_actor_user_id,
    NULL, NULL, NULL,
    v_assertion_payload, v_assertion_canonical,
    v_receipt_payload, v_receipt_canonical, v_receipt_sha256, v_created_at
  );

  v_ordinal := 0;
  FOR v_member IN
    SELECT item.value
    FROM jsonb_array_elements(v_evidence_members) AS item(value)
    ORDER BY item.value->>'memberDigest'
  LOOP
    v_evidence_payload := v_member->'payload';
    v_source_document := v_evidence_payload->'sourceDocument';
    v_source_use := v_evidence_payload->'sourceUse';
    INSERT INTO core.relationship_graph_assertion_evidence_v2(
      assertion_id, assertion_revision, assertion_digest,
      evidence_ordinal, evidence_id, evidence_version, evidence_digest,
      source_document_id, source_asset_id, source_asset_revision,
      source_content_sha256,
      source_use_agent_run_id, source_use_id, source_use_sha256,
      locator_digest, evidence_binding_canonical, evidence_member_digest,
      created_at
    ) VALUES (
      v_assertion_id, 1, v_assertion_digest,
      v_ordinal,
      (v_evidence_payload->>'evidenceId')::uuid,
      (v_evidence_payload->>'evidenceVersion')::bigint,
      v_evidence_payload->>'evidenceDigest',
      CASE WHEN v_source_document <> 'null'::jsonb
        THEN (v_source_document->>'id')::uuid END,
      CASE WHEN v_source_document <> 'null'::jsonb
        THEN (v_source_document->>'assetId')::uuid END,
      CASE WHEN v_source_document <> 'null'::jsonb
        THEN (v_source_document->>'assetRevision')::bigint END,
      CASE WHEN v_source_document <> 'null'::jsonb
        THEN v_source_document->>'contentSha256' END,
      CASE WHEN v_source_use <> 'null'::jsonb
        THEN (v_source_use->>'agentRunId')::uuid END,
      CASE WHEN v_source_use <> 'null'::jsonb
        THEN (v_source_use->>'sourceUseId')::uuid END,
      CASE WHEN v_source_use <> 'null'::jsonb
        THEN v_source_use->>'sourceUseSha256' END,
      v_evidence_payload->>'locatorDigest',
      ops.canonical_jsonb_v1(v_evidence_payload),
      v_member->>'memberDigest', v_created_at
    );
    v_ordinal := v_ordinal + 1;
  END LOOP;

  RETURN QUERY SELECT
    v_assertion_id, 1::bigint, v_assertion_digest, v_receipt_sha256,
    'PENDING_HUMAN'::text, 'NOT_REVIEWED'::text,
    'PENDING_HUMAN'::text, false;
END
$$;
ALTER FUNCTION core.record_typed_relationship_assertion_v2(jsonb)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION core.record_typed_relationship_assertion_v2(jsonb)
  FROM PUBLIC;
-- 0016 intentionally removed identity-api's broad core access.  Restore only
-- schema name resolution for the two typed graph owner routines below; no
-- relation privilege is granted by schema USAGE.
GRANT USAGE ON SCHEMA core TO gurine_identity_api;
GRANT EXECUTE ON FUNCTION core.record_typed_relationship_assertion_v2(jsonb)
  TO gurine_ingest_worker, gurine_identity_api;

CREATE OR REPLACE FUNCTION core.decide_typed_relationship_assertion_v2(
  p_assertion_id uuid,
  p_request jsonb
) RETURNS TABLE(
  decision_id uuid,
  assertion_id uuid,
  assertion_revision bigint,
  assertion_digest char(64),
  verification_status text,
  public_use_status text,
  receipt_sha256 char(64),
  replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_decision_kind text;
  v_reason_code text;
  v_reason text;
  v_reason_digest char(64);
  v_actor_user_id uuid;
  v_session_actor text;
  v_request_payload jsonb;
  v_current core.relationship_graph_assertions_v2%ROWTYPE;
  v_status text;
  v_public_use_status text;
  v_revision bigint;
  v_decision_id uuid := gen_random_uuid();
  v_decision_payload jsonb;
  v_decision_canonical bytea;
  v_decision_digest char(64);
  v_assertion_payload jsonb;
  v_assertion_canonical bytea;
  v_assertion_digest char(64);
  v_receipt_payload jsonb;
  v_receipt_canonical bytea;
  v_receipt_sha256 char(64);
  v_decided_at timestamptz := clock_timestamp();
  v_evidence_count bigint;
  v_evidence_digests jsonb;
  v_evidence_set_digest char(64);
  v_evidence record;
  v_prior_decision core.relationship_graph_verification_decisions_v2%ROWTYPE;
  v_prior_result core.relationship_graph_assertions_v2%ROWTYPE;
BEGIN
  IF p_assertion_id IS NULL
     OR NOT ops.jsonb_object_has_exact_keys_v1(p_request, ARRAY[
       'schemaVersion', 'decision', 'reasonCode', 'reason',
       'actorUserId', 'operationId'
     ]::text[]) THEN
    RAISE EXCEPTION 'typed_relationship_decision_request_shape_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF p_request->>'schemaVersion' <>
       'typed-relationship-assertion.decision.request.v2'
     OR p_request->>'operationId' <> 'decideTypedRelationshipAssertion'
     OR COALESCE(jsonb_typeof(p_request->'decision'), '') <> 'string'
     OR COALESCE(jsonb_typeof(p_request->'reasonCode'), '') <> 'string'
     OR COALESCE(jsonb_typeof(p_request->'reason'), '') <> 'string'
     OR COALESCE(p_request->>'actorUserId' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false THEN
    RAISE EXCEPTION 'typed_relationship_decision_request_invalid'
      USING ERRCODE = '22023';
  END IF;
  v_decision_kind := p_request->>'decision';
  v_reason_code := p_request->>'reasonCode';
  v_reason := p_request->>'reason';
  v_actor_user_id := (p_request->>'actorUserId')::uuid;
  IF v_decision_kind NOT IN ('VERIFY', 'REJECT', 'MARK_CONFLICT', 'SUPERSEDE')
     OR nullif(btrim(v_reason_code), '') IS NULL
     OR length(btrim(v_reason_code)) > 100
     OR nullif(btrim(v_reason), '') IS NULL
     OR octet_length(v_reason) > 2000
     OR NOT pg_has_role(session_user, 'gurine_identity_api', 'MEMBER') THEN
    RAISE EXCEPTION 'typed_relationship_decision_value_invalid'
      USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM ops.users AS active_user
    WHERE active_user.id = v_actor_user_id
      AND active_user.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'typed_relationship_reviewer_inactive'
      USING ERRCODE = '28000';
  END IF;
  v_session_actor := nullif(
    current_setting('gurine.actor_user_id', true), ''
  );
  IF v_session_actor IS NULL
     OR v_session_actor IS DISTINCT FROM v_actor_user_id::text THEN
    RAISE EXCEPTION 'typed_relationship_reviewer_mismatch'
      USING ERRCODE = '28000';
  END IF;

  v_request_payload := jsonb_build_object(
    'schemaVersion', 'typed-relationship-assertion.decision.request.v2',
    'decision', v_decision_kind,
    'reasonCode', v_reason_code,
    'reason', v_reason,
    'actorUserId', v_actor_user_id,
    'operationId', 'decideTypedRelationshipAssertion'
  );

  -- Serialize exact replays with the first decision writer.  Without taking
  -- the assertion lock before replay lookup, a concurrent retry can miss the
  -- decision and then observe only the already-decided assertion revision.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'TYPED_RELATIONSHIP_ASSERTION:' || p_assertion_id::text, 0
  ));
  SELECT decision.*
  INTO v_prior_decision
  FROM core.relationship_graph_verification_decisions_v2 AS decision
  JOIN core.relationship_graph_assertions_v2 AS result
    ON result.assertion_id = decision.assertion_id
   AND result.assertion_revision = decision.resulting_assertion_revision
   AND result.assertion_digest = decision.resulting_assertion_digest
  WHERE decision.assertion_id = p_assertion_id
    AND decision.decision_payload->'request' = v_request_payload
  ORDER BY decision.decided_at DESC
  LIMIT 1;
  IF FOUND THEN
    SELECT result.*
    INTO STRICT v_prior_result
    FROM core.relationship_graph_assertions_v2 AS result
    WHERE result.assertion_id = v_prior_decision.assertion_id
      AND result.assertion_revision =
        v_prior_decision.resulting_assertion_revision
      AND result.assertion_digest =
        v_prior_decision.resulting_assertion_digest;
    RETURN QUERY SELECT
      v_prior_decision.decision_id,
      v_prior_result.assertion_id,
      v_prior_result.assertion_revision,
      v_prior_result.assertion_digest,
      v_prior_result.verification_status,
      v_prior_result.public_use_status,
      v_prior_decision.receipt_sha256,
      true;
    RETURN;
  END IF;

  SELECT assertion.* INTO v_current
  FROM core.relationship_graph_assertions_v2 AS assertion
  WHERE assertion.assertion_id = p_assertion_id
  ORDER BY assertion.assertion_revision DESC
  LIMIT 1
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'typed_relationship_assertion_not_found'
      USING ERRCODE = 'P0002';
  END IF;
  IF v_current.verification_status <> 'PENDING_HUMAN'
     OR v_current.public_use_status <> 'NOT_REVIEWED' THEN
    RAISE EXCEPTION 'typed_relationship_assertion_already_decided'
      USING ERRCODE = '40001';
  END IF;
  IF v_actor_user_id IS NOT DISTINCT FROM v_current.proposed_by THEN
    RAISE EXCEPTION 'typed_relationship_independent_reviewer_required'
      USING ERRCODE = '42501';
  END IF;
  IF v_decision_kind = 'VERIFY'
     AND v_current.validity_coverage_status <> 'COMPLETE' THEN
    RAISE EXCEPTION 'typed_relationship_verify_requires_complete_coverage'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*)::bigint,
         COALESCE(jsonb_agg(
           to_jsonb(btrim(evidence.evidence_member_digest))
           ORDER BY evidence.evidence_member_digest
         ), '[]'::jsonb)
  INTO v_evidence_count, v_evidence_digests
  FROM core.relationship_graph_assertion_evidence_v2 AS evidence
  WHERE evidence.assertion_id = v_current.assertion_id
    AND evidence.assertion_revision = v_current.assertion_revision;
  v_evidence_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_evidence_digests), 'sha256'
  ), 'hex');
  IF v_evidence_count IS DISTINCT FROM v_current.evidence_count::bigint
     OR v_evidence_set_digest IS DISTINCT FROM v_current.evidence_set_digest THEN
    RAISE EXCEPTION 'typed_relationship_evidence_set_drift'
      USING ERRCODE = '23514';
  END IF;

  v_status := CASE v_decision_kind
    WHEN 'VERIFY' THEN 'VERIFIED'
    WHEN 'REJECT' THEN 'REJECTED'
    WHEN 'MARK_CONFLICT' THEN 'CONFLICTED'
    WHEN 'SUPERSEDE' THEN 'SUPERSEDED'
  END;
  v_public_use_status := CASE
    WHEN v_decision_kind = 'VERIFY' THEN 'APPROVED'
    ELSE 'DENIED'
  END;
  v_revision := v_current.assertion_revision + 1;
  v_reason_digest := encode(
    extensions.digest(convert_to(v_reason, 'UTF8'), 'sha256'), 'hex'
  );
  v_decision_payload := jsonb_build_object(
    'schemaVersion', 'typed-relationship-verification-decision.v2',
    'decisionId', v_decision_id,
    'assertionId', p_assertion_id,
    'priorAssertionRevision', v_current.assertion_revision,
    'priorAssertionDigest', btrim(v_current.assertion_digest),
    'priorReceiptSha256', btrim(v_current.receipt_sha256),
    'request', v_request_payload,
    'reasonDigest', btrim(v_reason_digest),
    'resultingVerificationStatus', v_status,
    'resultingPublicUseStatus', v_public_use_status
  );
  v_decision_canonical := ops.canonical_jsonb_v1(v_decision_payload);
  v_decision_digest := encode(
    extensions.digest(v_decision_canonical, 'sha256'), 'hex'
  );

  v_assertion_payload := v_current.assertion_payload || jsonb_build_object(
    'assertionRevision', v_revision,
    'predecessorRevision', v_current.assertion_revision,
    'predecessorDigest', btrim(v_current.assertion_digest),
    'priorReceiptSha256', btrim(v_current.receipt_sha256),
    'verificationStatus', v_status,
    'publicUseStatus', v_public_use_status,
    'verifiedBy', v_actor_user_id,
    'verifiedAt', v_decided_at,
    'verificationReasonDigest', btrim(v_reason_digest),
    'decisionDigest', btrim(v_decision_digest)
  );
  v_assertion_canonical := ops.canonical_jsonb_v1(v_assertion_payload);
  v_assertion_digest := encode(
    extensions.digest(v_assertion_canonical, 'sha256'), 'hex'
  );
  v_receipt_payload := jsonb_build_object(
    'schemaVersion', 'typed-relationship-decision-receipt.v2',
    'decisionId', v_decision_id,
    'decisionDigest', btrim(v_decision_digest),
    'assertionId', p_assertion_id,
    'assertionRevision', v_revision,
    'assertionDigest', btrim(v_assertion_digest),
    'priorAssertionRevision', v_current.assertion_revision,
    'priorAssertionDigest', btrim(v_current.assertion_digest),
    'priorReceiptSha256', btrim(v_current.receipt_sha256),
    'verificationStatus', v_status,
    'publicUseStatus', v_public_use_status,
    'evidenceCount', v_current.evidence_count,
    'evidenceSetDigest', btrim(v_current.evidence_set_digest),
    'reviewerUserId', v_actor_user_id,
    'reasonDigest', btrim(v_reason_digest),
    'decidedAt', v_decided_at
  );
  v_receipt_canonical := ops.canonical_jsonb_v1(v_receipt_payload);
  v_receipt_sha256 := encode(
    extensions.digest(v_receipt_canonical, 'sha256'), 'hex'
  );

  INSERT INTO core.relationship_graph_assertions_v2(
    assertion_id, assertion_revision, assertion_digest,
    predecessor_revision, predecessor_digest, prior_receipt_sha256,
    relationship_kind, source_kind, source_locator, source_locator_digest,
    subject_endpoint_id, subject_endpoint_kind, subject_endpoint_digest,
    object_endpoint_id, object_endpoint_kind, object_endpoint_digest,
    valid_from, valid_to, departed_on, validity_coverage_status,
    verification_status, public_use_status,
    evidence_count, evidence_set_digest,
    proposed_actor_type, proposed_actor_id, proposed_by,
    verified_by, verified_at, verification_reason_digest,
    assertion_payload, assertion_canonical,
    receipt_payload, receipt_canonical, receipt_sha256, created_at
  ) VALUES (
    v_current.assertion_id, v_revision, v_assertion_digest,
    v_current.assertion_revision, v_current.assertion_digest,
    v_current.receipt_sha256,
    v_current.relationship_kind, v_current.source_kind,
    v_current.source_locator, v_current.source_locator_digest,
    v_current.subject_endpoint_id, v_current.subject_endpoint_kind,
    v_current.subject_endpoint_digest,
    v_current.object_endpoint_id, v_current.object_endpoint_kind,
    v_current.object_endpoint_digest,
    v_current.valid_from, v_current.valid_to, v_current.departed_on,
    v_current.validity_coverage_status,
    v_status, v_public_use_status,
    v_current.evidence_count, v_current.evidence_set_digest,
    v_current.proposed_actor_type, v_current.proposed_actor_id,
    v_current.proposed_by,
    v_actor_user_id, v_decided_at, v_reason_digest,
    v_assertion_payload, v_assertion_canonical,
    v_receipt_payload, v_receipt_canonical, v_receipt_sha256, v_decided_at
  );

  FOR v_evidence IN
    SELECT evidence.*
    FROM core.relationship_graph_assertion_evidence_v2 AS evidence
    WHERE evidence.assertion_id = v_current.assertion_id
      AND evidence.assertion_revision = v_current.assertion_revision
    ORDER BY evidence.evidence_ordinal
  LOOP
    INSERT INTO core.relationship_graph_assertion_evidence_v2(
      assertion_id, assertion_revision, assertion_digest,
      evidence_ordinal, evidence_id, evidence_version, evidence_digest,
      source_document_id, source_asset_id, source_asset_revision,
      source_content_sha256,
      source_use_agent_run_id, source_use_id, source_use_sha256,
      locator_digest, evidence_binding_canonical, evidence_member_digest,
      created_at
    ) VALUES (
      v_current.assertion_id, v_revision, v_assertion_digest,
      v_evidence.evidence_ordinal, v_evidence.evidence_id,
      v_evidence.evidence_version, v_evidence.evidence_digest,
      v_evidence.source_document_id, v_evidence.source_asset_id,
      v_evidence.source_asset_revision, v_evidence.source_content_sha256,
      v_evidence.source_use_agent_run_id, v_evidence.source_use_id,
      v_evidence.source_use_sha256,
      v_evidence.locator_digest, v_evidence.evidence_binding_canonical,
      v_evidence.evidence_member_digest, v_decided_at
    );
  END LOOP;

  INSERT INTO core.relationship_graph_verification_decisions_v2(
    decision_id, assertion_id,
    prior_assertion_revision, prior_assertion_digest,
    resulting_assertion_revision, resulting_assertion_digest,
    decision_kind, reviewer_user_id, reason_digest,
    decision_payload, decision_canonical, decision_digest,
    prior_receipt_sha256,
    receipt_payload, receipt_canonical, receipt_sha256,
    decided_at, created_at
  ) VALUES (
    v_decision_id, p_assertion_id,
    v_current.assertion_revision, v_current.assertion_digest,
    v_revision, v_assertion_digest,
    v_decision_kind, v_actor_user_id, v_reason_digest,
    v_decision_payload, v_decision_canonical, v_decision_digest,
    v_current.receipt_sha256,
    v_receipt_payload, v_receipt_canonical, v_receipt_sha256,
    v_decided_at, v_decided_at
  );

  RETURN QUERY SELECT
    v_decision_id, p_assertion_id, v_revision, v_assertion_digest,
    v_status, v_public_use_status, v_receipt_sha256, false;
END
$$;
ALTER FUNCTION core.decide_typed_relationship_assertion_v2(uuid,jsonb)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  core.decide_typed_relationship_assertion_v2(uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION
  core.decide_typed_relationship_assertion_v2(uuid,jsonb)
  TO gurine_identity_api;

CREATE OR REPLACE FUNCTION core.typed_person_node_ref_v3(
  p_agent_run_id uuid,
  p_snapshot_id uuid,
  p_snapshot_generation bigint,
  p_snapshot_sha256 char(64),
  p_endpoint_id uuid,
  p_endpoint_digest char(64),
  p_person_node_digest char(64)
) RETURNS char(64)
LANGUAGE sql IMMUTABLE PARALLEL SAFE
SET search_path = pg_catalog, ops, extensions, pg_temp
AS $$
  SELECT encode(extensions.digest(
    ops.canonical_jsonb_v1(jsonb_build_object(
      'schemaVersion', 'relationship-person-node-ref.v3',
      'agentRunId', p_agent_run_id,
      'inputSnapshotId', p_snapshot_id,
      'inputSnapshotGeneration', p_snapshot_generation,
      'inputSnapshotSha256', btrim(p_snapshot_sha256),
      'hiddenEndpointId', p_endpoint_id,
      'hiddenEndpointDigest', btrim(p_endpoint_digest),
      'hiddenPersonNodeDigest', btrim(p_person_node_digest)
    )), 'sha256'
  ), 'hex')::char(64)
$$;
ALTER FUNCTION core.typed_person_node_ref_v3(
  uuid,uuid,bigint,char(64),uuid,char(64),char(64)
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION core.typed_person_node_ref_v3(
  uuid,uuid,bigint,char(64),uuid,char(64),char(64)
) FROM PUBLIC;

CREATE OR REPLACE FUNCTION core.list_typed_relationship_neighbors_v3(
  p_agent_run_id uuid,
  p_snapshot_id uuid,
  p_snapshot_generation bigint,
  p_snapshot_sha256 char(64),
  p_request_canonical bytea,
  p_limit bigint
) RETURNS TABLE(
  query_digest char(64),
  relationship_kind text,
  subject jsonb,
  object jsonb,
  assertion_id uuid,
  assertion_revision bigint,
  assertion_digest char(64),
  valid_from date,
  valid_to date,
  evidence_count integer,
  evidence_set_digest char(64),
  subject_source_use_id uuid,
  subject_source_use_sha256 char(64),
  object_source_use_id uuid,
  object_source_use_sha256 char(64),
  verification_status text,
  public_use_status text,
  proposed_actor_type text,
  proposed_actor_id text,
  verified_by uuid,
  verified_at timestamptz,
  verification_reason_digest char(64)
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_request jsonb;
  v_selector jsonb;
  v_selector_kind text;
  v_selector_endpoint_id uuid;
  v_selector_person_ref char(64);
  v_as_of date;
  v_kinds jsonb;
  v_previous_kind_order integer := 0;
  v_kind_order integer;
  v_kind text;
BEGIN
  IF p_agent_run_id IS NULL OR p_snapshot_id IS NULL
     OR p_snapshot_generation < 1
     OR COALESCE(p_snapshot_sha256 ~ '^[0-9a-f]{64}$', false) = false
     OR p_request_canonical IS NULL
     OR p_limit NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'typed_relationship_neighbors_binding_invalid'
      USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_request := convert_from(p_request_canonical, 'UTF8')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'typed_relationship_neighbors_canonical_invalid'
      USING ERRCODE = '22023';
  END;
  IF p_request_canonical IS DISTINCT FROM ops.canonical_jsonb_v1(v_request)
     OR NOT ops.jsonb_object_has_exact_keys_v1(v_request, ARRAY[
       'schemaVersion', 'runId', 'inputSnapshotId',
       'inputSnapshotSha256', 'selector', 'relationshipKinds',
       'asOf', 'limit'
     ]::text[])
     OR v_request->>'schemaVersion' <>
       'relationship.neighbors.request.v3'
     OR v_request->>'runId' IS DISTINCT FROM p_agent_run_id::text
     OR v_request->>'inputSnapshotId' IS DISTINCT FROM p_snapshot_id::text
     OR v_request->>'inputSnapshotSha256' IS DISTINCT FROM
       btrim(p_snapshot_sha256)
     OR COALESCE(jsonb_typeof(v_request->'relationshipKinds'), '') <> 'array'
     OR jsonb_array_length(v_request->'relationshipKinds') > 9
     OR COALESCE(jsonb_typeof(v_request->'limit'), '') <> 'number'
     OR COALESCE((v_request->>'limit')::bigint = p_limit, false) = false THEN
    RAISE EXCEPTION 'typed_relationship_neighbors_request_invalid'
      USING ERRCODE = '22023';
  END IF;

  v_selector := v_request->'selector';
  v_selector_kind := v_selector->>'kind';
  IF v_selector_kind = 'PERSON' THEN
    IF NOT ops.jsonb_object_has_exact_keys_v1(
       v_selector, ARRAY['kind', 'personNodeRef']::text[]
    ) OR COALESCE(
      v_selector->>'personNodeRef' ~ '^[0-9a-f]{64}$', false
    ) = false THEN
      RAISE EXCEPTION 'typed_relationship_neighbors_person_selector_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_selector_person_ref := v_selector->>'personNodeRef';
  ELSIF v_selector_kind IN (
    'SUPPLIER', 'AGENCY', 'PROCUREMENT_NOTICE', 'SANCTION'
  ) THEN
    IF NOT ops.jsonb_object_has_exact_keys_v1(
       v_selector, ARRAY['kind', 'endpointId']::text[]
    ) OR COALESCE(v_selector->>'endpointId' ~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
      false
    ) = false THEN
      RAISE EXCEPTION 'typed_relationship_neighbors_endpoint_selector_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_selector_endpoint_id := (v_selector->>'endpointId')::uuid;
  ELSE
    RAISE EXCEPTION 'typed_relationship_neighbors_selector_kind_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF v_request->'asOf' <> 'null'::jsonb THEN
    IF COALESCE(jsonb_typeof(v_request->'asOf'), '') <> 'string'
       OR COALESCE(v_request->>'asOf' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$', false)
         = false THEN
      RAISE EXCEPTION 'typed_relationship_neighbors_as_of_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_as_of := (v_request->>'asOf')::date;
    IF to_char(v_as_of, 'YYYY-MM-DD') <> v_request->>'asOf' THEN
      RAISE EXCEPTION 'typed_relationship_neighbors_as_of_invalid'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  v_kinds := v_request->'relationshipKinds';
  FOR v_kind IN
    SELECT item.value
    FROM jsonb_array_elements_text(v_kinds) AS item(value)
  LOOP
    v_kind_order := array_position(ARRAY[
       'OWNERSHIP', 'BENEFICIAL_OWNERSHIP', 'CONTROL', 'MANAGEMENT_ROLE',
       'LEGAL_REPRESENTATIVE', 'CONTRACTUAL_RELATIONSHIP',
       'BID_PARTICIPATION', 'SANCTION', 'FORMER_OFFICIAL_ROLE'
    ]::text[], v_kind);
    IF v_kind_order IS NULL OR v_kind_order <= v_previous_kind_order THEN
      RAISE EXCEPTION 'typed_relationship_neighbors_kind_set_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_previous_kind_order := v_kind_order;
  END LOOP;

  PERFORM 1
  FROM ops.agent_runs AS run
  JOIN core.dataset_snapshots AS snapshot
    ON snapshot.id = run.dataset_snapshot_id
   AND snapshot.snapshot_sha256 = run.input_snapshot_hash
  WHERE run.id = p_agent_run_id
    AND run.run_contract_version = 2
    AND run.status = 'RUNNING'
    AND run.control_state = 'ACTIVE'
    AND run.dataset_snapshot_id = p_snapshot_id
    AND run.input_snapshot_hash = p_snapshot_sha256
    AND snapshot.id = p_snapshot_id
    AND snapshot.snapshot_sha256 = p_snapshot_sha256
    AND snapshot.producer_generation = p_snapshot_generation
    AND snapshot.snapshot_kind = 'AGENT_CASE'
    AND snapshot.state = 'READY'
  FOR SHARE OF run, snapshot;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'typed_relationship_neighbors_ready_snapshot_required'
      USING ERRCODE = '23514';
  END IF;

  RETURN QUERY
  WITH bound AS (
    SELECT
      assertion.*,
      member.id AS snapshot_member_id,
      member.member_digest AS snapshot_member_digest,
      core.typed_person_node_ref_v3(
        p_agent_run_id, p_snapshot_id, p_snapshot_generation,
        p_snapshot_sha256, subject_endpoint.endpoint_id,
        subject_endpoint.endpoint_digest,
        subject_endpoint.person_node_digest
      ) AS subject_person_ref,
      core.typed_person_node_ref_v3(
        p_agent_run_id, p_snapshot_id, p_snapshot_generation,
        p_snapshot_sha256, object_endpoint.endpoint_id,
        object_endpoint.endpoint_digest,
        object_endpoint.person_node_digest
      ) AS object_person_ref,
      subject_endpoint.endpoint_id AS subject_id,
      subject_endpoint.endpoint_kind AS subject_kind,
      subject_endpoint.source_document_id AS subject_document_id,
      subject_endpoint.source_asset_id AS subject_asset_id,
      subject_endpoint.source_asset_revision AS subject_asset_revision,
      subject_endpoint.source_content_sha256 AS subject_content_sha256,
      subject_endpoint.parser_run_id AS subject_parser_run_id,
      subject_endpoint.parsed_record_id AS subject_parsed_record_id,
      subject_endpoint.normalization_run_id AS subject_normalization_run_id,
      object_endpoint.endpoint_id AS object_id,
      object_endpoint.endpoint_kind AS object_kind,
      object_endpoint.source_document_id AS object_document_id,
      object_endpoint.source_asset_id AS object_asset_id,
      object_endpoint.source_asset_revision AS object_asset_revision,
      object_endpoint.source_content_sha256 AS object_content_sha256,
      object_endpoint.parser_run_id AS object_parser_run_id,
      object_endpoint.parsed_record_id AS object_parsed_record_id,
      object_endpoint.normalization_run_id AS object_normalization_run_id
    FROM core.dataset_snapshot_relationship_assertions_v2 AS frozen
    JOIN core.relationship_graph_assertions_v2 AS assertion
      ON assertion.assertion_id = frozen.assertion_id
     AND assertion.assertion_revision = frozen.assertion_revision
     AND assertion.assertion_digest = frozen.assertion_digest
    JOIN core.relationship_graph_endpoints_v2 AS subject_endpoint
      ON subject_endpoint.endpoint_id = assertion.subject_endpoint_id
     AND subject_endpoint.endpoint_kind = assertion.subject_endpoint_kind
     AND subject_endpoint.endpoint_digest = assertion.subject_endpoint_digest
    JOIN core.relationship_graph_endpoints_v2 AS object_endpoint
      ON object_endpoint.endpoint_id = assertion.object_endpoint_id
     AND object_endpoint.endpoint_kind = assertion.object_endpoint_kind
     AND object_endpoint.endpoint_digest = assertion.object_endpoint_digest
    JOIN core.dataset_snapshot_members AS member
      ON member.dataset_snapshot_id = frozen.dataset_snapshot_id
     AND member.object_type = 'TYPED_RELATIONSHIP_ASSERTION'
     AND member.object_id = frozen.assertion_id
     AND member.object_version = frozen.assertion_revision
     AND member.object_content_sha256 = frozen.assertion_digest
    WHERE frozen.dataset_snapshot_id = p_snapshot_id
      AND frozen.snapshot_generation = p_snapshot_generation
      AND frozen.snapshot_sha256 = p_snapshot_sha256
      AND assertion.verification_status = 'VERIFIED'
      AND assertion.public_use_status = 'APPROVED'
      AND assertion.validity_coverage_status = 'COMPLETE'
      AND assertion.verified_by IS NOT NULL
      AND assertion.verified_by IS DISTINCT FROM assertion.proposed_by
      AND assertion.verified_at IS NOT NULL
      AND assertion.verification_reason_digest IS NOT NULL
      AND assertion.evidence_count BETWEEN 1 AND 1000
      AND (
        (
          assertion.relationship_kind IN (
            'OWNERSHIP', 'BENEFICIAL_OWNERSHIP', 'CONTROL',
            'CONTRACTUAL_RELATIONSHIP'
          )
          AND subject_endpoint.endpoint_kind = 'SUPPLIER'
          AND object_endpoint.endpoint_kind = 'SUPPLIER'
        )
        OR (
          assertion.relationship_kind IN (
            'MANAGEMENT_ROLE', 'LEGAL_REPRESENTATIVE'
          )
          AND subject_endpoint.endpoint_kind = 'PERSON'
          AND object_endpoint.endpoint_kind = 'SUPPLIER'
        )
        OR (
          assertion.relationship_kind = 'BID_PARTICIPATION'
          AND subject_endpoint.endpoint_kind = 'SUPPLIER'
          AND object_endpoint.endpoint_kind = 'PROCUREMENT_NOTICE'
        )
        OR (
          assertion.relationship_kind = 'SANCTION'
          AND subject_endpoint.endpoint_kind = 'SUPPLIER'
          AND object_endpoint.endpoint_kind = 'SANCTION'
        )
        OR (
          assertion.relationship_kind = 'FORMER_OFFICIAL_ROLE'
          AND subject_endpoint.endpoint_kind = 'PERSON'
          AND object_endpoint.endpoint_kind = 'AGENCY'
        )
      )
  ), eligible AS (
    SELECT
      bound.*,
      subject_use.source_use_id AS subject_use_id,
      subject_use.source_use_sha256 AS subject_use_sha,
      object_use.source_use_id AS object_use_id,
      object_use.source_use_sha256 AS object_use_sha,
      CASE
        WHEN bound.subject_kind = 'PERSON' THEN btrim(bound.subject_person_ref)
        ELSE bound.subject_id::text
      END AS subject_stable_key,
      CASE
        WHEN bound.object_kind = 'PERSON' THEN btrim(bound.object_person_ref)
        ELSE bound.object_id::text
      END AS object_stable_key
    FROM bound
    JOIN core.dataset_snapshot_member_sources AS subject_source
      ON subject_source.dataset_snapshot_id = p_snapshot_id
     AND subject_source.snapshot_member_id = bound.snapshot_member_id
     AND subject_source.snapshot_member_digest = bound.snapshot_member_digest
     AND subject_source.source_ordinal = 0
     AND subject_source.source_kind = 'SOURCE_DOCUMENT'
     AND subject_source.source_document_id = bound.subject_document_id
     AND subject_source.source_asset_id = bound.subject_asset_id
     AND subject_source.source_asset_revision = bound.subject_asset_revision
     AND subject_source.source_content_sha256 = bound.subject_content_sha256
     AND (
       (
         bound.subject_parser_run_id IS NOT NULL
         AND bound.subject_parsed_record_id IS NOT NULL
         AND bound.subject_normalization_run_id IS NULL
         AND subject_source.lineage_kind = 'PARSED_RECORD'
         AND subject_source.parser_run_id = bound.subject_parser_run_id
         AND subject_source.parsed_record_id = bound.subject_parsed_record_id
         AND subject_source.normalization_run_id IS NULL
       )
       OR (
         bound.subject_parser_run_id IS NULL
         AND bound.subject_parsed_record_id IS NULL
         AND bound.subject_normalization_run_id IS NOT NULL
         AND subject_source.lineage_kind = 'NORMALIZED_FIELD'
         AND subject_source.normalization_run_id =
           bound.subject_normalization_run_id
       )
     )
    JOIN ops.agent_source_uses AS subject_use
      ON subject_use.agent_run_id = p_agent_run_id
     AND subject_use.use_kind = 'TOOL_QUERY'
     AND subject_use.source_kind = 'DATASET_MEMBER'
     AND subject_use.dataset_snapshot_id = p_snapshot_id
     AND subject_use.snapshot_member_id = bound.snapshot_member_id
     AND subject_use.snapshot_member_digest = bound.snapshot_member_digest
     AND subject_use.snapshot_member_source_id = subject_source.id
     AND subject_use.snapshot_member_source_digest =
       subject_source.source_digest
    JOIN core.dataset_snapshot_member_sources AS object_source
      ON object_source.dataset_snapshot_id = p_snapshot_id
     AND object_source.snapshot_member_id = bound.snapshot_member_id
     AND object_source.snapshot_member_digest = bound.snapshot_member_digest
     AND object_source.source_ordinal = 1
     AND object_source.source_kind = 'SOURCE_DOCUMENT'
     AND object_source.source_document_id = bound.object_document_id
     AND object_source.source_asset_id = bound.object_asset_id
     AND object_source.source_asset_revision = bound.object_asset_revision
     AND object_source.source_content_sha256 = bound.object_content_sha256
     AND (
       (
         bound.object_parser_run_id IS NOT NULL
         AND bound.object_parsed_record_id IS NOT NULL
         AND bound.object_normalization_run_id IS NULL
         AND object_source.lineage_kind = 'PARSED_RECORD'
         AND object_source.parser_run_id = bound.object_parser_run_id
         AND object_source.parsed_record_id = bound.object_parsed_record_id
         AND object_source.normalization_run_id IS NULL
       )
       OR (
         bound.object_parser_run_id IS NULL
         AND bound.object_parsed_record_id IS NULL
         AND bound.object_normalization_run_id IS NOT NULL
         AND object_source.lineage_kind = 'NORMALIZED_FIELD'
         AND object_source.normalization_run_id =
           bound.object_normalization_run_id
       )
     )
    JOIN ops.agent_source_uses AS object_use
      ON object_use.agent_run_id = p_agent_run_id
     AND object_use.use_kind = 'TOOL_QUERY'
     AND object_use.source_kind = 'DATASET_MEMBER'
     AND object_use.dataset_snapshot_id = p_snapshot_id
     AND object_use.snapshot_member_id = bound.snapshot_member_id
     AND object_use.snapshot_member_digest = bound.snapshot_member_digest
     AND object_use.snapshot_member_source_id = object_source.id
     AND object_use.snapshot_member_source_digest = object_source.source_digest
    WHERE subject_use.source_use_id <> object_use.source_use_id
      AND (
        jsonb_array_length(v_kinds) = 0
        OR bound.relationship_kind IN (
          SELECT jsonb_array_elements_text(v_kinds)
        )
      )
      AND (
        v_as_of IS NULL
        OR (
          (bound.valid_from IS NULL OR bound.valid_from <= v_as_of)
          AND (bound.valid_to IS NULL OR bound.valid_to >= v_as_of)
        )
      )
      AND (
        (
          v_selector_kind = 'PERSON'
          AND (
            (bound.subject_kind = 'PERSON'
             AND bound.subject_person_ref = v_selector_person_ref)
            OR (bound.object_kind = 'PERSON'
                AND bound.object_person_ref = v_selector_person_ref)
          )
        )
        OR (
          v_selector_kind <> 'PERSON'
          AND (
            (bound.subject_kind = v_selector_kind
             AND bound.subject_id = v_selector_endpoint_id)
            OR (bound.object_kind = v_selector_kind
                AND bound.object_id = v_selector_endpoint_id)
          )
        )
      )
  )
  SELECT
    encode(extensions.digest(p_request_canonical, 'sha256'), 'hex')::char(64),
    eligible.relationship_kind,
    CASE WHEN eligible.subject_kind = 'PERSON'
      THEN jsonb_build_object(
        'kind', 'PERSON',
        'personNodeRef', btrim(eligible.subject_person_ref)
      )
      ELSE jsonb_build_object(
        'kind', eligible.subject_kind,
        'endpointId', eligible.subject_id
      )
    END,
    CASE WHEN eligible.object_kind = 'PERSON'
      THEN jsonb_build_object(
        'kind', 'PERSON',
        'personNodeRef', btrim(eligible.object_person_ref)
      )
      ELSE jsonb_build_object(
        'kind', eligible.object_kind,
        'endpointId', eligible.object_id
      )
    END,
    eligible.assertion_id,
    eligible.assertion_revision,
    eligible.assertion_digest,
    eligible.valid_from,
    eligible.valid_to,
    eligible.evidence_count,
    eligible.evidence_set_digest,
    eligible.subject_use_id,
    eligible.subject_use_sha,
    eligible.object_use_id,
    eligible.object_use_sha,
    eligible.verification_status,
    eligible.public_use_status,
    eligible.proposed_actor_type,
    eligible.proposed_actor_id,
    eligible.verified_by,
    eligible.verified_at,
    eligible.verification_reason_digest
  FROM eligible
  ORDER BY
    eligible.relationship_kind,
    CASE
      WHEN (
        (v_selector_kind = 'PERSON'
         AND eligible.subject_person_ref = v_selector_person_ref)
        OR (v_selector_kind <> 'PERSON'
            AND eligible.subject_kind = v_selector_kind
            AND eligible.subject_id = v_selector_endpoint_id)
      ) THEN eligible.object_stable_key
      ELSE eligible.subject_stable_key
    END,
    eligible.assertion_id,
    eligible.assertion_revision
  LIMIT p_limit;
END
$$;
ALTER FUNCTION core.list_typed_relationship_neighbors_v3(
  uuid,uuid,bigint,char(64),bytea,bigint
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION core.list_typed_relationship_neighbors_v3(
  uuid,uuid,bigint,char(64),bytea,bigint
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION core.list_typed_relationship_neighbors_v3(
  uuid,uuid,bigint,char(64),bytea,bigint
) TO gurine_analysis_worker;

CREATE OR REPLACE FUNCTION ops.relationship_neighbors_payload_is_valid_v2_v3(
  p_request jsonb,
  p_result jsonb
) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
SET search_path = pg_catalog, ops, pg_temp
AS $$
DECLARE
  v_request_version text;
  v_response_version text;
  v_selector jsonb;
  v_kind text;
  v_previous_kind_order integer := 0;
  v_kind_order integer;
  v_neighbor jsonb;
  v_endpoint jsonb;
  v_count integer;
  v_distinct_count integer;
  v_as_of date;
  v_date date;
BEGIN
  IF p_request IS NULL OR jsonb_typeof(p_request) <> 'object' THEN
    RETURN false;
  END IF;
  v_request_version := p_request->>'schemaVersion';
  IF v_request_version = 'relationship.neighbors.request.v2' THEN
    IF NOT ops.jsonb_object_has_exact_keys_v1(p_request, ARRAY[
      'schemaVersion', 'runId', 'inputSnapshotId',
      'inputSnapshotSha256', 'supplierId', 'relationshipKinds',
      'asOf', 'limit'
    ]::text[])
       OR COALESCE(p_request->>'supplierId' ~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
         false) = false THEN
      RETURN false;
    END IF;
  ELSIF v_request_version = 'relationship.neighbors.request.v3' THEN
    IF NOT ops.jsonb_object_has_exact_keys_v1(p_request, ARRAY[
      'schemaVersion', 'runId', 'inputSnapshotId',
      'inputSnapshotSha256', 'selector', 'relationshipKinds',
      'asOf', 'limit'
    ]::text[]) THEN
      RETURN false;
    END IF;
    v_selector := p_request->'selector';
    IF v_selector->>'kind' = 'PERSON' THEN
      IF NOT ops.jsonb_object_has_exact_keys_v1(
        v_selector, ARRAY['kind', 'personNodeRef']::text[]
      ) OR COALESCE(
        v_selector->>'personNodeRef' ~ '^[0-9a-f]{64}$', false
      ) = false THEN
        RETURN false;
      END IF;
    ELSIF v_selector->>'kind' IN (
      'SUPPLIER', 'AGENCY', 'PROCUREMENT_NOTICE', 'SANCTION'
    ) THEN
      IF NOT ops.jsonb_object_has_exact_keys_v1(
        v_selector, ARRAY['kind', 'endpointId']::text[]
      ) OR COALESCE(v_selector->>'endpointId' ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
        false) = false THEN
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;
  ELSE
    RETURN false;
  END IF;

  IF COALESCE(p_request->>'runId' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
     OR COALESCE(p_request->>'inputSnapshotId' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
     OR COALESCE(
       p_request->>'inputSnapshotSha256' ~ '^[0-9a-f]{64}$', false
     ) = false
     OR COALESCE(jsonb_typeof(p_request->'relationshipKinds'), '') <> 'array'
     OR jsonb_array_length(p_request->'relationshipKinds') >
       (CASE WHEN v_request_version LIKE '%.v2' THEN 6 ELSE 9 END)
     OR COALESCE(jsonb_typeof(p_request->'limit'), '') <> 'number'
     OR (p_request->>'limit')::numeric <> trunc((p_request->>'limit')::numeric)
     OR (p_request->>'limit')::integer NOT BETWEEN 1 AND 50 THEN
    RETURN false;
  END IF;
  IF p_request->'asOf' <> 'null'::jsonb THEN
    IF jsonb_typeof(p_request->'asOf') <> 'string'
       OR COALESCE(p_request->>'asOf' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$', false)
         = false THEN
      RETURN false;
    END IF;
    v_as_of := (p_request->>'asOf')::date;
    IF to_char(v_as_of, 'YYYY-MM-DD') <> p_request->>'asOf' THEN
      RETURN false;
    END IF;
  END IF;

  SELECT count(*)::integer, count(DISTINCT item.value)::integer
  INTO v_count, v_distinct_count
  FROM jsonb_array_elements_text(
    p_request->'relationshipKinds'
  ) AS item(value);
  IF v_count <> v_distinct_count THEN
    RETURN false;
  END IF;
  FOR v_kind IN
    SELECT item.value
    FROM jsonb_array_elements_text(
      p_request->'relationshipKinds'
    ) AS item(value)
  LOOP
    v_kind_order := array_position(ARRAY[
       'OWNERSHIP', 'BENEFICIAL_OWNERSHIP', 'CONTROL', 'MANAGEMENT_ROLE',
       'LEGAL_REPRESENTATIVE', 'CONTRACTUAL_RELATIONSHIP',
       'BID_PARTICIPATION', 'SANCTION', 'FORMER_OFFICIAL_ROLE'
    ]::text[], v_kind);
    IF v_kind_order IS NULL OR (
      v_request_version LIKE '%.v2'
      AND v_kind IN (
        'BID_PARTICIPATION', 'SANCTION', 'FORMER_OFFICIAL_ROLE'
      )
    ) OR (
      v_request_version LIKE '%.v3'
      AND v_kind_order <= v_previous_kind_order
    ) THEN
      RETURN false;
    END IF;
    IF v_request_version LIKE '%.v3' THEN
      v_previous_kind_order := v_kind_order;
    END IF;
  END LOOP;

  IF p_result IS NULL THEN
    RETURN true;
  END IF;
  IF jsonb_typeof(p_result) <> 'object' THEN
    RETURN false;
  END IF;
  v_response_version := p_result->>'schemaVersion';
  IF v_request_version = 'relationship.neighbors.request.v2' THEN
    IF v_response_version <> 'relationship.neighbors.response.v2'
       OR NOT ops.jsonb_object_has_exact_keys_v1(p_result, ARRAY[
         'schemaVersion', 'supplierId', 'neighbors'
       ]::text[])
       OR p_result->>'supplierId' IS DISTINCT FROM p_request->>'supplierId' THEN
      RETURN false;
    END IF;
  ELSE
    IF v_response_version <> 'relationship.neighbors.response.v3'
       OR NOT ops.jsonb_object_has_exact_keys_v1(p_result, ARRAY[
         'schemaVersion', 'queryDigest', 'neighbors'
       ]::text[])
       OR COALESCE(p_result->>'queryDigest' ~ '^[0-9a-f]{64}$', false)
         = false
       OR p_result->>'queryDigest' IS DISTINCT FROM encode(
         extensions.digest(ops.canonical_jsonb_v1(p_request), 'sha256'),
         'hex'
       ) THEN
      RETURN false;
    END IF;
  END IF;
  IF jsonb_typeof(p_result->'neighbors') <> 'array'
     OR jsonb_array_length(p_result->'neighbors') > 50 THEN
    RETURN false;
  END IF;

  FOR v_neighbor IN
    SELECT item.value
    FROM jsonb_array_elements(p_result->'neighbors') AS item(value)
  LOOP
    IF v_response_version = 'relationship.neighbors.response.v2' THEN
      IF NOT ops.jsonb_object_has_exact_keys_v1(v_neighbor, ARRAY[
        'neighborSupplierId', 'relationshipKind', 'assertionId',
        'assertionRevision', 'assertionDigest', 'validFrom', 'validTo',
        'evidenceSetDigest', 'subjectSourceUseId', 'objectSourceUseId'
      ]::text[])
         OR COALESCE(v_neighbor->>'neighborSupplierId' ~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
           false) = false
         OR v_neighbor->>'relationshipKind' NOT IN (
           'OWNERSHIP', 'BENEFICIAL_OWNERSHIP', 'CONTROL',
           'MANAGEMENT_ROLE', 'LEGAL_REPRESENTATIVE',
           'CONTRACTUAL_RELATIONSHIP'
         ) THEN
        RETURN false;
      END IF;
    ELSE
      IF NOT ops.jsonb_object_has_exact_keys_v1(v_neighbor, ARRAY[
        'subject', 'object', 'relationshipKind', 'assertionId',
        'assertionRevision', 'assertionDigest', 'validFrom', 'validTo',
        'evidenceSetDigest', 'subjectSourceUseId', 'objectSourceUseId'
      ]::text[])
         OR v_neighbor->>'relationshipKind' NOT IN (
           'OWNERSHIP', 'BENEFICIAL_OWNERSHIP', 'CONTROL',
           'MANAGEMENT_ROLE', 'LEGAL_REPRESENTATIVE',
           'CONTRACTUAL_RELATIONSHIP', 'BID_PARTICIPATION',
           'SANCTION', 'FORMER_OFFICIAL_ROLE'
         ) THEN
        RETURN false;
      END IF;
      FOREACH v_endpoint IN ARRAY ARRAY[
        v_neighbor->'subject', v_neighbor->'object'
      ] LOOP
        IF v_endpoint->>'kind' = 'PERSON' THEN
          IF NOT ops.jsonb_object_has_exact_keys_v1(
            v_endpoint, ARRAY['kind', 'personNodeRef']::text[]
          ) OR COALESCE(
            v_endpoint->>'personNodeRef' ~ '^[0-9a-f]{64}$', false
          ) = false THEN
            RETURN false;
          END IF;
        ELSIF v_endpoint->>'kind' IN (
          'SUPPLIER', 'AGENCY', 'PROCUREMENT_NOTICE', 'SANCTION'
        ) THEN
          IF NOT ops.jsonb_object_has_exact_keys_v1(
            v_endpoint, ARRAY['kind', 'endpointId']::text[]
          ) OR COALESCE(v_endpoint->>'endpointId' ~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
            false) = false THEN
            RETURN false;
          END IF;
        ELSE
          RETURN false;
        END IF;
      END LOOP;
    END IF;

    IF COALESCE(v_neighbor->>'assertionId' ~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
       false) = false
       OR jsonb_typeof(v_neighbor->'assertionRevision') <> 'number'
       OR (v_neighbor->>'assertionRevision')::numeric < 1
       OR (v_neighbor->>'assertionRevision')::numeric <>
         trunc((v_neighbor->>'assertionRevision')::numeric)
       OR COALESCE(v_neighbor->>'assertionDigest' ~ '^[0-9a-f]{64}$', false)
         = false
       OR COALESCE(v_neighbor->>'evidenceSetDigest' ~ '^[0-9a-f]{64}$', false)
         = false
       OR COALESCE(v_neighbor->>'subjectSourceUseId' ~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
         false) = false
       OR COALESCE(v_neighbor->>'objectSourceUseId' ~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
         false) = false THEN
      RETURN false;
    END IF;
    FOREACH v_endpoint IN ARRAY ARRAY[
      v_neighbor->'validFrom', v_neighbor->'validTo'
    ] LOOP
      IF v_endpoint <> 'null'::jsonb THEN
        IF jsonb_typeof(v_endpoint) <> 'string'
           OR COALESCE(v_endpoint #>> '{}' ~
             '^[0-9]{4}-[0-9]{2}-[0-9]{2}$', false) = false THEN
          RETURN false;
        END IF;
        v_date := (v_endpoint #>> '{}')::date;
        IF to_char(v_date, 'YYYY-MM-DD') <> v_endpoint #>> '{}' THEN
          RETURN false;
        END IF;
      END IF;
    END LOOP;
    IF v_response_version = 'relationship.neighbors.response.v3' THEN
      IF NOT (
        (
          v_neighbor->>'relationshipKind' IN (
            'OWNERSHIP', 'BENEFICIAL_OWNERSHIP', 'CONTROL',
            'CONTRACTUAL_RELATIONSHIP'
          )
          AND v_neighbor->'subject'->>'kind' = 'SUPPLIER'
          AND v_neighbor->'object'->>'kind' = 'SUPPLIER'
        )
        OR (
          v_neighbor->>'relationshipKind' IN (
            'MANAGEMENT_ROLE', 'LEGAL_REPRESENTATIVE'
          )
          AND v_neighbor->'subject'->>'kind' = 'PERSON'
          AND v_neighbor->'object'->>'kind' = 'SUPPLIER'
        )
        OR (
          v_neighbor->>'relationshipKind' = 'BID_PARTICIPATION'
          AND v_neighbor->'subject'->>'kind' = 'SUPPLIER'
          AND v_neighbor->'object'->>'kind' = 'PROCUREMENT_NOTICE'
        )
        OR (
          v_neighbor->>'relationshipKind' = 'SANCTION'
          AND v_neighbor->'subject'->>'kind' = 'SUPPLIER'
          AND v_neighbor->'object'->>'kind' = 'SANCTION'
        )
        OR (
          v_neighbor->>'relationshipKind' = 'FORMER_OFFICIAL_ROLE'
          AND v_neighbor->'subject'->>'kind' = 'PERSON'
          AND v_neighbor->'object'->>'kind' = 'AGENCY'
        )
      ) THEN
        RETURN false;
      END IF;
      IF NOT (
        (
          v_selector->>'kind' = 'PERSON'
          AND (
            (
              v_neighbor->'subject'->>'kind' = 'PERSON'
              AND v_neighbor->'subject'->>'personNodeRef' =
                v_selector->>'personNodeRef'
            )
            OR (
              v_neighbor->'object'->>'kind' = 'PERSON'
              AND v_neighbor->'object'->>'personNodeRef' =
                v_selector->>'personNodeRef'
            )
          )
        )
        OR (
          v_selector->>'kind' <> 'PERSON'
          AND (
            (
              v_neighbor->'subject'->>'kind' = v_selector->>'kind'
              AND (v_neighbor->'subject'->>'endpointId')::uuid =
                (v_selector->>'endpointId')::uuid
            )
            OR (
              v_neighbor->'object'->>'kind' = v_selector->>'kind'
              AND (v_neighbor->'object'->>'endpointId')::uuid =
                (v_selector->>'endpointId')::uuid
            )
          )
        )
      ) THEN
        RETURN false;
      END IF;
      IF jsonb_array_length(p_request->'relationshipKinds') > 0
         AND NOT (
           p_request->'relationshipKinds' @>
             jsonb_build_array(v_neighbor->>'relationshipKind')
         ) THEN
        RETURN false;
      END IF;
      IF (
           v_neighbor->'validFrom' <> 'null'::jsonb
           AND v_neighbor->'validTo' <> 'null'::jsonb
           AND (v_neighbor->>'validFrom')::date >
             (v_neighbor->>'validTo')::date
         )
         OR (
           v_as_of IS NOT NULL
           AND (
             (
               v_neighbor->'validFrom' <> 'null'::jsonb
               AND (v_neighbor->>'validFrom')::date > v_as_of
             )
             OR (
               v_neighbor->'validTo' <> 'null'::jsonb
               AND (v_neighbor->>'validTo')::date < v_as_of
             )
           )
         ) THEN
        RETURN false;
      END IF;
    END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END
$$;
ALTER FUNCTION ops.relationship_neighbors_payload_is_valid_v2_v3(jsonb,jsonb)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  ops.relationship_neighbors_payload_is_valid_v2_v3(jsonb,jsonb)
  FROM PUBLIC;

CREATE OR REPLACE FUNCTION ops.agent_tool_payload_is_valid(
  p_tool_id text,
  p_request jsonb,
  p_result jsonb
) RETURNS boolean
LANGUAGE sql IMMUTABLE PARALLEL SAFE
SET search_path = pg_catalog, ops, pg_temp
AS $$
  SELECT COALESCE(
    p_request IS NOT NULL
    AND jsonb_typeof(p_request) = 'object'
    AND CASE p_tool_id
      WHEN 'agency.profile' THEN
        p_request->>'schemaVersion' = 'agency.profile.request.v2'
      WHEN 'claim.language_check' THEN
        p_request->>'schemaVersion' = 'claim.language_check.request.v2'
      WHEN 'contract.find_comparables' THEN
        p_request->>'schemaVersion' = 'contract.find_comparables.request.v2'
      WHEN 'contract.search' THEN
        p_request->>'schemaVersion' = 'contract.search.request.v2'
      WHEN 'entity.lookup' THEN
        p_request->>'schemaVersion' = 'entity.lookup.request.v2'
      WHEN 'evidence.read' THEN
        p_request->>'schemaVersion' = 'evidence.read.request.v2'
      WHEN 'evidence.search' THEN
        p_request->>'schemaVersion' = 'evidence.search.request.v2'
      WHEN 'relationship.neighbors' THEN
        ops.relationship_neighbors_payload_is_valid_v2_v3(
          p_request, p_result
        )
      WHEN 'response.read' THEN
        p_request->>'schemaVersion' = 'response.read.request.v2'
      WHEN 'rule.reproduce' THEN
        p_request->>'schemaVersion' = 'rule.reproduce.request.v2'
      WHEN 'source.fetch' THEN true
      WHEN 'source.locator_verify' THEN
        p_request->>'schemaVersion' = 'source.locator_verify.request.v2'
      WHEN 'supplier.profile' THEN
        p_request->>'schemaVersion' = 'supplier.profile.request.v2'
      ELSE false
    END
    AND (
      p_tool_id = 'relationship.neighbors'
      OR p_result IS NULL
      OR (
        jsonb_typeof(p_result) = 'object'
        AND p_result->>'schemaVersion' = CASE p_tool_id
          WHEN 'agency.profile' THEN 'agency.profile.response.v2'
          WHEN 'claim.language_check' THEN 'claim.language_check.response.v2'
          WHEN 'contract.find_comparables' THEN
            'contract.find_comparables.response.v2'
          WHEN 'contract.search' THEN 'contract.search.response.v2'
          WHEN 'entity.lookup' THEN 'entity.lookup.response.v2'
          WHEN 'evidence.read' THEN 'evidence.read.response.v2'
          WHEN 'evidence.search' THEN 'evidence.search.response.v2'
          WHEN 'response.read' THEN 'response.read.response.v2'
          WHEN 'rule.reproduce' THEN 'rule.reproduce.response.v2'
          WHEN 'source.fetch' THEN 'source.fetch.response.v2'
          WHEN 'source.locator_verify' THEN
            'source.locator_verify.response.v2'
          WHEN 'supplier.profile' THEN 'supplier.profile.response.v2'
          ELSE NULL
        END
      )
    ),
    false
  )
$$;
ALTER FUNCTION ops.agent_tool_payload_is_valid(text,jsonb,jsonb)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.agent_tool_payload_is_valid(text,jsonb,jsonb)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.agent_tool_payload_is_valid(text,jsonb,jsonb)
  TO gurine_analysis_worker;

