CREATE OR REPLACE FUNCTION ops.complete_agent_run_worker_v2(
  p_agent_run_id uuid,
  p_expected_version bigint,
  p_prior_receipt_id uuid,
  p_prior_receipt_sha256 char(64),
  p_job_id uuid,
  p_lease_token uuid,
  p_job_fencing_token bigint,
  p_next_status text,
  p_provider text,
  p_model text,
  p_output_payload jsonb,
  p_output_sha256 char(64),
  p_failure_code text,
  p_failure_proof jsonb,
  p_failure_proof_sha256 char(64),
  p_actual_cost numeric
) RETURNS TABLE(
  version bigint,
  terminal_receipt_id uuid,
  terminal_receipt_sha256 char(64),
  replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, extensions, pg_temp
AS $$
DECLARE
  v_run ops.agent_runs%ROWTYPE;
  v_job ops.jobs%ROWTYPE;
  v_prior ops.agent_run_control_receipts%ROWTYPE;
  v_existing ops.agent_run_control_receipts%ROWTYPE;
  v_output_validation ops.agent_output_validations%ROWTYPE;
  v_output_validation_id uuid;
  v_now timestamptz := clock_timestamp();
  v_output_sha256 char(64);
  v_proof_sha256 char(64);
  v_proof_kind text;
  v_reason_code text;
  v_reason_binding jsonb;
  v_reason_sha256 char(64);
  v_budget_disposition text;
  v_budget_state text;
  v_budget_set_sha256 char(64);
  v_actual_micros_krw bigint;
  v_receipt_id uuid;
  v_receipt_sha256 char(64);
  v_unused_audit uuid;
  v_unused_outbox uuid;
BEGIN
  IF p_agent_run_id IS NULL OR p_expected_version IS NULL
     OR p_expected_version < 2
     OR p_prior_receipt_id IS NULL
     OR p_prior_receipt_sha256 IS NULL
     OR p_prior_receipt_sha256 !~ '^[0-9a-f]{64}$'
     OR p_job_id IS NULL OR p_lease_token IS NULL
     OR p_job_fencing_token IS NULL OR p_job_fencing_token < 1
     OR p_next_status IS NULL
     OR p_next_status NOT IN (
       'SUCCEEDED','FAILED','BUDGET_BLOCKED','POLICY_BLOCKED'
     )
     OR p_actual_cost IS NULL OR p_actual_cost < 0
     OR scale(p_actual_cost) > 6 THEN
    RAISE EXCEPTION 'agent_run_terminal_request_invalid'
      USING ERRCODE = '22023';
  END IF;
  v_actual_micros_krw := round(p_actual_cost * 1000000)::bigint;
  IF p_next_status = 'FAILED' THEN
    IF p_provider IS NOT NULL OR p_model IS NOT NULL
       OR p_output_payload IS NOT NULL OR p_output_sha256 IS NOT NULL
       OR p_actual_cost <> 0
       OR p_failure_code IS NULL
       OR p_failure_code NOT IN (
         'OUTPUT_SCHEMA_INVALID','PROVIDER_UNAVAILABLE',
         'INTERNAL_EXECUTION_FAILED','CITATION_INVALID','RIGHTS_DENIED',
         'CLASSIFICATION_DENIED','ITERATION_LIMIT_REACHED',
         'CANCELLED_BY_USER','RECONCILIATION_FAILED'
       )
       OR p_failure_proof IS NULL
       OR jsonb_typeof(p_failure_proof) IS DISTINCT FROM 'object'
       OR p_failure_proof_sha256 IS NULL
       OR p_failure_proof_sha256 !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'agent_run_failure_shape_invalid'
        USING ERRCODE = '22023';
    END IF;
    IF (SELECT count(*) FROM jsonb_object_keys(p_failure_proof)) <> 5
       OR NOT p_failure_proof ?& ARRAY[
         'schemaVersion','runId','failureCode','detailSha256','redacted'
       ]
       OR jsonb_typeof(p_failure_proof->'schemaVersion')
         IS DISTINCT FROM 'string'
       OR p_failure_proof->>'schemaVersion' IS DISTINCT FROM
         'agent-run-definitive-failure-proof.v1'
       OR jsonb_typeof(p_failure_proof->'runId') IS DISTINCT FROM 'string'
       OR p_failure_proof->>'runId' IS DISTINCT FROM p_agent_run_id::text
       OR jsonb_typeof(p_failure_proof->'failureCode')
         IS DISTINCT FROM 'string'
       OR p_failure_proof->>'failureCode' IS DISTINCT FROM p_failure_code
       OR jsonb_typeof(p_failure_proof->'detailSha256')
         IS DISTINCT FROM 'string'
       OR COALESCE(p_failure_proof->>'detailSha256','')
         !~ '^[0-9a-f]{64}$'
       OR jsonb_typeof(p_failure_proof->'redacted')
         IS DISTINCT FROM 'boolean'
       OR p_failure_proof->'redacted' IS DISTINCT FROM 'true'::jsonb
       OR p_failure_proof_sha256 IS DISTINCT FROM encode(
         extensions.digest(
           ops.canonical_jsonb_v1(p_failure_proof), 'sha256'
         ), 'hex'
       ) THEN
      RAISE EXCEPTION 'agent_run_failure_proof_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_proof_sha256 := p_failure_proof_sha256;
    v_proof_kind := 'DEFINITIVE_INTERNAL_FAILURE';
    v_reason_code := 'DEFINITIVE_FAILURE';
  ELSE
    IF nullif(btrim(p_provider), '') IS NULL
       OR nullif(btrim(p_model), '') IS NULL
       OR p_output_payload IS NULL
       OR p_output_sha256 IS NULL
       OR p_output_sha256 !~ '^[0-9a-f]{64}$'
       OR p_failure_code IS NOT NULL OR p_failure_proof IS NOT NULL
       OR p_failure_proof_sha256 IS NOT NULL THEN
      RAISE EXCEPTION 'agent_run_output_shape_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_output_sha256 := encode(
      extensions.digest(
        ops.canonical_jsonb_v1(p_output_payload), 'sha256'
      ), 'hex'
    );
    IF p_output_sha256 <> v_output_sha256 THEN
      RAISE EXCEPTION 'agent_run_output_digest_mismatch'
        USING ERRCODE = '22023';
    END IF;
    v_proof_sha256 := p_output_sha256;
    v_proof_kind := CASE p_next_status
      WHEN 'SUCCEEDED' THEN 'VALIDATED_FINAL_OUTPUT'
      ELSE 'DEFINITIVE_NO_DISPATCH'
    END;
    v_reason_code := CASE p_next_status
      WHEN 'SUCCEEDED' THEN 'FINAL_OUTPUT_VALIDATED'
      WHEN 'BUDGET_BLOCKED' THEN 'BUDGET_DENIED'
      ELSE 'POLICY_DENIED'
    END;
  END IF;
  v_reason_binding := jsonb_build_object(
    'schemaVersion', 'agent-run-worker-transition-command.v1',
    'runId', p_agent_run_id,
    'expectedVersion', p_expected_version,
    'priorReceiptId', p_prior_receipt_id,
    'priorReceiptSha256', btrim(p_prior_receipt_sha256),
    'nextStatus', p_next_status,
    'nextControlState', 'SETTLED',
    'provider', p_provider,
    'model', p_model,
    'outputSha256', CASE
      WHEN p_output_sha256 IS NULL THEN NULL ELSE btrim(p_output_sha256)
    END,
    'failureCode', p_failure_code,
    'failureProofSha256', CASE WHEN p_failure_proof_sha256 IS NULL
      THEN NULL ELSE btrim(p_failure_proof_sha256) END,
    'actualCost', p_actual_cost::text,
    'jobId', p_job_id,
    'leaseTokenSha256', encode(
      extensions.digest(convert_to(p_lease_token::text, 'UTF8'), 'sha256'),
      'hex'
    ),
    'fencingToken', p_job_fencing_token
  );
  v_reason_sha256 := encode(
    extensions.digest(
      ops.canonical_jsonb_v1(v_reason_binding), 'sha256'
    ), 'hex'
  );
  SELECT run.* INTO v_run
  FROM ops.agent_runs AS run
  WHERE run.id = p_agent_run_id
  FOR UPDATE;
  IF NOT FOUND OR v_run.run_contract_version <> 2 THEN
    RAISE EXCEPTION 'agent_run_v2_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_actual_micros_krw > v_run.reserved_micros_krw
     OR v_actual_micros_krw > v_run.max_micros_krw THEN
    RAISE EXCEPTION 'agent_run_terminal_cost_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF p_next_status = 'SUCCEEDED' THEN
    BEGIN
      SELECT validation.* INTO STRICT v_output_validation
      FROM ops.agent_output_validations AS validation
      WHERE validation.agent_run_id = v_run.id
        AND validation.provider_output_sha256 = p_output_sha256
        AND validation.input_snapshot_sha256 = v_run.input_snapshot_hash
        AND validation.validation_status = 'VALID'
        AND validation.schema_status = 'PASS'
        AND validation.citation_status = 'PASS'
        AND validation.policy_status = 'PASS'
        AND validation.run_terminal_status = 'SUCCEEDED'
        AND validation.output_schema_id = v_run.output_schema_id
        AND validation.output_schema_version =
          v_run.output_schema_contract_version
        AND validation.output_schema_sha256 = v_run.output_schema_sha256
      FOR KEY SHARE;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RAISE EXCEPTION 'agent_run_success_validation_missing'
          USING ERRCODE = '23514';
      WHEN TOO_MANY_ROWS THEN
        RAISE EXCEPTION 'agent_run_success_validation_ambiguous'
          USING ERRCODE = '23514';
    END;
    v_output_validation_id := v_output_validation.validation_id;
  END IF;

  IF v_run.version = p_expected_version + 1
     AND v_run.status = p_next_status
     AND v_run.control_state = 'SETTLED' THEN
    SELECT receipt.* INTO v_existing
    FROM ops.agent_run_control_receipts AS receipt
    WHERE receipt.agent_run_id = v_run.id
      AND receipt.aggregate_version = p_expected_version
    FOR SHARE;
    IF NOT FOUND OR v_existing.reason_sha256 <> v_reason_sha256
       OR v_existing.proof_sha256 <> v_proof_sha256
       OR v_existing.prior_receipt_id IS DISTINCT FROM p_prior_receipt_id
       OR v_existing.prior_receipt_sha256 IS DISTINCT FROM
         p_prior_receipt_sha256
       OR v_existing.worker_job_id IS DISTINCT FROM p_job_id
       OR v_existing.worker_lease_token IS DISTINCT FROM p_lease_token
       OR v_existing.worker_fencing_token IS DISTINCT FROM
         p_job_fencing_token
       OR v_run.provider IS DISTINCT FROM p_provider
       OR v_run.model IS DISTINCT FROM p_model
       OR v_run.output_payload IS DISTINCT FROM p_output_payload
       OR v_run.output_validation_id IS DISTINCT FROM v_output_validation_id
       OR v_run.failure_code IS DISTINCT FROM p_failure_code
       OR v_run.actual_cost IS DISTINCT FROM p_actual_cost THEN
      RAISE EXCEPTION 'agent_run_terminal_replay_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN QUERY SELECT v_run.version, v_existing.receipt_id,
      v_existing.receipt_sha256, true;
    RETURN;
  END IF;
  IF v_run.version <> p_expected_version OR v_run.status <> 'RUNNING'
     OR v_run.control_state <> 'ACTIVE' THEN
    RAISE EXCEPTION 'agent_run_terminal_fence_stale'
      USING ERRCODE = '40001';
  END IF;
  SELECT receipt.* INTO v_prior
  FROM ops.agent_run_control_receipts AS receipt
  WHERE receipt.agent_run_id = v_run.id
    AND receipt.aggregate_version = p_expected_version - 1
    AND receipt.receipt_id = p_prior_receipt_id
    AND receipt.receipt_sha256 = p_prior_receipt_sha256
  FOR SHARE;
  IF NOT FOUND OR v_prior.next_status <> v_run.status
     OR v_prior.next_control_state <> v_run.control_state THEN
    RAISE EXCEPTION 'agent_run_control_predecessor_invalid'
      USING ERRCODE = '23514';
  END IF;
  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_job_id AND job.job_type = 'AGENT_RUN'
    AND job.queue = 'analysis-worker' AND job.status = 'RUNNING'
    AND job.lease_token = p_lease_token
    AND job.fencing_token = p_job_fencing_token
    AND job.lease_expires_at > v_now
    AND job.payload->>'agentRunId' = p_agent_run_id::text
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent_run_job_fence_stale' USING ERRCODE = '40001';
  END IF;
  v_budget_disposition := CASE p_next_status
    WHEN 'BUDGET_BLOCKED' THEN 'RELEASED'
    WHEN 'POLICY_BLOCKED' THEN 'RELEASED'
    ELSE 'SETTLED'
  END;
  v_budget_state := v_budget_disposition;
  v_budget_set_sha256 := encode(
    extensions.digest(ops.canonical_jsonb_v1(jsonb_build_object(
      'maxMicrosKrw', v_run.max_micros_krw,
      'reservedMicrosKrw', v_run.reserved_micros_krw,
      'settledMicrosKrw', v_actual_micros_krw,
      'releasedMicrosKrw', v_run.reserved_micros_krw - v_actual_micros_krw,
      'budgetReservationState', v_budget_state
    )), 'sha256'), 'hex'
  );
  SELECT appended.receipt_id, appended.receipt_sha256,
         appended.audit_event_id, appended.outbox_event_id
  INTO v_receipt_id, v_receipt_sha256, v_unused_audit, v_unused_outbox
  FROM ops.append_analysis_run_control_receipt_v2(
    v_run.id, v_run.version, v_run.status, v_run.control_state,
    p_next_status, 'SETTLED', v_proof_kind, v_proof_sha256,
    v_budget_disposition, v_budget_set_sha256, v_reason_code,
    v_reason_sha256, p_prior_receipt_id, p_prior_receipt_sha256,
    p_job_id, p_lease_token, p_job_fencing_token, v_now
  ) AS appended;
  UPDATE ops.agent_runs AS run
  SET status = p_next_status, control_state = 'SETTLED',
      provider = p_provider, model = p_model,
      output_payload = p_output_payload,
      output_validation_id = v_output_validation_id,
      actual_cost = p_actual_cost,
      settled_micros_krw = v_actual_micros_krw,
      remaining_micros_krw = run.max_micros_krw - v_actual_micros_krw,
      budget_reservation_state = v_budget_state,
      failure_code = p_failure_code,
      terminal_receipt_sha256 = v_receipt_sha256,
      completed_at = v_now, version = run.version + 1, updated_at = v_now
  WHERE run.id = v_run.id AND run.version = v_run.version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent_run_terminal_fence_stale'
      USING ERRCODE = '40001';
  END IF;
  PERFORM ops.enqueue_outbox(
    'agent_run', v_run.id::text, v_run.version,
    'agent.run_completed.v1',
    jsonb_build_object(
      'agent_run_id', v_run.id,
      'case_id', v_run.case_id,
      'output_digest', btrim(v_proof_sha256),
      'status', p_next_status
    ), v_now
  );
  RETURN QUERY SELECT v_run.version + 1, v_receipt_id,
    v_receipt_sha256, false;
END
$$;
ALTER FUNCTION ops.complete_agent_run_worker_v2(
  uuid,bigint,uuid,char(64),uuid,uuid,bigint,text,text,text,jsonb,char(64),
  text,jsonb,char(64),numeric
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.complete_agent_run_worker_v2(
  uuid,bigint,uuid,char(64),uuid,uuid,bigint,text,text,text,jsonb,char(64),
  text,jsonb,char(64),numeric
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.complete_agent_run_worker_v2(
  uuid,bigint,uuid,char(64),uuid,uuid,bigint,text,text,text,jsonb,char(64),
  text,jsonb,char(64),numeric
) TO gurine_analysis_worker;

-- 0030's generic preview branch used the action proposal id and preview
-- request digest as a synthetic HYPOTHESIS approval detail.  Preserve the
-- existing owner routine for all other action kinds, but make accepted
-- AgentProposalV2 HYPOTHESIS rows the sole preview authority for this branch.
ALTER FUNCTION ops.execute_action_approval_v1(text,jsonb,uuid)
  RENAME TO execute_action_approval_v1_legacy_0030;
REVOKE ALL ON FUNCTION
  ops.execute_action_approval_v1_legacy_0030(text,jsonb,uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION
  ops.execute_action_approval_v1_legacy_0030(text,jsonb,uuid)
  FROM gurine_control_api;

-- 0003/0006 predate the migration-owned relation convention.  The preview
-- owner needs source access to the accepted suggestion and case. PostgreSQL
-- requires UPDATE privilege for SELECT ... FOR SHARE on the suggestion; the
-- only caller remains the migration-owned SECURITY DEFINER boundary.
GRANT SELECT,UPDATE ON ops.agent_suggestions TO gurine_migrator;
GRANT SELECT,UPDATE ON editorial.cases TO gurine_migrator;

-- The approved HYPOTHESIS executor inserts the human-approved row and uses
-- RETURNING to bind its immutable terminal receipt.  The legacy relation is
-- postgres-owned, so the SECURITY DEFINER owner needs only those two table
-- capabilities; callers still receive no direct relation access.
GRANT SELECT,INSERT ON editorial.hypotheses TO gurine_migrator;

CREATE OR REPLACE FUNCTION ops.accepted_hypothesis_action_authority_v2(
  p_proposal_id uuid,
  p_proposal_version bigint
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, editorial, raw, extensions, pg_temp
AS $$
DECLARE
  v_proposal ops.action_proposals%ROWTYPE;
  v_version ops.action_proposal_versions%ROWTYPE;
  v_suggestion ops.agent_suggestions%ROWTYPE;
  v_origin_run ops.agent_runs%ROWTYPE;
  v_validation ops.agent_output_validations%ROWTYPE;
  v_accept_audit ops.audit_events%ROWTYPE;
  v_materialization_audit ops.audit_events%ROWTYPE;
  v_payload jsonb;
  v_required_citation_ids jsonb;
  v_evidence_segment_ids jsonb;
  v_supporting_evidence_segment_ids jsonb;
  v_contradicting_evidence_segment_ids jsonb;
  v_statement_digest char(64);
  v_evidence_segment_set_digest char(64);
  v_supporting_evidence_set_digest char(64);
  v_contrary_evidence_set_digest char(64);
  v_unknown_set_digest char(64);
BEGIN
  IF p_proposal_id IS NULL OR p_proposal_version IS NULL
     OR p_proposal_version < 1 THEN
    RAISE EXCEPTION 'hypothesis_action_authority_invalid_parameter'
      USING ERRCODE = '22023';
  END IF;
  SELECT proposal.* INTO v_proposal
  FROM ops.action_proposals AS proposal
  WHERE proposal.id = p_proposal_id
    AND proposal.action_kind = 'HYPOTHESIS'
    AND proposal.origin_kind = 'AGENT_PROPOSAL'
    AND proposal.target_type = 'CASE';
  SELECT version.* INTO v_version
  FROM ops.action_proposal_versions AS version
  WHERE version.proposal_id = p_proposal_id
    AND version.version = p_proposal_version;
  IF v_proposal.id IS NULL OR v_version.proposal_id IS NULL
     OR v_proposal.target_id !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR NOT EXISTS (
       SELECT 1 FROM editorial.cases AS current_case
       WHERE current_case.id = v_proposal.target_id::uuid
     ) THEN
    RAISE EXCEPTION 'hypothesis_action_authority_proposal_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT suggestion.* INTO v_suggestion
  FROM ops.agent_suggestions AS suggestion
  WHERE suggestion.id = v_proposal.origin_id
    AND suggestion.proposal_contract_version = 2
    AND suggestion.suggestion_type = 'HYPOTHESIS'
    AND suggestion.status = 'ACCEPTED'
    AND suggestion.decision_kind = 'ACCEPT'
    AND suggestion.case_id = v_proposal.target_id::uuid
    AND suggestion.materialized_target_type = 'ACTION_PROPOSAL_DRAFT'
    AND suggestion.materialized_target_id = v_proposal.id
    AND suggestion.materialized_target_version = v_version.version
    AND suggestion.materialized_target_digest = v_version.content_digest
    AND suggestion.materialized_action_proposal_id = v_proposal.id
    AND suggestion.materialization_receipt_sha256 IS NOT NULL
  FOR SHARE;
  IF NOT FOUND
     OR v_suggestion.version <> v_proposal.origin_version + 1
     OR v_proposal.origin_digest IS DISTINCT FROM v_suggestion.payload_sha256
     OR v_proposal.target_digest
       IS DISTINCT FROM v_suggestion.input_snapshot_sha256 THEN
    RAISE EXCEPTION 'hypothesis_action_authority_suggestion_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT audit.* INTO v_accept_audit
  FROM ops.audit_events AS audit
  WHERE audit.id = v_suggestion.decision_audit_event_id
    AND audit.actor_type = 'USER'
    AND audit.actor_id = v_suggestion.decided_by::text
    AND audit.action = 'AGENT_SUGGESTION_ACCEPTED'
    AND audit.object_type = 'AgentSuggestion'
    AND audit.object_id = v_suggestion.id::text
    AND audit.capability = 'agents.review'
    AND audit.outcome = 'SUCCESS'
    AND audit.reason IS NOT DISTINCT FROM v_suggestion.decision_reason
    AND jsonb_typeof(audit.details) = 'object'
    AND (SELECT count(*) FROM jsonb_object_keys(audit.details)) = 5
    AND audit.details ?& ARRAY[
      'suggestionId','version','payloadSha256','decision','reason'
    ]
    AND audit.details->>'suggestionId' = v_suggestion.id::text
    AND audit.details->>'version' = v_proposal.origin_version::text
    AND audit.details->>'payloadSha256' = btrim(v_suggestion.payload_sha256::text)
    AND audit.details->>'decision' = 'ACCEPT'
    AND audit.details->>'reason' = v_suggestion.decision_reason;
  IF NOT FOUND
     OR v_suggestion.decision_sha256 IS DISTINCT FROM encode(
       extensions.digest(convert_to(
         'ACCEPT:' || v_suggestion.id::text || ':'
           || v_proposal.origin_version::text || ':'
           || v_suggestion.decision_reason,'UTF8'),'sha256'),'hex'
     ) THEN
    RAISE EXCEPTION 'hypothesis_action_authority_acceptance_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT run.* INTO v_origin_run
  FROM ops.agent_runs AS run
  WHERE run.id = v_suggestion.agent_run_id
    AND run.run_contract_version = 2
    AND run.case_id = v_suggestion.case_id
    AND run.status = 'SUCCEEDED'
    AND run.control_state = 'SETTLED'
    AND run.input_snapshot_hash = v_suggestion.input_snapshot_sha256
    AND run.output_payload IS NOT NULL
    AND run.output_validation_id = v_suggestion.citation_validation_id;
  SELECT validation.* INTO v_validation
  FROM ops.agent_output_validations AS validation
  WHERE validation.validation_id = v_suggestion.citation_validation_id
    AND validation.agent_run_id = v_suggestion.agent_run_id
    AND validation.input_snapshot_sha256 = v_suggestion.input_snapshot_sha256
    AND validation.provider_output_sha256 = encode(extensions.digest(
      ops.canonical_jsonb_v1(v_origin_run.output_payload),'sha256'),'hex')
    AND validation.output_schema_id = v_suggestion.target_schema_version
    AND validation.output_schema_id = v_origin_run.output_schema_id
    AND validation.output_schema_version =
      v_origin_run.output_schema_contract_version
    AND validation.output_schema_sha256 = v_origin_run.output_schema_sha256
    AND validation.validation_status = 'VALID'
    AND validation.schema_status = 'PASS'
    AND validation.citation_status = 'PASS'
    AND validation.policy_status = 'PASS'
    AND validation.run_terminal_status = 'SUCCEEDED';
  IF v_origin_run.id IS NULL OR v_validation.validation_id IS NULL THEN
    RAISE EXCEPTION 'hypothesis_action_authority_validation_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT audit.* INTO v_materialization_audit
  FROM ops.audit_events AS audit
  WHERE audit.actor_type = 'USER'
    AND audit.actor_id = v_suggestion.decided_by::text
    AND audit.action = 'ACTION_PROPOSAL_CREATED'
    AND audit.object_type = 'ActionProposal'
    AND audit.object_id = v_proposal.id::text
    AND audit.capability = 'actions.propose'
    AND audit.outcome = 'SUCCESS'
    AND audit.reason IS NULL
    AND jsonb_typeof(audit.details) = 'object'
    AND (SELECT count(*) FROM jsonb_object_keys(audit.details)) = 9
    AND audit.details ?& ARRAY[
      'proposalId','proposalVersion','state','actionKind','targetType',
      'targetId','targetVersion','contentDigest','acceptedAt'
    ]
    AND audit.details->>'proposalId' = v_proposal.id::text
    AND audit.details->>'proposalVersion' = v_version.version::text
    AND audit.details->>'state' = 'DRAFT'
    AND audit.details->>'actionKind' = 'HYPOTHESIS'
    AND audit.details->>'targetType' = 'CASE'
    AND audit.details->>'targetId' = v_proposal.target_id
    AND audit.details->>'targetVersion' = v_proposal.target_version::text
    AND audit.details->>'contentDigest' = btrim(v_version.content_digest::text)
    AND encode(extensions.digest(
      convert_to(audit.details::text,'UTF8'),'sha256'),'hex') =
      v_suggestion.materialization_receipt_sha256
  ORDER BY audit.occurred_at,audit.id
  LIMIT 1;
  IF NOT FOUND OR (
    SELECT count(*)
    FROM ops.audit_events AS audit
    WHERE audit.action = 'ACTION_PROPOSAL_CREATED'
      AND audit.object_type = 'ActionProposal'
      AND audit.object_id = v_proposal.id::text
      AND encode(extensions.digest(
        convert_to(audit.details::text,'UTF8'),'sha256'),'hex') =
        v_suggestion.materialization_receipt_sha256
  ) <> 1 THEN
    RAISE EXCEPTION 'hypothesis_action_authority_materialization_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_payload := v_suggestion.payload;
  IF jsonb_typeof(v_payload) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(v_payload)) <> 6
     OR NOT v_payload ?& ARRAY[
       'kind','statement','supportingCitationIds',
       'contradictingCitationIds','unknowns','limitations'
     ]
     OR v_payload->>'kind' IS DISTINCT FROM 'HYPOTHESIS'
     OR jsonb_typeof(v_payload->'statement') IS DISTINCT FROM 'string'
     OR char_length(btrim(v_payload->>'statement')) NOT BETWEEN 1 AND 4000
     OR jsonb_typeof(v_payload->'supportingCitationIds')
       IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_payload->'supportingCitationIds') > 100
     OR jsonb_typeof(v_payload->'contradictingCitationIds')
       IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_payload->'contradictingCitationIds') > 100
     OR (
       jsonb_array_length(v_payload->'supportingCitationIds') = 0
       AND jsonb_array_length(v_payload->'contradictingCitationIds') = 0
     )
     OR EXISTS (
       SELECT 1 FROM (
         SELECT item.value
         FROM jsonb_array_elements(v_payload->'supportingCitationIds')
           AS item(value)
         UNION ALL
         SELECT item.value
         FROM jsonb_array_elements(v_payload->'contradictingCitationIds')
           AS item(value)
       ) AS citation(value)
       WHERE jsonb_typeof(citation.value) IS DISTINCT FROM 'string'
          OR citation.value #>> '{}' !~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements_text(v_payload->'supportingCitationIds')
         AS item(value)
       GROUP BY item.value HAVING count(*) <> 1
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements_text(v_payload->'contradictingCitationIds')
         AS item(value)
       GROUP BY item.value HAVING count(*) <> 1
     )
     OR EXISTS (
       SELECT 1
       FROM (
         SELECT item.value
         FROM jsonb_array_elements_text(v_payload->'supportingCitationIds')
           AS item(value)
         UNION ALL
         SELECT item.value
         FROM jsonb_array_elements_text(v_payload->'contradictingCitationIds')
           AS item(value)
       ) AS all_citations(value)
       GROUP BY all_citations.value HAVING count(*) <> 1
     )
     OR jsonb_typeof(v_payload->'unknowns') IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_payload->'unknowns') > 50
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_payload->'unknowns') AS item(value)
       WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
          OR char_length(btrim(item.value #>> '{}')) NOT BETWEEN 1 AND 1000
     )
     OR jsonb_typeof(v_payload->'limitations') IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_payload->'limitations') > 50
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_payload->'limitations') AS item(value)
       WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
          OR char_length(btrim(item.value #>> '{}')) NOT BETWEEN 1 AND 1000
     )
     OR v_suggestion.payload_canonical
       IS DISTINCT FROM ops.canonical_jsonb_v1(v_payload)
     OR v_suggestion.payload_sha256 IS DISTINCT FROM encode(
       extensions.digest(v_suggestion.payload_canonical,'sha256'),'hex'
     ) THEN
    RAISE EXCEPTION 'hypothesis_action_authority_payload_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(required.citation_id)
      ORDER BY required.citation_id),'[]'::jsonb)
    INTO v_required_citation_ids
  FROM (
    SELECT item.value::uuid AS citation_id
    FROM jsonb_array_elements_text(v_payload->'supportingCitationIds')
      AS item(value)
    UNION
    SELECT item.value::uuid AS citation_id
    FROM jsonb_array_elements_text(v_payload->'contradictingCitationIds')
      AS item(value)
  ) AS required;
  LOCK TABLE ops.agent_proposal_citations IN SHARE MODE;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(v_required_citation_ids) AS item(value)
    WHERE NOT EXISTS (
      SELECT 1 FROM ops.agent_proposal_citations AS citation
      WHERE citation.citation_id = item.value::uuid
        AND citation.citation_contract_version = 2
        AND citation.proposal_id = v_suggestion.id
        AND citation.agent_run_id = v_origin_run.id
        AND citation.provider_turn_id = v_validation.provider_turn_id
        AND citation.validation_id = v_validation.validation_id
        AND citation.dataset_snapshot_id = v_origin_run.dataset_snapshot_id
        AND citation.input_snapshot_sha256 = v_origin_run.input_snapshot_hash
        AND citation.proposal_payload_sha256 = v_suggestion.payload_sha256
        AND (
          (citation.source_kind = 'EVIDENCE_SEGMENT'
           AND citation.evidence_segment_id IS NOT NULL
           AND citation.research_artifact_id IS NULL)
          OR
          (citation.source_kind = 'RUN_TOOL_ARTIFACT'
           AND citation.research_artifact_id IS NOT NULL
           AND citation.evidence_segment_id IS NULL)
        )
    )
  ) OR EXISTS (
    SELECT 1 FROM ops.agent_proposal_citations AS citation
    WHERE citation.proposal_id = v_suggestion.id
      AND (
        citation.citation_contract_version <> 2
        OR citation.agent_run_id <> v_origin_run.id
        OR citation.provider_turn_id <> v_validation.provider_turn_id
        OR citation.validation_id <> v_validation.validation_id
        OR citation.dataset_snapshot_id <> v_origin_run.dataset_snapshot_id
        OR citation.input_snapshot_sha256 <> v_origin_run.input_snapshot_hash
        OR citation.proposal_payload_sha256 <> v_suggestion.payload_sha256
        OR NOT (
          (citation.source_kind = 'EVIDENCE_SEGMENT'
           AND citation.evidence_segment_id IS NOT NULL
           AND citation.research_artifact_id IS NULL)
          OR
          (citation.source_kind = 'RUN_TOOL_ARTIFACT'
           AND citation.research_artifact_id IS NOT NULL
           AND citation.evidence_segment_id IS NULL)
        )
        OR NOT v_required_citation_ids @> jsonb_build_array(citation.citation_id)
      )
  ) THEN
    RAISE EXCEPTION 'hypothesis_action_authority_citation_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(bound.evidence_segment_id)
      ORDER BY bound.citation_ordinal),'[]'::jsonb)
    INTO v_evidence_segment_ids
  FROM (
    SELECT citation.evidence_segment_id,
           min(citation.citation_ordinal) AS citation_ordinal
    FROM ops.agent_proposal_citations AS citation
    WHERE citation.proposal_id = v_suggestion.id
      AND citation.source_kind = 'EVIDENCE_SEGMENT'
    GROUP BY citation.evidence_segment_id
  ) AS bound;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'citationOrdinal',bound.citation_ordinal,
      'citationDigest',btrim(bound.citation_digest::text))
      ORDER BY bound.citation_ordinal),'[]'::jsonb)
    INTO v_supporting_evidence_segment_ids
  FROM (
    SELECT citation.citation_ordinal,citation.citation_digest
    FROM ops.agent_proposal_citations AS citation
    WHERE citation.proposal_id = v_suggestion.id
      AND v_payload->'supportingCitationIds'
        @> jsonb_build_array(citation.citation_id)
  ) AS bound;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'citationOrdinal',bound.citation_ordinal,
      'citationDigest',btrim(bound.citation_digest::text))
      ORDER BY bound.citation_ordinal),'[]'::jsonb)
    INTO v_contradicting_evidence_segment_ids
  FROM (
    SELECT citation.citation_ordinal,citation.citation_digest
    FROM ops.agent_proposal_citations AS citation
    WHERE citation.proposal_id = v_suggestion.id
      AND v_payload->'contradictingCitationIds'
        @> jsonb_build_array(citation.citation_id)
  ) AS bound;

  v_statement_digest := encode(extensions.digest(
    convert_to(v_payload->>'statement','UTF8'),'sha256'),'hex');
  v_evidence_segment_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_evidence_segment_ids),'sha256'),'hex');
  v_supporting_evidence_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_supporting_evidence_segment_ids),'sha256'),'hex');
  v_contrary_evidence_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_contradicting_evidence_segment_ids),'sha256'),'hex');
  v_unknown_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_payload->'unknowns'),'sha256'),'hex');

  RETURN jsonb_build_object(
    'proposalId',v_proposal.id,
    'proposalVersion',v_version.version,
    'suggestionId',v_suggestion.id,
    'caseId',v_proposal.target_id::uuid,
    'expectedCaseVersion',v_proposal.target_version,
    'payload',v_payload,
    'payloadSha256',v_suggestion.payload_sha256,
    'statementDigest',v_statement_digest,
    'evidenceSegmentSetDigest',v_evidence_segment_set_digest,
    'supportingEvidenceSetDigest',v_supporting_evidence_set_digest,
    'contraryEvidenceSetDigest',v_contrary_evidence_set_digest,
    'unknownSetDigest',v_unknown_set_digest,
    'materializationReceiptSha256',
      v_suggestion.materialization_receipt_sha256
  );
END $$;
ALTER FUNCTION ops.accepted_hypothesis_action_authority_v2(uuid,bigint)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  ops.accepted_hypothesis_action_authority_v2(uuid,bigint) FROM PUBLIC;

CREATE OR REPLACE FUNCTION ops.preview_accepted_hypothesis_action_draft_v2(
  p_request jsonb,
  p_actor uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, editorial, raw, extensions, pg_temp
AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_proposal ops.action_proposals%ROWTYPE;
  v_version ops.action_proposal_versions%ROWTYPE;
  v_suggestion ops.agent_suggestions%ROWTYPE;
  v_case editorial.cases%ROWTYPE;
  v_payload jsonb;
  v_required_citation_ids jsonb;
  v_evidence_segment_ids jsonb;
  v_supporting_evidence_segment_ids jsonb;
  v_contradicting_evidence_segment_ids jsonb;
  v_statement_digest char(64);
  v_evidence_segment_set_digest char(64);
  v_supporting_evidence_set_digest char(64);
  v_contrary_evidence_set_digest char(64);
  v_unknown_set_digest char(64);
  v_request_digest char(64);
  v_policy_digest char(64);
  v_quorum_plan_digest char(64);
  v_detail jsonb;
  v_detail_canonical bytea;
  v_detail_digest char(64);
  v_preview_id uuid := gen_random_uuid();
  v_preview_audit_event_id uuid := gen_random_uuid();
  v_due_at timestamptz;
  v_binding jsonb;
  v_binding_canonical bytea;
  v_approval_digest char(64);
  v_receipt jsonb;
  v_receipt_digest char(64);
  v_updated_count bigint;
  v_authority jsonb;
BEGIN
  IF p_request IS NULL OR jsonb_typeof(p_request) <> 'object'
     OR p_actor IS NULL THEN
    RAISE EXCEPTION 'invalid_parameter' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM ops.users AS actor
    WHERE actor.id = p_actor AND actor.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'capability_denied' USING ERRCODE = '28000';
  END IF;

  SELECT proposal.* INTO v_proposal
  FROM ops.action_proposals AS proposal
  WHERE proposal.id = NULLIF(p_request->>'proposalId','')::uuid
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'resource_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_proposal.action_kind <> 'HYPOTHESIS' THEN
    RAISE EXCEPTION 'hypothesis_preview_action_kind_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT version.* INTO v_version
  FROM ops.action_proposal_versions AS version
  WHERE version.proposal_id = v_proposal.id
    AND version.version = v_proposal.current_version
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'resource_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_version.state <> 'DRAFT' OR v_version.preview_id IS NOT NULL
     OR NULLIF(p_request->>'expectedVersion','')::bigint
       IS DISTINCT FROM v_version.version
     OR btrim(NULLIF(p_request->>'expectedContentDigest',''))
       IS DISTINCT FROM btrim(v_version.content_digest::text) THEN
    RAISE EXCEPTION 'action_digest_mismatch' USING ERRCODE = '40001';
  END IF;
  v_authority := ops.accepted_hypothesis_action_authority_v2(
    v_proposal.id,v_version.version);

  SELECT suggestion.* INTO v_suggestion
  FROM ops.agent_suggestions AS suggestion
  WHERE suggestion.id = v_proposal.origin_id
    AND suggestion.proposal_contract_version = 2
    AND suggestion.suggestion_type = 'HYPOTHESIS'
    AND suggestion.status = 'ACCEPTED'
    AND suggestion.decision_kind = 'ACCEPT'
    AND suggestion.decision_sha256 IS NOT NULL
    AND suggestion.decision_audit_event_id IS NOT NULL
    AND suggestion.decided_by IS NOT NULL
    AND suggestion.decided_at IS NOT NULL
    AND suggestion.materialized_target_type = 'ACTION_PROPOSAL_DRAFT'
    AND suggestion.materialized_target_id = v_proposal.id
    AND suggestion.materialized_target_version = v_version.version
    AND suggestion.materialized_action_proposal_id = v_proposal.id
    AND suggestion.materialization_receipt_sha256 IS NOT NULL
  FOR SHARE;
  IF NOT FOUND
     OR v_proposal.origin_kind <> 'AGENT_PROPOSAL'
     OR v_proposal.origin_digest IS DISTINCT FROM v_suggestion.payload_sha256
     OR v_version.content_digest
       IS DISTINCT FROM v_suggestion.materialized_target_digest
     OR v_proposal.target_type <> 'CASE'
     OR v_proposal.target_id IS DISTINCT FROM v_suggestion.case_id::text
     OR v_proposal.target_digest
       IS DISTINCT FROM v_suggestion.input_snapshot_sha256 THEN
    RAISE EXCEPTION 'hypothesis_preview_requires_accepted_agent_suggestion'
      USING ERRCODE = '23514';
  END IF;

  SELECT current_case.* INTO v_case
  FROM editorial.cases AS current_case
  WHERE current_case.id = v_suggestion.case_id
  FOR SHARE;
  IF NOT FOUND
     OR v_proposal.target_version IS DISTINCT FROM v_case.version THEN
    RAISE EXCEPTION 'hypothesis_preview_case_version_stale'
      USING ERRCODE = '40001';
  END IF;

  v_payload := v_suggestion.payload;
  IF jsonb_typeof(v_payload) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(v_payload)) <> 6
     OR NOT v_payload ?& ARRAY[
       'kind','statement','supportingCitationIds',
       'contradictingCitationIds','unknowns','limitations'
     ]
     OR jsonb_typeof(v_payload->'kind') IS DISTINCT FROM 'string'
     OR v_payload->>'kind' IS DISTINCT FROM 'HYPOTHESIS'
     OR jsonb_typeof(v_payload->'statement') IS DISTINCT FROM 'string'
     OR char_length(btrim(v_payload->>'statement')) NOT BETWEEN 1 AND 4000
     OR jsonb_typeof(v_payload->'supportingCitationIds')
       IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_payload->'supportingCitationIds') > 100
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(v_payload->'supportingCitationIds') AS item(value)
       WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
          OR item.value #>> '{}' !~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements_text(v_payload->'supportingCitationIds')
         AS item(value)
       GROUP BY item.value HAVING count(*) <> 1
     )
     OR jsonb_typeof(v_payload->'contradictingCitationIds')
       IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_payload->'contradictingCitationIds') > 100
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(v_payload->'contradictingCitationIds')
         AS item(value)
       WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
          OR item.value #>> '{}' !~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements_text(v_payload->'contradictingCitationIds')
         AS item(value)
       GROUP BY item.value HAVING count(*) <> 1
     )
     OR EXISTS (
       SELECT 1
       FROM (
         SELECT item.value
         FROM jsonb_array_elements_text(v_payload->'supportingCitationIds')
           AS item(value)
         UNION ALL
         SELECT item.value
         FROM jsonb_array_elements_text(v_payload->'contradictingCitationIds')
           AS item(value)
       ) AS all_citations(value)
       GROUP BY all_citations.value HAVING count(*) <> 1
     )
     OR (
       jsonb_array_length(v_payload->'supportingCitationIds') = 0
       AND jsonb_array_length(v_payload->'contradictingCitationIds') = 0
     )
     OR jsonb_typeof(v_payload->'unknowns') IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_payload->'unknowns') > 50
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_payload->'unknowns') AS item(value)
       WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
          OR char_length(btrim(item.value #>> '{}')) NOT BETWEEN 1 AND 1000
     )
     OR jsonb_typeof(v_payload->'limitations') IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_payload->'limitations') > 50
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(v_payload->'limitations') AS item(value)
       WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
          OR char_length(btrim(item.value #>> '{}')) NOT BETWEEN 1 AND 1000
     )
     OR v_suggestion.payload_canonical
       IS DISTINCT FROM ops.canonical_jsonb_v1(v_payload)
     OR v_suggestion.payload_sha256 IS DISTINCT FROM encode(
       extensions.digest(v_suggestion.payload_canonical,'sha256'),'hex'
     ) THEN
    RAISE EXCEPTION 'hypothesis_preview_payload_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(required.citation_id)
      ORDER BY required.citation_id),'[]'::jsonb)
    INTO v_required_citation_ids
  FROM (
    SELECT item.value::uuid AS citation_id
    FROM jsonb_array_elements_text(v_payload->'supportingCitationIds')
      AS item(value)
    UNION
    SELECT item.value::uuid AS citation_id
    FROM jsonb_array_elements_text(v_payload->'contradictingCitationIds')
      AS item(value)
  ) AS required;

  -- Exact-set validation needs to exclude a concurrent citation insert as well
  -- as lock every currently bound row.  SHARE conflicts with the writer's
  -- ROW EXCLUSIVE lock and is released with this preview transaction.
  LOCK TABLE ops.agent_proposal_citations IN SHARE MODE;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(v_required_citation_ids) AS item(value)
    WHERE NOT EXISTS (
      SELECT 1
      FROM ops.agent_proposal_citations AS citation
      WHERE citation.citation_id = item.value::uuid
        AND citation.citation_contract_version = 2
        AND citation.proposal_id = v_suggestion.id
        AND citation.agent_run_id = v_suggestion.agent_run_id
        AND citation.validation_id = v_suggestion.citation_validation_id
        AND citation.input_snapshot_sha256 = v_suggestion.input_snapshot_sha256
        AND citation.proposal_payload_sha256 = v_suggestion.payload_sha256
        AND (
          (citation.source_kind = 'EVIDENCE_SEGMENT'
           AND citation.evidence_segment_id IS NOT NULL
           AND citation.research_artifact_id IS NULL)
          OR
          (citation.source_kind = 'RUN_TOOL_ARTIFACT'
           AND citation.research_artifact_id IS NOT NULL
           AND citation.evidence_segment_id IS NULL)
        )
    )
  ) OR EXISTS (
    SELECT 1
    FROM ops.agent_proposal_citations AS citation
    WHERE citation.proposal_id = v_suggestion.id
      AND (
        citation.citation_contract_version <> 2
        OR citation.agent_run_id <> v_suggestion.agent_run_id
        OR citation.validation_id <> v_suggestion.citation_validation_id
        OR citation.input_snapshot_sha256 <> v_suggestion.input_snapshot_sha256
        OR citation.proposal_payload_sha256 <> v_suggestion.payload_sha256
        OR NOT (
          (citation.source_kind = 'EVIDENCE_SEGMENT'
           AND citation.evidence_segment_id IS NOT NULL
           AND citation.research_artifact_id IS NULL)
          OR
          (citation.source_kind = 'RUN_TOOL_ARTIFACT'
           AND citation.research_artifact_id IS NOT NULL
           AND citation.evidence_segment_id IS NULL)
        )
        OR NOT v_required_citation_ids @> jsonb_build_array(citation.citation_id)
      )
  ) THEN
    RAISE EXCEPTION 'hypothesis_preview_citation_binding_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(bound.evidence_segment_id)
      ORDER BY bound.citation_ordinal),'[]'::jsonb)
    INTO v_evidence_segment_ids
  FROM (
    SELECT citation.evidence_segment_id,
           min(citation.citation_ordinal) AS citation_ordinal
    FROM ops.agent_proposal_citations AS citation
    WHERE citation.proposal_id = v_suggestion.id
      AND citation.source_kind = 'EVIDENCE_SEGMENT'
    GROUP BY citation.evidence_segment_id
  ) AS bound;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'citationOrdinal',bound.citation_ordinal,
      'citationDigest',btrim(bound.citation_digest::text))
      ORDER BY bound.citation_ordinal),'[]'::jsonb)
    INTO v_supporting_evidence_segment_ids
  FROM (
    SELECT citation.citation_ordinal,citation.citation_digest
    FROM ops.agent_proposal_citations AS citation
    WHERE citation.proposal_id = v_suggestion.id
      AND v_payload->'supportingCitationIds'
        @> jsonb_build_array(citation.citation_id)
  ) AS bound;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'citationOrdinal',bound.citation_ordinal,
      'citationDigest',btrim(bound.citation_digest::text))
      ORDER BY bound.citation_ordinal),'[]'::jsonb)
    INTO v_contradicting_evidence_segment_ids
  FROM (
    SELECT citation.citation_ordinal,citation.citation_digest
    FROM ops.agent_proposal_citations AS citation
    WHERE citation.proposal_id = v_suggestion.id
      AND v_payload->'contradictingCitationIds'
        @> jsonb_build_array(citation.citation_id)
  ) AS bound;

  v_statement_digest := encode(extensions.digest(
    convert_to(v_payload->>'statement','UTF8'),'sha256'),'hex');
  v_evidence_segment_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_evidence_segment_ids),'sha256'),'hex');
  v_supporting_evidence_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_supporting_evidence_segment_ids),'sha256'),'hex');
  v_contrary_evidence_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_contradicting_evidence_segment_ids),'sha256'),'hex');
  v_unknown_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_payload->'unknowns'),'sha256'),'hex');
  IF v_authority->>'caseId' IS DISTINCT FROM v_proposal.target_id
     OR (v_authority->>'expectedCaseVersion')::bigint
       IS DISTINCT FROM v_proposal.target_version
     OR v_authority->>'statementDigest'
       IS DISTINCT FROM btrim(v_statement_digest::text)
     OR v_authority->>'evidenceSegmentSetDigest'
       IS DISTINCT FROM btrim(v_evidence_segment_set_digest::text)
     OR v_authority->>'supportingEvidenceSetDigest'
       IS DISTINCT FROM btrim(v_supporting_evidence_set_digest::text)
     OR v_authority->>'contraryEvidenceSetDigest'
       IS DISTINCT FROM btrim(v_contrary_evidence_set_digest::text)
     OR v_authority->>'unknownSetDigest'
       IS DISTINCT FROM btrim(v_unknown_set_digest::text) THEN
    RAISE EXCEPTION 'hypothesis_preview_authority_digest_mismatch'
      USING ERRCODE = '23514';
  END IF;
  v_request_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(p_request),'sha256'),'hex');
  v_policy_digest := encode(extensions.digest(
    convert_to('approval-policy.v1','UTF8'),'sha256'),'hex');

  v_detail := jsonb_build_object(
    'kind','HYPOTHESIS',
    'caseId',v_proposal.target_id::uuid,
    'expectedCaseVersion',v_proposal.target_version,
    'statementDigest',v_statement_digest,
    'evidenceSegmentSetDigest',v_evidence_segment_set_digest,
    'unknownSetDigest',v_unknown_set_digest
  );
  v_detail_canonical := ops.canonical_jsonb_v1(jsonb_build_object(
    'actionDetailKind','HYPOTHESIS','actionDetail',v_detail));
  v_detail_digest := encode(extensions.digest(
    v_detail_canonical,'sha256'),'hex');
  v_quorum_plan_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(jsonb_build_object(
      'schemaVersion','action-quorum-plan.v1',
      'proposalId',v_proposal.id,
      'proposalVersion',v_version.version,
      'actionKind','HYPOTHESIS',
      'contentDigest',v_version.content_digest,
      'policyDigest',v_policy_digest,
      'requiredSlots',jsonb_build_array('primary')
    )),'sha256'),'hex');
  v_due_at := LEAST(
    v_now + interval '6 days',v_version.expires_at - interval '1 second');
  IF v_due_at < v_now THEN
    RAISE EXCEPTION 'hypothesis_preview_expired' USING ERRCODE = '40001';
  END IF;

  v_binding := jsonb_build_object(
    'schemaVersion','approval-binding.v1',
    'proposalId',v_proposal.id,
    'proposalVersion',v_version.version,
    'actionKind','HYPOTHESIS',
    'originDigest',v_proposal.origin_digest,
    'contentDigest',v_version.content_digest,
    'rationaleDigest',v_version.rationale_digest,
    'targetType',v_proposal.target_type,
    'targetId',v_proposal.target_id,
    'targetVersion',v_proposal.target_version,
    'targetDigest',v_proposal.target_digest,
    'objectScopeDigest',v_proposal.object_scope_digest,
    'operationId','submitActionDecision',
    'requiredCapability','actions.review',
    'targetRequestDigest',v_version.content_digest,
    'previewId',v_preview_id,
    'approvalSubjectDigest',v_statement_digest,
    'evidenceSetDigest',v_supporting_evidence_set_digest,
    'contraryEvidenceSetDigest',v_contrary_evidence_set_digest,
    'uncertaintySetDigest',v_unknown_set_digest,
    'riskAssessmentDigest',v_request_digest,
    'policySnapshotDigest',v_policy_digest,
    'conflictSnapshotDigest',v_request_digest,
    'expectedEffectDigest',v_request_digest,
    'reversible',true,
    'quorumPlanDigest',v_quorum_plan_digest,
    'effectIdempotencyKeySha256',v_request_digest,
    'notBefore',v_now,
    'expiresAt',v_version.expires_at,
    'actionDetailKind','HYPOTHESIS',
    'actionDetail',v_detail,
    'actionDetailDigest',v_detail_digest
  );
  v_binding_canonical := ops.canonical_jsonb_v1(v_binding);
  v_approval_digest := encode(extensions.digest(
    v_binding_canonical,'sha256'),'hex');
  v_receipt := jsonb_build_object(
    'proposalId',v_proposal.id,
    'proposalVersion',v_version.version,
    'previewId',v_preview_id,
    'previewDigest',v_approval_digest,
    'approvalDigest',v_approval_digest,
    'state','DRAFT',
    'acceptedAt',clock_timestamp()
  );
  v_receipt_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_receipt),'sha256'),'hex');

  UPDATE ops.action_proposal_versions
  SET preview_id = v_preview_id,
      preview_digest = v_approval_digest,
      preview_policy_digest = v_policy_digest,
      preview_encrypted = convert_to(rpad(
        convert_from(v_detail_canonical,'UTF8'),
        greatest(32,octet_length(v_detail_canonical)),' '),'UTF8'),
      previewed_at = v_now,
      previewed_by = p_actor,
      preview_receipt_digest = v_receipt_digest,
      preview_audit_event_id = v_preview_audit_event_id,
      approval_binding = v_binding,
      approval_binding_canonical = v_binding_canonical,
      approval_digest = v_approval_digest,
      operation_id = 'submitActionDecision',
      required_capability = 'actions.review',
      target_request_digest = v_version.content_digest,
      evidence_set_digest = v_supporting_evidence_set_digest,
      contrary_evidence_set_digest = v_contrary_evidence_set_digest,
      uncertainty_set_digest = v_unknown_set_digest,
      risk_assessment_digest = v_request_digest,
      policy_snapshot_digest = v_policy_digest,
      conflict_snapshot_digest = v_request_digest,
      expected_effect_digest = v_request_digest,
      reversible = true,
      quorum_plan_digest = v_quorum_plan_digest,
      effect_idempotency_key_sha256 = v_request_digest,
      action_detail_kind = 'HYPOTHESIS',
      action_detail = v_detail,
      action_detail_canonical = v_detail_canonical,
      action_detail_digest = v_detail_digest,
      quorum_policy_version = 'approval-policy.v1',
      not_before = v_now,
      due_at = v_due_at,
      submitted_at = v_now,
      state_version = state_version + 1,
      updated_at = v_now
  WHERE proposal_id = v_proposal.id
    AND version = v_version.version
    AND state = 'DRAFT'
    AND preview_id IS NULL;
  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> 1 THEN
    RAISE EXCEPTION 'action_digest_mismatch' USING ERRCODE = '40001';
  END IF;

  INSERT INTO ops.action_approval_hypothesis_details(
    proposal_id,proposal_version,detail_kind,detail_binding_canonical,
    action_detail_digest,case_id,expected_case_version,statement_digest,
    evidence_segment_set_digest,unknown_set_digest
  ) VALUES (
    v_proposal.id,v_version.version,'HYPOTHESIS',v_detail_canonical,
    v_detail_digest,v_proposal.target_id::uuid,v_proposal.target_version,
    v_statement_digest,
    v_evidence_segment_set_digest,v_unknown_set_digest
  );

  UPDATE ops.action_proposals
  SET aggregate_version = aggregate_version + 1,
      last_receipt_digest = v_receipt_digest,
      last_audit_event_id = v_preview_audit_event_id,
      updated_at = clock_timestamp()
  WHERE id = v_proposal.id;

  RETURN v_receipt || jsonb_build_object(
    'receiptDigest',v_receipt_digest,
    'outboxEventIds','[]'::jsonb,
    'approvalBinding',v_binding,
    'approvalSubjectDigest',v_statement_digest,
    'actionDetailKind','HYPOTHESIS',
    'actionDetail',v_detail,
    'expiresAt',v_version.expires_at,
    'contentDigest',v_version.content_digest,
    'actionKind','HYPOTHESIS',
    'targetType',v_proposal.target_type,
    'targetId',v_proposal.target_id,
    'targetVersion',v_proposal.target_version
  );
END $$;
ALTER FUNCTION ops.preview_accepted_hypothesis_action_draft_v2(jsonb,uuid)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  ops.preview_accepted_hypothesis_action_draft_v2(jsonb,uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION ops.execute_action_approval_v1(
  p_operation text,
  p_request jsonb,
  p_actor uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, pg_temp
AS $$
DECLARE
  v_proposal_id uuid;
  v_action_kind text;
  v_origin_kind text;
  v_proposal_contract_version smallint;
BEGIN
  IF p_operation = 'previewActionDraft'
     AND p_request IS NOT NULL
     AND jsonb_typeof(p_request) = 'object' THEN
    v_proposal_id := NULLIF(p_request->>'proposalId','')::uuid;
    IF v_proposal_id IS NOT NULL THEN
      SELECT proposal.action_kind,proposal.origin_kind,
             suggestion.proposal_contract_version
        INTO v_action_kind,v_origin_kind,v_proposal_contract_version
      FROM ops.action_proposals AS proposal
      LEFT JOIN ops.agent_suggestions AS suggestion
        ON suggestion.id = proposal.origin_id
      WHERE proposal.id = v_proposal_id;
      IF v_action_kind = 'HYPOTHESIS'
         AND v_origin_kind = 'AGENT_PROPOSAL'
         AND v_proposal_contract_version = 2 THEN
        RETURN ops.preview_accepted_hypothesis_action_draft_v2(
          p_request,p_actor);
      END IF;
    END IF;
  END IF;
  RETURN ops.execute_action_approval_v1_legacy_0030(
    p_operation,p_request,p_actor);
END $$;
ALTER FUNCTION ops.execute_action_approval_v1(text,jsonb,uuid)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.execute_action_approval_v1(text,jsonb,uuid)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.execute_action_approval_v1(text,jsonb,uuid)
  TO gurine_control_api;

-- Forward owner for accepted AgentProposalV2 HYPOTHESIS review submission.
-- 0030's generic branch persists the nonexistent role alias APPROVER.  Keep
-- every legacy action path intact, but select one currently eligible reviewer
-- and persist that reviewer's exact active role code for strict v2 proposals.
ALTER TABLE editorial.conflict_snapshots
  DROP CONSTRAINT conflict_snapshots_candidate_role_ck;
ALTER TABLE editorial.conflict_snapshots
  ADD CONSTRAINT conflict_snapshots_candidate_role_ck CHECK (
    candidate_role IN (
      'AUTHOR','INVESTIGATOR','EDITOR','LEGAL_REVIEWER','PUBLISHER',
      'APPROVER','EXECUTOR','OPERATIONS','ACCESS_ADMIN','SECURITY_ADMIN',
      'EXECUTIVE_APPROVER'
    )
  );

CREATE OR REPLACE FUNCTION ops.submit_accepted_hypothesis_action_for_review_v2(
  p_request jsonb,
  p_actor uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, editorial, extensions, pg_temp
AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_proposal ops.action_proposals%ROWTYPE;
  v_version ops.action_proposal_versions%ROWTYPE;
  v_detail ops.action_approval_hypothesis_details%ROWTYPE;
  v_case editorial.cases%ROWTYPE;
  v_authority jsonb;
  v_reviewer uuid;
  v_reviewer_role text;
  v_assignment uuid := gen_random_uuid();
  v_conflict_id uuid := gen_random_uuid();
  v_event_id uuid := gen_random_uuid();
  v_due_at timestamptz;
  v_request_digest char(64);
  v_zero_digest char(64);
  v_role_snapshot_digest char(64);
  v_conflict_digest char(64);
  v_conflict_receipt_digest char(64);
  v_excluded_actor_ids uuid[];
  v_exclusion_set_digest char(64);
  v_assignment_digest char(64);
  v_receipt jsonb;
  v_receipt_digest char(64);
  v_updated_count bigint;
BEGIN
  IF p_request IS NULL OR jsonb_typeof(p_request) <> 'object'
     OR p_actor IS NULL THEN
    RAISE EXCEPTION 'invalid_parameter' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM ops.users AS actor
    WHERE actor.id = p_actor AND actor.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'capability_denied' USING ERRCODE = '28000';
  END IF;

  SELECT proposal.* INTO v_proposal
  FROM ops.action_proposals AS proposal
  JOIN ops.agent_suggestions AS suggestion
    ON suggestion.id = proposal.origin_id
   AND suggestion.proposal_contract_version = 2
  WHERE proposal.id = NULLIF(p_request->>'proposalId','')::uuid
    AND proposal.action_kind = 'HYPOTHESIS'
    AND proposal.origin_kind = 'AGENT_PROPOSAL'
    AND proposal.target_type = 'CASE'
  FOR UPDATE OF proposal;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'resource_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT version.* INTO v_version
  FROM ops.action_proposal_versions AS version
  WHERE version.proposal_id = v_proposal.id
    AND version.version = v_proposal.current_version
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'resource_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_version.state <> 'DRAFT'
     OR v_version.preview_id IS NULL
     OR v_version.approval_digest IS NULL
     OR NULLIF(p_request->>'expectedVersion','')::bigint
       IS DISTINCT FROM v_version.version
     OR btrim(NULLIF(p_request->>'expectedContentDigest',''))
       IS DISTINCT FROM btrim(v_version.content_digest::text)
     OR NULLIF(p_request->>'previewId','')::uuid
       IS DISTINCT FROM v_version.preview_id
     OR btrim(NULLIF(p_request->>'previewDigest',''))
       IS DISTINCT FROM btrim(v_version.approval_digest::text) THEN
    RAISE EXCEPTION 'action_preview_stale' USING ERRCODE = '40001';
  END IF;

  v_authority := ops.accepted_hypothesis_action_authority_v2(
    v_proposal.id,v_version.version);
  SELECT detail.* INTO v_detail
  FROM ops.action_approval_hypothesis_details AS detail
  WHERE detail.proposal_id = v_proposal.id
    AND detail.proposal_version = v_version.version;
  SELECT current_case.* INTO v_case
  FROM editorial.cases AS current_case
  WHERE current_case.id = v_proposal.target_id::uuid
  FOR SHARE;
  IF v_detail.proposal_id IS NULL OR v_case.id IS NULL
     OR v_case.version IS DISTINCT FROM v_proposal.target_version
     OR v_version.action_detail_kind IS DISTINCT FROM 'HYPOTHESIS'
     OR v_version.action_detail IS DISTINCT FROM
       convert_from(v_detail.detail_binding_canonical,'UTF8')::jsonb
         ->'actionDetail'
     OR v_version.action_detail_digest
       IS DISTINCT FROM v_detail.action_detail_digest
     OR v_version.approval_binding->'actionDetail'
       IS DISTINCT FROM v_version.action_detail
     OR v_version.approval_binding->>'actionDetailDigest'
       IS DISTINCT FROM btrim(v_detail.action_detail_digest::text)
     OR v_authority->>'caseId' IS DISTINCT FROM v_detail.case_id::text
     OR (v_authority->>'expectedCaseVersion')::bigint
       IS DISTINCT FROM v_detail.expected_case_version
     OR v_authority->>'statementDigest'
       IS DISTINCT FROM btrim(v_detail.statement_digest::text)
     OR v_authority->>'evidenceSegmentSetDigest'
       IS DISTINCT FROM btrim(v_detail.evidence_segment_set_digest::text)
     OR v_authority->>'unknownSetDigest'
       IS DISTINCT FROM btrim(v_detail.unknown_set_digest::text)
     OR v_version.approval_binding->>'approvalSubjectDigest'
       IS DISTINCT FROM v_authority->>'statementDigest'
     OR v_version.approval_binding->>'evidenceSetDigest'
       IS DISTINCT FROM v_authority->>'supportingEvidenceSetDigest'
     OR v_version.approval_binding->>'contraryEvidenceSetDigest'
       IS DISTINCT FROM v_authority->>'contraryEvidenceSetDigest'
     OR v_version.approval_binding->>'uncertaintySetDigest'
       IS DISTINCT FROM v_authority->>'unknownSetDigest' THEN
    RAISE EXCEPTION 'hypothesis_review_authority_mismatch'
      USING ERRCODE = '23514';
  END IF;

  -- Select the user and exact active role as one deterministic row.  Exclude
  -- both the persisted proposer and the current submitter so a delegated
  -- submission cannot create a self-review side door.
  SELECT reviewer.id,role.code INTO v_reviewer,v_reviewer_role
  FROM ops.users AS reviewer
  JOIN ops.user_roles AS membership
    ON membership.user_id = reviewer.id
   AND membership.revoked_at IS NULL
   AND (membership.expires_at IS NULL OR membership.expires_at > v_now)
  JOIN ops.roles AS role ON role.id = membership.role_id
  JOIN ops.role_capabilities AS role_capability
    ON role_capability.role_id = role.id
   AND role_capability.capability_code = 'actions.review'
  WHERE reviewer.status = 'ACTIVE'
    AND reviewer.id <> v_proposal.created_by
    AND reviewer.id <> p_actor
  ORDER BY reviewer.id,role.code
  LIMIT 1;
  IF v_reviewer IS NULL OR v_reviewer_role IS NULL THEN
    RAISE EXCEPTION 'hypothesis_action_quorum_unavailable'
      USING ERRCODE = '55000';
  END IF;

  v_due_at := LEAST(
    v_now + interval '6 days',v_version.expires_at - interval '1 second');
  IF v_due_at < v_now THEN
    RAISE EXCEPTION 'action_preview_stale' USING ERRCODE = '40001';
  END IF;
  v_request_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(p_request),'sha256'),'hex');
  v_zero_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1('[]'::jsonb),'sha256'),'hex');
  v_role_snapshot_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(jsonb_build_object(
      'reviewerId',v_reviewer,'roleCode',v_reviewer_role)),
    'sha256'),'hex');
  v_conflict_digest := encode(extensions.digest(convert_to(
    v_conflict_id::text || ':' || v_reviewer::text || ':'
      || btrim(v_version.approval_digest::text),'UTF8'),'sha256'),'hex');
  v_conflict_receipt_digest := encode(extensions.digest(convert_to(
    btrim(v_conflict_digest::text) || ':receipt','UTF8'),'sha256'),'hex');
  SELECT ARRAY(SELECT DISTINCT excluded.actor_id
      FROM unnest(ARRAY[v_proposal.created_by,p_actor]) AS excluded(actor_id)
      ORDER BY excluded.actor_id)
    INTO v_excluded_actor_ids;
  v_exclusion_set_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(to_jsonb(v_excluded_actor_ids)),
    'sha256'),'hex');
  v_assignment_digest := encode(extensions.digest(convert_to(
    v_assignment::text || ':primary:'
      || btrim(v_version.approval_digest::text),'UTF8'),'sha256'),'hex');

  INSERT INTO editorial.conflict_snapshots(
    id,subject_actor_id,target_type,target_id,target_version,target_digest,
    operation_id,action_kind,candidate_role,declaration_set_digest,
    finding_set,finding_set_digest,authorship_digest,party_recipient_digest,
    role_digest,relationship_digest,funding_customer_digest,policy_digest,
    evaluation_state,valid_until,evaluated_at,evaluated_by_type,
    evaluated_by_id,snapshot_sha256,receipt_digest
  ) VALUES (
    v_conflict_id,v_reviewer,'ACTION_PROPOSAL',v_proposal.id::text,
    v_version.version,v_version.approval_digest,'submitActionDecision',
    'HYPOTHESIS',v_reviewer_role,v_zero_digest,'{}'::jsonb,v_zero_digest,
    v_request_digest,v_request_digest,v_role_snapshot_digest,
    v_request_digest,v_request_digest,v_request_digest,'CLEAR',v_due_at,
    v_now,'SERVICE','action-approval',v_conflict_digest,
    v_conflict_receipt_digest
  );
  INSERT INTO ops.action_review_assignments(
    id,proposal_id,proposal_version,approval_digest,assignment_generation,
    slot_id,slot_ordinal,required_capability,approve_assurance,
    allowed_role_codes,reviewer_id,reviewer_role_snapshot_digest,
    eligibility_snapshot_digest,conflict_snapshot_id,
    conflict_snapshot_digest,conflict_target_id,conflict_target_version,
    conflict_target_digest,conflict_evaluation_state,conflict_valid_until,
    excluded_actor_ids,exclusion_set_digest,quorum_plan_digest,
    assignment_digest,state,version,assigned_by,due_at,last_receipt_digest,
    last_audit_event_id
  ) VALUES (
    v_assignment,v_proposal.id,v_version.version,v_version.approval_digest,
    1,'primary',1,'actions.review','STEP_UP',ARRAY[v_reviewer_role],
    v_reviewer,v_role_snapshot_digest,v_conflict_digest,v_conflict_id,
    v_conflict_digest,v_proposal.id,v_version.version,
    v_version.approval_digest,'CLEAR',v_due_at,v_excluded_actor_ids,
    v_exclusion_set_digest,v_version.quorum_plan_digest,v_assignment_digest,
    'ASSIGNED',1,p_actor,v_due_at,v_version.approval_digest,v_event_id
  );

  UPDATE ops.action_proposal_versions
  SET state = 'PENDING_QUORUM',
      state_version = state_version + 1,
      updated_at = v_now
  WHERE proposal_id = v_proposal.id
    AND version = v_version.version
    AND state = 'DRAFT'
    AND preview_id = v_version.preview_id
    AND approval_digest = v_version.approval_digest;
  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> 1 THEN
    RAISE EXCEPTION 'action_preview_stale' USING ERRCODE = '40001';
  END IF;

  v_receipt := jsonb_build_object(
    'proposalId',v_proposal.id,
    'proposalVersion',v_version.version,
    'assignmentIds',jsonb_build_array(v_assignment),
    'state','PENDING_QUORUM',
    'actionKind','HYPOTHESIS',
    'contentDigest',v_version.content_digest,
    'approvalDigest',v_version.approval_digest,
    'targetType',v_proposal.target_type,
    'targetId',v_proposal.target_id,
    'targetVersion',v_proposal.target_version,
    'expiresAt',v_version.expires_at,
    'acceptedAt',v_now,
    'assignments',jsonb_build_array(jsonb_build_object(
      'assignmentId',v_assignment,
      'version',1,
      'assignmentGeneration',1,
      'slotKind','primary',
      'requiredCapability','actions.review',
      'reviewer',jsonb_build_object(
        'actorType','HUMAN','actorId',v_reviewer,
        'displayName',v_reviewer_role),
      'state','ASSIGNED',
      'dueAt',v_due_at,
      'approvalDigest',v_version.approval_digest)),
    'quorum',jsonb_build_object(
      'planDigest',v_version.quorum_plan_digest,
      'requiredSlots',jsonb_build_array('primary'),
      'satisfiedSlots','[]'::jsonb,
      'blockingSlots',jsonb_build_array('primary'),
      'conflictSnapshotDigest',v_conflict_digest,
      'complete',false)
  );
  v_receipt_digest := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_receipt),'sha256'),'hex');
  UPDATE ops.action_proposals
  SET aggregate_version = aggregate_version + 1,
      last_receipt_digest = v_receipt_digest,
      last_audit_event_id = v_event_id,
      updated_at = v_now
  WHERE id = v_proposal.id;

  RETURN v_receipt || jsonb_build_object(
    'receiptDigest',v_receipt_digest,
    'outboxEventIds','[]'::jsonb
  );
END $$;
ALTER FUNCTION ops.submit_accepted_hypothesis_action_for_review_v2(jsonb,uuid)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  ops.submit_accepted_hypothesis_action_for_review_v2(jsonb,uuid)
  FROM PUBLIC;

-- Replace only the public owner wrapper.  The strict preview route from the
-- preceding forward owner remains unchanged; submit routing uses the same
-- joined v2 discriminator and all other calls retain the 0030 legacy path.
CREATE OR REPLACE FUNCTION ops.execute_action_approval_v1(
  p_operation text,
  p_request jsonb,
  p_actor uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, pg_temp
AS $$
DECLARE
  v_proposal_id uuid;
  v_action_kind text;
  v_origin_kind text;
  v_proposal_contract_version smallint;
BEGIN
  IF p_operation IN ('previewActionDraft','submitActionForReview')
     AND p_request IS NOT NULL
     AND jsonb_typeof(p_request) = 'object' THEN
    v_proposal_id := NULLIF(p_request->>'proposalId','')::uuid;
    IF v_proposal_id IS NOT NULL THEN
      SELECT proposal.action_kind,proposal.origin_kind,
             suggestion.proposal_contract_version
        INTO v_action_kind,v_origin_kind,v_proposal_contract_version
      FROM ops.action_proposals AS proposal
      LEFT JOIN ops.agent_suggestions AS suggestion
        ON suggestion.id = proposal.origin_id
      WHERE proposal.id = v_proposal_id;
      IF v_action_kind = 'HYPOTHESIS'
         AND v_origin_kind = 'AGENT_PROPOSAL'
         AND v_proposal_contract_version = 2 THEN
        IF p_operation = 'previewActionDraft' THEN
          RETURN ops.preview_accepted_hypothesis_action_draft_v2(
            p_request,p_actor);
        END IF;
        RETURN ops.submit_accepted_hypothesis_action_for_review_v2(
          p_request,p_actor);
      END IF;
    END IF;
  END IF;
  RETURN ops.execute_action_approval_v1_legacy_0030(
    p_operation,p_request,p_actor);
END $$;
ALTER FUNCTION ops.execute_action_approval_v1(text,jsonb,uuid)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.execute_action_approval_v1(text,jsonb,uuid)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.execute_action_approval_v1(text,jsonb,uuid)
  TO gurine_control_api;

-- Strict AgentProposalV2 HYPOTHESIS decision precondition.  Governance,
-- assurance, quorum, authorization, audit, and effect creation remain owned by
-- 0030; this owner only locks and revalidates the accepted authority before
-- entering that unchanged legacy transaction body.
CREATE OR REPLACE FUNCTION ops.execute_accepted_hypothesis_action_decision_v2(
  p_request jsonb,
  p_actor uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, editorial, extensions, pg_temp
AS $$
DECLARE
  v_proposal ops.action_proposals%ROWTYPE;
  v_version ops.action_proposal_versions%ROWTYPE;
  v_assignment ops.action_review_assignments%ROWTYPE;
  v_detail ops.action_approval_hypothesis_details%ROWTYPE;
  v_case editorial.cases%ROWTYPE;
  v_authority jsonb;
  v_detail_canonical bytea;
  v_binding_canonical bytea;
  v_binding_digest char(64);
BEGIN
  IF p_request IS NULL OR jsonb_typeof(p_request) <> 'object'
     OR p_actor IS NULL THEN
    RAISE EXCEPTION 'invalid_parameter' USING ERRCODE = '22023';
  END IF;

  -- Match 0030's lock order for the mutable approval aggregate.  Every lock
  -- survives the nested SECURITY DEFINER call because it is the same SQL
  -- transaction, closing the validation-to-decision race.
  SELECT proposal.* INTO v_proposal
  FROM ops.action_proposals AS proposal
  JOIN ops.agent_suggestions AS suggestion
    ON suggestion.id = proposal.origin_id
   AND suggestion.proposal_contract_version = 2
  WHERE proposal.id = NULLIF(p_request->>'proposalId','')::uuid
    AND proposal.action_kind = 'HYPOTHESIS'
    AND proposal.origin_kind = 'AGENT_PROPOSAL'
    AND proposal.target_type = 'CASE'
  FOR UPDATE OF proposal;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'resource_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT version.* INTO v_version
  FROM ops.action_proposal_versions AS version
  WHERE version.proposal_id = v_proposal.id
    AND version.version = v_proposal.current_version
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'resource_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT assignment.* INTO v_assignment
  FROM ops.action_review_assignments AS assignment
  WHERE assignment.id = NULLIF(p_request->>'assignmentId','')::uuid
    AND assignment.proposal_id = v_proposal.id
    AND assignment.proposal_version = v_version.version
  FOR UPDATE;

  -- Aggregate, request, and assignment concurrency mismatches are version
  -- drift.  They must fail before any decision, authorization, or effect row.
  IF v_version.state <> 'PENDING_QUORUM'
     OR v_version.approval_digest IS NULL
     OR NULLIF(p_request->>'expectedProposalVersion','')::bigint
       IS DISTINCT FROM v_version.version
     OR btrim(NULLIF(p_request->>'expectedApprovalDigest',''))
       IS DISTINCT FROM btrim(v_version.approval_digest::text)
     OR NULLIF(p_request->>'actionKind','') IS DISTINCT FROM 'HYPOTHESIS'
     OR v_assignment.id IS NULL
     OR v_assignment.approval_digest
       IS DISTINCT FROM v_version.approval_digest
     OR NULLIF(p_request->>'expectedAssignmentVersion','')::bigint
       IS DISTINCT FROM v_assignment.version THEN
    RAISE EXCEPTION 'hypothesis_action_decision_version_drift'
      USING ERRCODE = '40001';
  END IF;

  SELECT detail.* INTO v_detail
  FROM ops.action_approval_hypothesis_details AS detail
  WHERE detail.proposal_id = v_proposal.id
    AND detail.proposal_version = v_version.version
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_action_decision_authority_mismatch'
      USING ERRCODE = '23514';
  END IF;

  -- The shared verifier locks the accepted suggestion and exact citation set.
  -- Calling it after the aggregate locks makes its authority stable until the
  -- nested legacy decision routine returns.
  v_authority := ops.accepted_hypothesis_action_authority_v2(
    v_proposal.id,v_version.version);
  SELECT current_case.* INTO v_case
  FROM editorial.cases AS current_case
  WHERE current_case.id = v_proposal.target_id::uuid
  FOR SHARE;
  IF v_case.id IS NULL
     OR v_case.version IS DISTINCT FROM v_proposal.target_version THEN
    RAISE EXCEPTION 'hypothesis_action_decision_case_version_drift'
      USING ERRCODE = '40001';
  END IF;

  v_detail_canonical := ops.canonical_jsonb_v1(jsonb_build_object(
    'actionDetailKind','HYPOTHESIS',
    'actionDetail',v_version.action_detail));
  v_binding_canonical := ops.canonical_jsonb_v1(v_version.approval_binding);
  v_binding_digest := encode(extensions.digest(
    v_binding_canonical,'sha256'),'hex');
  IF v_version.action_detail_kind IS DISTINCT FROM 'HYPOTHESIS'
     OR jsonb_typeof(v_version.action_detail) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(v_version.action_detail)) <> 6
     OR NOT v_version.action_detail ?& ARRAY[
       'kind','caseId','expectedCaseVersion','statementDigest',
       'evidenceSegmentSetDigest','unknownSetDigest'
     ]
     OR v_version.action_detail->>'kind' IS DISTINCT FROM 'HYPOTHESIS'
     OR v_version.action_detail_canonical
       IS DISTINCT FROM v_detail_canonical
     OR v_detail.detail_binding_canonical
       IS DISTINCT FROM v_detail_canonical
     OR v_version.action_detail_digest IS DISTINCT FROM encode(
       extensions.digest(v_detail_canonical,'sha256'),'hex')
     OR v_detail.action_detail_digest
       IS DISTINCT FROM v_version.action_detail_digest
     OR v_version.approval_binding_canonical
       IS DISTINCT FROM v_binding_canonical
     OR v_version.approval_digest IS DISTINCT FROM v_binding_digest
     OR v_version.approval_binding->'actionDetail'
       IS DISTINCT FROM v_version.action_detail
     OR v_version.approval_binding->>'actionDetailDigest'
       IS DISTINCT FROM btrim(v_version.action_detail_digest::text)
     OR v_version.approval_binding->>'proposalId'
       IS DISTINCT FROM v_proposal.id::text
     OR v_version.approval_binding->>'proposalVersion'
       IS DISTINCT FROM v_version.version::text
     OR v_version.approval_binding->>'actionKind'
       IS DISTINCT FROM 'HYPOTHESIS'
     OR v_version.approval_binding->>'contentDigest'
       IS DISTINCT FROM btrim(v_version.content_digest::text)
     OR v_authority->>'caseId' IS DISTINCT FROM v_detail.case_id::text
     OR (v_authority->>'expectedCaseVersion')::bigint
       IS DISTINCT FROM v_detail.expected_case_version
     OR v_authority->>'statementDigest'
       IS DISTINCT FROM btrim(v_detail.statement_digest::text)
     OR v_authority->>'evidenceSegmentSetDigest'
       IS DISTINCT FROM btrim(v_detail.evidence_segment_set_digest::text)
     OR v_authority->>'unknownSetDigest'
       IS DISTINCT FROM btrim(v_detail.unknown_set_digest::text)
     OR v_version.approval_binding->>'approvalSubjectDigest'
       IS DISTINCT FROM v_authority->>'statementDigest'
     OR btrim(v_version.evidence_set_digest::text)
       IS DISTINCT FROM v_authority->>'supportingEvidenceSetDigest'
     OR btrim(v_version.contrary_evidence_set_digest::text)
       IS DISTINCT FROM v_authority->>'contraryEvidenceSetDigest'
     OR btrim(v_version.uncertainty_set_digest::text)
       IS DISTINCT FROM v_authority->>'unknownSetDigest'
     OR v_version.approval_binding->>'evidenceSetDigest'
       IS DISTINCT FROM v_authority->>'supportingEvidenceSetDigest'
     OR v_version.approval_binding->>'contraryEvidenceSetDigest'
       IS DISTINCT FROM v_authority->>'contraryEvidenceSetDigest'
     OR v_version.approval_binding->>'uncertaintySetDigest'
       IS DISTINCT FROM v_authority->>'unknownSetDigest' THEN
    RAISE EXCEPTION 'hypothesis_action_decision_authority_mismatch'
      USING ERRCODE = '23514';
  END IF;

  RETURN ops.execute_action_approval_v1_legacy_0030(
    'submitActionDecision',p_request,p_actor);
END $$;
ALTER FUNCTION ops.execute_accepted_hypothesis_action_decision_v2(jsonb,uuid)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  ops.execute_accepted_hypothesis_action_decision_v2(jsonb,uuid)
  FROM PUBLIC;

-- Extend the forward wrapper discriminator once more.  V2 decision requests
-- enter the precondition owner; every non-v2 and non-HYPOTHESIS path remains
-- byte-for-byte owned by the renamed 0030 implementation.
CREATE OR REPLACE FUNCTION ops.execute_action_approval_v1(
  p_operation text,
  p_request jsonb,
  p_actor uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, pg_temp
AS $$
DECLARE
  v_proposal_id uuid;
  v_action_kind text;
  v_origin_kind text;
  v_proposal_contract_version smallint;
BEGIN
  IF p_operation IN (
       'previewActionDraft','submitActionForReview','submitActionDecision'
     )
     AND p_request IS NOT NULL
     AND jsonb_typeof(p_request) = 'object' THEN
    v_proposal_id := NULLIF(p_request->>'proposalId','')::uuid;
    IF v_proposal_id IS NOT NULL THEN
      SELECT proposal.action_kind,proposal.origin_kind,
             suggestion.proposal_contract_version
        INTO v_action_kind,v_origin_kind,v_proposal_contract_version
      FROM ops.action_proposals AS proposal
      LEFT JOIN ops.agent_suggestions AS suggestion
        ON suggestion.id = proposal.origin_id
      WHERE proposal.id = v_proposal_id;
      IF v_action_kind = 'HYPOTHESIS'
         AND v_origin_kind = 'AGENT_PROPOSAL'
         AND v_proposal_contract_version = 2 THEN
        IF p_operation = 'previewActionDraft' THEN
          RETURN ops.preview_accepted_hypothesis_action_draft_v2(
            p_request,p_actor);
        ELSIF p_operation = 'submitActionForReview' THEN
          RETURN ops.submit_accepted_hypothesis_action_for_review_v2(
            p_request,p_actor);
        END IF;
        RETURN ops.execute_accepted_hypothesis_action_decision_v2(
          p_request,p_actor);
      END IF;
    END IF;
  END IF;
  RETURN ops.execute_action_approval_v1_legacy_0030(
    p_operation,p_request,p_actor);
END $$;
ALTER FUNCTION ops.execute_action_approval_v1(text,jsonb,uuid)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.execute_action_approval_v1(text,jsonb,uuid)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.execute_action_approval_v1(text,jsonb,uuid)
  TO gurine_control_api;

-- HYPOTHESIS is a DATABASE_ONLY effect. Loading is a mutation-free sealed
-- read. The executor commits claim, dispatch, editorial mutation and terminal
-- proof atomically, so no committed intermediate lease can require reclaim.

-- PostgreSQL row-locking SELECT requires an UPDATE privilege. Keep this to the
-- two inbox ownership columns; neither runtime worker receives table DML.
GRANT UPDATE (processed_at, result) ON ops.inbox TO gurine_migrator;

CREATE OR REPLACE FUNCTION ops.load_approved_hypothesis_execution_v1(
  p_job_id uuid,
  p_lease_token uuid,
  p_job_fencing_token bigint,
  p_execution_id uuid,
  p_generation bigint,
  p_event jsonb
) RETURNS TABLE(
  proposal_id uuid,
  proposal_version bigint,
  target_request_encrypted bytea,
  target_request_sha256 char(64)
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, editorial, extensions, pg_temp
AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_event_id uuid;
  v_job ops.jobs%ROWTYPE;
  v_inbox ops.inbox%ROWTYPE;
  v_outbox ops.outbox%ROWTYPE;
  v_auth ops.execution_authorizations%ROWTYPE;
  v_effect ops.in_flight_effects%ROWTYPE;
  v_attempt ops.execution_attempts%ROWTYPE;
  v_initial_receipt ops.execution_receipts%ROWTYPE;
  v_terminal_receipt ops.execution_receipts%ROWTYPE;
  v_version ops.action_proposal_versions%ROWTYPE;
  v_proposal ops.action_proposals%ROWTYPE;
  v_detail ops.action_approval_hypothesis_details%ROWTYPE;
  v_suggestion ops.agent_suggestions%ROWTYPE;
  v_authority jsonb;
  v_expected_draft jsonb;
  v_expected_sha256 char(64);
BEGIN
  IF session_user <> 'gurine_workflow_worker'
     OR p_job_id IS NULL OR p_lease_token IS NULL
     OR p_job_fencing_token IS NULL OR p_job_fencing_token < 1
     OR p_execution_id IS NULL OR p_generation IS DISTINCT FROM 1
     OR p_event IS NULL
     OR jsonb_typeof(p_event) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(p_event)) <> 8
     OR NOT p_event ?& ARRAY[
       'executionId','generation','actionKind','decisionDigest',
       'executionDigest','targetCommand','targetRequestSha256','expiresAt'
     ]
     OR COALESCE(p_event->>'executionId','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR p_event->>'executionId' IS DISTINCT FROM p_execution_id::text
     OR p_event->>'generation' IS DISTINCT FROM p_generation::text
     OR COALESCE(p_event->>'decisionDigest','') !~ '^[0-9a-f]{64}$'
     OR COALESCE(p_event->>'executionDigest','') !~ '^[0-9a-f]{64}$'
     OR COALESCE(p_event->>'targetRequestSha256','') !~ '^[0-9a-f]{64}$'
     OR p_event->>'actionKind' IS DISTINCT FROM 'HYPOTHESIS'
     OR p_event->>'targetCommand' IS DISTINCT FROM 'createHypothesis'
     OR COALESCE(p_event->>'expiresAt','') = '' THEN
    RAISE EXCEPTION 'hypothesis_execution_load_invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_job_id
    AND job.job_type = 'EVENT_DELIVERY'
    AND job.queue = 'workflow-worker'
    AND job.status = 'RUNNING'
    AND job.lease_owner IS NOT NULL
    AND length(btrim(job.lease_owner)) BETWEEN 1 AND 160
    AND job.lease_token = p_lease_token
    AND job.fencing_token = p_job_fencing_token
    AND job.lease_expires_at > v_now
  FOR SHARE;
  IF NOT FOUND OR jsonb_typeof(v_job.payload) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(v_job.payload)) <> 8
     OR v_job.payload->>'consumerId'
       IS DISTINCT FROM 'action-execution-worker'
     OR v_job.payload->>'eventType'
       IS DISTINCT FROM 'action.execution_authorized.v1'
     OR v_job.payload->>'aggregateType' IS DISTINCT FROM 'action_execution'
     OR v_job.payload->>'aggregateId' IS DISTINCT FROM p_execution_id::text
     OR COALESCE(v_job.payload->>'eventId','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR v_job.payload->>'aggregateVersion' IS DISTINCT FROM '1'
     OR v_job.payload->'payload' IS DISTINCT FROM p_event
     OR COALESCE(v_job.payload->>'occurredAt','') = '' THEN
    RAISE EXCEPTION 'hypothesis_execution_job_fence_invalid'
      USING ERRCODE = '40001';
  END IF;
  v_event_id := (v_job.payload->>'eventId')::uuid;
  SELECT inbox.* INTO v_inbox
  FROM ops.inbox AS inbox
  WHERE inbox.consumer = 'action-execution-worker'
    AND inbox.event_id = v_event_id
    AND inbox.processed_at IS NULL
    AND inbox.result = 'DISPATCHED:' || p_job_id::text
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_execution_event_not_claimable'
      USING ERRCODE = '40001';
  END IF;
  SELECT event.* INTO v_outbox
  FROM ops.outbox AS event
  WHERE event.id = v_event_id
    AND event.aggregate_type = 'action_execution'
    AND event.aggregate_id = p_execution_id::text
    AND event.aggregate_version = 1
    AND event.event_type = 'action.execution_authorized.v1'
    AND event.payload = p_event
    AND event.occurred_at = (v_job.payload->>'occurredAt')::timestamptz
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_execution_outbox_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT auth.* INTO v_auth
  FROM ops.execution_authorizations AS auth
  WHERE auth.execution_id = p_execution_id AND auth.generation = 1
  FOR SHARE;
  IF NOT FOUND OR v_auth.authorization_kind IS DISTINCT FROM 'INITIAL_APPROVAL'
     OR v_auth.retry_of_generation IS NOT NULL
     OR v_auth.safe_retry_proof IS NOT NULL
     OR v_auth.requested_by_actor_id IS NOT NULL
     OR v_auth.outbox_id IS DISTINCT FROM v_outbox.id
     OR v_auth.action_kind IS DISTINCT FROM 'HYPOTHESIS'
     OR v_auth.executor_id IS DISTINCT FROM 'createHypothesis'
     OR v_auth.transport IS DISTINCT FROM 'BASE_APPLICATION_COMMAND'
     OR v_auth.required_capability IS DISTINCT FROM 'cases.investigate'
     OR v_auth.target_request_schema_version
       IS DISTINCT FROM 'action-payload.v1'
     OR v_auth.effect_boundary IS DISTINCT FROM 'DATABASE_ONLY'
     OR v_auth.cost_class IS DISTINCT FROM 'NO_PAID_EGRESS'
     OR v_auth.provider_config_id IS NOT NULL
     OR v_auth.provider_config_version IS NOT NULL
     OR btrim(v_auth.execution_digest::text)
       IS DISTINCT FROM p_event->>'executionDigest'
     OR btrim(v_auth.terminal_decision_receipt_digest::text)
       IS DISTINCT FROM p_event->>'decisionDigest'
     OR btrim(v_auth.target_request_sha256::text)
       IS DISTINCT FROM p_event->>'targetRequestSha256'
     OR v_auth.expires_at IS DISTINCT FROM
       (p_event->>'expiresAt')::timestamptz THEN
    RAISE EXCEPTION 'hypothesis_execution_authorization_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT proposal.* INTO v_proposal
  FROM ops.action_proposals AS proposal
  WHERE proposal.id = v_auth.proposal_id
    AND proposal.current_version = v_auth.proposal_version
    AND proposal.action_kind = 'HYPOTHESIS'
    AND proposal.origin_kind = 'AGENT_PROPOSAL'
    AND proposal.target_type = 'CASE'
  FOR SHARE;
  SELECT version.* INTO v_version
  FROM ops.action_proposal_versions AS version
  WHERE version.proposal_id = v_auth.proposal_id
    AND version.version = v_auth.proposal_version
    AND version.state = 'APPROVED'
    AND version.approval_digest = v_auth.approval_digest
    AND version.action_detail_kind = 'HYPOTHESIS'
  FOR SHARE;
  SELECT detail.* INTO v_detail
  FROM ops.action_approval_hypothesis_details AS detail
  WHERE detail.proposal_id = v_auth.proposal_id
    AND detail.proposal_version = v_auth.proposal_version
    AND detail.detail_kind = 'HYPOTHESIS'
    AND detail.action_detail_digest = v_version.action_detail_digest
    AND detail.detail_binding_canonical = v_version.action_detail_canonical
    AND detail.case_id::text = v_proposal.target_id
    AND detail.expected_case_version = v_proposal.target_version
  FOR SHARE;
  SELECT suggestion.* INTO v_suggestion
  FROM ops.agent_suggestions AS suggestion
  WHERE suggestion.id = v_proposal.origin_id
    AND suggestion.proposal_contract_version = 2
    AND suggestion.suggestion_type = 'HYPOTHESIS'
    AND suggestion.status = 'ACCEPTED'
    AND suggestion.decision_kind = 'ACCEPT'
    AND suggestion.decided_by = v_proposal.created_by
    AND v_proposal.owner_user_id = v_proposal.created_by
    AND suggestion.materialized_action_proposal_id = v_proposal.id
  FOR SHARE;
  IF v_proposal.id IS NULL OR v_version.proposal_id IS NULL
     OR v_detail.proposal_id IS NULL OR v_suggestion.id IS NULL
     OR v_version.content_digest IS DISTINCT FROM v_auth.target_request_sha256
     OR v_version.target_request_digest
       IS DISTINCT FROM v_auth.target_request_sha256
     OR v_version.payload_encrypted
       IS DISTINCT FROM v_auth.target_request_encrypted THEN
    RAISE EXCEPTION 'hypothesis_execution_proposal_invalid'
      USING ERRCODE = '23514';
  END IF;
  v_authority := ops.accepted_hypothesis_action_authority_v2(
    v_proposal.id,v_version.version
  );
  IF jsonb_typeof(v_authority) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(v_authority)) <> 13
     OR v_authority->>'proposalId' IS DISTINCT FROM v_proposal.id::text
     OR v_authority->>'proposalVersion'
       IS DISTINCT FROM v_version.version::text
     OR v_authority->>'suggestionId' IS DISTINCT FROM v_suggestion.id::text
     OR v_authority->>'caseId' IS DISTINCT FROM v_proposal.target_id
     OR v_authority->>'expectedCaseVersion'
       IS DISTINCT FROM v_proposal.target_version::text
     OR v_authority->>'statementDigest'
       IS DISTINCT FROM btrim(v_detail.statement_digest::text)
     OR v_authority->>'evidenceSegmentSetDigest'
       IS DISTINCT FROM btrim(v_detail.evidence_segment_set_digest::text)
     OR v_authority->>'unknownSetDigest'
       IS DISTINCT FROM btrim(v_detail.unknown_set_digest::text)
     OR v_authority->>'supportingEvidenceSetDigest'
       IS DISTINCT FROM btrim(v_version.evidence_set_digest::text)
     OR v_authority->>'contraryEvidenceSetDigest'
       IS DISTINCT FROM btrim(v_version.contrary_evidence_set_digest::text)
     OR v_authority->>'materializationReceiptSha256'
       IS DISTINCT FROM btrim(v_suggestion.materialization_receipt_sha256::text)
  THEN
    RAISE EXCEPTION 'hypothesis_execution_payload_authority_invalid'
      USING ERRCODE = '23514';
  END IF;
  v_expected_draft := jsonb_build_object(
    'kind','HYPOTHESIS',
    'target',jsonb_build_object(
      'type','CASE','id',v_proposal.target_id,
      'version',v_proposal.target_version,
      'digest',btrim(v_proposal.target_digest::text)
    ),
    'objectScopeDigest',btrim(v_proposal.object_scope_digest::text),
    'contentDigest',v_authority->>'payloadSha256',
    'proposal',v_authority->'payload'
  );
  v_expected_sha256 := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_expected_draft),'sha256'
  ),'hex');
  IF v_expected_sha256 IS DISTINCT FROM v_version.content_digest
     OR v_auth.target_request_encrypted IS NULL
     OR octet_length(v_auth.target_request_encrypted) < 32 THEN
    RAISE EXCEPTION 'hypothesis_execution_sealed_draft_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT effect.* INTO v_effect
  FROM ops.in_flight_effects AS effect
  WHERE effect.id = p_execution_id
    AND effect.effect_type = 'ACTION_EXECUTION'
    AND effect.action_kind = 'HYPOTHESIS'
    AND effect.action_proposal_id = v_auth.proposal_id
    AND effect.action_proposal_version = v_auth.proposal_version
    AND effect.approval_digest = v_auth.approval_digest
    AND effect.current_generation = 1
  FOR SHARE;
  SELECT attempt.* INTO v_attempt
  FROM ops.execution_attempts AS attempt
  WHERE attempt.execution_id = p_execution_id AND attempt.generation = 1
  FOR SHARE;
  IF v_effect.id IS NULL OR v_attempt.id IS NULL
     OR v_effect.last_receipt_sequence
       IS DISTINCT FROM v_attempt.last_receipt_sequence
     OR v_effect.last_receipt_digest
       IS DISTINCT FROM v_attempt.last_receipt_digest THEN
    RAISE EXCEPTION 'hypothesis_execution_chain_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF v_effect.state = 'SUCCEEDED'
     AND v_effect.state_version = 3
     AND v_attempt.attempt_state = 'SUCCEEDED'
     AND v_attempt.state_version = 4
     AND v_effect.last_receipt_sequence = 4 THEN
    SELECT receipt.* INTO v_terminal_receipt
    FROM ops.execution_receipts AS receipt
    WHERE receipt.execution_id = p_execution_id
      AND receipt.generation = 1
      AND receipt.receipt_sequence = 4
      AND receipt.receipt_digest = v_effect.last_receipt_digest
      AND receipt.receipt_kind = 'EFFECT_SUCCEEDED'
      AND receipt.aggregate_state = 'SUCCEEDED'
      AND receipt.aggregate_state_version = 3
      AND receipt.attempt_state = 'SUCCEEDED'
      AND receipt.receipt_payload->>'attemptStateVersion' = '4'
      AND receipt.receipt_payload->>'receiptSequence' = '4'
      AND receipt.proof_kind = 'NO_EGRESS'
      AND receipt.fencing_token > 0
      AND receipt.receipt_payload->>'producerJobId' = p_job_id::text
    FOR SHARE;
    IF NOT FOUND OR v_attempt.terminal_proof_digest
       IS DISTINCT FROM v_terminal_receipt.proof_digest THEN
      RAISE EXCEPTION 'hypothesis_execution_terminal_chain_invalid'
        USING ERRCODE = '23514';
    END IF;
    RETURN QUERY SELECT v_proposal.id,v_version.version,
      v_auth.target_request_encrypted,v_auth.target_request_sha256;
    RETURN;
  END IF;

  SELECT receipt.* INTO v_initial_receipt
  FROM ops.execution_receipts AS receipt
  WHERE receipt.execution_id = p_execution_id
    AND receipt.generation = 1
    AND receipt.receipt_sequence = 1
    AND receipt.receipt_digest = v_effect.last_receipt_digest
    AND receipt.receipt_kind = 'AUTHORIZATION_QUEUED'
    AND receipt.aggregate_state = 'QUEUED'
    AND receipt.aggregate_state_version = 1
    AND receipt.attempt_state = 'QUEUED'
    AND receipt.outbox_id = v_auth.outbox_id
    AND receipt.request_id = v_auth.request_id
    AND receipt.audit_event_id = v_auth.audit_event_id
    AND receipt.proof_kind = 'NO_EGRESS'
    AND receipt.proof_digest = v_auth.target_request_sha256
  FOR SHARE;
  IF v_effect.state IS DISTINCT FROM 'QUEUED'
     OR v_effect.state_version <> 1
     OR v_attempt.attempt_state IS DISTINCT FROM 'QUEUED'
     OR v_attempt.state_version <> 1
     OR v_effect.last_receipt_sequence <> 1
     OR v_initial_receipt.id IS NULL
     OR v_auth.expires_at <= v_now
     OR NOT EXISTS (
       SELECT 1 FROM editorial.cases AS current_case
       WHERE current_case.id = v_proposal.target_id::uuid
         AND current_case.version = v_proposal.target_version
     ) THEN
    RAISE EXCEPTION 'hypothesis_execution_not_loadable'
      USING ERRCODE = '40001';
  END IF;
  RETURN QUERY SELECT v_proposal.id,v_version.version,
    v_auth.target_request_encrypted,v_auth.target_request_sha256;
END
$$;
ALTER FUNCTION ops.load_approved_hypothesis_execution_v1(
  uuid,uuid,bigint,uuid,bigint,jsonb
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.load_approved_hypothesis_execution_v1(
  uuid,uuid,bigint,uuid,bigint,jsonb
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.load_approved_hypothesis_execution_v1(
  uuid,uuid,bigint,uuid,bigint,jsonb
) TO gurine_workflow_worker;

CREATE OR REPLACE FUNCTION ops.execute_approved_hypothesis_v1(
  p_job_id uuid,
  p_lease_token uuid,
  p_job_fencing_token bigint,
  p_execution_id uuid,
  p_generation bigint,
  p_event jsonb,
  p_decrypted_draft jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, editorial, extensions, pg_temp
AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_event_id uuid;
  v_loaded record;
  v_job ops.jobs%ROWTYPE;
  v_inbox ops.inbox%ROWTYPE;
  v_authorized_outbox ops.outbox%ROWTYPE;
  v_auth ops.execution_authorizations%ROWTYPE;
  v_effect ops.in_flight_effects%ROWTYPE;
  v_attempt ops.execution_attempts%ROWTYPE;
  v_initial_receipt ops.execution_receipts%ROWTYPE;
  v_claim_receipt ops.execution_receipts%ROWTYPE;
  v_dispatch_receipt ops.execution_receipts%ROWTYPE;
  v_terminal_receipt ops.execution_receipts%ROWTYPE;
  v_terminal_outbox ops.outbox%ROWTYPE;
  v_terminal_audit ops.audit_events%ROWTYPE;
  v_claim_audit ops.audit_events%ROWTYPE;
  v_dispatch_audit ops.audit_events%ROWTYPE;
  v_proposal ops.action_proposals%ROWTYPE;
  v_version ops.action_proposal_versions%ROWTYPE;
  v_detail ops.action_approval_hypothesis_details%ROWTYPE;
  v_suggestion ops.agent_suggestions%ROWTYPE;
  v_decision ops.action_decisions%ROWTYPE;
  v_authority jsonb;
  v_expected_draft jsonb;
  v_expected_sha256 char(64);
  v_case editorial.cases%ROWTYPE;
  v_case_version bigint;
  v_hypothesis editorial.hypotheses%ROWTYPE;
  v_hypothesis_id uuid := gen_random_uuid();
  v_proof jsonb;
  v_proof_canonical bytea;
  v_proof_sha256 char(64);
  v_expected_terminal_payload jsonb;
  v_expected_initial_payload jsonb;
  v_expected_claim_payload jsonb;
  v_expected_dispatch_payload jsonb;
  v_expected_outbox_payload jsonb;
  v_expected_audit_details jsonb;
  v_expected_claim_audit_details jsonb;
  v_expected_dispatch_audit_details jsonb;
  v_audit_canonical text;
  v_expected_audit_hash char(64);
  v_receipt_payload jsonb;
  v_receipt_canonical bytea;
  v_receipt_digest char(64);
  v_prior_receipt_digest char(64);
  v_receipt_id uuid;
  v_outbox_id uuid;
  v_audit_id uuid;
BEGIN
  IF p_decrypted_draft IS NULL
     OR jsonb_typeof(p_decrypted_draft) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'hypothesis_execution_completion_invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO STRICT v_loaded
  FROM ops.load_approved_hypothesis_execution_v1(
    p_job_id,p_lease_token,p_job_fencing_token,
    p_execution_id,p_generation,p_event
  );
  v_event_id := (p_event->>'executionId')::uuid;
  IF v_event_id IS DISTINCT FROM p_execution_id THEN
    RAISE EXCEPTION 'hypothesis_execution_identity_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_job_id
    AND job.job_type = 'EVENT_DELIVERY'
    AND job.queue = 'workflow-worker'
    AND job.status = 'RUNNING'
    AND job.lease_token = p_lease_token
    AND job.fencing_token = p_job_fencing_token
    AND job.lease_expires_at > v_now
  FOR SHARE;
  IF NOT FOUND OR v_job.payload->>'consumerId'
       IS DISTINCT FROM 'action-execution-worker'
     OR v_job.payload->>'eventType'
       IS DISTINCT FROM 'action.execution_authorized.v1'
     OR v_job.payload->>'aggregateId' IS DISTINCT FROM p_execution_id::text
     OR v_job.payload->'payload' IS DISTINCT FROM p_event THEN
    RAISE EXCEPTION 'hypothesis_execution_job_fence_invalid'
      USING ERRCODE = '40001';
  END IF;
  v_event_id := (v_job.payload->>'eventId')::uuid;
  SELECT inbox.* INTO v_inbox
  FROM ops.inbox AS inbox
  WHERE inbox.consumer = 'action-execution-worker'
    AND inbox.event_id = v_event_id
    AND inbox.processed_at IS NULL
    AND inbox.result = 'DISPATCHED:' || p_job_id::text
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_execution_event_not_claimable'
      USING ERRCODE = '40001';
  END IF;
  SELECT event.* INTO v_authorized_outbox
  FROM ops.outbox AS event
  WHERE event.id = v_event_id
    AND event.aggregate_type = 'action_execution'
    AND event.aggregate_id = p_execution_id::text
    AND event.aggregate_version = 1
    AND event.event_type = 'action.execution_authorized.v1'
    AND event.payload = p_event
  FOR SHARE;
  SELECT auth.* INTO v_auth
  FROM ops.execution_authorizations AS auth
  WHERE auth.execution_id = p_execution_id AND auth.generation = 1
  FOR SHARE;
  IF v_authorized_outbox.id IS NULL OR v_auth.execution_id IS NULL
     OR v_auth.outbox_id IS DISTINCT FROM v_authorized_outbox.id
     OR v_auth.action_kind IS DISTINCT FROM 'HYPOTHESIS'
     OR v_auth.executor_id IS DISTINCT FROM 'createHypothesis'
     OR v_auth.effect_boundary IS DISTINCT FROM 'DATABASE_ONLY'
     OR btrim(v_auth.target_request_sha256::text)
       IS DISTINCT FROM btrim(v_loaded.target_request_sha256::text)
     OR v_auth.target_request_encrypted
       IS DISTINCT FROM v_loaded.target_request_encrypted THEN
    RAISE EXCEPTION 'hypothesis_execution_revalidation_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT proposal.* INTO v_proposal
  FROM ops.action_proposals AS proposal
  WHERE proposal.id = v_auth.proposal_id
    AND proposal.current_version = v_auth.proposal_version
    AND proposal.action_kind = 'HYPOTHESIS'
    AND proposal.origin_kind = 'AGENT_PROPOSAL'
    AND proposal.target_type = 'CASE'
  FOR SHARE;
  SELECT version.* INTO v_version
  FROM ops.action_proposal_versions AS version
  WHERE version.proposal_id = v_auth.proposal_id
    AND version.version = v_auth.proposal_version
    AND version.state = 'APPROVED'
    AND version.approval_digest = v_auth.approval_digest
    AND version.action_detail_kind = 'HYPOTHESIS'
  FOR SHARE;
  SELECT detail.* INTO v_detail
  FROM ops.action_approval_hypothesis_details AS detail
  WHERE detail.proposal_id = v_auth.proposal_id
    AND detail.proposal_version = v_auth.proposal_version
    AND detail.detail_kind = 'HYPOTHESIS'
    AND detail.action_detail_digest = v_version.action_detail_digest
    AND detail.detail_binding_canonical = v_version.action_detail_canonical
    AND detail.case_id::text = v_proposal.target_id
    AND detail.expected_case_version = v_proposal.target_version
  FOR SHARE;
  SELECT suggestion.* INTO v_suggestion
  FROM ops.agent_suggestions AS suggestion
  WHERE suggestion.id = v_proposal.origin_id
    AND suggestion.proposal_contract_version = 2
    AND suggestion.suggestion_type = 'HYPOTHESIS'
    AND suggestion.status = 'ACCEPTED'
    AND suggestion.decision_kind = 'ACCEPT'
    AND suggestion.decided_by = v_proposal.created_by
    AND v_proposal.owner_user_id = v_proposal.created_by
    AND suggestion.materialized_action_proposal_id = v_proposal.id
  FOR SHARE;
  SELECT decision.* INTO v_decision
  FROM ops.action_decisions AS decision
  WHERE decision.id = v_auth.terminal_decision_id
    AND decision.proposal_id = v_auth.proposal_id
    AND decision.proposal_version = v_auth.proposal_version
    AND decision.approval_digest = v_auth.approval_digest
    AND decision.receipt_digest = v_auth.terminal_decision_receipt_digest
    AND decision.record_kind = 'DECISION'
    AND decision.decision_kind = 'APPROVE'
    AND decision.counts_toward_quorum
    AND decision.quorum_satisfied_after
    AND decision.resulting_proposal_state = 'APPROVED'
    AND decision.execution_id = p_execution_id
  FOR SHARE;
  IF v_proposal.id IS NULL OR v_version.proposal_id IS NULL
     OR v_detail.proposal_id IS NULL OR v_suggestion.id IS NULL
     OR v_decision.id IS NULL
     OR v_version.content_digest IS DISTINCT FROM v_auth.target_request_sha256
     OR v_version.target_request_digest
       IS DISTINCT FROM v_auth.target_request_sha256
     OR v_version.payload_encrypted
       IS DISTINCT FROM v_auth.target_request_encrypted THEN
    RAISE EXCEPTION 'hypothesis_execution_proposal_invalid'
      USING ERRCODE = '23514';
  END IF;
  v_authority := ops.accepted_hypothesis_action_authority_v2(
    v_proposal.id,v_version.version
  );
  v_expected_draft := jsonb_build_object(
    'kind','HYPOTHESIS',
    'target',jsonb_build_object(
      'type','CASE','id',v_proposal.target_id,
      'version',v_proposal.target_version,
      'digest',btrim(v_proposal.target_digest::text)
    ),
    'objectScopeDigest',btrim(v_proposal.object_scope_digest::text),
    'contentDigest',v_authority->>'payloadSha256',
    'proposal',v_authority->'payload'
  );
  v_expected_sha256 := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_expected_draft),'sha256'
  ),'hex');
  IF p_decrypted_draft IS DISTINCT FROM v_expected_draft
     OR v_expected_sha256 IS DISTINCT FROM v_version.content_digest
     OR v_authority->>'proposalId' IS DISTINCT FROM v_proposal.id::text
     OR v_authority->>'suggestionId' IS DISTINCT FROM v_suggestion.id::text
     OR v_authority->>'caseId' IS DISTINCT FROM v_proposal.target_id
     OR v_authority->>'expectedCaseVersion'
       IS DISTINCT FROM v_proposal.target_version::text
     OR v_authority->>'statementDigest'
       IS DISTINCT FROM btrim(v_detail.statement_digest::text)
     OR v_authority->>'evidenceSegmentSetDigest'
       IS DISTINCT FROM btrim(v_detail.evidence_segment_set_digest::text)
     OR v_authority->>'unknownSetDigest'
       IS DISTINCT FROM btrim(v_detail.unknown_set_digest::text)
     OR v_authority->>'supportingEvidenceSetDigest'
       IS DISTINCT FROM btrim(v_version.evidence_set_digest::text)
     OR v_authority->>'contraryEvidenceSetDigest'
       IS DISTINCT FROM btrim(v_version.contrary_evidence_set_digest::text)
     OR v_authority->>'materializationReceiptSha256'
       IS DISTINCT FROM btrim(v_suggestion.materialization_receipt_sha256::text)
  THEN
    RAISE EXCEPTION 'hypothesis_execution_decrypted_draft_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT effect.* INTO v_effect
  FROM ops.in_flight_effects AS effect
  WHERE effect.id = p_execution_id
    AND effect.effect_type = 'ACTION_EXECUTION'
    AND effect.action_kind = 'HYPOTHESIS'
    AND effect.action_proposal_id = v_auth.proposal_id
    AND effect.action_proposal_version = v_auth.proposal_version
    AND effect.approval_digest = v_auth.approval_digest
    AND effect.current_generation = 1
  FOR UPDATE;
  SELECT attempt.* INTO v_attempt
  FROM ops.execution_attempts AS attempt
  WHERE attempt.execution_id = p_execution_id AND attempt.generation = 1
  FOR UPDATE;
  IF v_effect.id IS NULL OR v_attempt.id IS NULL
     OR v_effect.last_receipt_sequence
       IS DISTINCT FROM v_attempt.last_receipt_sequence
     OR v_effect.last_receipt_digest
       IS DISTINCT FROM v_attempt.last_receipt_digest THEN
    RAISE EXCEPTION 'hypothesis_execution_chain_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF v_effect.state = 'SUCCEEDED'
     AND v_effect.state_version = 3
     AND v_attempt.attempt_state = 'SUCCEEDED'
     AND v_attempt.state_version = 4
     AND v_effect.last_receipt_sequence = 4 THEN
    SELECT receipt.* INTO v_terminal_receipt
    FROM ops.execution_receipts AS receipt
    WHERE receipt.execution_id = p_execution_id
      AND receipt.generation = 1
      AND receipt.receipt_sequence = 4
      AND receipt.receipt_digest = v_effect.last_receipt_digest
      AND receipt.receipt_kind = 'EFFECT_SUCCEEDED'
      AND receipt.aggregate_state = 'SUCCEEDED'
      AND receipt.aggregate_state_version = 3
      AND receipt.attempt_state = 'SUCCEEDED'
      AND receipt.receipt_payload->>'attemptStateVersion' = '4'
      AND receipt.receipt_payload->>'receiptSequence' = '4'
      AND receipt.proof_kind = 'NO_EGRESS'
      AND receipt.receipt_payload->>'producerJobId' = p_job_id::text
      AND receipt.receipt_payload->>'terminalApprovalUserId'
        = v_decision.actor_id::text
      AND receipt.receipt_payload->>'creatorUserId'
        = v_decision.actor_id::text
      AND receipt.receipt_payload->>'proposalCreatedBy'
        = v_proposal.created_by::text
      AND receipt.receipt_payload->>'suggestionAcceptedBy'
        = v_suggestion.decided_by::text
    FOR SHARE;
    IF NOT FOUND
       OR COALESCE(v_terminal_receipt.receipt_payload->>'hypothesisId','')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR v_attempt.terminal_proof_digest
         IS DISTINCT FROM v_terminal_receipt.proof_digest
       OR v_attempt.lease_owner IS NOT NULL
       OR v_attempt.lease_token IS NOT NULL
       OR v_attempt.lease_expires_at IS NOT NULL THEN
      RAISE EXCEPTION 'hypothesis_execution_replay_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_hypothesis_id :=
      (v_terminal_receipt.receipt_payload->>'hypothesisId')::uuid;
    SELECT receipt.* INTO v_initial_receipt
    FROM ops.execution_receipts AS receipt
    WHERE receipt.execution_id = p_execution_id
      AND receipt.generation = 1
      AND receipt.receipt_sequence = 1
      AND receipt.receipt_kind = 'AUTHORIZATION_QUEUED'
      AND receipt.receipt_digest = (
        SELECT claim.prior_receipt_digest
        FROM ops.execution_receipts AS claim
        WHERE claim.execution_id = p_execution_id
          AND claim.receipt_sequence = 2
      )
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_execution_replay_authorization_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_expected_initial_payload := jsonb_build_object(
      'schemaVersion','action-execution-receipt.v1',
      'receiptKind','AUTHORIZATION_QUEUED',
      'executionId',p_execution_id,'generation',1,
      'aggregateState','QUEUED','aggregateStateVersion',1,
      'attemptState','QUEUED','attemptStateVersion',1,
      'cancellationGeneration',0,
      'effectCertainty','DEFINITIVE_NOT_ACCEPTED',
      'decisionDigest',btrim(v_auth.terminal_decision_receipt_digest::text),
      'executionDigest',btrim(v_auth.execution_digest::text),
      'targetRequestSha256',btrim(v_auth.target_request_sha256::text),
      'requestId',v_auth.request_id,'occurredAt',v_initial_receipt.observed_at
    );
    IF v_initial_receipt.receipt_payload
         IS DISTINCT FROM v_expected_initial_payload
       OR v_initial_receipt.receipt_payload_canonical
         IS DISTINCT FROM convert_to(v_expected_initial_payload::text,'UTF8')
       OR v_initial_receipt.receipt_digest IS DISTINCT FROM encode(
         extensions.digest(
           convert_to(v_expected_initial_payload::text,'UTF8'),'sha256'
         ),'hex'
       )
       OR NOT v_initial_receipt.mutates_aggregate_state
       OR v_initial_receipt.prior_aggregate_state IS NOT NULL
       OR v_initial_receipt.aggregate_state IS DISTINCT FROM 'QUEUED'
       OR v_initial_receipt.aggregate_state_version IS DISTINCT FROM 1
       OR v_initial_receipt.prior_attempt_state IS NOT NULL
       OR v_initial_receipt.attempt_state IS DISTINCT FROM 'QUEUED'
       OR v_initial_receipt.fencing_token IS DISTINCT FROM 0
       OR v_initial_receipt.cancellation_generation IS DISTINCT FROM 0
       OR v_initial_receipt.attempt_id IS DISTINCT FROM v_attempt.id
       OR v_initial_receipt.provider_acknowledgement_digest IS NOT NULL
       OR v_initial_receipt.provider_observation_digest IS NOT NULL
       OR v_initial_receipt.proof_kind IS DISTINCT FROM 'NO_EGRESS'
       OR v_initial_receipt.proof_digest
         IS DISTINCT FROM v_auth.target_request_sha256
       OR v_initial_receipt.actual_amount IS NOT NULL
       OR v_initial_receipt.actual_currency IS NOT NULL
       OR v_initial_receipt.cost_event_ids IS DISTINCT FROM '{}'::uuid[]
       OR v_initial_receipt.budget_reservation_id
         IS DISTINCT FROM v_auth.budget_reservation_id
       OR v_initial_receipt.budget_reservation_digest
         IS DISTINCT FROM v_auth.budget_reservation_digest
       OR v_initial_receipt.request_id IS DISTINCT FROM v_auth.request_id
       OR v_initial_receipt.audit_event_id IS DISTINCT FROM v_auth.audit_event_id
       OR v_initial_receipt.outbox_id IS DISTINCT FROM v_auth.outbox_id
       OR v_initial_receipt.prior_receipt_digest IS NOT NULL
    THEN
      RAISE EXCEPTION 'hypothesis_execution_replay_authorization_exact_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT receipt.* INTO v_claim_receipt
    FROM ops.execution_receipts AS receipt
    WHERE receipt.execution_id = p_execution_id
      AND receipt.generation = 1
      AND receipt.receipt_sequence = 2
      AND receipt.receipt_kind = 'LEASE_CLAIMED'
      AND receipt.prior_receipt_digest = v_initial_receipt.receipt_digest
    FOR SHARE;
    IF NOT FOUND OR COALESCE(
         v_claim_receipt.receipt_payload->>'leaseExpiresAt',''
       ) = '' THEN
      RAISE EXCEPTION 'hypothesis_execution_replay_claim_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_expected_claim_payload := jsonb_build_object(
      'schemaVersion','action-execution-receipt.v1',
      'receiptKind','LEASE_CLAIMED',
      'executionId',p_execution_id,'generation',1,
      'aggregateState','QUEUED','aggregateStateVersion',1,
      'attemptState','CLAIMED','attemptStateVersion',2,
      'cancellationGeneration',v_effect.cancellation_generation,
      'effectCertainty','DEFINITIVE_NOT_ACCEPTED',
      'executionDigest',btrim(v_auth.execution_digest::text),
