      'attemptId',v_attempt.id,'producerJobId',p_job_id,
      'jobFencingToken',v_claim_receipt.fencing_token,
      'leaseExpiresAt',
        (v_claim_receipt.receipt_payload->>'leaseExpiresAt')::timestamptz,
      'requestId',v_auth.request_id,'occurredAt',v_claim_receipt.observed_at
    );
    v_expected_claim_audit_details := jsonb_build_object(
      'executionId',p_execution_id,'generation',1,
      'attemptId',v_attempt.id,'receiptSequence',2,
      'receiptDigest',v_claim_receipt.receipt_digest,
      'producerJobId',p_job_id,
      'jobFencingToken',v_claim_receipt.fencing_token,
      'leaseExpiresAt',
        (v_claim_receipt.receipt_payload->>'leaseExpiresAt')::timestamptz,
      'priorReceiptDigest',v_initial_receipt.receipt_digest
    );
    SELECT audit.* INTO v_claim_audit
    FROM ops.audit_events AS audit
    WHERE audit.id = v_claim_receipt.audit_event_id
      AND audit.actor_type = 'SERVICE'
      AND audit.actor_id = 'workflow-worker'
      AND audit.session_id IS NULL
      AND audit.action = 'ACTION_EXECUTION_CLAIMED'
      AND audit.object_type = 'ActionExecution'
      AND audit.object_id = p_execution_id::text
      AND audit.capability = 'cases.investigate'
      AND audit.outcome = 'SUCCESS'
      AND audit.reason IS NULL
      AND audit.request_id = v_auth.request_id
      AND audit.details = v_expected_claim_audit_details
    FOR SHARE;
