      RAISE EXCEPTION 'hypothesis_execution_replay_claim_audit_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_audit_canonical := jsonb_build_object(
      'id',v_claim_audit.id,
      'stream_key','workflow:action-execution:' || p_execution_id::text,
      'occurred_at',v_claim_audit.occurred_at,
      'actor_type',v_claim_audit.actor_type,
      'actor_id',v_claim_audit.actor_id,
      'session_id',v_claim_audit.session_id,
      'action',v_claim_audit.action,
      'object_type',v_claim_audit.object_type,
      'object_id',v_claim_audit.object_id,
      'capability',v_claim_audit.capability,
      'outcome',v_claim_audit.outcome,
      'reason',v_claim_audit.reason,
      'request_id',v_claim_audit.request_id,
      'details',v_claim_audit.details,
      'previous_event_hash',v_claim_audit.previous_event_hash
    )::text;
    v_expected_audit_hash := encode(extensions.digest(convert_to(
      COALESCE(v_claim_audit.previous_event_hash,'') ||
      v_audit_canonical,'UTF8'
    ),'sha256'),'hex');
    IF v_claim_receipt.receipt_payload
         IS DISTINCT FROM v_expected_claim_payload
       OR v_claim_receipt.receipt_payload_canonical
         IS DISTINCT FROM ops.canonical_jsonb_v1(v_expected_claim_payload)
       OR v_claim_receipt.receipt_digest IS DISTINCT FROM encode(
         extensions.digest(
           ops.canonical_jsonb_v1(v_expected_claim_payload),'sha256'
         ),'hex'
       )
       OR v_claim_receipt.mutates_aggregate_state
       OR v_claim_receipt.prior_aggregate_state IS DISTINCT FROM 'QUEUED'
       OR v_claim_receipt.aggregate_state IS DISTINCT FROM 'QUEUED'
       OR v_claim_receipt.aggregate_state_version IS DISTINCT FROM 1
       OR v_claim_receipt.prior_attempt_state IS DISTINCT FROM 'QUEUED'
       OR v_claim_receipt.attempt_state IS DISTINCT FROM 'CLAIMED'
       OR v_claim_receipt.attempt_id IS DISTINCT FROM v_attempt.id
       OR v_claim_receipt.fencing_token IS DISTINCT FROM
         (v_claim_receipt.receipt_payload->>'jobFencingToken')::bigint
       OR v_claim_receipt.fencing_token IS NULL
       OR v_claim_receipt.fencing_token < 1
       OR v_claim_receipt.cancellation_generation
         IS DISTINCT FROM v_effect.cancellation_generation
       OR v_claim_receipt.provider_acknowledgement_digest IS NOT NULL
       OR v_claim_receipt.provider_observation_digest IS NOT NULL
       OR v_claim_receipt.outbox_id IS NOT NULL
       OR v_claim_receipt.proof_kind
         IS DISTINCT FROM 'DEFINITIVE_NOT_ACCEPTED'
       OR v_claim_receipt.proof_digest
         IS DISTINCT FROM v_detail.action_detail_digest
       OR v_claim_receipt.actual_amount IS NOT NULL
       OR v_claim_receipt.actual_currency IS NOT NULL
       OR v_claim_receipt.cost_event_ids IS DISTINCT FROM '{}'::uuid[]
       OR v_claim_receipt.budget_reservation_id
         IS DISTINCT FROM v_auth.budget_reservation_id
       OR v_claim_receipt.budget_reservation_digest
         IS DISTINCT FROM v_auth.budget_reservation_digest
       OR v_claim_receipt.request_id IS DISTINCT FROM v_auth.request_id
       OR v_claim_receipt.audit_event_id IS DISTINCT FROM v_claim_audit.id
       OR v_claim_receipt.observed_at IS DISTINCT FROM
         (v_claim_receipt.receipt_payload->>'occurredAt')::timestamptz
       OR v_claim_receipt.prior_receipt_digest
         IS DISTINCT FROM v_initial_receipt.receipt_digest
       OR v_claim_audit.previous_event_hash IS NOT NULL
       OR v_claim_audit.event_hash IS DISTINCT FROM v_expected_audit_hash
    THEN
      RAISE EXCEPTION 'hypothesis_execution_replay_claim_exact_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT receipt.* INTO v_dispatch_receipt
    FROM ops.execution_receipts AS receipt
    WHERE receipt.execution_id = p_execution_id
      AND receipt.generation = 1
      AND receipt.receipt_sequence = 3
