      'stream_key','workflow:action-execution:' || p_execution_id::text,
      'occurred_at',v_dispatch_audit.occurred_at,
      'actor_type',v_dispatch_audit.actor_type,
      'actor_id',v_dispatch_audit.actor_id,
      'session_id',v_dispatch_audit.session_id,
      'action',v_dispatch_audit.action,
      'object_type',v_dispatch_audit.object_type,
