    )::text;
    v_expected_audit_hash := encode(extensions.digest(convert_to(
      COALESCE(v_dispatch_audit.previous_event_hash,'') ||
      v_audit_canonical,'UTF8'
    ),'sha256'),'hex');
    IF v_dispatch_receipt.receipt_payload
         IS DISTINCT FROM v_expected_dispatch_payload
       OR v_dispatch_receipt.receipt_payload_canonical
         IS DISTINCT FROM ops.canonical_jsonb_v1(v_expected_dispatch_payload)
       OR v_dispatch_receipt.receipt_digest IS DISTINCT FROM encode(
         extensions.digest(
           ops.canonical_jsonb_v1(v_expected_dispatch_payload),'sha256'
         ),'hex'
       )
       OR v_dispatch_receipt.attempt_id IS DISTINCT FROM v_attempt.id
       OR NOT v_dispatch_receipt.mutates_aggregate_state
