      'executionDigest',btrim(v_auth.execution_digest::text),
      'receiptSequence',4,
      'receiptDigest',btrim(v_terminal_receipt.receipt_digest::text),
      'costFactIds','[]'::jsonb
    );
    SELECT event.* INTO v_terminal_outbox
    FROM ops.outbox AS event
    WHERE event.id = v_terminal_receipt.outbox_id
      AND event.aggregate_type = 'action_execution'
      AND event.aggregate_id = p_execution_id::text
      AND event.aggregate_version = 3
      AND event.event_type = 'action.execution_completed.v1'
      AND event.payload = v_expected_outbox_payload
      AND (SELECT count(*) FROM jsonb_object_keys(event.payload)) = 8
      AND event.occurred_at = v_terminal_receipt.observed_at
    FOR SHARE;
    v_expected_audit_details := jsonb_build_object(
