       OR v_terminal_receipt.receipt_payload
         IS DISTINCT FROM v_expected_terminal_payload
       OR v_terminal_receipt.receipt_payload_canonical
         IS DISTINCT FROM ops.canonical_jsonb_v1(v_expected_terminal_payload)
       OR v_terminal_receipt.receipt_digest IS DISTINCT FROM encode(
         extensions.digest(
           ops.canonical_jsonb_v1(v_expected_terminal_payload),'sha256'
         ),'hex'
       )
       OR NOT v_terminal_receipt.mutates_aggregate_state
       OR v_terminal_receipt.prior_aggregate_state IS DISTINCT FROM 'RUNNING'
       OR v_terminal_receipt.prior_attempt_state
         IS DISTINCT FROM 'DISPATCHING'
       OR v_terminal_receipt.attempt_id IS DISTINCT FROM v_attempt.id
       OR v_terminal_receipt.fencing_token
         IS DISTINCT FROM v_dispatch_receipt.fencing_token
       OR v_terminal_receipt.cancellation_generation
         IS DISTINCT FROM v_effect.cancellation_generation
       OR v_terminal_receipt.provider_acknowledgement_digest IS NOT NULL
       OR v_terminal_receipt.provider_observation_digest IS NOT NULL
       OR v_terminal_receipt.actual_amount IS NOT NULL
       OR v_terminal_receipt.actual_currency IS NOT NULL
       OR v_terminal_receipt.cost_event_ids IS DISTINCT FROM '{}'::uuid[]
       OR v_terminal_receipt.budget_reservation_id
         IS DISTINCT FROM v_auth.budget_reservation_id
       OR v_terminal_receipt.budget_reservation_digest
         IS DISTINCT FROM v_auth.budget_reservation_digest
       OR v_terminal_receipt.request_id IS DISTINCT FROM v_auth.request_id
       OR v_terminal_receipt.audit_event_id IS DISTINCT FROM v_terminal_audit.id
       OR v_terminal_receipt.outbox_id IS DISTINCT FROM v_terminal_outbox.id
       OR v_terminal_receipt.observed_at
         IS DISTINCT FROM v_terminal_outbox.occurred_at
       OR v_terminal_audit.previous_event_hash IS NOT NULL
       OR v_terminal_outbox.id IS NULL
       OR v_terminal_audit.event_hash IS DISTINCT FROM v_expected_audit_hash
    THEN
      RAISE EXCEPTION 'hypothesis_execution_replay_proof_invalid'
        USING ERRCODE = '23514';
    END IF;
    RETURN v_terminal_receipt.receipt_payload || jsonb_build_object(
      'receiptDigest',v_terminal_receipt.receipt_digest,
      'auditEventId',v_terminal_receipt.audit_event_id,
      'outboxId',v_terminal_receipt.outbox_id,
      'idempotencyReplay',true
    );
  END IF;

  SELECT receipt.* INTO v_initial_receipt
  FROM ops.execution_receipts AS receipt
  WHERE receipt.execution_id = p_execution_id
    AND receipt.generation = 1
    AND receipt.receipt_sequence = 1
    AND receipt.receipt_digest = v_effect.last_receipt_digest
    AND receipt.receipt_kind = 'AUTHORIZATION_QUEUED'
    AND receipt.aggregate_state = 'QUEUED'
    AND receipt.aggregate_state_version = 1
    AND receipt.attempt_state = 'QUEUED'
    AND receipt.outbox_id = v_auth.outbox_id
    AND receipt.request_id = v_auth.request_id
    AND receipt.audit_event_id = v_auth.audit_event_id
    AND receipt.proof_kind = 'NO_EGRESS'
    AND receipt.proof_digest = v_auth.target_request_sha256
  FOR SHARE;
  SELECT current_case.* INTO v_case
  FROM editorial.cases AS current_case
  WHERE current_case.id = v_proposal.target_id::uuid
    AND current_case.version = v_proposal.target_version
  FOR UPDATE;
  IF v_effect.state IS DISTINCT FROM 'QUEUED'
     OR v_effect.state_version <> 1
     OR v_attempt.attempt_state IS DISTINCT FROM 'QUEUED'
     OR v_attempt.state_version <> 1
     OR v_effect.last_receipt_sequence <> 1
     OR v_initial_receipt.id IS NULL OR v_case.id IS NULL
     OR v_auth.expires_at <= v_now THEN
    RAISE EXCEPTION 'hypothesis_execution_not_claimable'
      USING ERRCODE = '40001';
  END IF;

  -- The preceding reads hold every mutable authority row needed by the
  -- DATABASE_ONLY commit. Refresh time only after any lock wait, immediately
  -- before the first audit/receipt write, and recheck the locked fences.
  v_now := clock_timestamp();
  IF v_job.id IS DISTINCT FROM p_job_id
     OR v_job.job_type IS DISTINCT FROM 'EVENT_DELIVERY'
     OR v_job.queue IS DISTINCT FROM 'workflow-worker'
     OR v_job.status IS DISTINCT FROM 'RUNNING'
     OR v_job.lease_owner IS NULL
     OR length(btrim(v_job.lease_owner)) NOT BETWEEN 1 AND 160
     OR v_job.lease_token IS DISTINCT FROM p_lease_token
     OR v_job.fencing_token IS DISTINCT FROM p_job_fencing_token
     OR v_job.lease_expires_at <= v_now
     OR v_job.payload->>'eventId' IS DISTINCT FROM v_event_id::text
     OR v_job.payload->'payload' IS DISTINCT FROM p_event
     OR v_inbox.consumer IS DISTINCT FROM 'action-execution-worker'
     OR v_inbox.event_id IS DISTINCT FROM v_event_id
     OR v_inbox.processed_at IS NOT NULL
     OR v_inbox.result IS DISTINCT FROM
       'DISPATCHED:' || p_job_id::text
     OR v_authorized_outbox.id IS DISTINCT FROM v_event_id
     OR v_authorized_outbox.payload IS DISTINCT FROM p_event
     OR v_auth.execution_id IS DISTINCT FROM p_execution_id
     OR v_auth.generation IS DISTINCT FROM 1
     OR v_auth.outbox_id IS DISTINCT FROM v_authorized_outbox.id
     OR v_auth.expires_at <= v_now
     OR btrim(v_auth.execution_digest::text)
       IS DISTINCT FROM p_event->>'executionDigest'
     OR btrim(v_auth.terminal_decision_receipt_digest::text)
       IS DISTINCT FROM p_event->>'decisionDigest'
     OR btrim(v_auth.target_request_sha256::text)
       IS DISTINCT FROM p_event->>'targetRequestSha256'
     OR v_case.version IS DISTINCT FROM v_proposal.target_version
  THEN
    RAISE EXCEPTION 'hypothesis_execution_locked_fence_expired_or_stale'
      USING ERRCODE = '40001';
  END IF;

  v_receipt_id := gen_random_uuid();
  v_receipt_payload := jsonb_build_object(
    'schemaVersion','action-execution-receipt.v1',
    'receiptKind','LEASE_CLAIMED',
    'executionId',p_execution_id,'generation',1,
    'aggregateState','QUEUED','aggregateStateVersion',1,
    'attemptState','CLAIMED','attemptStateVersion',2,
    'cancellationGeneration',v_effect.cancellation_generation,
    'effectCertainty','DEFINITIVE_NOT_ACCEPTED',
    'executionDigest',btrim(v_auth.execution_digest::text),
    'targetRequestSha256',btrim(v_auth.target_request_sha256::text),
    'attemptId',v_attempt.id,'producerJobId',p_job_id,
    'jobFencingToken',p_job_fencing_token,
    'leaseExpiresAt',v_job.lease_expires_at,
    'requestId',v_auth.request_id,'occurredAt',v_now
  );
  v_receipt_canonical := ops.canonical_jsonb_v1(v_receipt_payload);
  v_receipt_digest := encode(extensions.digest(
    v_receipt_canonical,'sha256'
  ),'hex');
  v_audit_id := ops.append_audit_event(
    'workflow:action-execution:' || p_execution_id::text,
    'SERVICE','workflow-worker',NULL::uuid,
    'ACTION_EXECUTION_CLAIMED','ActionExecution',p_execution_id::text,
    'cases.investigate','SUCCESS',NULL,v_auth.request_id,
    jsonb_build_object(
      'executionId',p_execution_id,'generation',1,
      'attemptId',v_attempt.id,'receiptSequence',2,
      'receiptDigest',v_receipt_digest,'producerJobId',p_job_id,
      'jobFencingToken',p_job_fencing_token,
      'leaseExpiresAt',v_job.lease_expires_at,
      'priorReceiptDigest',v_effect.last_receipt_digest
    )
  );
  INSERT INTO ops.execution_receipts(
    id,execution_id,generation,attempt_id,receipt_sequence,receipt_kind,
    mutates_aggregate_state,prior_aggregate_state,aggregate_state,
    aggregate_state_version,prior_attempt_state,attempt_state,fencing_token,
    cancellation_generation,proof_kind,proof_digest,receipt_payload,
    receipt_payload_canonical,budget_reservation_id,budget_reservation_digest,
    request_id,audit_event_id,outbox_id,observed_at,prior_receipt_digest,
    receipt_digest
  ) VALUES (
    v_receipt_id,p_execution_id,1,v_attempt.id,2,'LEASE_CLAIMED',
    false,'QUEUED','QUEUED',1,'QUEUED','CLAIMED',p_job_fencing_token,
    v_effect.cancellation_generation,'DEFINITIVE_NOT_ACCEPTED',
    v_detail.action_detail_digest,v_receipt_payload,v_receipt_canonical,
    v_auth.budget_reservation_id,v_auth.budget_reservation_digest,
    v_auth.request_id,v_audit_id,NULL,v_now,
    v_effect.last_receipt_digest,v_receipt_digest
  );
  UPDATE ops.execution_attempts SET
    attempt_state = 'CLAIMED',state_version = 2,
    lease_owner = v_job.lease_owner,lease_token = p_lease_token,
    lease_expires_at = v_job.lease_expires_at,
    fencing_token = p_job_fencing_token,claimed_at = v_now,
    last_receipt_sequence = 2,last_receipt_digest = v_receipt_digest,
    updated_at = v_now
  WHERE id = v_attempt.id
    AND attempt_state = 'QUEUED' AND state_version = 1
    AND last_receipt_sequence = 1
    AND last_receipt_digest = v_effect.last_receipt_digest;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_execution_claim_stale'
      USING ERRCODE = '40001';
  END IF;
  UPDATE ops.in_flight_effects SET
    last_receipt_sequence = 2,last_receipt_digest = v_receipt_digest,
    updated_at = v_now
  WHERE id = p_execution_id
    AND state = 'QUEUED' AND state_version = 1
    AND last_receipt_sequence = 1
    AND last_receipt_digest = v_effect.last_receipt_digest;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_execution_effect_claim_stale'
      USING ERRCODE = '40001';
  END IF;
  v_prior_receipt_digest := v_receipt_digest;

  v_receipt_id := gen_random_uuid();
  v_receipt_payload := jsonb_build_object(
    'schemaVersion','action-execution-receipt.v1',
    'receiptKind','DISPATCH_STARTED',
    'executionId',p_execution_id,'generation',1,
    'aggregateState','RUNNING','aggregateStateVersion',2,
    'attemptState','DISPATCHING','attemptStateVersion',3,
    'cancellationGeneration',v_effect.cancellation_generation,
    'effectCertainty','DEFINITIVE_NOT_ACCEPTED',
    'executionDigest',btrim(v_auth.execution_digest::text),
    'targetRequestSha256',btrim(v_auth.target_request_sha256::text),
    'attemptId',v_attempt.id,'producerJobId',p_job_id,
    'jobFencingToken',p_job_fencing_token,
    'leaseExpiresAt',v_job.lease_expires_at,
    'requestId',v_auth.request_id,'occurredAt',v_now
  );
  v_receipt_canonical := ops.canonical_jsonb_v1(v_receipt_payload);
  v_receipt_digest := encode(extensions.digest(
    v_receipt_canonical,'sha256'
  ),'hex');
  v_audit_id := ops.append_audit_event(
    'workflow:action-execution:' || p_execution_id::text,
    'SERVICE','workflow-worker',NULL::uuid,
    'ACTION_EXECUTION_DISPATCH_STARTED','ActionExecution',
    p_execution_id::text,'cases.investigate','SUCCESS',NULL,
    v_auth.request_id,jsonb_build_object(
      'executionId',p_execution_id,'generation',1,
      'attemptId',v_attempt.id,'receiptSequence',3,
      'receiptDigest',v_receipt_digest,'producerJobId',p_job_id,
      'jobFencingToken',p_job_fencing_token,
      'leaseExpiresAt',v_job.lease_expires_at,
      'priorReceiptDigest',v_prior_receipt_digest
    )
  );
  INSERT INTO ops.execution_receipts(
    id,execution_id,generation,attempt_id,receipt_sequence,receipt_kind,
    mutates_aggregate_state,prior_aggregate_state,aggregate_state,
    aggregate_state_version,prior_attempt_state,attempt_state,fencing_token,
    cancellation_generation,proof_kind,proof_digest,receipt_payload,
    receipt_payload_canonical,budget_reservation_id,budget_reservation_digest,
    request_id,audit_event_id,outbox_id,observed_at,prior_receipt_digest,
    receipt_digest
  ) VALUES (
    v_receipt_id,p_execution_id,1,v_attempt.id,3,'DISPATCH_STARTED',
    true,'QUEUED','RUNNING',2,'CLAIMED','DISPATCHING',
    p_job_fencing_token,v_effect.cancellation_generation,
    'DEFINITIVE_NOT_ACCEPTED',v_detail.action_detail_digest,
    v_receipt_payload,v_receipt_canonical,v_auth.budget_reservation_id,
    v_auth.budget_reservation_digest,v_auth.request_id,v_audit_id,NULL,v_now,
    v_prior_receipt_digest,v_receipt_digest
  );
  UPDATE ops.execution_attempts SET
    attempt_state = 'DISPATCHING',state_version = 3,dispatch_ordinal = 1,
    dispatch_started_at = v_now,last_receipt_sequence = 3,
    last_receipt_digest = v_receipt_digest,updated_at = v_now
  WHERE id = v_attempt.id
    AND attempt_state = 'CLAIMED' AND state_version = 2
    AND lease_token = p_lease_token
    AND fencing_token = p_job_fencing_token
    AND last_receipt_sequence = 2
    AND last_receipt_digest = v_prior_receipt_digest;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_execution_dispatch_stale'
      USING ERRCODE = '40001';
  END IF;
  UPDATE ops.in_flight_effects SET
    state = 'RUNNING',state_version = 2,dispatch_attempt_count = 1,
    last_receipt_sequence = 3,last_receipt_digest = v_receipt_digest,
    updated_at = v_now
  WHERE id = p_execution_id
    AND state = 'QUEUED' AND state_version = 1
    AND last_receipt_sequence = 2
    AND last_receipt_digest = v_prior_receipt_digest;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_execution_effect_dispatch_stale'
      USING ERRCODE = '40001';
  END IF;
  v_prior_receipt_digest := v_receipt_digest;

  INSERT INTO editorial.hypotheses(
    id,case_id,statement,status,unknowns,created_by,created_at,updated_at
  ) VALUES (
    v_hypothesis_id,v_case.id,v_authority#>>'{payload,statement}',
    'OPEN',v_authority#>'{payload,unknowns}',v_decision.actor_id,
    v_now,v_now
  ) RETURNING * INTO v_hypothesis;
  UPDATE editorial.cases SET version = version + 1,updated_at = v_now
  WHERE id = v_case.id AND version = v_proposal.target_version
  RETURNING version INTO v_case_version;
  IF v_case_version IS DISTINCT FROM v_proposal.target_version + 1 THEN
    RAISE EXCEPTION 'hypothesis_execution_case_version_stale'
      USING ERRCODE = '40001';
  END IF;

  v_proof := jsonb_build_object(
    'schemaVersion','approved-hypothesis-execution-proof.v1',
    'executionId',p_execution_id,'generation',1,
    'proposalId',v_proposal.id,'proposalVersion',v_version.version,
    'approvalDigest',btrim(v_auth.approval_digest::text),
    'terminalDecisionId',v_decision.id,
    'terminalDecisionReceiptDigest',
      btrim(v_auth.terminal_decision_receipt_digest::text),
    'terminalApprovalUserId',v_decision.actor_id,
    'hypothesisId',v_hypothesis.id,'caseId',v_hypothesis.case_id,
    'priorCaseVersion',v_proposal.target_version,
    'resultingCaseVersion',v_case_version,
    'hypothesisPayloadSha256',v_authority->>'payloadSha256',
    'statementDigest',v_authority->>'statementDigest',
    'evidenceSegmentSetDigest',v_authority->>'evidenceSegmentSetDigest',
    'supportingEvidenceSetDigest',v_authority->>'supportingEvidenceSetDigest',
    'contraryEvidenceSetDigest',v_authority->>'contraryEvidenceSetDigest',
    'unknownSetDigest',v_authority->>'unknownSetDigest',
    'materializationReceiptSha256',
      v_authority->>'materializationReceiptSha256',
    'creatorUserId',v_decision.actor_id,
    'proposalCreatedBy',v_proposal.created_by,
    'suggestionAcceptedBy',v_suggestion.decided_by,
    'actorType','SERVICE','actorId','workflow-worker',
    'producerJobId',p_job_id,'jobFencingToken',p_job_fencing_token,
    'committedAt',v_now
  );
  v_proof_canonical := ops.canonical_jsonb_v1(v_proof);
  v_proof_sha256 := encode(extensions.digest(
    v_proof_canonical,'sha256'
  ),'hex');
  v_receipt_id := gen_random_uuid();
  v_receipt_payload := jsonb_build_object(
    'schemaVersion','action-execution-receipt.v1',
    'receiptKind','EFFECT_SUCCEEDED',
    'executionId',p_execution_id,'generation',1,
    'aggregateState','SUCCEEDED','aggregateStateVersion',3,
    'attemptState','SUCCEEDED','attemptStateVersion',4,
    'cancellationGeneration',v_effect.cancellation_generation,
    'effectCertainty','NO_EGRESS',
    'executionDigest',btrim(v_auth.execution_digest::text),
    'targetRequestSha256',btrim(v_auth.target_request_sha256::text),
    'hypothesisId',v_hypothesis.id,'caseId',v_hypothesis.case_id,
    'priorCaseVersion',v_proposal.target_version,
    'resultingCaseVersion',v_case_version,
    'creatorUserId',v_decision.actor_id,
    'proposalCreatedBy',v_proposal.created_by,
    'suggestionAcceptedBy',v_suggestion.decided_by,
    'terminalApprovalUserId',v_decision.actor_id,
    'terminalDecisionReceiptDigest',
      btrim(v_auth.terminal_decision_receipt_digest::text),
    'producerJobId',p_job_id,'jobFencingToken',p_job_fencing_token,
    'receiptSequence',4,'proofSha256',btrim(v_proof_sha256::text),
    'requestId',v_auth.request_id,'occurredAt',v_now
  );
  v_receipt_canonical := ops.canonical_jsonb_v1(v_receipt_payload);
  v_receipt_digest := encode(extensions.digest(
    v_receipt_canonical,'sha256'
  ),'hex');
  v_outbox_id := ops.enqueue_outbox(
    'action_execution',p_execution_id::text,3,
    'action.execution_completed.v1',jsonb_build_object(
      'executionId',p_execution_id,'generation',1,'stateVersion',3,
      'terminalOrReconciliationState','SUCCEEDED',
      'executionDigest',btrim(v_auth.execution_digest::text),
      'receiptSequence',4,'receiptDigest',v_receipt_digest,
      'costFactIds','[]'::jsonb
    ),v_now
  );
  v_audit_id := ops.append_audit_event(
    'workflow:hypothesis:' || v_hypothesis.id::text,
    'SERVICE','workflow-worker',NULL::uuid,
    'command.createHypothesis','Hypothesis',v_hypothesis.id::text,
    'cases.investigate','SUCCESS',NULL,v_auth.request_id,
    jsonb_build_object(
      'proof',v_proof,'proofSha256',v_proof_sha256,
      'receiptDigest',v_receipt_digest,'outboxId',v_outbox_id
    )
  );
  INSERT INTO ops.execution_receipts(
    id,execution_id,generation,attempt_id,receipt_sequence,receipt_kind,
    mutates_aggregate_state,prior_aggregate_state,aggregate_state,
    aggregate_state_version,prior_attempt_state,attempt_state,fencing_token,
    cancellation_generation,proof_kind,proof_digest,receipt_payload,
    receipt_payload_canonical,actual_amount,actual_currency,cost_event_ids,
    budget_reservation_id,budget_reservation_digest,request_id,
    audit_event_id,outbox_id,observed_at,prior_receipt_digest,receipt_digest
  ) VALUES (
    v_receipt_id,p_execution_id,1,v_attempt.id,4,'EFFECT_SUCCEEDED',
    true,'RUNNING','SUCCEEDED',3,'DISPATCHING','SUCCEEDED',
    p_job_fencing_token,v_effect.cancellation_generation,
    'NO_EGRESS',v_proof_sha256,v_receipt_payload,v_receipt_canonical,
    NULL,NULL,'{}'::uuid[],v_auth.budget_reservation_id,
    v_auth.budget_reservation_digest,v_auth.request_id,v_audit_id,
    v_outbox_id,v_now,v_prior_receipt_digest,v_receipt_digest
  );
  UPDATE ops.execution_attempts SET
    attempt_state = 'SUCCEEDED',state_version = 4,
    lease_owner = NULL,lease_token = NULL,lease_expires_at = NULL,
    terminal_proof_digest = v_proof_sha256,completed_at = v_now,
    last_receipt_sequence = 4,last_receipt_digest = v_receipt_digest,
    updated_at = v_now
  WHERE id = v_attempt.id
    AND attempt_state = 'DISPATCHING' AND state_version = 3
    AND lease_token = p_lease_token
    AND fencing_token = p_job_fencing_token
    AND last_receipt_sequence = 3
    AND last_receipt_digest = v_prior_receipt_digest;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_execution_attempt_stale'
      USING ERRCODE = '40001';
  END IF;
  UPDATE ops.in_flight_effects SET
    state = 'SUCCEEDED',state_version = 3,
    last_receipt_sequence = 4,last_receipt_digest = v_receipt_digest,
    terminal_at = v_now,updated_at = v_now
  WHERE id = p_execution_id
    AND state = 'RUNNING' AND state_version = 2
    AND last_receipt_sequence = 3
    AND last_receipt_digest = v_prior_receipt_digest;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_execution_effect_stale'
      USING ERRCODE = '40001';
  END IF;
  RETURN v_receipt_payload || jsonb_build_object(
    'receiptDigest',v_receipt_digest,'auditEventId',v_audit_id,
    'outboxId',v_outbox_id,'idempotencyReplay',false
  );
END
$$;
ALTER FUNCTION ops.execute_approved_hypothesis_v1(
  uuid,uuid,bigint,uuid,bigint,jsonb,jsonb
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.execute_approved_hypothesis_v1(
  uuid,uuid,bigint,uuid,bigint,jsonb,jsonb
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.execute_approved_hypothesis_v1(
  uuid,uuid,bigint,uuid,bigint,jsonb,jsonb
) TO gurine_workflow_worker;
-- R6c hypothesis recursion owner routines.
-- This snippet is intended to be appended after the 0037 recursion tables.

CREATE OR REPLACE FUNCTION ops.process_hypothesis_execution_completed_v1(
  p_payload jsonb,
  p_producer_job_id uuid
) RETURNS TABLE(
  disposition text,
  receipt_id uuid,
  plan_id uuid,
  node_id uuid,
  agent_run_id uuid,
  job_id uuid,
  receipt_digest char(64),
  replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, editorial, ops, extensions, pg_temp
AS $$
DECLARE
  v_job ops.jobs%ROWTYPE;
  v_outbox ops.outbox%ROWTYPE;
  v_existing ops.hypothesis_recursion_receipts%ROWTYPE;
  v_auth ops.execution_authorizations%ROWTYPE;
  v_effect ops.in_flight_effects%ROWTYPE;
  v_execution_receipt ops.execution_receipts%ROWTYPE;
  v_proposal ops.action_proposals%ROWTYPE;
  v_proposal_version ops.action_proposal_versions%ROWTYPE;
  v_hypothesis_detail ops.action_approval_hypothesis_details%ROWTYPE;
  v_hypothesis_authority jsonb;
  v_suggestion ops.agent_suggestions%ROWTYPE;
  v_accept_audit ops.audit_events%ROWTYPE;
  v_origin_run ops.agent_runs%ROWTYPE;
  v_origin_validation ops.agent_output_validations%ROWTYPE;
  v_snapshot core.dataset_snapshots%ROWTYPE;
  v_case editorial.cases%ROWTYPE;
  v_policy ops.hypothesis_recursion_policies%ROWTYPE;
  v_execution_id uuid;
  v_generation bigint;
  v_state_version bigint;
  v_receipt_sequence bigint;
  v_event_id uuid;
  v_terminal_state text;
  v_execution_digest char(64);
  v_execution_receipt_sha256 char(64);
  v_trigger_digest char(64);
  v_policy_payload jsonb;
  v_disposition text;
  v_plan_id uuid;
  v_node_id uuid;
  v_agent_run_id uuid;
  v_job_id uuid;
  v_receipt_id uuid := gen_random_uuid();
  v_snapshot_sha256 char(64);
  v_hypothesis_execution_digest char(64);
  v_hypothesis_payload jsonb;
  v_hypothesis_payload_sha256 char(64);
  v_objective text;
  v_stage text := 'MARKET_RESEARCHER';
  v_depth integer := 1;
  v_stage_budget bigint;
  v_dedupe_payload jsonb;
  v_dedupe_key char(64);
  v_plan_payload jsonb;
  v_plan_canonical bytea;
  v_plan_digest char(64);
  v_node_payload jsonb;
  v_node_canonical bytea;
  v_node_digest char(64);
  v_initial_transcript_sha256 char(64);
  v_transition_payload jsonb;
  v_transition_canonical bytea;
  v_transition_receipt char(64);
  v_prior_transition_receipt char(64);
  v_ledger_payload jsonb;
  v_ledger_canonical bytea;
  v_ledger_receipt char(64);
  v_receipt_payload jsonb;
  v_receipt_canonical bytea;
  v_receipt_digest char(64);
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
     OR p_producer_job_id IS NULL
     OR (SELECT count(*) FROM jsonb_object_keys(p_payload)) <> 8
     OR NOT p_payload ?& ARRAY[
       'executionId','generation','stateVersion',
       'terminalOrReconciliationState','executionDigest',
       'receiptSequence','receiptDigest','costFactIds'
     ]
     OR COALESCE(p_payload->>'executionId','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR COALESCE(p_payload->>'generation','') !~ '^[0-9]+$'
     OR COALESCE(p_payload->>'stateVersion','') !~ '^[0-9]+$'
     OR COALESCE(p_payload->>'receiptSequence','') !~ '^[0-9]+$'
     OR COALESCE(p_payload->>'executionDigest','') !~ '^[0-9a-f]{64}$'
     OR COALESCE(p_payload->>'receiptDigest','') !~ '^[0-9a-f]{64}$'
     OR COALESCE(p_payload->>'terminalOrReconciliationState','') NOT IN (
       'SUCCEEDED','RETRYABLE_FAILED','PERMANENT_FAILED','CANCELLED',
       'EXPIRED','RECONCILIATION_REQUIRED'
     )
     OR jsonb_typeof(p_payload->'costFactIds') IS DISTINCT FROM 'array'
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_payload->'costFactIds') AS item(value)
       WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
          OR item.value #>> '{}' !~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements_text(p_payload->'costFactIds') AS item(value)
       GROUP BY item.value HAVING count(*) <> 1
     ) THEN
    RAISE EXCEPTION 'hypothesis_recursion_execution_payload_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT pg_has_role(session_user, 'gurine_workflow_worker', 'MEMBER') THEN
    RAISE EXCEPTION 'hypothesis_recursion_worker_role_required'
      USING ERRCODE = '42501';
  END IF;

  v_execution_id := (p_payload->>'executionId')::uuid;
  v_generation := (p_payload->>'generation')::bigint;
  v_state_version := (p_payload->>'stateVersion')::bigint;
  v_receipt_sequence := (p_payload->>'receiptSequence')::bigint;
  v_terminal_state := p_payload->>'terminalOrReconciliationState';
  v_execution_digest := (p_payload->>'executionDigest')::char(64);
  v_execution_receipt_sha256 := (p_payload->>'receiptDigest')::char(64);
  IF v_generation <= 0 OR v_state_version <= 0 OR v_receipt_sequence <= 0 THEN
    RAISE EXCEPTION 'hypothesis_recursion_execution_payload_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_producer_job_id
    AND job.job_type = 'EVENT_DELIVERY'
    AND job.queue = 'workflow-worker'
    AND job.status = 'RUNNING'
  FOR SHARE;
  IF NOT FOUND OR jsonb_typeof(v_job.payload) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(v_job.payload)) <> 8
     OR v_job.payload->>'consumerId' IS DISTINCT FROM 'workflow-worker'
     OR v_job.payload->>'eventType'
       IS DISTINCT FROM 'action.execution_completed.v1'
     OR v_job.payload->>'aggregateType' IS DISTINCT FROM 'action_execution'
     OR v_job.payload->>'aggregateId' IS DISTINCT FROM v_execution_id::text
     OR COALESCE(v_job.payload->>'eventId','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR COALESCE(v_job.payload->>'aggregateVersion','') !~ '^[0-9]+$'
     OR v_job.payload->'payload' IS DISTINCT FROM p_payload THEN
    RAISE EXCEPTION 'hypothesis_recursion_producer_job_invalid'
      USING ERRCODE = '23514';
  END IF;
  v_event_id := (v_job.payload->>'eventId')::uuid;
  SELECT event.* INTO v_outbox
  FROM ops.outbox AS event
  WHERE event.id = v_event_id
    AND event.aggregate_type = 'action_execution'
    AND event.aggregate_id = v_execution_id::text
    AND event.aggregate_version = v_state_version
    AND event.event_type = 'action.execution_completed.v1'
    AND event.payload = p_payload
    AND EXISTS (
      SELECT 1 FROM ops.event_types AS event_type
      WHERE event_type.event_type = event.event_type
        AND event_type.active
        AND event_type.payload_schema_uri IS NOT NULL
    )
  FOR SHARE;
  IF NOT FOUND
     OR (v_job.payload->>'aggregateVersion')::bigint
       IS DISTINCT FROM v_outbox.aggregate_version
     OR NULLIF(v_job.payload->>'occurredAt','')::timestamptz
       IS DISTINCT FROM v_outbox.occurred_at THEN
    RAISE EXCEPTION 'hypothesis_recursion_outbox_binding_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_trigger_digest := encode(
    extensions.digest(ops.canonical_jsonb_v1(p_payload), 'sha256'), 'hex'
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'HYPOTHESIS_RECURSION:ACTION_EXECUTION:'
        || v_execution_id::text || ':' || v_generation::text,
      0
    )
  );
  SELECT receipt.* INTO v_existing
  FROM ops.hypothesis_recursion_receipts AS receipt
  WHERE receipt.trigger_kind = 'ACTION_EXECUTION'
    AND receipt.trigger_id = v_execution_id
    AND receipt.trigger_generation = v_generation
  ORDER BY receipt.created_at, receipt.receipt_id
  LIMIT 1
  FOR SHARE;
  IF FOUND THEN
    IF v_existing.trigger_digest IS DISTINCT FROM v_trigger_digest
       OR v_existing.trigger_receipt_sha256
         IS DISTINCT FROM v_execution_receipt_sha256
       OR v_existing.producer_job_id IS DISTINCT FROM p_producer_job_id
       OR v_existing.receipt_payload->>'triggerPayloadSha256'
         IS DISTINCT FROM btrim(v_trigger_digest::text) THEN
      RAISE EXCEPTION 'hypothesis_recursion_trigger_replay_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN QUERY SELECT
      v_existing.disposition, v_existing.receipt_id,
      v_existing.plan_id, v_existing.node_id,
      v_existing.agent_run_id, v_existing.job_id,
      v_existing.receipt_digest, true;
    RETURN;
  END IF;

  SELECT auth.* INTO v_auth
  FROM ops.execution_authorizations AS auth
  WHERE auth.execution_id = v_execution_id
    AND auth.generation = v_generation
    AND auth.execution_digest = v_execution_digest
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_recursion_execution_authority_invalid'
      USING ERRCODE = '23514';
  END IF;
  SELECT effect.* INTO v_effect
  FROM ops.in_flight_effects AS effect
  WHERE effect.id = v_execution_id
    AND effect.effect_type = 'ACTION_EXECUTION'
    AND effect.current_generation = v_generation
    AND effect.state_version = v_state_version
    AND effect.state = v_terminal_state
    AND effect.action_kind = v_auth.action_kind
    AND effect.action_proposal_id = v_auth.proposal_id
    AND effect.action_proposal_version = v_auth.proposal_version
    AND effect.approval_digest = v_auth.approval_digest
    AND effect.last_receipt_sequence = v_receipt_sequence
    AND effect.last_receipt_digest = v_execution_receipt_sha256
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_recursion_execution_effect_invalid'
      USING ERRCODE = '23514';
  END IF;
  SELECT receipt.* INTO v_execution_receipt
  FROM ops.execution_receipts AS receipt
  WHERE receipt.execution_id = v_execution_id
    AND receipt.generation = v_generation
    AND receipt.receipt_sequence = v_receipt_sequence
    AND receipt.receipt_digest = v_execution_receipt_sha256
    AND receipt.aggregate_state = v_terminal_state
    AND receipt.aggregate_state_version = v_state_version
    AND receipt.mutates_aggregate_state
    AND receipt.outbox_id = v_outbox.id
    AND receipt.cost_event_ids IS NOT DISTINCT FROM ARRAY(
      SELECT item.value::uuid
      FROM jsonb_array_elements_text(p_payload->'costFactIds')
        AS item(value)
      ORDER BY item.value::uuid
    )
    AND receipt.observed_at = v_outbox.occurred_at
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_recursion_execution_receipt_invalid'
      USING ERRCODE = '23514';
  END IF;

  <<evaluate_trigger>>
  BEGIN
    IF v_auth.action_kind <> 'HYPOTHESIS' THEN
      v_disposition := 'NOT_HYPOTHESIS';
      EXIT evaluate_trigger;
    END IF;
    IF v_terminal_state <> 'SUCCEEDED'
       OR v_execution_receipt.receipt_kind <> 'EFFECT_SUCCEEDED' THEN
      v_disposition := 'NOT_SUCCEEDED';
      EXIT evaluate_trigger;
    END IF;

    SELECT proposal.* INTO v_proposal
    FROM ops.action_proposals AS proposal
    WHERE proposal.id = v_auth.proposal_id
      AND proposal.action_kind = 'HYPOTHESIS'
      AND proposal.origin_kind = 'AGENT_PROPOSAL'
      AND proposal.target_type = 'CASE'
    FOR SHARE;
    SELECT version.* INTO v_proposal_version
    FROM ops.action_proposal_versions AS version
    WHERE version.proposal_id = v_auth.proposal_id
      AND version.version = v_auth.proposal_version
      AND version.state = 'APPROVED'
      AND version.approval_digest = v_auth.approval_digest
      AND version.action_detail_kind = 'HYPOTHESIS'
    FOR SHARE;
    SELECT detail.* INTO v_hypothesis_detail
    FROM ops.action_approval_hypothesis_details AS detail
    WHERE detail.proposal_id = v_auth.proposal_id
      AND detail.proposal_version = v_auth.proposal_version
      AND detail.detail_kind = 'HYPOTHESIS'
      AND detail.action_detail_digest = v_proposal_version.action_detail_digest
      AND detail.expected_case_version = v_proposal.target_version
    FOR SHARE;
    IF v_proposal.id IS NULL OR v_proposal_version.proposal_id IS NULL
       OR v_hypothesis_detail.proposal_id IS NULL THEN
      RAISE EXCEPTION 'hypothesis_recursion_approved_proposal_invalid'
        USING ERRCODE = '23514';
    END IF;

    SELECT suggestion.* INTO v_suggestion
    FROM ops.agent_suggestions AS suggestion
    WHERE suggestion.id = v_proposal.origin_id
      AND suggestion.proposal_contract_version = 2
      AND suggestion.suggestion_type = 'HYPOTHESIS'
      AND suggestion.status = 'ACCEPTED'
      AND suggestion.decision_kind = 'ACCEPT'
      AND suggestion.decided_by IS NOT NULL
      AND suggestion.decision_reason IS NOT NULL
      AND suggestion.decision_sha256 IS NOT NULL
      AND suggestion.decision_audit_event_id IS NOT NULL
      AND suggestion.decided_at IS NOT NULL
      AND suggestion.payload_sha256 = v_proposal.origin_digest
      AND suggestion.version = v_proposal.origin_version + 1
      AND suggestion.materialized_target_type = 'ACTION_PROPOSAL_DRAFT'
      AND suggestion.materialized_action_proposal_id = v_proposal.id
      AND suggestion.materialization_receipt_sha256 IS NOT NULL
      AND suggestion.case_id::text = v_proposal.target_id
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_accepted_suggestion_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_hypothesis_authority :=
      ops.accepted_hypothesis_action_authority_v2(
        v_proposal.id, v_proposal_version.version
      );
    IF jsonb_typeof(v_hypothesis_authority) IS DISTINCT FROM 'object'
       OR (SELECT count(*)
           FROM jsonb_object_keys(v_hypothesis_authority)) <> 13
       OR NOT v_hypothesis_authority ?& ARRAY[
         'proposalId','proposalVersion','suggestionId','caseId',
         'expectedCaseVersion','payload','payloadSha256',
         'statementDigest','evidenceSegmentSetDigest',
         'supportingEvidenceSetDigest','contraryEvidenceSetDigest',
         'unknownSetDigest','materializationReceiptSha256'
       ]
       OR v_hypothesis_authority->>'proposalId'
         IS DISTINCT FROM v_proposal.id::text
       OR v_hypothesis_authority->>'proposalVersion'
         IS DISTINCT FROM v_proposal_version.version::text
       OR v_hypothesis_authority->>'suggestionId'
         IS DISTINCT FROM v_suggestion.id::text
       OR v_hypothesis_authority->>'caseId'
         IS DISTINCT FROM v_proposal.target_id
       OR v_hypothesis_authority->>'expectedCaseVersion'
         IS DISTINCT FROM v_proposal.target_version::text
       OR v_hypothesis_authority->'payload'
         IS DISTINCT FROM v_suggestion.payload
       OR v_hypothesis_authority->>'payloadSha256'
         IS DISTINCT FROM btrim(v_suggestion.payload_sha256::text)
       OR v_hypothesis_authority->>'statementDigest'
         IS DISTINCT FROM btrim(v_hypothesis_detail.statement_digest::text)
       OR v_hypothesis_authority->>'evidenceSegmentSetDigest'
         IS DISTINCT FROM btrim(
           v_hypothesis_detail.evidence_segment_set_digest::text
         )
       OR v_hypothesis_authority->>'unknownSetDigest'
         IS DISTINCT FROM btrim(v_hypothesis_detail.unknown_set_digest::text)
       OR v_hypothesis_authority->>'supportingEvidenceSetDigest'
         IS DISTINCT FROM btrim(v_proposal_version.evidence_set_digest::text)
       OR v_hypothesis_authority->>'contraryEvidenceSetDigest'
         IS DISTINCT FROM btrim(
           v_proposal_version.contrary_evidence_set_digest::text
         )
       OR v_hypothesis_detail.case_id::text
         IS DISTINCT FROM v_proposal.target_id
       OR v_hypothesis_detail.expected_case_version
         IS DISTINCT FROM v_proposal.target_version THEN
      RAISE EXCEPTION 'hypothesis_recursion_hypothesis_authority_invalid'
        USING ERRCODE = '23514';
    END IF;
    IF jsonb_typeof(v_suggestion.payload) IS DISTINCT FROM 'object'
       OR (SELECT count(*) FROM jsonb_object_keys(v_suggestion.payload)) <> 6
       OR NOT v_suggestion.payload ?& ARRAY[
         'kind','statement','supportingCitationIds',
         'contradictingCitationIds','unknowns','limitations'
       ]
       OR jsonb_typeof(v_suggestion.payload->'kind')
         IS DISTINCT FROM 'string'
       OR v_suggestion.payload->>'kind' IS DISTINCT FROM 'HYPOTHESIS'
       OR jsonb_typeof(v_suggestion.payload->'statement')
         IS DISTINCT FROM 'string'
       OR char_length(btrim(v_suggestion.payload->>'statement'))
         NOT BETWEEN 1 AND 4000
       OR jsonb_typeof(v_suggestion.payload->'supportingCitationIds')
         IS DISTINCT FROM 'array'
       OR jsonb_array_length(
         v_suggestion.payload->'supportingCitationIds'
       ) > 100
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements(
           v_suggestion.payload->'supportingCitationIds'
         ) AS item(value)
         WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
            OR item.value #>> '{}' !~*
              '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       )
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements_text(
           v_suggestion.payload->'supportingCitationIds'
         ) AS item(value)
         GROUP BY item.value HAVING count(*) <> 1
       )
       OR jsonb_typeof(v_suggestion.payload->'contradictingCitationIds')
         IS DISTINCT FROM 'array'
       OR jsonb_array_length(
         v_suggestion.payload->'contradictingCitationIds'
       ) > 100
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements(
           v_suggestion.payload->'contradictingCitationIds'
         ) AS item(value)
         WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
            OR item.value #>> '{}' !~*
              '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       )
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements_text(
           v_suggestion.payload->'contradictingCitationIds'
         ) AS item(value)
         GROUP BY item.value HAVING count(*) <> 1
       )
       OR (
         jsonb_array_length(v_suggestion.payload->'supportingCitationIds') = 0
         AND jsonb_array_length(
           v_suggestion.payload->'contradictingCitationIds'
         ) = 0
       )
       OR jsonb_typeof(v_suggestion.payload->'unknowns')
         IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_suggestion.payload->'unknowns') > 50
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements(v_suggestion.payload->'unknowns')
           AS item(value)
         WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
            OR char_length(btrim(item.value #>> '{}')) NOT BETWEEN 1 AND 1000
       )
       OR jsonb_typeof(v_suggestion.payload->'limitations')
         IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_suggestion.payload->'limitations') > 50
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements(v_suggestion.payload->'limitations')
           AS item(value)
         WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
            OR char_length(btrim(item.value #>> '{}')) NOT BETWEEN 1 AND 1000
       )
       OR v_suggestion.payload_canonical IS DISTINCT FROM
         ops.canonical_jsonb_v1(v_suggestion.payload)
       OR v_suggestion.payload_sha256 IS DISTINCT FROM encode(
         extensions.digest(v_suggestion.payload_canonical, 'sha256'), 'hex'
       ) THEN
      RAISE EXCEPTION 'hypothesis_recursion_hypothesis_payload_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_hypothesis_payload := v_suggestion.payload;
    v_hypothesis_payload_sha256 := v_suggestion.payload_sha256;
    IF v_suggestion.decision_sha256 IS DISTINCT FROM encode(
         extensions.digest(convert_to(
           'ACCEPT:' || v_suggestion.id::text || ':'
             || v_proposal.origin_version::text || ':'
             || v_suggestion.decision_reason,
           'UTF8'
         ), 'sha256'), 'hex'
       ) THEN
      RAISE EXCEPTION 'hypothesis_recursion_acceptance_decision_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT audit.* INTO v_accept_audit
    FROM ops.audit_events AS audit
    WHERE audit.id = v_suggestion.decision_audit_event_id
      AND audit.actor_type = 'USER'
      AND audit.actor_id = v_suggestion.decided_by::text
      AND audit.action = 'AGENT_SUGGESTION_ACCEPTED'
      AND audit.object_type = 'AgentSuggestion'
      AND audit.object_id = v_suggestion.id::text
      AND audit.capability = 'agents.review'
      AND audit.outcome = 'SUCCESS'
      AND audit.reason = v_suggestion.decision_reason
      AND jsonb_typeof(audit.details) = 'object'
      AND (SELECT count(*) FROM jsonb_object_keys(audit.details)) = 5
      AND audit.details ?& ARRAY[
        'suggestionId','version','payloadSha256','decision','reason'
      ]
      AND audit.details->>'suggestionId' = v_suggestion.id::text
      AND audit.details->>'version' = v_proposal.origin_version::text
      AND audit.details->>'decision' = 'ACCEPT'
      AND audit.details->>'payloadSha256'
        = btrim(v_suggestion.payload_sha256::text)
      AND audit.details->>'reason' = v_suggestion.decision_reason
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_acceptance_audit_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT run.* INTO v_origin_run
    FROM ops.agent_runs AS run
    WHERE run.id = v_suggestion.agent_run_id
      AND run.run_contract_version = 2
      AND run.agent_type = 'investigator'
      AND run.case_id = v_suggestion.case_id
      AND run.status = 'SUCCEEDED'
      AND run.control_state = 'SETTLED'
      AND run.input_snapshot_hash = v_suggestion.input_snapshot_sha256
      AND run.dataset_snapshot_id IS NOT NULL
      AND run.output_payload IS NOT NULL
      AND run.output_validation_id = v_suggestion.citation_validation_id
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_origin_run_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT validation.* INTO v_origin_validation
    FROM ops.agent_output_validations AS validation
    WHERE validation.validation_id = v_suggestion.citation_validation_id
      AND validation.agent_run_id = v_origin_run.id
      AND validation.input_snapshot_sha256 = v_origin_run.input_snapshot_hash
      AND validation.provider_output_sha256 = encode(
        extensions.digest(
          ops.canonical_jsonb_v1(v_origin_run.output_payload), 'sha256'
        ), 'hex'
      )
      AND validation.output_schema_id = v_origin_run.output_schema_id
      AND validation.output_schema_version =
        v_origin_run.output_schema_contract_version
      AND validation.output_schema_sha256 = v_origin_run.output_schema_sha256
      AND validation.validation_status = 'VALID'
      AND validation.schema_status = 'PASS'
      AND validation.citation_status = 'PASS'
      AND validation.policy_status = 'PASS'
      AND validation.run_terminal_status = 'SUCCEEDED'
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_origin_validation_invalid'
        USING ERRCODE = '23514';
    END IF;
    LOCK TABLE ops.agent_proposal_citations IN SHARE MODE;
    IF EXISTS (
      SELECT 1
      FROM (
        SELECT item.value::uuid AS citation_id
        FROM jsonb_array_elements_text(
          v_hypothesis_payload->'supportingCitationIds'
        ) AS item(value)
        UNION
        SELECT item.value::uuid AS citation_id
        FROM jsonb_array_elements_text(
          v_hypothesis_payload->'contradictingCitationIds'
        ) AS item(value)
      ) AS required
      WHERE NOT EXISTS (
        SELECT 1
        FROM ops.agent_proposal_citations AS citation
        WHERE citation.citation_id = required.citation_id
          AND citation.citation_contract_version = 2
          AND citation.proposal_id = v_suggestion.id
          AND citation.agent_run_id = v_origin_run.id
          AND citation.provider_turn_id = v_origin_validation.provider_turn_id
          AND citation.validation_id = v_origin_validation.validation_id
          AND citation.dataset_snapshot_id = v_origin_run.dataset_snapshot_id
          AND citation.input_snapshot_sha256 =
            v_origin_run.input_snapshot_hash
          AND citation.proposal_payload_sha256 =
            v_hypothesis_payload_sha256
      )
    ) OR EXISTS (
      SELECT 1
      FROM ops.agent_proposal_citations AS citation
      WHERE citation.proposal_id = v_suggestion.id
        AND (
          citation.citation_contract_version <> 2
          OR citation.agent_run_id <> v_origin_run.id
          OR citation.provider_turn_id <> v_origin_validation.provider_turn_id
          OR citation.validation_id <> v_origin_validation.validation_id
          OR citation.dataset_snapshot_id <> v_origin_run.dataset_snapshot_id
          OR citation.input_snapshot_sha256 <>
            v_origin_run.input_snapshot_hash
          OR citation.proposal_payload_sha256 <>
            v_hypothesis_payload_sha256
          OR NOT EXISTS (
            SELECT 1
            FROM (
              SELECT item.value::uuid AS citation_id
              FROM jsonb_array_elements_text(
                v_hypothesis_payload->'supportingCitationIds'
              ) AS item(value)
              UNION
              SELECT item.value::uuid AS citation_id
              FROM jsonb_array_elements_text(
                v_hypothesis_payload->'contradictingCitationIds'
              ) AS item(value)
            ) AS required
            WHERE required.citation_id = citation.citation_id
          )
        )
    ) THEN
      RAISE EXCEPTION 'hypothesis_recursion_citation_binding_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT snapshot.* INTO v_snapshot
    FROM core.dataset_snapshots AS snapshot
    WHERE snapshot.id = v_origin_run.dataset_snapshot_id
      AND snapshot.snapshot_sha256 = v_origin_run.input_snapshot_hash
      AND snapshot.snapshot_kind = 'AGENT_CASE'
      AND snapshot.state = 'READY'
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_snapshot_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT current_case.* INTO v_case
    FROM editorial.cases AS current_case
    WHERE current_case.id = v_suggestion.case_id
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_case_invalid'
        USING ERRCODE = '23514';
    END IF;

    SELECT policy.* INTO v_policy
    FROM ops.hypothesis_recursion_policies AS policy
    WHERE policy.policy_key = 'HYPOTHESIS_RECURSION'
    ORDER BY policy.version DESC, policy.policy_id DESC
    LIMIT 1
    FOR SHARE;
    IF NOT FOUND THEN
      v_disposition := 'POLICY_ABSENT';
      EXIT evaluate_trigger;
    END IF;
    IF NOT v_policy.enabled THEN
      v_disposition := 'POLICY_DISABLED';
      EXIT evaluate_trigger;
    END IF;
    v_policy_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-policy.v1',
      'policyId',v_policy.policy_id,
      'policyKey',v_policy.policy_key,
      'version',v_policy.version,
      'enabled',v_policy.enabled,
      'maxDepth',v_policy.max_depth,
      'caseBudgetMicrosKrw',v_policy.case_budget_micros_krw,
      'marketResearcherStageBudgetMicrosKrw',
        v_policy.market_researcher_stage_budget_micros_krw,
      'skepticStageBudgetMicrosKrw',
        v_policy.skeptic_stage_budget_micros_krw,
      'providerPolicyVersion',v_policy.provider_policy_version,
      'providerPolicySha256',btrim(v_policy.provider_policy_sha256::text),
      'providerClassification',v_policy.provider_classification,
      'providerCandidateIds',to_jsonb(v_policy.provider_candidate_ids),
      'budgetPolicyVersion',v_policy.budget_policy_version,
      'budgetPolicySha256',btrim(v_policy.budget_policy_sha256::text),
      'maxProviderTurns',v_policy.max_provider_turns,
      'maxToolCalls',v_policy.max_tool_calls,
      'deadlineInterval',v_policy.deadline_interval::text,
      'marketResearcherPromptId',v_policy.market_researcher_prompt_id,
      'marketResearcherPromptVersion',
        v_policy.market_researcher_prompt_version,
      'marketResearcherPromptSha256',
        btrim(v_policy.market_researcher_prompt_sha256::text),
      'marketResearcherOutputSchemaId',
        v_policy.market_researcher_output_schema_id,
      'marketResearcherOutputSchemaVersion',
        v_policy.market_researcher_output_schema_version,
      'marketResearcherOutputSchemaSha256',
        btrim(v_policy.market_researcher_output_schema_sha256::text),
      'skepticPromptId',v_policy.skeptic_prompt_id,
      'skepticPromptVersion',v_policy.skeptic_prompt_version,
      'skepticPromptSha256',btrim(v_policy.skeptic_prompt_sha256::text),
      'skepticOutputSchemaId',v_policy.skeptic_output_schema_id,
      'skepticOutputSchemaVersion',v_policy.skeptic_output_schema_version,
      'skepticOutputSchemaSha256',
        btrim(v_policy.skeptic_output_schema_sha256::text),
      'createdBy',v_policy.created_by
    );
    IF v_policy.policy_canonical IS DISTINCT FROM
         ops.canonical_jsonb_v1(v_policy_payload)
       OR v_policy.policy_digest IS DISTINCT FROM encode(
         extensions.digest(v_policy.policy_canonical, 'sha256'), 'hex'
       ) THEN
      RAISE EXCEPTION 'hypothesis_recursion_policy_binding_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_snapshot_sha256 := v_snapshot.snapshot_sha256;
    v_hypothesis_execution_digest := v_auth.execution_digest;
    v_stage_budget := v_policy.market_researcher_stage_budget_micros_krw;
    IF v_depth > v_policy.max_depth THEN
      v_disposition := 'MAX_DEPTH_REACHED';
      EXIT evaluate_trigger;
    END IF;
    IF v_stage_budget IS NULL OR v_stage_budget <= 0 THEN
      RAISE EXCEPTION 'hypothesis_recursion_stage_budget_invalid'
        USING ERRCODE = '23514';
    END IF;
    IF v_stage_budget > v_policy.case_budget_micros_krw THEN
      v_disposition := 'CASE_BUDGET_BLOCKED';
      EXIT evaluate_trigger;
    END IF;
    v_dedupe_payload := jsonb_build_array(
      v_case.id, btrim(v_hypothesis_execution_digest::text),
      btrim(v_snapshot_sha256::text), v_stage, v_depth
    );
    v_dedupe_key := encode(extensions.digest(
      ops.canonical_jsonb_v1(v_dedupe_payload), 'sha256'
    ), 'hex');
    v_plan_id := gen_random_uuid();
    v_agent_run_id := gen_random_uuid();
    v_node_id := gen_random_uuid();
    v_job_id := gen_random_uuid();
    v_objective := convert_from(ops.canonical_jsonb_v1(
      jsonb_build_object(
        'schemaVersion','hypothesis-recursion-market-objective.v1',
        'task','승인된 가설의 근거 공백 조사',
        'hypothesisPayload',v_hypothesis_payload,
        'hypothesisPayloadSha256',
          btrim(v_hypothesis_payload_sha256::text)
      )
    ), 'UTF8');
    v_plan_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-plan.v1',
      'planId',v_plan_id,'caseId',v_case.id,
      'rootHypothesisExecutionId',v_execution_id,
      'rootHypothesisExecutionGeneration',v_generation,
      'rootHypothesisExecutionDigest',
        btrim(v_hypothesis_execution_digest::text),
      'hypothesisPayload',v_hypothesis_payload,
      'hypothesisPayloadSha256',
        btrim(v_hypothesis_payload_sha256::text),
      'datasetSnapshotId',v_snapshot.id,
      'snapshotSha256',btrim(v_snapshot_sha256::text),
      'policyId',v_policy.policy_id,'policyVersion',v_policy.version,
      'policyDigest',btrim(v_policy.policy_digest::text),
      'maxDepth',v_policy.max_depth,
      'caseBudgetMicrosKrw',v_policy.case_budget_micros_krw,
      'actorType','SERVICE','actorId','workflow-worker'
    );
    v_plan_canonical := ops.canonical_jsonb_v1(v_plan_payload);
    v_plan_digest := encode(
      extensions.digest(v_plan_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_plans(
      plan_id,case_id,root_hypothesis_execution_id,
      root_hypothesis_execution_generation,root_hypothesis_execution_digest,
      dataset_snapshot_id,snapshot_sha256,policy_id,policy_version,
      policy_digest,max_depth,case_budget_micros_krw,actor_type,actor_id,
      plan_canonical,plan_digest,created_at
    ) VALUES (
      v_plan_id,v_case.id,v_execution_id,v_generation,
      v_hypothesis_execution_digest,v_snapshot.id,v_snapshot_sha256,
      v_policy.policy_id,v_policy.version,v_policy.policy_digest,
      v_policy.max_depth,v_policy.case_budget_micros_krw,
      'SERVICE','workflow-worker',v_plan_canonical,v_plan_digest,v_now
    );

    v_initial_transcript_sha256 := encode(extensions.digest(
      ops.canonical_jsonb_v1(jsonb_build_object(
        'schemaVersion','agent-transcript.initial.v1',
        'runId',v_agent_run_id,'caseId',v_case.id,
        'recursionPlanId',v_plan_id,'recursionNodeId',v_node_id,
        'stage',v_stage,'depth',v_depth,
        'hypothesisExecutionDigest',
          btrim(v_hypothesis_execution_digest::text),
        'hypothesisPayloadSha256',
          btrim(v_hypothesis_payload_sha256::text),
        'inputSnapshotSha256',btrim(v_snapshot_sha256::text),
        'promptSha256',
          btrim(v_policy.market_researcher_prompt_sha256::text),
        'outputSchemaSha256',
          btrim(v_policy.market_researcher_output_schema_sha256::text),
        'providerPolicySha256',
          btrim(v_policy.provider_policy_sha256::text)
      )), 'sha256'
    ), 'hex');
    INSERT INTO ops.agent_runs(
      id,case_id,agent_type,objective,evidence_scope_ids,provider_policy,
      status,input_snapshot_hash,output_schema_version,max_cost,created_by,
      run_contract_version,dataset_snapshot_id,initial_transcript_sha256,
      control_state,prompt_id,prompt_version,prompt_sha256,output_schema_id,
      output_schema_contract_version,output_schema_sha256,
      provider_policy_version,provider_policy_sha256,
      provider_classification,provider_candidate_ids,max_micros_krw,
      reserved_micros_krw,settled_micros_krw,remaining_micros_krw,
      budget_reservation_state,budget_policy_version,budget_policy_sha256,
      max_provider_turns,max_tool_calls,completed_provider_turns,
      completed_tool_calls,next_turn_sequence,deadline_at,
      created_actor_type,created_service,created_at,updated_at
    ) VALUES (
      v_agent_run_id,v_case.id,'market-researcher',
      v_objective, '[]'::jsonb,
      v_policy.provider_policy_version,'QUEUED',v_snapshot_sha256,
      v_policy.market_researcher_output_schema_version,
      v_stage_budget::numeric / 1000000,NULL,2,v_snapshot.id,
      v_initial_transcript_sha256,'NONE',
      v_policy.market_researcher_prompt_id,
      v_policy.market_researcher_prompt_version,
      v_policy.market_researcher_prompt_sha256,
      v_policy.market_researcher_output_schema_id,
      v_policy.market_researcher_output_schema_version,
      v_policy.market_researcher_output_schema_sha256,
      v_policy.provider_policy_version,v_policy.provider_policy_sha256,
      v_policy.provider_classification,v_policy.provider_candidate_ids,
      v_stage_budget,v_stage_budget,0,v_stage_budget,'RESERVED',
      v_policy.budget_policy_version,v_policy.budget_policy_sha256,
      v_policy.max_provider_turns,v_policy.max_tool_calls,0,0,1,
      v_now + v_policy.deadline_interval,'SERVICE','workflow-worker',
      v_now,v_now
    );
    INSERT INTO ops.jobs(
      id,job_type,queue,payload,dedupe_key,run_after,created_at,updated_at
    ) VALUES (
      v_job_id,'AGENT_RUN','analysis-worker',
      jsonb_build_object('agentRunId',v_agent_run_id),
      'agent-run:' || v_agent_run_id::text,v_now,v_now,v_now
    );
    v_node_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-node.v1',
      'nodeId',v_node_id,'planId',v_plan_id,
      'parentNodeId',NULL,'parentDepth',NULL,
      'caseId',v_case.id,'depth',v_depth,'stage',v_stage,
      'hypothesisExecutionDigest',
        btrim(v_hypothesis_execution_digest::text),
      'hypothesisPayloadSha256',
        btrim(v_hypothesis_payload_sha256::text),
      'datasetSnapshotId',v_snapshot.id,
      'snapshotSha256',btrim(v_snapshot_sha256::text),
      'agentRunId',v_agent_run_id,'jobId',v_job_id,
      'reservedMicrosKrw',v_stage_budget,
      'dedupeKeySha256',btrim(v_dedupe_key::text),
      'actorType','SERVICE','actorId','workflow-worker'
    );
    v_node_canonical := ops.canonical_jsonb_v1(v_node_payload);
    v_node_digest := encode(
      extensions.digest(v_node_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_nodes(
      node_id,plan_id,parent_node_id,parent_depth,case_id,depth,stage,
      hypothesis_execution_digest,dataset_snapshot_id,snapshot_sha256,
      agent_run_id,job_id,reserved_micros_krw,dedupe_key_sha256,
      node_canonical,node_digest,created_at
    ) VALUES (
      v_node_id,v_plan_id,NULL,NULL,v_case.id,v_depth,v_stage,
      v_hypothesis_execution_digest,v_snapshot.id,v_snapshot_sha256,
      v_agent_run_id,v_job_id,v_stage_budget,v_dedupe_key,
      v_node_canonical,v_node_digest,v_now
    );

    v_transition_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-transition.v1',
      'planId',v_plan_id,'nodeId',NULL,'transitionSequence',1,
      'transitionScope','PLAN','stage',NULL,
      'priorState',NULL,'nextState','ACTIVE',
      'proofKind','ACTION_EXECUTION_RECEIPT',
      'proofSha256',btrim(v_execution_receipt_sha256::text),
      'actorType','SERVICE','actorId','workflow-worker',
      'priorTransitionSequence',NULL,
      'priorReceiptSha256',NULL,'occurredAt',v_now
    );
    v_transition_canonical := ops.canonical_jsonb_v1(v_transition_payload);
    v_transition_receipt := encode(
      extensions.digest(v_transition_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_transitions(
      plan_id,node_id,transition_sequence,transition_scope,stage,
      prior_state,next_state,proof_kind,proof_sha256,actor_type,actor_id,
      prior_transition_sequence,prior_receipt_sha256,
      transition_payload,transition_canonical,
      receipt_sha256,occurred_at,created_at
    ) VALUES (
      v_plan_id,NULL,1,'PLAN',NULL,NULL,'ACTIVE',
      'ACTION_EXECUTION_RECEIPT',v_execution_receipt_sha256,
      'SERVICE','workflow-worker',NULL,NULL,v_transition_payload,
      v_transition_canonical,v_transition_receipt,v_now,v_now
    );
    v_prior_transition_receipt := v_transition_receipt;
    v_transition_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-transition.v1',
      'planId',v_plan_id,'nodeId',v_node_id,'transitionSequence',2,
      'transitionScope','NODE','stage',v_stage,
      'priorState',NULL,'nextState','QUEUED',
      'proofKind','RECURSION_POLICY',
      'proofSha256',btrim(v_policy.policy_digest::text),
      'actorType','SERVICE','actorId','workflow-worker',
      'priorTransitionSequence',1,
      'priorReceiptSha256',btrim(v_prior_transition_receipt::text),
      'occurredAt',v_now
    );
    v_transition_canonical := ops.canonical_jsonb_v1(v_transition_payload);
    v_transition_receipt := encode(
      extensions.digest(v_transition_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_transitions(
      plan_id,node_id,transition_sequence,transition_scope,stage,
      prior_state,next_state,proof_kind,proof_sha256,actor_type,actor_id,
      prior_transition_sequence,prior_receipt_sha256,
      transition_payload,transition_canonical,
      receipt_sha256,occurred_at,created_at
    ) VALUES (
      v_plan_id,v_node_id,2,'NODE',v_stage,NULL,'QUEUED',
      'RECURSION_POLICY',v_policy.policy_digest,
      'SERVICE','workflow-worker',1,v_prior_transition_receipt,
      v_transition_payload,v_transition_canonical,v_transition_receipt,
      v_now,v_now
    );

    v_ledger_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-budget-ledger.v1',
      'planId',v_plan_id,'nodeId',v_node_id,'ledgerSequence',1,
      'stage',v_stage,'entryKind','RESERVE',
      'amountMicrosKrw',v_stage_budget,
      'priorReservedMicrosKrw',0,'nextReservedMicrosKrw',v_stage_budget,
      'priorSettledMicrosKrw',0,'nextSettledMicrosKrw',0,
      'actorType','SERVICE','actorId','workflow-worker',
      'priorLedgerSequence',NULL,
      'priorReceiptSha256',NULL,'occurredAt',v_now
    );
    v_ledger_canonical := ops.canonical_jsonb_v1(v_ledger_payload);
    v_ledger_receipt := encode(
      extensions.digest(v_ledger_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_budget_ledger(
      plan_id,node_id,ledger_sequence,stage,entry_kind,
      amount_micros_krw,prior_reserved_micros_krw,
      next_reserved_micros_krw,prior_settled_micros_krw,
      next_settled_micros_krw,actor_type,actor_id,
      prior_ledger_sequence,prior_receipt_sha256,
      ledger_payload,ledger_canonical,
      receipt_sha256,created_at
    ) VALUES (
      v_plan_id,v_node_id,1,v_stage,'RESERVE',v_stage_budget,
      0,v_stage_budget,0,0,'SERVICE','workflow-worker',NULL,NULL,
      v_ledger_payload,v_ledger_canonical,v_ledger_receipt,v_now
    );
    v_disposition := 'STARTED';
  END evaluate_trigger;

  IF v_disposition IS NULL THEN
    RAISE EXCEPTION 'hypothesis_recursion_disposition_missing'
      USING ERRCODE = '55000';
  END IF;
  IF v_disposition <> 'STARTED' THEN
    v_plan_id := NULL;
    v_node_id := NULL;
    v_agent_run_id := NULL;
    v_job_id := NULL;
  END IF;
  v_receipt_payload := jsonb_build_object(
    'schemaVersion','hypothesis-recursion-receipt.v1',
    'receiptId',v_receipt_id,'triggerKind','ACTION_EXECUTION',
    'triggerId',v_execution_id,'triggerGeneration',v_generation,
    'triggerDigest',btrim(v_trigger_digest::text),
    'triggerReceiptSha256',btrim(v_execution_receipt_sha256::text),
    'triggerPayloadSha256',btrim(v_trigger_digest::text),
    'producerJobId',p_producer_job_id,
    'policyId',CASE WHEN v_policy.policy_id IS NULL
      THEN NULL ELSE v_policy.policy_id END,
    'policyVersion',CASE WHEN v_policy.policy_id IS NULL
      THEN NULL ELSE v_policy.version END,
    'hypothesisPayloadSha256',CASE
      WHEN v_hypothesis_payload_sha256 IS NULL THEN NULL
      ELSE btrim(v_hypothesis_payload_sha256::text) END,
    'disposition',v_disposition,'planId',v_plan_id,'nodeId',v_node_id,
    'agentRunId',v_agent_run_id,'jobId',v_job_id,
    'actorType','SERVICE','actorId','workflow-worker','occurredAt',v_now
  );
  v_receipt_canonical := ops.canonical_jsonb_v1(v_receipt_payload);
  v_receipt_digest := encode(
    extensions.digest(v_receipt_canonical, 'sha256'), 'hex'
  );
  INSERT INTO ops.hypothesis_recursion_receipts(
    receipt_id,trigger_kind,trigger_id,trigger_generation,trigger_digest,
    trigger_receipt_sha256,producer_job_id,policy_id,policy_version,
    disposition,plan_id,node_id,agent_run_id,job_id,actor_type,actor_id,
    receipt_payload,receipt_canonical,receipt_digest,created_at
  ) VALUES (
    v_receipt_id,'ACTION_EXECUTION',v_execution_id,v_generation,
    v_trigger_digest,v_execution_receipt_sha256,p_producer_job_id,
    CASE WHEN v_policy.policy_id IS NULL THEN NULL ELSE v_policy.policy_id END,
    CASE WHEN v_policy.policy_id IS NULL THEN NULL ELSE v_policy.version END,
    v_disposition,v_plan_id,v_node_id,v_agent_run_id,v_job_id,
    'SERVICE','workflow-worker',v_receipt_payload,v_receipt_canonical,
    v_receipt_digest,v_now
  );
  RETURN QUERY SELECT v_disposition,v_receipt_id,v_plan_id,v_node_id,
    v_agent_run_id,v_job_id,v_receipt_digest,false;
END
$$;
ALTER FUNCTION ops.process_hypothesis_execution_completed_v1(jsonb,uuid)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  ops.process_hypothesis_execution_completed_v1(jsonb,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION
  ops.process_hypothesis_execution_completed_v1(jsonb,uuid)
  TO gurine_workflow_worker;

CREATE OR REPLACE FUNCTION ops.process_hypothesis_recursion_stage_completed_v1(
  p_payload jsonb,
  p_producer_job_id uuid
) RETURNS TABLE(
  disposition text,
  receipt_id uuid,
  plan_id uuid,
  node_id uuid,
  agent_run_id uuid,
  job_id uuid,
  receipt_digest char(64),
  replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, editorial, ops, extensions, pg_temp
AS $$
DECLARE
  v_job ops.jobs%ROWTYPE;
  v_outbox ops.outbox%ROWTYPE;
  v_existing ops.hypothesis_recursion_receipts%ROWTYPE;
  v_run ops.agent_runs%ROWTYPE;
  v_control_receipt ops.agent_run_control_receipts%ROWTYPE;
  v_output_validation ops.agent_output_validations%ROWTYPE;
  v_parent_node ops.hypothesis_recursion_nodes%ROWTYPE;
  v_plan ops.hypothesis_recursion_plans%ROWTYPE;
  v_policy ops.hypothesis_recursion_policies%ROWTYPE;
  v_snapshot core.dataset_snapshots%ROWTYPE;
  v_agent_run_id_input uuid;
  v_case_id uuid;
  v_event_id uuid;
  v_trigger_generation bigint;
  v_output_digest char(64);
  v_trigger_receipt_sha256 char(64);
  v_trigger_digest char(64);
  v_status text;
  v_policy_payload jsonb;
  v_plan_payload jsonb;
  v_hypothesis_payload jsonb;
  v_hypothesis_payload_sha256 char(64);
  v_parent_output_payload jsonb;
  v_parent_output_sha256 char(64);
  v_objective text;
  v_plan_state text;
  v_parent_node_state text;
  v_disposition text;
  v_plan_id uuid;
  v_node_id uuid;
  v_agent_run_id uuid;
  v_job_id uuid;
  v_receipt_id uuid := gen_random_uuid();
  v_stage text := 'SKEPTIC';
  v_depth integer;
  v_stage_budget bigint;
  v_actual_micros_krw bigint;
  v_release_micros_krw bigint;
  v_dedupe_payload jsonb;
  v_dedupe_key char(64);
  v_node_payload jsonb;
  v_node_canonical bytea;
  v_node_digest char(64);
  v_initial_transcript_sha256 char(64);
  v_transition_sequence bigint;
  v_transition_payload jsonb;
  v_transition_canonical bytea;
  v_transition_receipt char(64);
  v_prior_transition_receipt char(64);
  v_ledger_sequence bigint;
  v_prior_reserved_micros_krw bigint;
  v_prior_settled_micros_krw bigint;
  v_current_reserved_micros_krw bigint;
  v_parent_stage_budget_micros_krw bigint;
  v_ledger_payload jsonb;
  v_ledger_canonical bytea;
  v_ledger_receipt char(64);
  v_prior_ledger_receipt char(64);
  v_receipt_payload jsonb;
  v_receipt_canonical bytea;
  v_receipt_digest char(64);
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
     OR p_producer_job_id IS NULL
     OR (SELECT count(*) FROM jsonb_object_keys(p_payload)) <> 4
     OR NOT p_payload ?& ARRAY[
       'agent_run_id','case_id','output_digest','status'
     ]
     OR COALESCE(p_payload->>'agent_run_id','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR COALESCE(p_payload->>'case_id','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR COALESCE(p_payload->>'output_digest','') !~ '^[0-9a-f]{64}$'
     OR COALESCE(p_payload->>'status','') NOT IN (
       'SUCCEEDED','FAILED','CANCELLED','BUDGET_BLOCKED','POLICY_BLOCKED'
     ) THEN
    RAISE EXCEPTION 'hypothesis_recursion_stage_payload_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT pg_has_role(session_user, 'gurine_workflow_worker', 'MEMBER') THEN
    RAISE EXCEPTION 'hypothesis_recursion_worker_role_required'
      USING ERRCODE = '42501';
  END IF;
  v_agent_run_id_input := (p_payload->>'agent_run_id')::uuid;
  v_case_id := (p_payload->>'case_id')::uuid;
  v_output_digest := (p_payload->>'output_digest')::char(64);
  v_status := p_payload->>'status';

  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_producer_job_id
    AND job.job_type = 'EVENT_DELIVERY'
    AND job.queue = 'workflow-worker'
    AND job.status = 'RUNNING'
  FOR SHARE;
  IF NOT FOUND OR jsonb_typeof(v_job.payload) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(v_job.payload)) <> 8
     OR v_job.payload->>'consumerId' IS DISTINCT FROM 'workflow-worker'
     OR v_job.payload->>'eventType' IS DISTINCT FROM 'agent.run_completed.v1'
     OR v_job.payload->>'aggregateType' IS DISTINCT FROM 'agent_run'
     OR v_job.payload->>'aggregateId'
       IS DISTINCT FROM v_agent_run_id_input::text
     OR COALESCE(v_job.payload->>'eventId','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR COALESCE(v_job.payload->>'aggregateVersion','') !~ '^[0-9]+$'
     OR v_job.payload->'payload' IS DISTINCT FROM p_payload THEN
    RAISE EXCEPTION 'hypothesis_recursion_producer_job_invalid'
      USING ERRCODE = '23514';
  END IF;
  v_event_id := (v_job.payload->>'eventId')::uuid;
  v_trigger_generation := (v_job.payload->>'aggregateVersion')::bigint;
  IF v_trigger_generation <= 0 THEN
    RAISE EXCEPTION 'hypothesis_recursion_stage_generation_invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT event.* INTO v_outbox
  FROM ops.outbox AS event
  WHERE event.id = v_event_id
    AND event.aggregate_type = 'agent_run'
    AND event.aggregate_id = v_agent_run_id_input::text
    AND event.aggregate_version = v_trigger_generation
    AND event.event_type = 'agent.run_completed.v1'
    AND event.payload = p_payload
    AND EXISTS (
      SELECT 1 FROM ops.event_types AS event_type
      WHERE event_type.event_type = event.event_type
        AND event_type.active
        AND event_type.payload_schema_uri IS NOT NULL
    )
  FOR SHARE;
  IF NOT FOUND
     OR NULLIF(v_job.payload->>'occurredAt','')::timestamptz
       IS DISTINCT FROM v_outbox.occurred_at THEN
    RAISE EXCEPTION 'hypothesis_recursion_outbox_binding_invalid'
      USING ERRCODE = '23514';
  END IF;
  SELECT run.* INTO v_run
  FROM ops.agent_runs AS run
  WHERE run.id = v_agent_run_id_input
    AND run.case_id = v_case_id
    AND run.run_contract_version = 2
    AND run.version = v_trigger_generation + 1
    AND run.status = v_status
    AND run.control_state = 'SETTLED'
    AND run.completed_at IS NOT NULL
    AND run.terminal_receipt_sha256 IS NOT NULL
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_recursion_terminal_run_invalid'
      USING ERRCODE = '23514';
  END IF;
  SELECT receipt.* INTO v_control_receipt
  FROM ops.agent_run_control_receipts AS receipt
  WHERE receipt.agent_run_id = v_run.id
    AND receipt.aggregate_version = v_trigger_generation
    AND receipt.next_status = v_status
    AND receipt.next_control_state = 'SETTLED'
    AND receipt.proof_sha256 = v_output_digest
    AND receipt.receipt_sha256 = v_run.terminal_receipt_sha256
    AND receipt.occurred_at = v_outbox.occurred_at
    AND receipt.actor_type = 'SERVICE'
    AND receipt.actor_kind = 'ANALYSIS_WORKER'
    AND receipt.actor_id IS NULL
    AND receipt.actor_id_text = 'analysis-worker'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_recursion_terminal_receipt_invalid'
      USING ERRCODE = '23514';
  END IF;
  IF v_status = 'SUCCEEDED' THEN
    IF v_run.output_payload IS NULL
       OR v_run.output_validation_id IS NULL
       OR v_run.output_schema_id IS NULL
       OR v_run.output_schema_contract_version IS NULL
       OR v_run.output_schema_sha256 IS NULL
       OR encode(extensions.digest(
         ops.canonical_jsonb_v1(v_run.output_payload), 'sha256'
       ), 'hex') IS DISTINCT FROM btrim(v_output_digest::text) THEN
      RAISE EXCEPTION 'hypothesis_recursion_terminal_output_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT validation.* INTO v_output_validation
    FROM ops.agent_output_validations AS validation
    WHERE validation.validation_id = v_run.output_validation_id
      AND validation.agent_run_id = v_run.id
      AND validation.input_snapshot_sha256 = v_run.input_snapshot_hash
      AND validation.provider_output_sha256 = v_output_digest
      AND validation.output_schema_id = v_run.output_schema_id
      AND validation.output_schema_version =
        v_run.output_schema_contract_version
      AND validation.output_schema_sha256 = v_run.output_schema_sha256
      AND validation.validation_status = 'VALID'
      AND validation.schema_status = 'PASS'
      AND validation.citation_status = 'PASS'
      AND validation.policy_status = 'PASS'
      AND validation.run_terminal_status = 'SUCCEEDED'
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_terminal_validation_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_parent_output_payload := v_run.output_payload;
    v_parent_output_sha256 := v_output_digest;
  END IF;
  v_trigger_receipt_sha256 := v_control_receipt.receipt_sha256;
  v_trigger_digest := encode(
    extensions.digest(ops.canonical_jsonb_v1(p_payload), 'sha256'), 'hex'
  );

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'HYPOTHESIS_RECURSION:AGENT_RUN:'
        || v_agent_run_id_input::text || ':' || v_trigger_generation::text,
      0
    )
  );
  SELECT receipt.* INTO v_existing
  FROM ops.hypothesis_recursion_receipts AS receipt
  WHERE receipt.trigger_kind = 'AGENT_RUN'
    AND receipt.trigger_id = v_agent_run_id_input
    AND receipt.trigger_generation = v_trigger_generation
  ORDER BY receipt.created_at, receipt.receipt_id
  LIMIT 1
  FOR SHARE;
  IF FOUND THEN
    IF v_existing.trigger_digest IS DISTINCT FROM v_trigger_digest
       OR v_existing.trigger_receipt_sha256
         IS DISTINCT FROM v_trigger_receipt_sha256
       OR v_existing.producer_job_id IS DISTINCT FROM p_producer_job_id
       OR v_existing.receipt_payload->>'triggerPayloadSha256'
         IS DISTINCT FROM btrim(v_trigger_digest::text) THEN
      RAISE EXCEPTION 'hypothesis_recursion_trigger_replay_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN QUERY SELECT
      v_existing.disposition, v_existing.receipt_id,
      v_existing.plan_id, v_existing.node_id,
      v_existing.agent_run_id, v_existing.job_id,
      v_existing.receipt_digest, true;
    RETURN;
  END IF;

  <<evaluate_stage>>
  BEGIN
    SELECT node.* INTO v_parent_node
    FROM ops.hypothesis_recursion_nodes AS node
    WHERE node.agent_run_id = v_run.id
    FOR SHARE;
    IF NOT FOUND THEN
      v_disposition := 'NODE_NOT_RECURSIVE';
      EXIT evaluate_stage;
    END IF;
    SELECT plan.* INTO v_plan
    FROM ops.hypothesis_recursion_plans AS plan
    WHERE plan.plan_id = v_parent_node.plan_id
      AND plan.case_id = v_run.case_id
      AND plan.dataset_snapshot_id = v_run.dataset_snapshot_id
      AND plan.snapshot_sha256 = v_run.input_snapshot_hash
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_plan_binding_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_plan_payload := convert_from(v_plan.plan_canonical, 'UTF8')::jsonb;
    IF COALESCE(v_plan_payload->>'hypothesisPayloadSha256','')
         !~ '^[0-9a-f]{64}$'
       OR jsonb_typeof(v_plan_payload->'hypothesisPayload')
         IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'hypothesis_recursion_plan_hypothesis_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_hypothesis_payload := v_plan_payload->'hypothesisPayload';
    v_hypothesis_payload_sha256 :=
      (v_plan_payload->>'hypothesisPayloadSha256')::char(64);
    IF v_hypothesis_payload_sha256 IS DISTINCT FROM encode(
         extensions.digest(
           ops.canonical_jsonb_v1(v_hypothesis_payload), 'sha256'
         ), 'hex'
       ) THEN
      RAISE EXCEPTION 'hypothesis_recursion_plan_hypothesis_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_plan_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-plan.v1',
      'planId',v_plan.plan_id,'caseId',v_plan.case_id,
      'rootHypothesisExecutionId',v_plan.root_hypothesis_execution_id,
      'rootHypothesisExecutionGeneration',
        v_plan.root_hypothesis_execution_generation,
      'rootHypothesisExecutionDigest',
        btrim(v_plan.root_hypothesis_execution_digest::text),
      'hypothesisPayload',v_hypothesis_payload,
      'hypothesisPayloadSha256',
        btrim(v_hypothesis_payload_sha256::text),
      'datasetSnapshotId',v_plan.dataset_snapshot_id,
      'snapshotSha256',btrim(v_plan.snapshot_sha256::text),
      'policyId',v_plan.policy_id,'policyVersion',v_plan.policy_version,
      'policyDigest',btrim(v_plan.policy_digest::text),
      'maxDepth',v_plan.max_depth,
      'caseBudgetMicrosKrw',v_plan.case_budget_micros_krw,
      'actorType','SERVICE','actorId','workflow-worker'
    );
    IF v_plan.plan_canonical IS DISTINCT FROM
         ops.canonical_jsonb_v1(v_plan_payload)
       OR v_plan.plan_digest IS DISTINCT FROM encode(
         extensions.digest(v_plan.plan_canonical, 'sha256'), 'hex'
       ) THEN
      RAISE EXCEPTION 'hypothesis_recursion_plan_canonical_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT policy.* INTO v_policy
    FROM ops.hypothesis_recursion_policies AS policy
    WHERE policy.policy_id = v_plan.policy_id
      AND policy.version = v_plan.policy_version
      AND policy.policy_digest = v_plan.policy_digest
      AND policy.policy_key = 'HYPOTHESIS_RECURSION'
      AND policy.enabled
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_bound_policy_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_policy_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-policy.v1',
      'policyId',v_policy.policy_id,
      'policyKey',v_policy.policy_key,
      'version',v_policy.version,
      'enabled',v_policy.enabled,
      'maxDepth',v_policy.max_depth,
      'caseBudgetMicrosKrw',v_policy.case_budget_micros_krw,
      'marketResearcherStageBudgetMicrosKrw',
        v_policy.market_researcher_stage_budget_micros_krw,
      'skepticStageBudgetMicrosKrw',
        v_policy.skeptic_stage_budget_micros_krw,
      'providerPolicyVersion',v_policy.provider_policy_version,
      'providerPolicySha256',btrim(v_policy.provider_policy_sha256::text),
      'providerClassification',v_policy.provider_classification,
      'providerCandidateIds',to_jsonb(v_policy.provider_candidate_ids),
      'budgetPolicyVersion',v_policy.budget_policy_version,
      'budgetPolicySha256',btrim(v_policy.budget_policy_sha256::text),
      'maxProviderTurns',v_policy.max_provider_turns,
      'maxToolCalls',v_policy.max_tool_calls,
      'deadlineInterval',v_policy.deadline_interval::text,
      'marketResearcherPromptId',v_policy.market_researcher_prompt_id,
      'marketResearcherPromptVersion',
        v_policy.market_researcher_prompt_version,
      'marketResearcherPromptSha256',
        btrim(v_policy.market_researcher_prompt_sha256::text),
      'marketResearcherOutputSchemaId',
        v_policy.market_researcher_output_schema_id,
      'marketResearcherOutputSchemaVersion',
        v_policy.market_researcher_output_schema_version,
      'marketResearcherOutputSchemaSha256',
        btrim(v_policy.market_researcher_output_schema_sha256::text),
      'skepticPromptId',v_policy.skeptic_prompt_id,
      'skepticPromptVersion',v_policy.skeptic_prompt_version,
      'skepticPromptSha256',btrim(v_policy.skeptic_prompt_sha256::text),
      'skepticOutputSchemaId',v_policy.skeptic_output_schema_id,
      'skepticOutputSchemaVersion',v_policy.skeptic_output_schema_version,
      'skepticOutputSchemaSha256',
        btrim(v_policy.skeptic_output_schema_sha256::text),
      'createdBy',v_policy.created_by
    );
    IF v_policy.policy_canonical IS DISTINCT FROM
         ops.canonical_jsonb_v1(v_policy_payload)
       OR v_policy.policy_digest IS DISTINCT FROM encode(
         extensions.digest(v_policy.policy_canonical, 'sha256'), 'hex'
       ) THEN
      RAISE EXCEPTION 'hypothesis_recursion_policy_binding_invalid'
        USING ERRCODE = '23514';
    END IF;
    IF (
         v_parent_node.stage = 'MARKET_RESEARCHER'
         AND (
           v_run.agent_type IS DISTINCT FROM 'market-researcher'
           OR v_run.prompt_id IS DISTINCT FROM
             v_policy.market_researcher_prompt_id
           OR v_run.prompt_version IS DISTINCT FROM
             v_policy.market_researcher_prompt_version
           OR v_run.prompt_sha256 IS DISTINCT FROM
             v_policy.market_researcher_prompt_sha256
           OR v_run.output_schema_id IS DISTINCT FROM
             v_policy.market_researcher_output_schema_id
           OR v_run.output_schema_contract_version IS DISTINCT FROM
             v_policy.market_researcher_output_schema_version
           OR v_run.output_schema_sha256 IS DISTINCT FROM
             v_policy.market_researcher_output_schema_sha256
         )
       ) OR (
         v_parent_node.stage = 'SKEPTIC'
         AND (
           v_run.agent_type IS DISTINCT FROM 'skeptic'
           OR v_run.prompt_id IS DISTINCT FROM v_policy.skeptic_prompt_id
           OR v_run.prompt_version IS DISTINCT FROM
             v_policy.skeptic_prompt_version
           OR v_run.prompt_sha256 IS DISTINCT FROM
             v_policy.skeptic_prompt_sha256
           OR v_run.output_schema_id IS DISTINCT FROM
             v_policy.skeptic_output_schema_id
           OR v_run.output_schema_contract_version IS DISTINCT FROM
             v_policy.skeptic_output_schema_version
           OR v_run.output_schema_sha256 IS DISTINCT FROM
             v_policy.skeptic_output_schema_sha256
         )
       ) THEN
      RAISE EXCEPTION 'hypothesis_recursion_stage_contract_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT snapshot.* INTO v_snapshot
    FROM core.dataset_snapshots AS snapshot
    WHERE snapshot.id = v_plan.dataset_snapshot_id
      AND snapshot.snapshot_sha256 = v_plan.snapshot_sha256
      AND snapshot.snapshot_kind = 'AGENT_CASE'
      AND snapshot.state = 'READY'
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_snapshot_invalid'
        USING ERRCODE = '23514';
    END IF;

    SELECT transition.next_state INTO v_plan_state
    FROM ops.hypothesis_recursion_transitions AS transition
    WHERE transition.plan_id = v_plan.plan_id
      AND transition.transition_scope = 'PLAN'
    ORDER BY transition.transition_sequence DESC
    LIMIT 1;
    IF v_plan_state IN ('REVIEWED_TERMINAL','BUDGET_EXHAUSTED') THEN
      v_disposition := 'PLAN_TERMINAL';
      EXIT evaluate_stage;
    END IF;
    IF v_plan_state IS DISTINCT FROM 'ACTIVE' THEN
      RAISE EXCEPTION 'hypothesis_recursion_plan_state_invalid'
        USING ERRCODE = '23514';
    END IF;
    SELECT transition.next_state INTO v_parent_node_state
    FROM ops.hypothesis_recursion_transitions AS transition
    WHERE transition.plan_id = v_plan.plan_id
      AND transition.node_id = v_parent_node.node_id
      AND transition.transition_scope = 'NODE'
    ORDER BY transition.transition_sequence DESC
    LIMIT 1;
    IF v_parent_node_state IS DISTINCT FROM 'QUEUED' THEN
      RAISE EXCEPTION 'hypothesis_recursion_node_state_invalid'
        USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM ops.hypothesis_recursion_budget_ledger AS ledger
      WHERE ledger.plan_id = v_plan.plan_id
        AND ledger.node_id = v_parent_node.node_id
        AND ledger.entry_kind = 'RESERVE'
        AND ledger.amount_micros_krw = v_parent_node.reserved_micros_krw
    ) OR EXISTS (
      SELECT 1
      FROM ops.hypothesis_recursion_budget_ledger AS ledger
      WHERE ledger.plan_id = v_plan.plan_id
        AND ledger.node_id = v_parent_node.node_id
        AND ledger.entry_kind <> 'RESERVE'
    ) THEN
      RAISE EXCEPTION 'hypothesis_recursion_budget_reservation_invalid'
        USING ERRCODE = '23514';
    END IF;
    IF v_run.actual_cost IS NULL OR v_run.actual_cost < 0
       OR scale(v_run.actual_cost) > 6 THEN
      RAISE EXCEPTION 'hypothesis_recursion_terminal_cost_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_actual_micros_krw := round(v_run.actual_cost * 1000000)::bigint;
    v_parent_stage_budget_micros_krw := CASE v_parent_node.stage
      WHEN 'MARKET_RESEARCHER' THEN
        v_policy.market_researcher_stage_budget_micros_krw
      WHEN 'SKEPTIC' THEN v_policy.skeptic_stage_budget_micros_krw
      ELSE NULL
    END;
    IF v_actual_micros_krw > v_parent_node.reserved_micros_krw
       OR v_parent_stage_budget_micros_krw IS NULL
       OR v_parent_node.reserved_micros_krw <= 0
       OR v_parent_node.reserved_micros_krw
         > v_parent_stage_budget_micros_krw
       OR v_actual_micros_krw > v_parent_stage_budget_micros_krw
       OR v_run.max_micros_krw
         IS DISTINCT FROM v_parent_node.reserved_micros_krw
       OR v_run.reserved_micros_krw
         IS DISTINCT FROM v_parent_node.reserved_micros_krw
       OR v_run.settled_micros_krw IS DISTINCT FROM v_actual_micros_krw THEN
      RAISE EXCEPTION 'hypothesis_recursion_terminal_cost_invalid'
        USING ERRCODE = '23514';
    END IF;

    SELECT transition.transition_sequence, transition.receipt_sha256
    INTO v_transition_sequence, v_prior_transition_receipt
    FROM ops.hypothesis_recursion_transitions AS transition
    WHERE transition.plan_id = v_plan.plan_id
    ORDER BY transition.transition_sequence DESC
    LIMIT 1
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_transition_chain_missing'
        USING ERRCODE = '23514';
    END IF;
    v_transition_sequence := v_transition_sequence + 1;
    v_transition_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-transition.v1',
      'planId',v_plan.plan_id,'nodeId',v_parent_node.node_id,
      'transitionSequence',v_transition_sequence,
      'transitionScope','NODE','stage',v_parent_node.stage,
      'priorState','QUEUED',
      'nextState',CASE v_status
        WHEN 'SUCCEEDED' THEN 'SUCCEEDED'
        WHEN 'BUDGET_BLOCKED' THEN 'BUDGET_BLOCKED'
        ELSE 'FAILED' END,
      'proofKind','AGENT_RUN_OUTPUT',
      'proofSha256',btrim(v_output_digest::text),
      'actorType','SERVICE','actorId','workflow-worker',
      'priorTransitionSequence',v_transition_sequence - 1,
      'priorReceiptSha256',btrim(v_prior_transition_receipt::text),
      'occurredAt',v_now
    );
    v_transition_canonical := ops.canonical_jsonb_v1(v_transition_payload);
    v_transition_receipt := encode(
      extensions.digest(v_transition_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_transitions(
      plan_id,node_id,transition_sequence,transition_scope,stage,
      prior_state,next_state,proof_kind,proof_sha256,actor_type,actor_id,
      prior_transition_sequence,prior_receipt_sha256,
      transition_payload,transition_canonical,
      receipt_sha256,occurred_at,created_at
    ) VALUES (
      v_plan.plan_id,v_parent_node.node_id,v_transition_sequence,'NODE',
      v_parent_node.stage,'QUEUED',CASE v_status
        WHEN 'SUCCEEDED' THEN 'SUCCEEDED'
        WHEN 'BUDGET_BLOCKED' THEN 'BUDGET_BLOCKED'
        ELSE 'FAILED' END,
      'AGENT_RUN_OUTPUT',v_output_digest,'SERVICE','workflow-worker',
      v_transition_sequence - 1,v_prior_transition_receipt,
      v_transition_payload,
      v_transition_canonical,v_transition_receipt,v_now,v_now
    );
    v_prior_transition_receipt := v_transition_receipt;

    SELECT ledger.ledger_sequence, ledger.next_reserved_micros_krw,
           ledger.next_settled_micros_krw, ledger.receipt_sha256
    INTO v_ledger_sequence, v_prior_reserved_micros_krw,
         v_prior_settled_micros_krw, v_prior_ledger_receipt
    FROM ops.hypothesis_recursion_budget_ledger AS ledger
    WHERE ledger.plan_id = v_plan.plan_id
    ORDER BY ledger.ledger_sequence DESC
    LIMIT 1
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'hypothesis_recursion_budget_chain_missing'
        USING ERRCODE = '23514';
    END IF;
    v_ledger_sequence := v_ledger_sequence + 1;
    v_ledger_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-budget-ledger.v1',
      'planId',v_plan.plan_id,'nodeId',v_parent_node.node_id,
      'ledgerSequence',v_ledger_sequence,
      'stage',v_parent_node.stage,'entryKind','SETTLE',
      'amountMicrosKrw',v_actual_micros_krw,
      'priorReservedMicrosKrw',v_prior_reserved_micros_krw,
      'nextReservedMicrosKrw',v_prior_reserved_micros_krw,
      'priorSettledMicrosKrw',v_prior_settled_micros_krw,
      'nextSettledMicrosKrw',
        v_prior_settled_micros_krw + v_actual_micros_krw,
      'actorType','SERVICE','actorId','workflow-worker',
      'priorLedgerSequence',v_ledger_sequence - 1,
      'priorReceiptSha256',btrim(v_prior_ledger_receipt::text),
      'occurredAt',v_now
    );
    v_ledger_canonical := ops.canonical_jsonb_v1(v_ledger_payload);
    v_ledger_receipt := encode(
      extensions.digest(v_ledger_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_budget_ledger(
      plan_id,node_id,ledger_sequence,stage,entry_kind,
      amount_micros_krw,prior_reserved_micros_krw,
      next_reserved_micros_krw,prior_settled_micros_krw,
      next_settled_micros_krw,actor_type,actor_id,
      prior_ledger_sequence,prior_receipt_sha256,
      ledger_payload,ledger_canonical,
      receipt_sha256,created_at
    ) VALUES (
      v_plan.plan_id,v_parent_node.node_id,v_ledger_sequence,
      v_parent_node.stage,'SETTLE',v_actual_micros_krw,
      v_prior_reserved_micros_krw,v_prior_reserved_micros_krw,
      v_prior_settled_micros_krw,
      v_prior_settled_micros_krw + v_actual_micros_krw,
      'SERVICE','workflow-worker',v_ledger_sequence - 1,
      v_prior_ledger_receipt,
      v_ledger_payload,v_ledger_canonical,v_ledger_receipt,v_now
    );
    v_prior_settled_micros_krw :=
      v_prior_settled_micros_krw + v_actual_micros_krw;
    v_prior_ledger_receipt := v_ledger_receipt;

    v_release_micros_krw :=
      v_parent_node.reserved_micros_krw - v_actual_micros_krw;
    v_ledger_sequence := v_ledger_sequence + 1;
    v_ledger_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-budget-ledger.v1',
      'planId',v_plan.plan_id,'nodeId',v_parent_node.node_id,
      'ledgerSequence',v_ledger_sequence,
      'stage',v_parent_node.stage,'entryKind','RELEASE',
      'amountMicrosKrw',v_release_micros_krw,
      'priorReservedMicrosKrw',v_prior_reserved_micros_krw,
      'nextReservedMicrosKrw',
        v_prior_reserved_micros_krw - v_release_micros_krw,
      'priorSettledMicrosKrw',v_prior_settled_micros_krw,
      'nextSettledMicrosKrw',v_prior_settled_micros_krw,
      'actorType','SERVICE','actorId','workflow-worker',
      'priorLedgerSequence',v_ledger_sequence - 1,
      'priorReceiptSha256',btrim(v_prior_ledger_receipt::text),
      'occurredAt',v_now
    );
    v_ledger_canonical := ops.canonical_jsonb_v1(v_ledger_payload);
    v_ledger_receipt := encode(
      extensions.digest(v_ledger_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_budget_ledger(
      plan_id,node_id,ledger_sequence,stage,entry_kind,
      amount_micros_krw,prior_reserved_micros_krw,
      next_reserved_micros_krw,prior_settled_micros_krw,
      next_settled_micros_krw,actor_type,actor_id,
      prior_ledger_sequence,prior_receipt_sha256,
      ledger_payload,ledger_canonical,
      receipt_sha256,created_at
    ) VALUES (
      v_plan.plan_id,v_parent_node.node_id,v_ledger_sequence,
      v_parent_node.stage,'RELEASE',v_release_micros_krw,
      v_prior_reserved_micros_krw,
      v_prior_reserved_micros_krw - v_release_micros_krw,
      v_prior_settled_micros_krw,v_prior_settled_micros_krw,
      'SERVICE','workflow-worker',v_ledger_sequence - 1,
      v_prior_ledger_receipt,
      v_ledger_payload,v_ledger_canonical,v_ledger_receipt,v_now
    );
    v_prior_reserved_micros_krw :=
      v_prior_reserved_micros_krw - v_release_micros_krw;
    v_prior_ledger_receipt := v_ledger_receipt;

    IF v_status <> 'SUCCEEDED' THEN
      v_disposition := 'RUN_NOT_SUCCEEDED';
      EXIT evaluate_stage;
    END IF;
    IF v_parent_node.stage = 'SKEPTIC' THEN
      v_transition_sequence := v_transition_sequence + 1;
      v_transition_payload := jsonb_build_object(
        'schemaVersion','hypothesis-recursion-transition.v1',
        'planId',v_plan.plan_id,'nodeId',NULL,
        'transitionSequence',v_transition_sequence,
        'transitionScope','PLAN','stage',NULL,
        'priorState','ACTIVE','nextState','REVIEWED_TERMINAL',
        'proofKind','SKEPTIC_OUTPUT',
        'proofSha256',btrim(v_output_digest::text),
        'actorType','SERVICE','actorId','workflow-worker',
        'priorTransitionSequence',v_transition_sequence - 1,
        'priorReceiptSha256',btrim(v_prior_transition_receipt::text),
        'occurredAt',v_now
      );
      v_transition_canonical := ops.canonical_jsonb_v1(
        v_transition_payload
      );
      v_transition_receipt := encode(
        extensions.digest(v_transition_canonical, 'sha256'), 'hex'
      );
      INSERT INTO ops.hypothesis_recursion_transitions(
        plan_id,node_id,transition_sequence,transition_scope,stage,
        prior_state,next_state,proof_kind,proof_sha256,actor_type,actor_id,
        prior_transition_sequence,prior_receipt_sha256,
        transition_payload,transition_canonical,
        receipt_sha256,occurred_at,created_at
      ) VALUES (
        v_plan.plan_id,NULL,v_transition_sequence,'PLAN',NULL,
        'ACTIVE','REVIEWED_TERMINAL','SKEPTIC_OUTPUT',v_output_digest,
        'SERVICE','workflow-worker',v_transition_sequence - 1,
        v_prior_transition_receipt,
        v_transition_payload,v_transition_canonical,
        v_transition_receipt,v_now,v_now
      );
      v_disposition := 'PLAN_TERMINAL';
      EXIT evaluate_stage;
    END IF;
    IF v_parent_node.stage <> 'MARKET_RESEARCHER' THEN
      v_disposition := 'STAGE_NOT_MARKET_RESEARCHER';
      EXIT evaluate_stage;
    END IF;

    v_depth := v_parent_node.depth + 1;
    IF v_depth > v_plan.max_depth THEN
      v_disposition := 'MAX_DEPTH_REACHED';
      EXIT evaluate_stage;
    END IF;
    v_stage_budget := v_policy.skeptic_stage_budget_micros_krw;
    v_dedupe_payload := jsonb_build_array(
      v_plan.case_id,btrim(v_plan.root_hypothesis_execution_digest::text),
      btrim(v_plan.snapshot_sha256::text),v_stage,v_depth
    );
    v_dedupe_key := encode(extensions.digest(
      ops.canonical_jsonb_v1(v_dedupe_payload), 'sha256'
    ), 'hex');
    IF v_stage_budget IS NULL OR v_stage_budget <= 0 THEN
      RAISE EXCEPTION 'hypothesis_recursion_stage_budget_invalid'
        USING ERRCODE = '23514';
    END IF;
    IF v_prior_reserved_micros_krw < v_prior_settled_micros_krw THEN
      RAISE EXCEPTION 'hypothesis_recursion_budget_chain_invalid'
        USING ERRCODE = '23514';
    END IF;
    v_current_reserved_micros_krw :=
      v_prior_reserved_micros_krw - v_prior_settled_micros_krw;
    IF v_prior_settled_micros_krw
         + v_current_reserved_micros_krw + v_stage_budget
       > v_plan.case_budget_micros_krw THEN
      v_transition_sequence := v_transition_sequence + 1;
      v_transition_payload := jsonb_build_object(
        'schemaVersion','hypothesis-recursion-transition.v1',
        'planId',v_plan.plan_id,'nodeId',NULL,
        'transitionSequence',v_transition_sequence,
        'transitionScope','PLAN','stage',NULL,
        'priorState','ACTIVE','nextState','BUDGET_EXHAUSTED',
        'proofKind','RECURSION_POLICY',
        'proofSha256',btrim(v_policy.policy_digest::text),
        'actorType','SERVICE','actorId','workflow-worker',
        'priorTransitionSequence',v_transition_sequence - 1,
        'priorReceiptSha256',btrim(v_prior_transition_receipt::text),
        'accumulatedSettledMicrosKrw',v_prior_settled_micros_krw,
        'currentReservedMicrosKrw',v_current_reserved_micros_krw,
        'requestedReserveMicrosKrw',v_stage_budget,
        'caseBudgetMicrosKrw',v_plan.case_budget_micros_krw,
        'budgetLedgerReceiptSha256',btrim(v_prior_ledger_receipt::text),
        'occurredAt',v_now
      );
      v_transition_canonical := ops.canonical_jsonb_v1(
        v_transition_payload
      );
      v_transition_receipt := encode(
        extensions.digest(v_transition_canonical, 'sha256'), 'hex'
      );
      INSERT INTO ops.hypothesis_recursion_transitions(
        plan_id,node_id,transition_sequence,transition_scope,stage,
        prior_state,next_state,proof_kind,proof_sha256,actor_type,actor_id,
        prior_transition_sequence,prior_receipt_sha256,
        transition_payload,transition_canonical,
        receipt_sha256,occurred_at,created_at
      ) VALUES (
        v_plan.plan_id,NULL,v_transition_sequence,'PLAN',NULL,
        'ACTIVE','BUDGET_EXHAUSTED','RECURSION_POLICY',
        v_policy.policy_digest,'SERVICE','workflow-worker',
        v_transition_sequence - 1,v_prior_transition_receipt,
        v_transition_payload,v_transition_canonical,
        v_transition_receipt,v_now,v_now
      );
      v_disposition := 'CASE_BUDGET_BLOCKED';
      EXIT evaluate_stage;
    END IF;

    v_plan_id := v_plan.plan_id;
    v_agent_run_id := gen_random_uuid();
    v_node_id := gen_random_uuid();
    v_job_id := gen_random_uuid();
    v_parent_output_payload := v_run.output_payload;
    v_parent_output_sha256 := v_output_digest;
    v_objective := convert_from(ops.canonical_jsonb_v1(
      jsonb_build_object(
        'schemaVersion','hypothesis-recursion-skeptic-objective.v1',
        'task','승인된 가설과 후속 조사 결과의 반증 검토',
        'hypothesisPayload',v_hypothesis_payload,
        'hypothesisPayloadSha256',
          btrim(v_hypothesis_payload_sha256::text),
        'parentMarketResearchOutputUntrusted',v_parent_output_payload,
        'parentOutputSha256',btrim(v_parent_output_sha256::text)
      )
    ), 'UTF8');
    v_initial_transcript_sha256 := encode(extensions.digest(
      ops.canonical_jsonb_v1(jsonb_build_object(
        'schemaVersion','agent-transcript.initial.v1',
        'runId',v_agent_run_id,'caseId',v_plan.case_id,
        'recursionPlanId',v_plan.plan_id,'recursionNodeId',v_node_id,
        'parentNodeId',v_parent_node.node_id,
        'stage',v_stage,'depth',v_depth,
        'hypothesisExecutionDigest',
          btrim(v_plan.root_hypothesis_execution_digest::text),
        'hypothesisPayloadSha256',
          btrim(v_hypothesis_payload_sha256::text),
        'parentOutputSha256',btrim(v_parent_output_sha256::text),
        'inputSnapshotSha256',btrim(v_plan.snapshot_sha256::text),
        'promptSha256',btrim(v_policy.skeptic_prompt_sha256::text),
        'outputSchemaSha256',
          btrim(v_policy.skeptic_output_schema_sha256::text),
        'providerPolicySha256',
          btrim(v_policy.provider_policy_sha256::text)
      )), 'sha256'
    ), 'hex');
    INSERT INTO ops.agent_runs(
      id,case_id,agent_type,objective,evidence_scope_ids,provider_policy,
      status,input_snapshot_hash,output_schema_version,max_cost,created_by,
      run_contract_version,dataset_snapshot_id,initial_transcript_sha256,
      control_state,prompt_id,prompt_version,prompt_sha256,output_schema_id,
      output_schema_contract_version,output_schema_sha256,
      provider_policy_version,provider_policy_sha256,
      provider_classification,provider_candidate_ids,max_micros_krw,
      reserved_micros_krw,settled_micros_krw,remaining_micros_krw,
      budget_reservation_state,budget_policy_version,budget_policy_sha256,
      max_provider_turns,max_tool_calls,completed_provider_turns,
      completed_tool_calls,next_turn_sequence,deadline_at,
      created_actor_type,created_service,created_at,updated_at
    ) VALUES (
      v_agent_run_id,v_plan.case_id,'skeptic',
      v_objective, '[]'::jsonb,
      v_policy.provider_policy_version,'QUEUED',v_plan.snapshot_sha256,
      v_policy.skeptic_output_schema_version,
      v_stage_budget::numeric / 1000000,NULL,2,v_plan.dataset_snapshot_id,
      v_initial_transcript_sha256,'NONE',v_policy.skeptic_prompt_id,
      v_policy.skeptic_prompt_version,v_policy.skeptic_prompt_sha256,
      v_policy.skeptic_output_schema_id,
      v_policy.skeptic_output_schema_version,
      v_policy.skeptic_output_schema_sha256,
      v_policy.provider_policy_version,v_policy.provider_policy_sha256,
      v_policy.provider_classification,v_policy.provider_candidate_ids,
      v_stage_budget,v_stage_budget,0,v_stage_budget,'RESERVED',
      v_policy.budget_policy_version,v_policy.budget_policy_sha256,
      v_policy.max_provider_turns,v_policy.max_tool_calls,0,0,1,
      v_now + v_policy.deadline_interval,'SERVICE','workflow-worker',
      v_now,v_now
    );
    INSERT INTO ops.jobs(
      id,job_type,queue,payload,dedupe_key,run_after,created_at,updated_at
    ) VALUES (
      v_job_id,'AGENT_RUN','analysis-worker',
      jsonb_build_object('agentRunId',v_agent_run_id),
      'agent-run:' || v_agent_run_id::text,v_now,v_now,v_now
    );
    v_node_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-node.v1',
      'nodeId',v_node_id,'planId',v_plan.plan_id,
      'parentNodeId',v_parent_node.node_id,
      'parentDepth',v_parent_node.depth,
      'caseId',v_plan.case_id,'depth',v_depth,'stage',v_stage,
      'hypothesisExecutionDigest',
        btrim(v_plan.root_hypothesis_execution_digest::text),
      'hypothesisPayloadSha256',
        btrim(v_hypothesis_payload_sha256::text),
      'parentOutputSha256',btrim(v_parent_output_sha256::text),
      'datasetSnapshotId',v_plan.dataset_snapshot_id,
      'snapshotSha256',btrim(v_plan.snapshot_sha256::text),
      'agentRunId',v_agent_run_id,'jobId',v_job_id,
      'reservedMicrosKrw',v_stage_budget,
      'dedupeKeySha256',btrim(v_dedupe_key::text),
      'actorType','SERVICE','actorId','workflow-worker'
    );
    v_node_canonical := ops.canonical_jsonb_v1(v_node_payload);
    v_node_digest := encode(
      extensions.digest(v_node_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_nodes(
      node_id,plan_id,parent_node_id,parent_depth,case_id,depth,stage,
      hypothesis_execution_digest,dataset_snapshot_id,snapshot_sha256,
      agent_run_id,job_id,reserved_micros_krw,dedupe_key_sha256,
      node_canonical,node_digest,created_at
    ) VALUES (
      v_node_id,v_plan.plan_id,v_parent_node.node_id,v_parent_node.depth,
      v_plan.case_id,v_depth,v_stage,v_plan.root_hypothesis_execution_digest,
      v_plan.dataset_snapshot_id,v_plan.snapshot_sha256,
      v_agent_run_id,v_job_id,v_stage_budget,v_dedupe_key,
      v_node_canonical,v_node_digest,v_now
    );

    v_ledger_sequence := v_ledger_sequence + 1;
    v_ledger_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-budget-ledger.v1',
      'planId',v_plan.plan_id,'nodeId',v_node_id,
      'ledgerSequence',v_ledger_sequence,'stage',v_stage,
      'entryKind','RESERVE','amountMicrosKrw',v_stage_budget,
      'priorReservedMicrosKrw',v_prior_reserved_micros_krw,
      'nextReservedMicrosKrw',
        v_prior_reserved_micros_krw + v_stage_budget,
      'priorSettledMicrosKrw',v_prior_settled_micros_krw,
      'nextSettledMicrosKrw',v_prior_settled_micros_krw,
      'actorType','SERVICE','actorId','workflow-worker',
      'priorLedgerSequence',v_ledger_sequence - 1,
      'priorReceiptSha256',btrim(v_prior_ledger_receipt::text),
      'occurredAt',v_now
    );
    v_ledger_canonical := ops.canonical_jsonb_v1(v_ledger_payload);
    v_ledger_receipt := encode(
      extensions.digest(v_ledger_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_budget_ledger(
      plan_id,node_id,ledger_sequence,stage,entry_kind,
      amount_micros_krw,prior_reserved_micros_krw,
      next_reserved_micros_krw,prior_settled_micros_krw,
      next_settled_micros_krw,actor_type,actor_id,
      prior_ledger_sequence,prior_receipt_sha256,
      ledger_payload,ledger_canonical,
      receipt_sha256,created_at
    ) VALUES (
      v_plan.plan_id,v_node_id,v_ledger_sequence,v_stage,'RESERVE',
      v_stage_budget,v_prior_reserved_micros_krw,
      v_prior_reserved_micros_krw + v_stage_budget,
      v_prior_settled_micros_krw,v_prior_settled_micros_krw,
      'SERVICE','workflow-worker',v_ledger_sequence - 1,
      v_prior_ledger_receipt,
      v_ledger_payload,v_ledger_canonical,v_ledger_receipt,v_now
    );

    v_transition_sequence := v_transition_sequence + 1;
    v_transition_payload := jsonb_build_object(
      'schemaVersion','hypothesis-recursion-transition.v1',
      'planId',v_plan.plan_id,'nodeId',v_node_id,
      'transitionSequence',v_transition_sequence,
      'transitionScope','NODE','stage',v_stage,
      'priorState',NULL,'nextState','QUEUED',
      'proofKind','RECURSION_POLICY',
      'proofSha256',btrim(v_policy.policy_digest::text),
      'actorType','SERVICE','actorId','workflow-worker',
      'priorTransitionSequence',v_transition_sequence - 1,
      'priorReceiptSha256',btrim(v_prior_transition_receipt::text),
      'occurredAt',v_now
    );
    v_transition_canonical := ops.canonical_jsonb_v1(v_transition_payload);
    v_transition_receipt := encode(
      extensions.digest(v_transition_canonical, 'sha256'), 'hex'
    );
    INSERT INTO ops.hypothesis_recursion_transitions(
      plan_id,node_id,transition_sequence,transition_scope,stage,
      prior_state,next_state,proof_kind,proof_sha256,actor_type,actor_id,
      prior_transition_sequence,prior_receipt_sha256,
      transition_payload,transition_canonical,
      receipt_sha256,occurred_at,created_at
    ) VALUES (
      v_plan.plan_id,v_node_id,v_transition_sequence,'NODE',v_stage,
      NULL,'QUEUED','RECURSION_POLICY',v_policy.policy_digest,
      'SERVICE','workflow-worker',v_transition_sequence - 1,
      v_prior_transition_receipt,
      v_transition_payload,v_transition_canonical,
      v_transition_receipt,v_now,v_now
    );
    v_disposition := 'STARTED';
  END evaluate_stage;

  IF v_disposition IS NULL THEN
    RAISE EXCEPTION 'hypothesis_recursion_disposition_missing'
      USING ERRCODE = '55000';
  END IF;
  IF v_disposition <> 'STARTED' THEN
    v_plan_id := NULL;
    v_node_id := NULL;
    v_agent_run_id := NULL;
    v_job_id := NULL;
  END IF;
  v_receipt_payload := jsonb_build_object(
    'schemaVersion','hypothesis-recursion-receipt.v1',
    'receiptId',v_receipt_id,'triggerKind','AGENT_RUN',
    'triggerId',v_agent_run_id_input,
    'triggerGeneration',v_trigger_generation,
    'triggerDigest',btrim(v_trigger_digest::text),
    'triggerReceiptSha256',btrim(v_trigger_receipt_sha256::text),
    'triggerPayloadSha256',btrim(v_trigger_digest::text),
    'producerJobId',p_producer_job_id,
    'policyId',CASE WHEN v_policy.policy_id IS NULL
      THEN NULL ELSE v_policy.policy_id END,
    'policyVersion',CASE WHEN v_policy.policy_id IS NULL
      THEN NULL ELSE v_policy.version END,
    'hypothesisPayloadSha256',CASE
      WHEN v_hypothesis_payload_sha256 IS NULL THEN NULL
      ELSE btrim(v_hypothesis_payload_sha256::text) END,
    'parentOutputSha256',CASE
      WHEN v_parent_output_sha256 IS NULL THEN NULL
      ELSE btrim(v_parent_output_sha256::text) END,
    'disposition',v_disposition,'planId',v_plan_id,'nodeId',v_node_id,
    'agentRunId',v_agent_run_id,'jobId',v_job_id,
    'actorType','SERVICE','actorId','workflow-worker','occurredAt',v_now
  );
  v_receipt_canonical := ops.canonical_jsonb_v1(v_receipt_payload);
  v_receipt_digest := encode(
    extensions.digest(v_receipt_canonical, 'sha256'), 'hex'
  );
  INSERT INTO ops.hypothesis_recursion_receipts(
    receipt_id,trigger_kind,trigger_id,trigger_generation,trigger_digest,
    trigger_receipt_sha256,producer_job_id,policy_id,policy_version,
    disposition,plan_id,node_id,agent_run_id,job_id,actor_type,actor_id,
    receipt_payload,receipt_canonical,receipt_digest,created_at
  ) VALUES (
    v_receipt_id,'AGENT_RUN',v_agent_run_id_input,v_trigger_generation,
    v_trigger_digest,v_trigger_receipt_sha256,p_producer_job_id,
    CASE WHEN v_policy.policy_id IS NULL THEN NULL ELSE v_policy.policy_id END,
    CASE WHEN v_policy.policy_id IS NULL THEN NULL ELSE v_policy.version END,
    v_disposition,v_plan_id,v_node_id,v_agent_run_id,v_job_id,
    'SERVICE','workflow-worker',v_receipt_payload,v_receipt_canonical,
    v_receipt_digest,v_now
  );
  RETURN QUERY SELECT v_disposition,v_receipt_id,v_plan_id,v_node_id,
    v_agent_run_id,v_job_id,v_receipt_digest,false;
END
$$;
ALTER FUNCTION
  ops.process_hypothesis_recursion_stage_completed_v1(jsonb,uuid)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  ops.process_hypothesis_recursion_stage_completed_v1(jsonb,uuid)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION
  ops.process_hypothesis_recursion_stage_completed_v1(jsonb,uuid)
  TO gurine_workflow_worker;

-- Forward-only R6c fence hardening for hypothesis recursion event consumers.
-- Append before the final COMMIT of 0037 after the current two-argument
-- owner routines have been created.

ALTER FUNCTION ops.process_hypothesis_execution_completed_v1(jsonb,uuid)
  RENAME TO process_hypothesis_execution_completed_v1_unfenced_0037;
REVOKE ALL ON FUNCTION
  ops.process_hypothesis_execution_completed_v1_unfenced_0037(jsonb,uuid)
  FROM PUBLIC;
REVOKE ALL ON FUNCTION
  ops.process_hypothesis_execution_completed_v1_unfenced_0037(jsonb,uuid)
  FROM gurine_workflow_worker;

CREATE FUNCTION ops.process_hypothesis_execution_completed_v1(
  p_payload jsonb,
  p_producer_job_id uuid,
  p_producer_job_lease_token uuid,
  p_producer_job_fencing_token bigint
) RETURNS TABLE(
  disposition text,
  receipt_id uuid,
  plan_id uuid,
  node_id uuid,
  agent_run_id uuid,
  job_id uuid,
  receipt_digest char(64),
  replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, editorial, ops, extensions, pg_temp
AS $$
DECLARE
  v_job ops.jobs%ROWTYPE;
  v_outbox ops.outbox%ROWTYPE;
  v_event_id uuid;
  v_execution_id uuid;
  v_state_version bigint;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_payload IS NULL
     OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
     OR p_producer_job_id IS NULL
     OR p_producer_job_lease_token IS NULL
     OR p_producer_job_fencing_token IS NULL
     OR p_producer_job_fencing_token < 1
     OR COALESCE(p_payload->>'executionId','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR COALESCE(p_payload->>'stateVersion','') !~ '^[1-9][0-9]*$' THEN
    RAISE EXCEPTION 'hypothesis_recursion_execution_job_fence_input_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT pg_has_role(session_user, 'gurine_workflow_worker', 'MEMBER') THEN
    RAISE EXCEPTION 'hypothesis_recursion_worker_role_required'
      USING ERRCODE = '42501';
  END IF;

  v_execution_id := (p_payload->>'executionId')::uuid;
  v_state_version := (p_payload->>'stateVersion')::bigint;
  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_producer_job_id
    AND job.job_type = 'EVENT_DELIVERY'
    AND job.queue = 'workflow-worker'
    AND job.status = 'RUNNING'
    AND job.lease_token = p_producer_job_lease_token
    AND job.fencing_token = p_producer_job_fencing_token
    AND job.lease_expires_at > v_now
  FOR SHARE;
  IF NOT FOUND
     OR jsonb_typeof(v_job.payload) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(v_job.payload)) <> 8
     OR NOT v_job.payload ?& ARRAY[
       'consumerId','eventId','eventType','aggregateType','aggregateId',
       'aggregateVersion','occurredAt','payload'
     ]
     OR v_job.payload->>'consumerId' IS DISTINCT FROM 'workflow-worker'
     OR v_job.payload->>'eventType'
       IS DISTINCT FROM 'action.execution_completed.v1'
     OR v_job.payload->>'aggregateType' IS DISTINCT FROM 'action_execution'
     OR v_job.payload->>'aggregateId' IS DISTINCT FROM v_execution_id::text
     OR v_job.payload->>'aggregateVersion'
       IS DISTINCT FROM v_state_version::text
     OR COALESCE(v_job.payload->>'eventId','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR NULLIF(v_job.payload->>'occurredAt','') IS NULL
     OR v_job.payload->'payload' IS DISTINCT FROM p_payload THEN
    RAISE EXCEPTION 'hypothesis_recursion_execution_producer_job_fence_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_event_id := (v_job.payload->>'eventId')::uuid;
  SELECT event.* INTO v_outbox
  FROM ops.outbox AS event
  WHERE event.id = v_event_id
    AND event.aggregate_type = v_job.payload->>'aggregateType'
    AND event.aggregate_id = v_job.payload->>'aggregateId'
    AND event.aggregate_version = v_state_version
    AND event.event_type = v_job.payload->>'eventType'
    AND event.payload = p_payload
    AND event.occurred_at = (v_job.payload->>'occurredAt')::timestamptz
    AND EXISTS (
      SELECT 1
      FROM ops.event_types AS event_type
      WHERE event_type.event_type = event.event_type
        AND event_type.active
        AND event_type.payload_schema_uri IS NOT NULL
    )
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'hypothesis_recursion_execution_outbox_binding_invalid'
      USING ERRCODE = '23514';
  END IF;

  RETURN QUERY
  SELECT legacy.disposition, legacy.receipt_id, legacy.plan_id,
    legacy.node_id, legacy.agent_run_id, legacy.job_id,
    legacy.receipt_digest, legacy.replayed
  FROM ops.process_hypothesis_execution_completed_v1_unfenced_0037(
    p_payload, p_producer_job_id
